insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jb',38,15,'crampon1923','pour que les malfaiteurs soient privés de leur lumière, et que le bras levé pour le crime soit brisé?'),
('jb',38,16,'crampon1923','Es-tu descendu jusqu''aux sources de la mer, t''es-tu promené dans les profondeurs de l''abîme?'),
('jb',38,17,'crampon1923','Les portes de la mort se sont-elles ouvertes devant toi, as-tu vu les portes du sombre séjour?'),
('jb',38,18,'crampon1923','As-tu embrassé l''étendue de la terre? Parle, si tu sais toutes ces choses.'),
('jb',38,19,'crampon1923','Où est le chemin qui conduit au séjour de la lumière, et où se trouve la demeure des ténèbres?'),
('jb',38,20,'crampon1923','Tu pourrais les saisir en leur domaine, tu connais les sentiers de leur séjour!...'),
('jb',38,21,'crampon1923','Tu le sais sans doute, puisque tu étais né avant elles; le nombre de tes jours est si grand!...'),
('jb',38,22,'crampon1923','Es-tu entré dans les trésors de la neige? As-tu vu les réservoirs de la grêle,'),
('jb',38,23,'crampon1923','que je tiens prêts pour le temps de la détresse, pour les jours de la guerre et du combat?'),
('jb',38,24,'crampon1923','Par quelle voie la lumière se divise-t-elle, et le vent d''orient se répand-il sur la terre?'),
('jb',38,25,'crampon1923','Qui a ouvert des canaux aux ondées, et tracé une route aux feux du tonnerre,'),
('jb',38,26,'crampon1923','afin que la pluie tombe sur une terre inhabitée, sur le désert où il n''y a point d''hommes;'),
('jb',38,27,'crampon1923','pour qu''elle arrose la plaine vaste et vide, et y fasse germer l''herbe verte!'),
('jb',38,28,'crampon1923','La pluie a-t-elle un père? Qui engendre les gouttes de la rosée?'),
('jb',38,29,'crampon1923','De quel sein sort la glace? Et le givre du ciel, qui l''enfante,'),
('jb',38,30,'crampon1923','pour que les eaux durcissent comme la pierre, et que la surface de l''abîme se solidifie?'),
('jb',38,31,'crampon1923','Est-ce toi qui serres les liens des Pléiades, ou pourrais-tu relâcher les chaînes d''Orion?'),
('jb',38,32,'crampon1923','Est-ce toi qui fais lever les constellations en leur temps, qui conduis l''Ourse avec ses petits?'),
('jb',38,33,'crampon1923','Connais-tu les lois du ciel, règles-tu ses influences sur la terre?'),
('jb',38,34,'crampon1923','Elèves-tu ta voix jusque dans les nues, pour que des torrents d''eau tombent sur toi?'),
('jb',38,35,'crampon1923','Est-ce toi qui lâches les éclairs pour qu''ils partent, et te disent-ils: « Nous voici! »'),
('jb',38,36,'crampon1923','Qui a mis la sagesse dans les nuées, ou qui a donné l''intelligence aux météores?'),
('jb',38,37,'crampon1923','Qui peut exactement compter les nuées, incliner les urnes du ciel,'),
('jb',38,38,'crampon1923','pour que la poussière se forme en masse solide et que les glèbes adhèrent ensemble?'),
('jb',38,39,'crampon1923','Est-ce toi qui chasses pour la lionne sa proie, qui rassasies la faim des lionceaux,'),
('jb',38,40,'crampon1923','quand ils sont couchés dans leur tanière, qu''ils se tiennent en embuscade dans le taillis?'),
('jb',38,41,'crampon1923','Qui prépare au corbeau sa pâture, quand ses petits crient vers Dieu, qu''ils errent çà et là, sans nourriture?'),
('jb',39,1,'crampon1923','Connais-tu le temps où les chèvres sauvages font leurs petits? As-tu observé les biches quand elles mettent bas?'),
('jb',39,2,'crampon1923','As-tu compté les mois de leur portée, et connais-tu l''époque de leur délivrance?'),
('jb',39,3,'crampon1923','Elles se mettent à genoux, déposent leurs petits, et sont quittes de leurs douleurs.'),
('jb',39,4,'crampon1923','Leurs faons se fortifient et grandissent dans les champs; ils s''en vont, et ne reviennent plus.'),
('jb',39,5,'crampon1923','Qui a lâché l''onagre en liberté, qui a brisé les liens de l''âne sauvage,'),
('jb',39,6,'crampon1923','à qui j''ai donné le désert pour maison, pour demeure la plaine salée?'),
('jb',39,7,'crampon1923','Il méprise le tumulte des villes, il n''entend pas les cris d''un maître.'),
('jb',39,8,'crampon1923','Il parcourt les montagnes pour trouver sa pâture, il y poursuit les moindres traces de verdure.'),
('jb',39,9,'crampon1923','Le buffle voudra-t-il te servir, ou bien passera-t-il la nuit dans son étable?'),
('jb',39,10,'crampon1923','L''attacheras-tu avec une corde au sillon, ou bien hersera-t-il derrière toi dans les vallées?'),
('jb',39,11,'crampon1923','Te fieras-tu à lui parce qu''il est très fort, lui laisseras-tu faire tes travaux?'),
('jb',39,12,'crampon1923','Compteras-tu sur lui pour rentrer ta moisson, pour recueillir le blé dans ton aire?'),
('jb',39,13,'crampon1923','L''aile de l''autruche bat joyeusement; elle n''a ni l''aile pieuse ni le plumage de la cigogne.'),
('jb',39,14,'crampon1923','Elle abandonne ses œufs à la terre, et les laisse chauffer sur le sable.'),
('jb',39,15,'crampon1923','Elle oublie que le pied peut les fouler, la bête des champs les écraser.'),
('jb',39,16,'crampon1923','Elle est dure pour ses petits, comme s''ils n''étaient pas siens; que son travail soit vain, elle ne s''en inquiète pas.'),
('jb',39,17,'crampon1923','Car Dieu lui a refusé la sagesse, et ne lui a pas départi l''intelligence.'),
('jb',39,18,'crampon1923','Mais quand elle se bat les flancs et prend son essor, elle se rit du cheval et du cavalier.'),
('jb',39,19,'crampon1923','Est-ce toi qui donnes au cheval la vigueur, qui revêts son cou d''une crinière flottante,'),
('jb',39,20,'crampon1923','qui le fais bondir comme la sauterelle? Son fier hennissement répand la terreur.'),
('jb',39,21,'crampon1923','Il creuse du pied la terre, il est fier de sa force, il s''élance au-devant du combat.'),
('jb',39,22,'crampon1923','Il se rit de la peur; rien ne l''effraie; il ne recule pas devant l''épée.'),
('jb',39,23,'crampon1923','Sur lui résonne le carquois, la lance étincelante et le javelot.'),
('jb',39,24,'crampon1923','Il frémit, il s''agite, il dévore le sol; il ne se contient plus quand la trompette sonne.'),
('jb',39,25,'crampon1923','Au bruit de la trompette, il dit: « Allons! » De loin il flaire la bataille, la voix tonnante des chefs et les cris des guerriers.'),
('jb',39,26,'crampon1923','Est-ce par ta sagesse que l''épervier prend son vol et déploie ses ailes vers le midi?'),
('jb',39,27,'crampon1923','Est-ce à ton ordre que l''aigle s''élève, et fait son nid sur les hauteurs?'),
('jb',39,28,'crampon1923','Il habite les rochers, il fixe sa demeure dans les dents de la pierre, sur les sommets.'),
('jb',39,29,'crampon1923','De là, il guette sa proie, son regard perce au loin.'),
('jb',39,30,'crampon1923','Ses petits s''abreuvent de sang; partout où il y a des cadavres, on le trouve.'),
('jb',40,1,'crampon1923','Yahweh s''adressant à Job, dit:'),
('jb',40,2,'crampon1923','Le censeur du Tout-Puissant veut-il encore plaider contre lui? Celui qui dispute avec Dieu peut-il répondre?'),
('jb',40,3,'crampon1923','Job répondit à Yahweh, en disant:'),
('jb',40,4,'crampon1923','Chétif que je suis, que te répondrai-je? Je mets la main sur ma bouche.'),
('jb',40,5,'crampon1923','J''ai parlé une fois, je ne répliquerai pas; deux fois, je n''ajouterai rien.'),
('jb',40,6,'crampon1923','Yahweh parla encore à Job du sein de la tempête et dit:'),
('jb',40,7,'crampon1923','Ceins tes reins, comme un homme; Je vais t''interroger, et tu m''instruiras.'),
('jb',40,8,'crampon1923','Veux-tu donc anéantir ma justice, me condamner afin d''avoir droit?'),
('jb',40,9,'crampon1923','As-tu un bras comme celui de Dieu, et tonnes-tu de la voix comme lui?'),
('jb',40,10,'crampon1923','Pare-toi de grandeur et de magnificence, revêts-toi de gloire et de majesté;'),
('jb',40,11,'crampon1923','épanche les flots de ta colère, d''un regard abaisse tout superbe.'),
('jb',40,12,'crampon1923','D''un regard fais plier tout superbe, écrase sur place les méchants;'),
('jb',40,13,'crampon1923','cache-les tous ensemble dans la poussière, enferme leur visage dans les ténèbres.'),
('jb',40,14,'crampon1923','Alors, moi aussi, je te rendrai l''hommage, que ta droite peut te sauver.'),
('jb',40,15,'crampon1923','Vois Béhémoth, que j''ai créé comme toi: il se nourrit d''herbe, comme le bœuf.'),
('jb',40,16,'crampon1923','Vois donc, sa force est dans ses reins, et sa vigueur dans les muscles de ses flancs!'),
('jb',40,17,'crampon1923','Il dresse sa queue comme un cèdre; les nerfs de ses cuisses forment un solide faisceau.'),
('jb',40,18,'crampon1923','Ses os sont des tubes d''airain, ses côtes sont des barres de fer.'),
('jb',40,19,'crampon1923','C''est le chef-d''œuvre de Dieu; son Créateur l''a pourvu d''un glaive.'),
('jb',40,20,'crampon1923','Les montagnes produisent pour lui du fourrage, autour de lui se jouent toutes les bêtes des champs.'),
('jb',40,21,'crampon1923','Il se couche sous les lotus, dans le secret des roseaux et des marécages.'),
('jb',40,22,'crampon1923','Les lotus le couvrent de leur ombre, les saules du torrent l''environnent.'),
('jb',40,23,'crampon1923','Que le fleuve déborde, il ne craint pas; il serait calme, si le Jourdain montait à sa gueule.'),
('jb',40,24,'crampon1923','Est-ce en face qu''on pourra le saisir, avec des filets, et lui percer les narines?'),
('jb',40,25,'crampon1923','Tireras-tu Léviathan avec un hameçon, et lui serreras-tu la langue avec une corde?'),
('jb',40,26,'crampon1923','Lui passeras-tu un jonc dans les narines, et lui perceras-tu la mâchoire avec un anneau?'),
('jb',40,27,'crampon1923','T''adressera-t-il d''ardentes prières, te dira-t-il de douces paroles?'),
('jb',40,28,'crampon1923','Fera-t-il une alliance avec toi, le prendras-tu toujours à ton service?'),
('jb',40,29,'crampon1923','Joueras-tu avec lui comme avec un passereau, l''attacheras-tu pour amuser tes filles?'),
('jb',40,30,'crampon1923','Les pêcheurs associés en font-ils le commerce, le partagent-ils entre les marchands?'),
('jb',40,31,'crampon1923','Cribleras-tu sa peau de dards, perceras-tu sa tête du harpon?'),
('jb',40,32,'crampon1923','Essaie de mettre la main sur lui: souviens-toi du combat, et tu n''y reviendras plus.'),
('jb',41,1,'crampon1923','Voici que le chasseur est trompé dans son attente; la vue du monstre suffit à le terrasser.'),
('jb',41,2,'crampon1923','Nul n''est assez hardi pour provoquer Léviathan: qui donc oserait me résister en face?'),
('jb',41,3,'crampon1923','Qui m''a obligé, pour que j''aie à lui rendre? Tout ce qui est sous le ciel est à moi.'),
('jb',41,4,'crampon1923','Je ne veux pas taire ses membres, sa force, l''harmonie de sa structure.'),
('jb',41,5,'crampon1923','Qui jamais a soulevé le bord de sa cuirasse? Qui a franchi la double ligne de son râtelier?'),
('jb',41,6,'crampon1923','Qui a ouvert les portes de sa gueule? Autour de ses dents habite la terreur.'),
('jb',41,7,'crampon1923','Superbes sont les lignes de ses écailles, comme des sceaux étroitement serrés.'),
('jb',41,8,'crampon1923','Chacune touche sa voisine; un souffle ne passerait pas entre elles.'),
('jb',41,9,'crampon1923','Elles adhèrent l''une à l''autre, elles sont jointes et ne sauraient se séparer.'),
('jb',41,10,'crampon1923','Ses éternuements font jaillir la lumière, ses yeux sont comme les paupières de l''aurore.'),
('jb',41,11,'crampon1923','Des flammes jaillissent de sa gueule, il s''en échappe des étincelles de feu.'),
('jb',41,12,'crampon1923','Une fumée sort de ses narines, comme d''une chaudière ardente et bouillante.'),
('jb',41,13,'crampon1923','Son souffle allume les charbons, de sa bouche s''élance la flamme.'),
('jb',41,14,'crampon1923','Dans son cou réside la force, devant lui bondit l''épouvante.'),
('jb',41,15,'crampon1923','Les muscles de sa chair tiennent ensemble; fondus sur lui, inébranlables.'),
('jb',41,16,'crampon1923','Son cœur est dur comme la pierre, dur comme la meule inférieure.'),
('jb',41,17,'crampon1923','Quand il se lève, les plus braves ont peur, l''épouvante les fait défaillir.'),
('jb',41,18,'crampon1923','Qu''on l''attaque avec l''épée, l''épée ne résiste pas, ni la lance, ni le javelot, ni la flèche.'),
('jb',41,19,'crampon1923','Il tient le fer pour de la paille, l''airain comme un bois vermoulu.'),
('jb',41,20,'crampon1923','La fille de l''arc ne le fait pas fuir, les pierres de la fronde sont pour lui un fétu;'),
('jb',41,21,'crampon1923','la massue, un brin de chaume; il se rit du fracas des piques.'),
('jb',41,22,'crampon1923','Sous son ventre sont des tessons aigus: on dirait une herse qu''il étend sur le limon.'),
('jb',41,23,'crampon1923','Il fait bouillonner l''abîme comme une chaudière, il fait de la mer un vase de parfums.'),
('jb',41,24,'crampon1923','Il laisse après lui un sillage de lumière, on dirait que l''abîme a des cheveux blancs.'),
('jb',41,25,'crampon1923','Il n''a pas son égal sur la terre, il a été créé pour ne rien craindre.'),
('jb',41,26,'crampon1923','Il regarde en face tout ce qui est élevé, il est le roi des plus fiers animaux.'),
('jb',42,1,'crampon1923','Job répondit à Yahweh et dit:'),
('jb',42,2,'crampon1923','Je sais que tu peux tout, et que pour toi aucun dessein n''est trop difficile.'),
('jb',42,3,'crampon1923','« Quel est celui qui obscurcit le plan divin, sans savoir? » Oui, j''ai parlé sans intelligence de merveilles qui me dépassent et que j''ignore.'),
('jb',42,4,'crampon1923','« Ecoute-moi, je vais parler; je t''interrogerai, réponds-moi. »'),
('jb',42,5,'crampon1923','Mon oreille avait entendu parler de toi; mais maintenant mon œil t''a vu.'),
('jb',42,6,'crampon1923','C''est pourquoi je me condamne et me repens, sur la poussière et sur la cendre.'),
('jb',42,7,'crampon1923','Après que Yahweh eut adressé ces paroles à Job, il dit à Eliphaz de Théman: « Ma colère est allumée contre toi et contre tes deux amis, parce que vous n''avez pas parlé de moi selon la vérité, comme l''a fait mon serviteur Job.'),
('jb',42,8,'crampon1923','Maintenant, prenez sept jeunes taureaux et sept béliers; puis venez trouver mon serviteur Job, et offrez pour vous un holocauste. Job, mon serviteur, priera pour vous, et c''est par égard pour lui que je ne vous traiterai point selon votre folie; car vous n''avez pas parlé de moi selon la vérité, comme l''a fait mon serviteur Job. »'),
('jb',42,9,'crampon1923','Eliphaz de Théman, Baldad de Suhé et Sophar de Naaman allèrent donc et firent comme Yahweh leur avait dit; et Yahweh eut égard à la prière de Job.'),
('jb',42,10,'crampon1923','Yahweh rétablit Job dans son premier état, pendant que Job intercédait pour ses amis, et Yahweh rendit à Job le double de tous ses biens.'),
('jb',42,11,'crampon1923','Ses frères, ses sœurs et ses anciens amis vinrent tous le visiter et mangèrent avec lui dans sa maison. Ils le plaignirent et le consolèrent de tous les malheurs que Yahweh avait fait venir sur lui; et ils lui firent don chacun d''une késita et d''un anneau d''or.'),
('jb',42,12,'crampon1923','Et Yahweh bénit les derniers temps de Job plus encore que les premiers, et il posséda quatorze mille brebis, six mille chameaux, mille paires de bœufs et mille ânesses.'),
('jb',42,13,'crampon1923','Il eut sept fils et trois filles;'),
('jb',42,14,'crampon1923','il nomma la première Jémima, la deuxième Ketsia et la troisième Kéren-Hapouk.'),
('jb',42,15,'crampon1923','On ne trouvait pas dans toute la terre d''aussi belles femmes que les filles de Job, et leur père leur donna une part d''héritage parmi leurs frères.'),
('jb',42,16,'crampon1923','Job vécut après cela cent quarante ans, et il vit ses fils et les fils de ses fils jusqu''à la quatrième génération.'),
('jb',42,17,'crampon1923','Et Job mourut vieux et rassasié de jours.'),
('ps',1,1,'crampon1923','Heureux l''homme qui ne marche pas dans le conseil des impies, qui ne se tient pas dans la voie des pécheurs, et qui ne s''assied pas dans la compagnie des moqueurs,'),
('ps',1,2,'crampon1923','mais qui a son plaisir dans la loi de Yahweh, et qui la médite jour et nuit!'),
('ps',1,3,'crampon1923','Il est comme un arbre planté près d''un cours d''eau, qui donne son fruit en son temps, et dont le feuillage ne se flétrit pas: tout ce qu''il fait réussit.'),
('ps',1,4,'crampon1923','Il n''en est pas ainsi des impies: ils sont comme la paille que chasse le vent.'),
('ps',1,5,'crampon1923','Aussi les impies ne resteront-ils pas debout au jour du jugement, ni les pécheurs dans l''assemblée des justes.'),
('ps',1,6,'crampon1923','Car Yahweh connaît la voie du juste, mais la voie des pécheurs mène à la ruine.'),
('ps',2,1,'crampon1923','Pourquoi les nations s''agitent-elles en tumulte et les peuples méditent-ils de vains projets?'),
('ps',2,2,'crampon1923','Les rois de la terre se soulèvent, et les princes tiennent conseil ensemble, contre Yahweh et contre son Oint.'),
('ps',2,3,'crampon1923','" Brisons leurs liens, disent-ils, et jetons loin de nous leurs chaînes! "'),
('ps',2,4,'crampon1923','Celui qui est assis dans les cieux sourit, le Seigneur se moque d''eux.'),
('ps',2,5,'crampon1923','Alors il leur parlera dans sa colère, et dans sa fureur il les épouvantera:'),
('ps',2,6,'crampon1923','" Et moi, j''ai établi mon roi, sur Sion, ma montagne sainte. "'),
('ps',2,7,'crampon1923','" Je publierai le décret: Yahweh m''a dit: Tu es mon Fils, je t''ai engendré aujourd''hui.'),
('ps',2,8,'crampon1923','Demande, et je te donnerai les nations pour héritage, pour domaine les extrémités de la terre.'),
('ps',2,9,'crampon1923','Tu les briseras avec un sceptre de fer, tu les mettras en pièces comme le vase du potier. "'),
('ps',2,10,'crampon1923','Et maintenant, rois, devenez sages; recevez l''avertissement, juges de la terre.'),
('ps',2,11,'crampon1923','Servez Yahweh avec crainte, tressaillez de joie avec tremblement.'),
('ps',2,12,'crampon1923','Baisez le Fils, de peur qu''il ne s''irrite et que vous ne périssiez dans votre voie; Car bientôt s''allumerait sa colère; heureux tous ceux qui mettent en lui leur confiance.'),
('ps',3,1,'crampon1923','Chant de David. A l''occasion de sa fuite devant Absalon, son fils'),
('ps',3,2,'crampon1923','Yahweh, que mes ennemis sont nombreux! Quelle multitude se lève contre moi!'),
('ps',3,3,'crampon1923','Nombreux sont ceux qui disent à mon sujet: " Plus de salut pour lui auprès de Dieu! " — Séla.'),
('ps',3,4,'crampon1923','Mais toi, Yahweh, tu es mon bouclier; tu es ma gloire, et tu relèves ma tête.'),
('ps',3,5,'crampon1923','De ma voix je crie vers Yahweh, et il me répond de sa montagne sainte. — Séla.'),
('ps',3,6,'crampon1923','Je me suis couché et me suis endormi; je me suis réveillé, car Yahweh est mon soutien.'),
('ps',3,7,'crampon1923','je ne crains pas devant le peuple innombrable, qui m''assiège de toutes parts.'),
('ps',3,8,'crampon1923','Lève-toi, Yahweh! Sauve-moi, mon Dieu! Car tu frappes à la joue tous mes ennemis, tu brises les dents des méchants.'),
('ps',3,9,'crampon1923','A Yahweh le salut! Que ta bénédiction soit sur ton peuple! — Séla.'),
('ps',4,1,'crampon1923','Au maître de chant, sur les instruments à cordes. Psaume de David.'),
('ps',4,2,'crampon1923','Quand je t''invoque, réponds-moi, Dieu de ma justice, toi qui dans ma détresse, me mets au large. Aie pitié de moi et entends ma prière!'),
('ps',4,3,'crampon1923','Fils des hommes, jusques à quand ma gloire sera-t-elle outragée? Jusques à quand aimerez-vous la vanité, et rechercherez-vous le mensonge? — Séla.'),
('ps',4,4,'crampon1923','Sachez que Yahweh s''est choisi un homme pieux; Yahweh entend quand je l''invoque.'),
('ps',4,5,'crampon1923','Tremblez, et ne péchez plus! Parlez-vous à vous-mêmes sur votre couche, et cessez! — Séla.'),
('ps',4,6,'crampon1923','Offrez des sacrifices de justice, et confiez-vous en Yahweh.'),
('ps',4,7,'crampon1923','Beaucoup disent: " Qui nous fera voir le bonheur? " Fais lever sur nous la lumière de ta face, Yahweh!'),
('ps',4,8,'crampon1923','Tu as mis dans mon cœur plus de joie qu''ils n''en ont au temps où abondent leur froment et leur vin nouveau.'),
('ps',4,9,'crampon1923','En paix je me coucherai et je m''endormirai aussitôt; car toi, Yahweh, toi seul, tu me fais habiter dans la sécurité.'),
('ps',5,1,'crampon1923','Au maître de chant. Sur les flûtes. Psaume de David.'),
('ps',5,2,'crampon1923','Prête l''oreille à mes paroles, Yahweh, entends mes soupirs;'),
('ps',5,3,'crampon1923','sois attentif à mes cris, ô mon Roi et mon Dieu; car c''est à toi que j''adresse ma prière.'),
('ps',5,4,'crampon1923','Yahweh, dès le matin, tu entends ma voix; dès le matin, je t''offre mes vœux et j''attends.'),
('ps',5,5,'crampon1923','Car tu n''es pas un Dieu qui prenne plaisir au mal; avec toi le méchant ne saurait habiter.'),
('ps',5,6,'crampon1923','Les insensés ne subsistent pas devant tes yeux; tu hais tous les artisans d''iniquité.'),
('ps',5,7,'crampon1923','Tu fais périr les menteurs; Yahweh abhorre l''homme de sang et de fraude.'),
('ps',5,8,'crampon1923','Pour moi, par ta grande miséricorde, j''irai dans ta maison; je me prosternerai, dans ta crainte, devant ton saint temple.'),
('ps',5,9,'crampon1923','Seigneur, conduis-moi, dans ta justice, à cause de mes ennemis aplanis ta voie sous mes pas.'),
('ps',5,10,'crampon1923','Car il n''y a point de sincérité dans leur bouche; leur cœur n''est que malice; leur gosier est un sépulcre ouvert, leur langue se fait caressante.'),
('ps',5,11,'crampon1923','Châtie-les, ô Dieu. Qu''ils échouent dans leurs desseins! A cause de leurs crimes sans nombre, précipite-les; car ils sont en révolte contre toi.'),
('ps',5,12,'crampon1923','Alors se réjouiront tous ceux qui se confient en toi; ils seront dans une perpétuelle allégresse, et tu les protégeras; ils se livreront à de joyeux transports, ceux qui aiment ton nom.'),
('ps',5,13,'crampon1923','Car tu bénis le juste, Yahweh; tu l''entoures de bienveillance comme d''un bouclier.'),
('ps',6,1,'crampon1923','Au maître de chant. Sur les instruments à cordes. A l''octave. Psaume de David.'),
('ps',6,2,'crampon1923','Yahweh, ne me punis pas dans ta colère, et ne me châtie pas dans ta fureur.'),
('ps',6,3,'crampon1923','Aie pitié de moi, Yahweh, car je suis sans force; guéris-moi, Yahweh, car mes os sont tremblants.'),
('ps',6,4,'crampon1923','Mon âme est dans un trouble extrême; et toi, Yahweh, jusques à quand...?'),
('ps',6,5,'crampon1923','Reviens, Yahweh, délivre mon âme; sauve-moi à cause de ta miséricorde.'),
('ps',6,6,'crampon1923','Car celui qui meurt n''a plus souvenir de toi; qui te louera dans le schéol?'),
('ps',6,7,'crampon1923','Je suis épuisé à force de gémir; chaque nuit ma couche est baignée de mes larmes, mon lit est arrosé de mes pleurs.'),
('ps',6,8,'crampon1923','mon œil est consumé par le chagrin; il a vieilli à cause de tous ceux qui me persécutent.'),
('ps',6,9,'crampon1923','Eloignez-vous de moi, vous tous qui faites le mal! Car Yahweh a entendu la voix de mes larmes.'),
('ps',6,10,'crampon1923','Yahweh a entendu ma supplication, Yahweh accueille ma prière.'),
('ps',6,11,'crampon1923','Tous mes ennemis seront confondus et saisis d''épouvante; ils reculeront, soudain couverts de honte.'),
('ps',7,1,'crampon1923','Dithyrambe de David, qu''il chanta à Yahweh à l''occasion des paroles de Chus, le Benjamite.'),
('ps',7,2,'crampon1923','Yahweh, mon Dieu, en toi je me confie; sauve-moi de tous mes persécuteurs et délivre-moi,'),
('ps',7,3,'crampon1923','de peur qu''il ne me déchire, comme un lion, qu''il ne dévore sa proie, sans que nul ne la lui arrache.'),
('ps',7,4,'crampon1923','Yahweh, mon Dieu, si j''ai fait cela, s''il y a de l''iniquité dans mes mains;'),
('ps',7,5,'crampon1923','si j''ai rendu le mal à qui est en paix avec moi, si j''ai dépouillé celui qui m''opprime sans raison,'),
('ps',7,6,'crampon1923','que l''ennemi me poursuive et m''atteigne, qu''il foule à terre ma vie, qu''il couche ma gloire dans la poussière.'),
('ps',7,7,'crampon1923','Lève-toi, Yahweh, dans ta colère, porte-toi contre les fureurs de mes adversaires; réveille-toi pour me secourir, toi qui ordonnes un jugement.'),
('ps',7,8,'crampon1923','Que l''assemblée des peuples t''environne! Puis, t''élevant au-dessus d''elle, remonte dans les hauteurs.'),
('ps',7,9,'crampon1923','Yahweh juge les peuples: rends-moi justice, Yahweh, selon mon droit et mon innocence.'),
('ps',7,10,'crampon1923','Mets un terme à la malice des méchants, et affermis le juste, toi qui sondes les cœurs et les reins, ô Dieu juste!'),
('ps',7,11,'crampon1923','Mon bouclier est en Dieu, qui sauve les hommes au cœur droit.'),
('ps',7,12,'crampon1923','Dieu est un juste juge; tous les jours, le Tout-Puissant fait entendre ses menaces.'),
('ps',7,13,'crampon1923','Certes, de nouveau il aiguise son glaive, il bande son arc et il vise;'),
('ps',7,14,'crampon1923','il dirige sur lui des traits meurtriers, il rend ses flèches brûlantes.'),
('ps',7,15,'crampon1923','Voici le méchant en travail de l''iniquité: il a conçu le malheur, et il enfante le mensonge.'),
('ps',7,16,'crampon1923','il ouvre une fosse, il la creuse, et il tombe dans l''abîme qu''il préparait.'),
('ps',7,17,'crampon1923','Son iniquité retombe sur sa tête, et sa violence redescend sur son front.'),
('ps',7,18,'crampon1923','Je louerai Yahweh pour sa justice, je chanterai le nom de Yahweh, le Très-Haut.'),
('ps',8,1,'crampon1923','Au maître de chant. Sur la Gitthienne. Chant de David.'),
('ps',8,2,'crampon1923','Yahweh, notre Seigneur, que ton nom est glorieux sur toute la terre! Toi qui as revêtu les cieux de ta majesté!'),
('ps',8,3,'crampon1923','Par la bouche des enfants et de ceux qui sont à la mamelle tu t''es fondé une force pour confondre tes ennemis, pour imposer silence à l''adversaire et au blasphémateur.'),
('ps',8,4,'crampon1923','Quand je contemple tes cieux, ouvrage de tes doigts, la lune et les étoiles que tu as créées, je m''écrie:'),
('ps',8,5,'crampon1923','Qu''est-ce que l''homme, pour que tu te souviennes de lui, et le fils de l''homme, pour que tu en prennes soin?'),
('ps',8,6,'crampon1923','Tu l''as fait de peu inférieur à Dieu, tu l''as couronné de gloire et d''honneur.'),
('ps',8,7,'crampon1923','Tu lui as donné l''empire sur les œuvres de tes mains; tu as mis toutes choses sous ses pieds:'),
('ps',8,8,'crampon1923','Brebis et bœufs, tous ensemble, et les animaux des champs;'),
('ps',8,9,'crampon1923','oiseaux du ciel et poissons de la mer, et tout ce qui parcourt les sentiers des mers.'),
('ps',8,10,'crampon1923','Yahweh, notre Seigneur, que ton nom est glorieux sur toute la terre!'),
('ps',9,1,'crampon1923','Au maître de chant. Sur l''air " Mort au fils ". Psaume de David.'),
('ps',9,2,'crampon1923','Je louerai Yahweh de tout mon cœur, je raconterai toutes tes merveilles.'),
('ps',9,3,'crampon1923','Je me réjouirai et je tressaillerai en toi, je chanterai ton nom, ô Très-Haut.'),
('ps',9,4,'crampon1923','Mes ennemis reculent, ils trébuchent et tombent devant ta face.'),
('ps',9,5,'crampon1923','Car tu as fait triompher mon droit et ma cause, tu t''es assis sur ton trône en juste juge.'),
('ps',9,6,'crampon1923','Tu as châtié les nations, tu as fait périr l''impie, tu as effacé leur nom pour toujours et à jamais.'),
('ps',9,7,'crampon1923','L''ennemi est anéanti! Des ruines pour toujours! Des villes que tu as renversées! Leur souvenir a disparu!'),
('ps',9,8,'crampon1923','Mais Yahweh siège à jamais, il a dressé son trône pour le jugement.'),
('ps',9,9,'crampon1923','Il juge le monde avec justice, il juge les peuples avec droiture.'),
('ps',9,10,'crampon1923','Et Yahweh est un refuge pour l''opprimé, un refuge au temps de la détresse.'),
('ps',9,11,'crampon1923','En toi se confient tous ceux qui connaissent ton nom; car tu ne délaisses pas ceux qui te cherchent, Yahweh.'),
('ps',9,12,'crampon1923','Chantez à Yahweh, qui réside en Sion, publiez parmi les peuples ses hauts faits.'),
('ps',9,13,'crampon1923','Car celui qui redemande le sang versé s''en est souvenu, il n''a point oublié le cri des affligés.'),
('ps',9,14,'crampon1923','" Aie pitié de moi, Yahweh, disaient-ils; vois l''affliction où m''ont réduit mes ennemis, toi qui me retires des portes de la mort,'),
('ps',9,15,'crampon1923','afin que je puisse raconter toutes les louanges, aux portes de la fille de Sion, tressaillir de joie à cause de ton salut. "'),
('ps',9,16,'crampon1923','Les nations sont tombées dans la fosse qu''elles ont creusée, dans le lacet qu''elles ont caché s''est pris leur pied.'),
('ps',9,17,'crampon1923','Yahweh s''est montré, il a exercé le jugement, dans l''œuvre de ses mains il a enlacé l''impie. — Higgaion. Séla.'),
('ps',9,18,'crampon1923','Les impies retournent au schéol, toutes les nations qui oublient Dieu.'),
('ps',9,19,'crampon1923','Car le malheureux n''est pas toujours oublié, l''espérance des affligés ne périt pas à jamais.'),
('ps',9,20,'crampon1923','Lève-toi, Yahweh! Que l''homme ne triomphe pas! Que les nations soient jugées devant ta face!'),
('ps',9,21,'crampon1923','Répands sur elles l''épouvante, Yahweh; que les peuples sachent qu''ils sont des hommes! — Séla.'),
('ps',10,1,'crampon1923','Pourquoi, Yahweh, te tiens-tu éloigné? et te caches-tu au temps de la détresse?'),
('ps',10,2,'crampon1923','Quand le méchant s''enorgueillit, les malheureux sont consumés; ils sont pris dans les intrigues qu''il a conçues.'),
('ps',10,3,'crampon1923','Car le méchant se glorifie de sa convoitise; le ravisseur maudit, méprise Yahweh.'),
('ps',10,4,'crampon1923','Dans son arrogance, le méchant dit: " Il ne punit pas! " " Il n''y a pas de Dieu ": voilà toutes ses pensées.'),
('ps',10,5,'crampon1923','Ses voies sont prospères en tout temps! Tes jugements sont trop élevés pour qu''il s''en inquiète; tous ses adversaires, il les dissipe d''un souffle.'),
('ps',10,6,'crampon1923','Il dit dans son cœur: " Je ne serai pas ébranlé, je suis pour toujours à l''abri du malheur. "'),
('ps',10,7,'crampon1923','Sa bouche est pleine de malédiction, de tromperie et de violence; sous sa langue est la malice et l''iniquité.'),
('ps',10,8,'crampon1923','Il se met en embuscade près des hameaux, dans les lieux couverts il assassine l''innocent. Ses yeux épient l''homme sans défense,'),
('ps',10,9,'crampon1923','il est aux aguets dans le lieu couvert, comme un lion dans son fourré; il est aux aguets pour surprendre le pauvre, il se saisit du pauvre en le tirant dans son filet.'),
('ps',10,10,'crampon1923','Il se courbe, il se baisse, et les malheureux tombent dans ses griffes.'),
('ps',10,11,'crampon1923','Il dit dans son cœur: " Dieu a oublié! Il a couvert sa face, il ne voit jamais rien. "'),
('ps',10,12,'crampon1923','Lève-toi, Yahweh; ô Dieu, lève ta main! N''oublie pas les affligés.'),
('ps',10,13,'crampon1923','Pourquoi le méchant méprise-t-il Dieu? Pourquoi dit-il en son cœur: " Tu ne punis pas? "'),
('ps',10,14,'crampon1923','Tu as vu pourtant; car tu regardes la peine et la souffrance, pour prendre en main leur cause. A toi s''abandonne le malheureux, à l''orphelin tu viens en aide.'),
('ps',10,15,'crampon1923','Brise le bras du méchant; l''impie, — si tu cherches son crime, ne le trouveras-tu pas?'),
('ps',10,16,'crampon1923','Yahweh est roi à jamais et pour l''éternité, les nations seront exterminées de sa terre.'),
('ps',10,17,'crampon1923','Tu as entendu le désir des affligés, Yahweh; tu affermis leur cœur, tu prêtes une oreille attentive,'),
('ps',10,18,'crampon1923','pour rendre justice à l''orphelin et à l''opprimé, afin que l''homme, tiré de la terre, cesse d''inspirer l''effroi.'),
('ps',11,1,'crampon1923','Au maître de chant. De David. En Yahweh je me confie; comment dites-vous à mon âme: " Fuyez à votre montagne, comme l''oiseau.'),
('ps',11,2,'crampon1923','Car voici que les méchants bandent l''arc, ils ont ajusté leur flèche sur la corde, pour tirer dans l''ombre sur les hommes au cœur droit.'),
('ps',11,3,'crampon1923','Quand les fondements sont renversés, que peut faire le juste? "'),
('ps',11,4,'crampon1923','Yahweh dans son saint temple, Yahweh, qui a son trône dans les cieux, a les yeux ouverts; ses paupières sondent les enfants des hommes.'),
('ps',11,5,'crampon1923','Yahweh sonde le juste; il hait le méchant et celui qui se plaît à la violence.'),
('ps',11,6,'crampon1923','Il fera pleuvoir sur les méchants des lacets, du feu et du soufre; un vent brûlant, voilà la coupe qu''ils auront en partage.'),
('ps',11,7,'crampon1923','Car Yahweh est juste, il aime la justice; les hommes droits contempleront sa face.'),
('ps',12,1,'crampon1923','Au maître de chant. Sur l''octave. Chant de David.'),
('ps',12,2,'crampon1923','Sauve, Yahweh! car les hommes pieux s''en vont, les fidèles disparaissent d''entre les enfants des hommes.'),
('ps',12,3,'crampon1923','On se dit des mensonges les uns aux autres; on parle avec des lèvres flatteuses et un cœur double.'),
('ps',12,4,'crampon1923','Que Yahweh retranche toutes les lèvres flatteuses, la langue qui discourt avec jactance,'),
('ps',12,5,'crampon1923','ceux qui disent: " Par notre langue nous sommes forts; nous avons avec nous nos lèvres: qui serait notre maître? "'),
('ps',12,6,'crampon1923','" A cause de l''oppression des affligés, du gémissement des pauvres, je veux maintenant me lever, dit Yahweh; je leur apporterai le salut après lequel ils soupirent. "'),
('ps',12,7,'crampon1923','Les paroles de Yahweh sont des paroles pures, un argent fondu dans un creuset sur la terre, sept fois purifié.'),
('ps',12,8,'crampon1923','Toi, Yahweh, tu les garderas; tu les préserveras à jamais de cette génération.'),
('ps',12,9,'crampon1923','Autour d''eux les méchants se promènent avec arrogance: autant ils s''élèvent, autant seront humiliés les enfants des hommes.'),
('ps',13,1,'crampon1923','Au maître de chant. Chant de David.'),
('ps',13,2,'crampon1923','Jusques à quand, Yahweh, m''oublieras-tu toujours? Jusques à quand me cacheras-tu ta face?'),
('ps',13,3,'crampon1923','Jusques à quand formerai-je en mon âme des projets, et chaque jour le chagrin remplira-t-il mon cœur? Jusques à quand mon ennemi s''élèvera-t-il contre moi?'),
('ps',13,4,'crampon1923','Regarde, réponds-moi, Yahweh, mon Dieu! Donne la lumière à mes yeux, afin que je ne m''endorme pas dans la mort,'),
('ps',13,5,'crampon1923','afin que mon ennemi ne dise pas: " Je l''ai vaincu! " et que mes adversaires ne se réjouissent pas en me voyant chanceler.'),
('ps',13,6,'crampon1923','Moi, j''ai confiance en ta bonté; mon cœur tressaillira à cause de ton salut, je chanterai Yahweh pour le bien qu''il m''a fait.'),
('ps',14,1,'crampon1923','Au maître de chant. De David. L''insensé dit dans son cœur: " Il n''y a point de Dieu!... " Ils sont corrompus, ils commettent des actions abominables; il n''en est aucun qui fasse le bien.'),
('ps',14,2,'crampon1923','Yahweh, du haut des cieux regarde les fils de l''homme, pour voir s''il est quelqu''un de sage, quelqu''un qui cherche Dieu.'),
('ps',14,3,'crampon1923','Tous sont égarés, tous ensemble sont pervertis; il n''en est pas un qui fasse le bien, pas un seul!'),
('ps',14,4,'crampon1923','N''ont-ils pas de connaissance, tous ceux qui commettent l''iniquité? Ils dévorent mon peuple, comme ils mangent du pain; ils n''invoquent point Yahweh.'),
('ps',14,5,'crampon1923','Ils trembleront tout à coup d''épouvante, car Dieu est au milieu de la race juste.'),
('ps',14,6,'crampon1923','Vous voulez confondre les projets du malheureux! Mais Yahweh est son refuge.'),
('ps',14,7,'crampon1923','Oh! puisse venir de Sion la délivrance d''Israël! Quand Yahweh ramènera les captifs de son peuple, Jacob sera dans la joie, Israël dans l''allégresse.'),
('ps',15,1,'crampon1923','Psaume de David. Yahweh, qui habitera dans ta tente? Qui demeurera sur ta montagne sainte?'),
('ps',15,2,'crampon1923','Celui qui marche dans l''innocence, qui pratique la justice, et qui dit la vérité dans son cœur.'),
('ps',15,3,'crampon1923','Il ne calomnie point avec sa langue, il ne fait point de mal à son frère, et ne jette point l''opprobre sur son prochain.'),
('ps',15,4,'crampon1923','A ses yeux le réprouvé est digne de honte, mais il honore ceux qui craignent Yahweh. S''il a fait un serment à son préjudice, il n''y change rien,'),
('ps',15,5,'crampon1923','Il ne prête point son argent à usure, et il n''accepte pas de présent contre l''innocent: Celui qui se conduit ainsi ne chancellera jamais.'),
('ps',16,1,'crampon1923','Hymne de David. Garde-moi ô Dieu, car près de toi je me réfugie.'),
('ps',16,2,'crampon1923','Je dis à Yahweh: " Tu es mon Seigneur, toi seul es mon bien. "'),
('ps',16,3,'crampon1923','Les saints qui sont dans le pays, ces illustres, sont l''objet de toute mon affection.'),
('ps',16,4,'crampon1923','On multiplie les idoles, on court après les dieux étrangers; je ne répandrai point leurs libations de sang, je ne mettrai pas leurs noms sur mes lèvres.'),
('ps',16,5,'crampon1923','Yahweh est la part de mon héritage et de ma coupe, c''est toi qui m''assures mon lot.'),
('ps',16,6,'crampon1923','Le cordeau a mesuré pour moi une portion délicieuse; oui, un splendide héritage m''est échu.'),
('ps',16,7,'crampon1923','Je bénis Yahweh qui m''a conseillé; la nuit même, mes reins m''avertissent.'),
('ps',16,8,'crampon1923','Je mets Yahweh constamment sous mes yeux, car il est à ma droite: je ne chancellerai point.'),
('ps',16,9,'crampon1923','Aussi mon cœur est dans la joie, mon âme dans l''allégresse, mon corps lui-même repose en sécurité.'),
('ps',16,10,'crampon1923','Car tu ne livreras pas mon âme au schéol, tu ne permettras pas que celui qui t''aime voie la corruption.'),
('ps',16,11,'crampon1923','Tu me feras connaître le sentier de la vie; il y a plénitude de joie devant ta face, des délices éternelles dans ta droite.'),
('ps',17,1,'crampon1923','Prière de David. Yahweh, entends la justice, écoute mon cri; prête l''oreille à ma prière, qui n''est pas proférée par des lèvres trompeuses.'),
('ps',17,2,'crampon1923','Que mon jugement sorte de ta face, que tes yeux regardent l''équité!'),
('ps',17,3,'crampon1923','Tu as éprouvé mon cœur, tu l''as visité la nuit, tu m''as mis dans le creuset: tu ne trouves rien. Avec ma pensée ma bouche n''est pas en désaccord.'),
('ps',17,4,'crampon1923','Quant aux actions de l''homme, fidèle à la parole de tes lèvres, j''ai pris garde aux voies des violents.'),
('ps',17,5,'crampon1923','Mes pas se sont attachés à tes sentiers, et mes pieds n''ont pas chancelé.'),
('ps',17,6,'crampon1923','Je t''invoque, car tu m''exauces, ô Dieu; incline vers moi ton oreille, écoute ma prière.'),
('ps',17,7,'crampon1923','Signale ta bonté, toi qui sauves ceux qui se réfugient dans ta droite contre leurs adversaires.'),
('ps',17,8,'crampon1923','Garde-moi comme la prunelle de l''œil; à l''ombre de tes ailes mets-moi à couvert;'),
('ps',17,9,'crampon1923','des impies qui me persécutent, des ennemis mortels qui m''entourent.'),
('ps',17,10,'crampon1923','Ils ferment leurs entrailles à la pitié, ils ont à la bouche des paroles hautaines.'),
('ps',17,11,'crampon1923','Ils sont sur nos pas, ils nous entourent, ils nous épient pour nous renverser par terre.'),
('ps',17,12,'crampon1923','Ils ressemblent au lion avide de dévorer, au lionceau campé dans son fourré.'),
('ps',17,13,'crampon1923','Lève-toi, Yahweh, marche à sa rencontre, terrasse-le, délivre mon âme du méchant par ton glaive,'),
('ps',17,14,'crampon1923','des hommes par ta main, de ces hommes du siècle dont la part est dans la vie présente, dont tu remplis le ventre de tes trésors, qui sont rassasiés de fils, et laissent leur superflu à leurs petits-fils.'),
('ps',17,15,'crampon1923','Pour moi, dans mon innocence je contemplerai ta face; à mon réveil, je me rassasierai de ton image.'),
('ps',18,1,'crampon1923','Au maître de chant. Psaume du serviteur de Yahweh, de David, qui adressa à Yahweh les paroles de ce cantique, au jour où Yahweh l''eut délivré de la main de tous ses ennemis et de la main de Saül.'),
('ps',18,2,'crampon1923','Il dit: Je t''aime, Yahweh, ma force!'),
('ps',18,3,'crampon1923','Yahweh mon rocher, ma forteresse, mon libérateur, mon Dieu, mon roc où je trouve un asile, mon bouclier, la corne de mon salut, ma citadelle!'),
('ps',18,4,'crampon1923','J''invoquai celui qui est digne de louange, Yahweh, et je fus délivré de mes ennemis.'),
('ps',18,5,'crampon1923','Les liens de la mort m''environnaient, les torrents de Bélial m''épouvantaient,'),
('ps',18,6,'crampon1923','les liens du schéol m''enlaçaient, les filets de la mort étaient tombés devant moi.'),
('ps',18,7,'crampon1923','Dans ma détresse, j''invoquai Yahweh, et je criai vers mon Dieu; de son temple il entendit ma voix, et mon cri devant lui parvint à ses oreilles.'),
('ps',18,8,'crampon1923','La terre fut ébranlée et trembla, les fondements des montagnes s''agitèrent, et ils furent ébranlés, parce qu''il était courroucé;'),
('ps',18,9,'crampon1923','une fumée montait de ses narines, et un feu dévorant sortait de sa bouche; il en jaillissait des charbons embrasés.'),
('ps',18,10,'crampon1923','il abaissa les cieux, et descendit; une sombre nuée était sous ses pieds.'),
('ps',18,11,'crampon1923','Il monta sur un Chérubin, et il volait; il planait sur les ailes du vent.'),
('ps',18,12,'crampon1923','Il fit des ténèbres sa retraite, sa tente autour de lui c''étaient des eaux obscures et de sombres nuages.'),
('ps',18,13,'crampon1923','De l''éclat qui le précédait s''élancèrent ses nuées, portant la grêle et les charbons ardents.'),
('ps',18,14,'crampon1923','Yahweh tonna dans les cieux, le Très-Haut fit retentir sa voix: grêle et charbons ardents!'),
('ps',18,15,'crampon1923','Il lança ses flèches et les dispersa; il multiplia ses foudres et il les confondit.'),
('ps',18,16,'crampon1923','Alors le lit des eaux apparut, les fondements de la terre furent mis à nu, à ta menace, Yahweh, au souffle du vent de tes narines.'),
('ps',18,17,'crampon1923','Il étendit sa main d''en haut et me saisit, il me retira des grandes eaux.'),
('ps',18,18,'crampon1923','Il me délivra de mon ennemi puissant, de ceux qui me haïssaient, alors qu''ils étaient plus forts que moi.'),
('ps',18,19,'crampon1923','Ils m''avaient surpris au jour de mon malheur; mais Yahweh fut mon appui.'),
('ps',18,20,'crampon1923','Il m''a mis au large, il m''a sauvé, parce qu''il s''est complu en moi.'),
('ps',18,21,'crampon1923','Yahweh m''a récompensé selon ma justice, il m''a rendu selon la pureté de mes mains.'),
('ps',18,22,'crampon1923','Car j''ai gardé les voies de Yahweh, et je n''ai pas péché, pour m''éloigner de mon Dieu.'),
('ps',18,23,'crampon1923','Tous ses jugements étaient devant moi, et je n''ai point rejeté loin de moi ses lois.'),
('ps',18,24,'crampon1923','J''étais sans reproche envers lui, et je me tenais en garde contre mon iniquité.'),
('ps',18,25,'crampon1923','Yahweh m''a rendu selon ma justice, selon la pureté de mes mains devant ses yeux.'),
('ps',18,26,'crampon1923','Avec celui qui est bon tu te montres bon, avec l''homme droit tu te montres droit;'),
('ps',18,27,'crampon1923','avec celui qui est pur tu te montres pur, et avec le fourbe tu agis perfidement.'),
('ps',18,28,'crampon1923','Car tu sauves le peuple humilié, et tu abaisses les regards hautains.'),
('ps',18,29,'crampon1923','Oui, tu fais briller mon flambeau; Yahweh, mon Dieu, éclaire mes ténèbres.'),
('ps',18,30,'crampon1923','Avec toi je me précipite sur les bataillons armés; avec mon Dieu je franchis les murailles.'),
('ps',18,31,'crampon1923','Dieu!... Ses voies sont parfaites; la parole de Yahweh est éprouvée, il est un bouclier pour tous ceux qui se confient en lui.'),
('ps',18,32,'crampon1923','Car qui est Dieu, si ce n''est Yahweh, et qui est un rocher, si ce n''est notre Dieu?'),
('ps',18,33,'crampon1923','Le Dieu qui me ceint de force, qui rend ma voie parfaite;'),
('ps',18,34,'crampon1923','qui rend mes pieds semblables à ceux des biches, et me fait tenir debout sur mes hauteurs;'),
('ps',18,35,'crampon1923','qui forme mes mains au combat, et mes bras tendent l''arc d''airain.'),
('ps',18,36,'crampon1923','Tu m''as donné le bouclier de ton salut, et ta droite me soutient, et ta douceur me fait grandir.'),
('ps',18,37,'crampon1923','Tu élargis mon pas au-dessous de moi, et mes pieds ne chancellent point.'),
('ps',18,38,'crampon1923','Je poursuis mes ennemis et je les atteins; je ne reviens pas sans les avoir anéantis.'),
('ps',18,39,'crampon1923','Je les brise, et ils ne se relèvent pas; Ils tombent sous mes pieds.'),
('ps',18,40,'crampon1923','Tu me ceins de force pour le combat, tu fais plier sous moi mes adversaires.'),
('ps',18,41,'crampon1923','Mes ennemis!... tu leur fais tourner le dos devant moi, et j''extermine ceux qui me haïssent.'),
('ps',18,42,'crampon1923','Ils crient, et personne pour les sauver! Ils crient vers Yahweh, et il ne leur répond pas!'),
('ps',18,43,'crampon1923','Je les broie comme la poussière livrée au vent, je les balaie comme la boue des rues.'),
('ps',18,44,'crampon1923','Tu me délivres des révoltes du peuple, tu me mets à la tête des nations; Des peuples que je ne connaissais pas me sont asservis.'),
('ps',18,45,'crampon1923','Dès qu''ils ont entendu, ils m''obéissent; les fils de l''étranger me flattent.'),
('ps',18,46,'crampon1923','Les fils de l''étranger sont défaillants, ils sortent tremblants de leurs forteresses.'),
('ps',18,47,'crampon1923','Vive Yahweh et béni soit mon rocher! Que le Dieu de mon salut soit exalté;'),
('ps',18,48,'crampon1923','Dieu qui m''accorde des vengeances, qui me soumet les peuples,'),
('ps',18,49,'crampon1923','qui me délivre de mes ennemis! Oui, tu m''élèves au-dessus de mes adversaires, tu me sauves de l''homme de violence.'),
('ps',18,50,'crampon1923','C''est pourquoi je te louerai parmi les nations, ô Yahweh; je chanterai à la gloire de ton nom:'),
('ps',18,51,'crampon1923','Il accorde de glorieuses délivrances à son roi, il fait miséricorde à son oint, à David et à sa postérité pour toujours.'),
('ps',19,1,'crampon1923','Au maître de chant. Chant de David.'),
('ps',19,2,'crampon1923','Les cieux racontent la gloire de Dieu, et le firmament annonce l''œuvre de ses mains.'),
('ps',19,3,'crampon1923','Le jour crie au jour la louange, la nuit l''apprend à la nuit.'),
('ps',19,4,'crampon1923','Ce n''est pas un langage, ce ne sont pas des paroles; dont la voix ne soit pas entendue.'),
('ps',19,5,'crampon1923','Leur son parcourt toute la terre, leurs accents vont jusqu''aux extrémités du monde. C''est là qu''il a dressé une tente pour le soleil.'),
('ps',19,6,'crampon1923','Et lui, semblable à l''époux qui sort de la chambre nuptiale, s''élance joyeux, comme un héros, pour fournir sa carrière.'),
('ps',19,7,'crampon1923','Il part d''une extrémité du ciel, et sa course s''achève à l''autre extrémité: rien ne se dérobe à sa chaleur.'),
('ps',19,8,'crampon1923','La loi de Yahweh est parfaite: elle restaure l''âme. Le témoignage de Yahweh est sur: il donne la sagesse aux simples.'),
('ps',19,9,'crampon1923','Les ordonnances de Yahweh sont droites: elles réjouissent les cœurs. Le précepte de Yahweh est pur: il éclaire les yeux.'),
('ps',19,10,'crampon1923','La crainte de Yahweh est sainte: elle subsiste à jamais. Les décrets de Yahweh sont vrais: ils sont tous justes.'),
('ps',19,11,'crampon1923','Ils sont plus précieux que l''or, que beaucoup d''or fin; plus doux que le miel, que celui qui coule des rayons.'),
('ps',19,12,'crampon1923','Ton serviteur aussi est éclairé par eux; grande récompense à qui les observe.'),
('ps',19,13,'crampon1923','Qui connaît ses égarements? Pardonne-moi ceux que j''ignore!'),
('ps',19,14,'crampon1923','Préserve aussi ton serviteur des orgueilleux; qu''ils ne dominent point sur moi! Alors je serai parfait et je serai pur de grands péchés.'),
('ps',19,15,'crampon1923','Accueille avec faveur les paroles de ma bouche, et les sentiments de mon cœur, devant toi, Yahweh, mon rocher et mon libérateur!'),
('ps',20,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',20,2,'crampon1923','Que Yahweh t''exauce au jour de la détresse, que le nom du Dieu de Jacob te protège!'),
('ps',20,3,'crampon1923','Que du sanctuaire il t''envoie du secours, que de Sion il te soutienne!'),
('ps',20,4,'crampon1923','Qu''il se souvienne de toutes tes oblations, et qu''il ait pour agréable tes holocaustes! — Séla.'),
('ps',20,5,'crampon1923','Qu''il te donne ce que ton cœur désire, et qu''il accomplisse tous tes desseins!'),
('ps',20,6,'crampon1923','Puissions-nous de nos cris joyeux saluer ta victoire, lever l''étendard au nom de notre Dieu! Que Yahweh accomplisse tous tes vœux!'),
('ps',20,7,'crampon1923','Déjà je sais que Yahweh a sauvé son Oint; il l''exaucera des cieux, sa sainte demeure, par le secours puissant de sa droite.'),
('ps',20,8,'crampon1923','Ceux-ci comptent sur leurs chars, ceux-là sur leurs chevaux; nous, nous invoquons le nom de Yahweh, notre Dieu.'),
('ps',20,9,'crampon1923','Eux, ils plient et ils tombent; nous, nous nous relevons et tenons ferme.'),
('ps',20,10,'crampon1923','Yahweh, sauve le roi! — Qu''il nous exauce au jour où nous l''invoquons.'),
('ps',21,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',21,2,'crampon1923','Yahweh, le roi se réjouit de ta force; comme ton secours le remplit d''allégresse!'),
('ps',21,3,'crampon1923','Tu lui as donné ce que son cœur désirait, tu n''as pas refusé ce que demandaient ses lèvres. — Séla.'),
('ps',21,4,'crampon1923','Car tu l''as prévenu de bénédictions exquises, tu as mis sur sa tête une couronne d''or pur.'),
('ps',21,5,'crampon1923','Il te demandait la vie, tu la lui as donnée, de longs jours à jamais et à perpétuité.'),
('ps',21,6,'crampon1923','Sa gloire est grande, grâce à ton secours; tu mets sur lui splendeur et magnificence.'),
('ps',21,7,'crampon1923','Tu le rends à jamais un objet de bénédictions; tu le combles de joie devant ta face.'),
('ps',21,8,'crampon1923','Car le roi se confie en Yahweh, et par la bonté du Très-Haut il ne chancelle point.'),
('ps',21,9,'crampon1923','Ta main, ô roi, atteindra tous tes ennemis, ta droite atteindra ceux qui te haïssent.'),
('ps',21,10,'crampon1923','Tu les rendras comme une fournaise ardente, au jour où tu montreras ta face; Yahweh les anéantira dans sa colère, et le feu les dévorera.'),
('ps',21,11,'crampon1923','Tu feras disparaître de la terre leur postérité, et leur race d''entre les enfants des hommes.'),
('ps',21,12,'crampon1923','Ils ont préparé pour toi la ruine, ils ont conçu des desseins pervers, mais ils seront impuissants.'),
('ps',21,13,'crampon1923','Car tu leur feras tourner le dos; de tes traits tu les viseras au front.'),
('ps',21,14,'crampon1923','Lève-toi, Yahweh, dans ta force! Nous voulons chanter et célébrer ta puissance.'),
('ps',22,1,'crampon1923','Au maître de chant. Sur " Biche de l''aurore ". Psaume de David.'),
('ps',22,2,'crampon1923','Mon Dieu, mon Dieu, pourquoi m''as-tu abandonné? Je gémis, et le salut reste loin de moi!'),
('ps',22,3,'crampon1923','Mon Dieu, je crie pendant le jour, et tu ne réponds pas; la nuit, et je n''ai point de repos.'),
('ps',22,4,'crampon1923','Pourtant tu es saint, tu habites parmi les hymnes d''Israël.'),
('ps',22,5,'crampon1923','En toi se sont confiés nos pères; ils se sont confiés, et tu les as délivrés.'),
('ps',22,6,'crampon1923','Ils ont crié vers toi, et ils ont été sauvés; ils se sont confiés en toi, et ils n''ont pas été confus.'),
('ps',22,7,'crampon1923','Et moi, je suis un ver, et non un homme, l''opprobre des hommes et le rebut du peuple.'),
('ps',22,8,'crampon1923','Tous ceux qui me voient se moquent de moi; ils ouvrent les lèvres, ils branlent la tête:'),
('ps',22,9,'crampon1923','" Qu''il s''abandonne à Yahweh! Qu''il le sauve, qu''il le délivre, puisqu''il l''aime! "'),
('ps',22,10,'crampon1923','Oui, c''est toi qui m''as tiré du sein maternel, qui m''as donné confiance sur les mamelles de ma mère.'),
('ps',22,11,'crampon1923','Dès ma naissance, je t''ai été abandonné; depuis le sein de ma mère, c''est toi qui es mon Dieu.'),
('ps',22,12,'crampon1923','Ne t''éloigne pas de moi, car l''angoisse est proche, car personne ne vient à mon secours.'),
('ps',22,13,'crampon1923','Autour de moi sont de nombreux taureaux, les forts de Basan m''environnent.'),
('ps',22,14,'crampon1923','Ils ouvrent contre moi leur gueule, comme un lion qui déchire et rugit.'),
('ps',22,15,'crampon1923','Je suis comme de l''eau qui s''écoule, et tous mes os sont disjoints; mon cœur est comme de la cire, il se fond dans mes entrailles.'),
('ps',22,16,'crampon1923','Ma force s''est desséchée comme un tesson d''argile, et ma langue s''attache à mon palais; tu me couches dans la poussière de la mort.'),
('ps',22,17,'crampon1923','Car des chiens m''environnent, une troupe de scélérats rôdent autour de moi; ils ont percé mes pieds et mes mains,'),
('ps',22,18,'crampon1923','je pourrais compter tous mes os. Eux, ils m''observent, ils me contemplent;'),
('ps',22,19,'crampon1923','ils se partagent mes vêtements, ils tirent au sort ma tunique.'),
('ps',22,20,'crampon1923','Et toi, Yahweh, ne t''éloigne pas! Toi qui es ma force, viens en hâte à mon secours!'),
('ps',22,21,'crampon1923','Délivre mon âme de l''épée, ma vie du pouvoir du chien!'),
('ps',22,22,'crampon1923','Sauve-moi de la gueule du lion, tire-moi des cornes du buffle!'),
('ps',22,23,'crampon1923','Alors j''annoncerai ton nom à mes frères, au milieu de l''assemblée je te louerai:'),
('ps',22,24,'crampon1923','" Vous qui craignez Yahweh, louez-le! Vous tous, postérité de Jacob, glorifiez-le! Révérez-le, vous tous, postérité d''Israël!'),
('ps',22,25,'crampon1923','Car il n''a pas méprisé, il n''a pas rejeté la souffrance de l''affligé, il n''a pas caché sa face devant lui, et quand l''affligé a crié vers lui, il a entendu. "'),
('ps',22,26,'crampon1923','Grâce à toi, mon hymne retentira dans la grande assemblée, j''acquitterai mes vœux en présence de ceux qui te craignent.'),
('ps',22,27,'crampon1923','Les affligés mangeront et se rassasieront; ceux qui cherchent Yahweh le loueront. Que votre cœur revive à jamais!'),
('ps',22,28,'crampon1923','Toutes les extrémités de la terre se souviendront et se tourneront vers Yahweh, et toutes les familles des nations se prosterneront devant sa face.'),
('ps',22,29,'crampon1923','Car à Yahweh appartient l''empire, il domine sur les nations.'),
('ps',22,30,'crampon1923','Les puissants de la terre mangeront et se prosterneront; devant lui s''inclineront tous ceux qui descendent à la poussière, ceux qui ne peuvent prolonger leur vie.'),
('ps',22,31,'crampon1923','La postérité le servira; on parlera du Seigneur à la génération future.'),
('ps',22,32,'crampon1923','Ils viendront et ils annonceront sa justice, au peuple qui naîtra, ils diront ce qu''il a fait.'),
('ps',23,1,'crampon1923','Psaume de David. Yahweh est mon pasteur; je ne manquerai de rien.'),
('ps',23,2,'crampon1923','Il me fait reposer dans de verts pâturages, il me mène près des eaux rafraîchissantes;'),
('ps',23,3,'crampon1923','il restaure mon âme. Il me conduit dans les droits sentiers, à cause de son nom.'),
('ps',23,4,'crampon1923','Même quand je marche dans une vallée d''ombre mortelle, je ne crains aucun mal, car tu es avec moi: ta houlette et ton bâton me rassurent.'),
('ps',23,5,'crampon1923','Tu dresses devant moi une table en face de mes ennemis; tu répands l''huile sur ma tête; ma coupe est débordante.'),
('ps',23,6,'crampon1923','Oui, le bonheur et la grâce m''accompagneront, tous les jours de ma vie, et j''habiterai dans la maison de Yahweh, pour de longs jours.'),
('ps',24,1,'crampon1923','Psaume de David. A Yahweh est la terre et ce qu''elle renferme, le monde et tous ceux qui l''habitent.'),
('ps',24,2,'crampon1923','Car c''est lui qui l''a fondée sur les mers, qui l''a affermie sur les fleuves.'),
('ps',24,3,'crampon1923','Qui montera à la montagne de Yahweh? qui se tiendra dans son lieu saint? —'),
('ps',24,4,'crampon1923','Celui qui a les mains innocentes et le cœur pur; celui qui ne livre pas son âme au mensonge, et qui ne jure pas pour tromper.'),
('ps',24,5,'crampon1923','Il obtiendra la bénédiction de Yahweh, la justice du Dieu de son salut.'),
('ps',24,6,'crampon1923','Telle est la race de ceux qui le cherchent, de ceux qui cherchent la face du Dieu de Jacob. — Séla.'),
('ps',24,7,'crampon1923','Portes, élevez vos linteaux; élevez-vous, portes antiques: que le Roi de gloire fasse son entrée! —'),
('ps',24,8,'crampon1923','Quel est ce Roi de gloire? — Yahweh fort et puissant, Yahweh puissant dans les combats.'),
('ps',24,9,'crampon1923','Portes, élevez vos linteaux; élevez-vous, portes antiques: que le Roi de gloire fasse son entrée! —'),
('ps',24,10,'crampon1923','Quel est ce Roi de gloire? — Yahweh des armées, voilà le Roi de gloire! — Séla.'),
('ps',25,1,'crampon1923','Psaume de David. ALEPH. Vers toi, Yahweh, j''élève mon âme, mon Dieu.'),
('ps',25,2,'crampon1923','BETH. En toi je me confie: que je n''aie pas de confusion! Que mes ennemis ne se réjouissent pas à mon sujet!'),
('ps',25,3,'crampon1923','GHIMEL. Non, aucun de ceux qui espèrent en toi ne sera confondu; ceux là seront confondus qui sont infidèles sans cause.'),
('ps',25,4,'crampon1923','DALETH. Yahweh, fais-moi connaître tes voies, enseigne-moi tes sentiers.'),
('ps',25,5,'crampon1923','HÉ. Conduis-moi dans ta vérité, VAV. et instruis-moi, car tu es le Dieu de mon salut; tout le jour en toi j''espère.'),
('ps',25,6,'crampon1923','ZAÏN. Souviens-toi de ta miséricorde, Yahweh, et de ta bonté car elles sont éternelles.'),
('ps',25,7,'crampon1923','HETH. Ne te souviens pas des péchés de ma jeunesse ni de mes transgressions; souviens-toi de moi selon ta miséricorde, à cause de ta bonté, ô Yahweh,'),
('ps',25,8,'crampon1923','TETH. Yahweh est bon et droit; c''est pourquoi il indique aux pécheurs la voie.'),
('ps',25,9,'crampon1923','YOD. Il fait marcher les humbles dans la justice, il enseigne aux humbles sa voie.'),
('ps',25,10,'crampon1923','CAPH. Tous les sentiers de Yahweh sont miséricorde et fidélité, pour ceux qui gardent son alliance et ses commandements.'),
('ps',25,11,'crampon1923','LAMED. A cause de ton nom, Yahweh, tu pardonneras mon iniquité, car elle est grande.'),
('ps',25,12,'crampon1923','MEM. Quel est l''homme qui craint Yahweh? Yahweh lui montre la voie qu''il doit choisir.'),
('ps',25,13,'crampon1923','NUN. Son âme repose dans le bonheur, et sa postérité possédera le pays.'),
('ps',25,14,'crampon1923','SAMECH. La familiarité de Yahweh est pour ceux qui le craignent; il leur fait connaître les bénédictions de son alliance.'),
('ps',25,15,'crampon1923','AÏN. J''ai les yeux constamment tournés vers Yahweh, car c''est lui qui tirera mes pieds du lacet.'),
('ps',25,16,'crampon1923','PHÉ. Regarde-moi et prends pitié de moi, car je suis délaissé et malheureux.'),
('ps',25,17,'crampon1923','TSADÉ. Les angoisses de mon cœur se sont accrues: tire-moi de ma détresse!'),
('ps',25,18,'crampon1923','Vois ma misère et ma peine, et pardonne tous mes péchés.'),
('ps',25,19,'crampon1923','RESCH. Vois combien sont nombreux mes ennemis, et quelle haine violente ils ont contre moi!'),
('ps',25,20,'crampon1923','SCHIN. Garde mon âme et sauve-moi! Que je ne sois pas confus, car j''ai mis en toi ma confiance!'),
('ps',25,21,'crampon1923','THAV. Que l''innocence et la droiture me protègent, car j''espère en toi.'),
('ps',25,22,'crampon1923','O Dieu, délivre Israël de toutes ses angoisses!'),
('ps',26,1,'crampon1923','De David. Rends-moi justice, Yahweh, car j''ai marché dans mon innocence; je me confie en Yahweh, je ne chancellerai pas.'),
('ps',26,2,'crampon1923','Eprouve-moi, Yahweh, sonde-moi, fais passer au creuset mes reins et mon cœur:'),
('ps',26,3,'crampon1923','car ta miséricorde est devant mes yeux, et je marche dans ta vérité.'),
('ps',26,4,'crampon1923','Je ne me suis pas assis avec les hommes de mensonge, je ne vais pas avec les hommes dissimulés;'),
('ps',26,5,'crampon1923','Je hais l''assemblée de ceux qui font le mal, je ne siège pas avec les méchants.'),
('ps',26,6,'crampon1923','Je lave mes mains dans l''innocence, et j''entoure ton autel, Yahweh,'),
('ps',26,7,'crampon1923','pour faire entendre une voix de louange; et raconter toutes tes merveilles.'),
('ps',26,8,'crampon1923','Yahweh, j''aime le séjour de ta maison, le lieu où ta gloire réside.'),
('ps',26,9,'crampon1923','N''enlève pas mon âme avec celle des pécheurs, ma vie avec celle des hommes de sang,'),
('ps',26,10,'crampon1923','qui ont le crime dans les mains, et dont la droite est pleine de présents.'),
('ps',26,11,'crampon1923','Pour moi, je marche en mon innocence: délivre-moi et aie pitié de moi!'),
('ps',26,12,'crampon1923','Mon pied se tient sur un sol uni: je bénirai Yahweh dans les assemblées.'),
('ps',27,1,'crampon1923','De David. Yahweh est ma lumière et mon salut: qui craindrais-je? Yahweh est le rempart de ma vie: de qui aurais-je peur?'),
('ps',27,2,'crampon1923','Quand des méchants se sont avancés contre moi, pour dévorer ma chair; quand mes adversaires et mes ennemis se sont avancés, ce sont eux qui ont chancelé et qui sont tombés.'),
('ps',27,3,'crampon1923','Qu''une armée vienne camper contre moi, mon cœur ne craindra point; que contre moi s''engage le combat, alors même j''aurai confiance.'),
('ps',27,4,'crampon1923','Je demande à Yahweh une chose, je la désire ardemment: je voudrais habiter dans la maison de Yahweh, tous les jours de ma vie, pour jouir des amabilités de Yahweh, pour contempler son sanctuaire.'),
('ps',27,5,'crampon1923','Car il m''abritera dans sa demeure au jour de l''adversité, il me cachera dans le secret de sa tente, il m''établira sur un rocher.'),
('ps',27,6,'crampon1923','Alors ma tête s''élèvera au-dessus des ennemis; qui sont autour de moi. J''offrirai dans son tabernacle des sacrifices d''actions de grâces, je chanterai et je dirai des hymnes à Yahweh.'),
('ps',27,7,'crampon1923','Yahweh, écoute ma voix, je t''invoque; aie pitié de moi et exauce-moi!'),
('ps',27,8,'crampon1923','Mon cœur dit de ta part: " Cherchez ma face "; je cherche ta face, Yahweh.'),
('ps',27,9,'crampon1923','Ne me cache pas ta face, ne repousse pas avec colère ton serviteur; tu es mon secours, ne me délaisse pas, et ne m''abandonne pas, Dieu de mon salut!')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ps',27,10,'crampon1923','Car mon père et ma mère m''ont abandonné, mais Yahweh me recueillera.'),
('ps',27,11,'crampon1923','Seigneur, enseigne-moi ta voie; dirige-moi dans un sentier uni, à cause de ceux qui m''épient.'),
('ps',27,12,'crampon1923','Ne me livre pas à la fureur de mes adversaires, car contre moi s''élèvent des témoins de mensonge, et des gens qui ne respirent que violence.'),
('ps',27,13,'crampon1923','Ah! si je ne croyais pas voir la bonté de Yahweh, dans la terre des vivants...'),
('ps',27,14,'crampon1923','Espère en Yahweh! Aie courage et que ton cœur soit ferme! Espère en Yahweh!'),
('ps',28,1,'crampon1923','De David. C''est vers toi, Yahweh, que je crie; mon rocher, ne reste pas sourd à ma voix, de peur que, si tu gardes le silence, je ne ressemble à ceux qui descendent dans la fosse.'),
('ps',28,2,'crampon1923','Ecoute la voix de mes supplications, quand je crie vers toi, quand j''élève mes mains vers ton saint sanctuaire.'),
('ps',28,3,'crampon1923','Ne m''emporte pas avec les méchants et les artisans d''iniquité, qui parlent de paix à leur prochain, et qui ont la malice dans le cœur.'),
('ps',28,4,'crampon1923','Rends-leur selon leurs œuvres, et selon la malice de leurs actions; rends-leur selon l''ouvrage de leurs mains, donne-leur le salaire qu''ils méritent.'),
('ps',28,5,'crampon1923','Car ils ne prennent pas garde aux œuvres de Yahweh, à l''ouvrage de ses mains: il les détruira et ne les bâtira pas.'),
('ps',28,6,'crampon1923','Béni soit Yahweh, car il a entendu la voix de mes supplications!'),
('ps',28,7,'crampon1923','Yahweh est ma force et mon bouclier; en lui s''est confié mon cœur. J''ai été secouru; aussi mon cœur est dans l''allégresse, et je le louerai par mes cantiques.'),
('ps',28,8,'crampon1923','Yahweh est la force de son peuple, il est une forteresse de salut pour son Oint.'),
('ps',28,9,'crampon1923','Sauve ton peuple et bénis ton héritage! Sois leur pasteur et porte-les à jamais!'),
('ps',29,1,'crampon1923','Psaume de David. Donnez à Yahweh, fils de Dieu, donnez à Yahweh gloire et puissance!'),
('ps',29,2,'crampon1923','Donnez à Yahweh la gloire de son nom! Adorez Yahweh dans de saints ornements.'),
('ps',29,3,'crampon1923','La voix de Yahweh gronde au-dessus des eaux, le Dieu de la gloire tonne, Yahweh est sur les grandes eaux.'),
('ps',29,4,'crampon1923','La voix de Yahweh est puissante, la voix de Yahweh est majestueuse.'),
('ps',29,5,'crampon1923','La voix de Yahweh brise les cèdres, Yahweh brise les cèdres du Liban;'),
('ps',29,6,'crampon1923','il les fait bondir comme un jeune taureau, le Liban et le Sirion comme le petit du buffle.'),
('ps',29,7,'crampon1923','La voix de Yahweh fait jaillir des flammes de feu,'),
('ps',29,8,'crampon1923','la voix de Yahweh ébranle le désert, Yahweh ébranle le désert de Cadès.'),
('ps',29,9,'crampon1923','La voix de Yahweh fait enfanter les biches, elle dépouille les forêts de leur feuillage, et dans son temple tout dit: " Gloire! "'),
('ps',29,10,'crampon1923','Yahweh, au déluge, est assis sur son trône, Yahweh siège sur son trône, roi pour l''éternité.'),
('ps',29,11,'crampon1923','Yahweh donnera la force à son peuple; Yahweh bénira son peuple en lui donnant la paix.'),
('ps',30,1,'crampon1923','Psaume. Cantique pour la dédicace de la maison. De David.'),
('ps',30,2,'crampon1923','Je t''exalte, Yahweh, car tu m''as relevé, tu n''as pas réjoui mes ennemis à mon sujet.'),
('ps',30,3,'crampon1923','Yahweh, mon Dieu, j''ai crié vers toi, et tu m''as guéri.'),
('ps',30,4,'crampon1923','Yahweh, tu as fait remonter mon âme du schéol, tu m''as rendu la vie, loin de ceux qui descendent dans la fosse.'),
('ps',30,5,'crampon1923','Chantez Yahweh, vous ses fidèles, célébrez son saint souvenir!'),
('ps',30,6,'crampon1923','Car sa colère dure un instant, mais sa grâce toute la vie; le soir viennent les pleurs, et le matin l''allégresse.'),
('ps',30,7,'crampon1923','Je disais dans ma sécurité: " Je ne serai jamais ébranlé! "'),
('ps',30,8,'crampon1923','Yahweh, par ta grâce, tu avais affermi ma montagne; — tu as caché ta face, et j''ai été troublé.'),
('ps',30,9,'crampon1923','Yahweh, j''ai crié vers toi, j''ai imploré Yahweh:'),
('ps',30,10,'crampon1923','" Que gagnes-tu à verser mon sang; à me faire descendre dans la fosse? La poussière chantera-t-elle tes louanges, annoncera-t-elle ta vérité?'),
('ps',30,11,'crampon1923','Ecoute, Yahweh, sois-moi propice; Yahweh, viens à mon secours! " —'),
('ps',30,12,'crampon1923','Et tu as changé mes lamentations en allégresse, tu as délié mon sac et tu m''as ceint de joie,'),
('ps',30,13,'crampon1923','afin que mon âme te chante et ne se taise pas. Yahweh, mon Dieu, à jamais je te louerai.'),
('ps',31,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',31,2,'crampon1923','Yahweh, en toi j''ai placé mon refuge: que jamais je ne sois confondu! Dans ta justice sauve-moi!'),
('ps',31,3,'crampon1923','Incline vers moi ton oreille, hâte-toi de me délivrer! Sois pour moi un rocher protecteur, une forteresse où je trouve mon salut!'),
('ps',31,4,'crampon1923','Car tu es mon rocher, ma forteresse, et à cause de ton nom tu me conduiras et me dirigeras.'),
('ps',31,5,'crampon1923','Tu me tireras du filet qu''ils m''ont tendu, car tu es ma défense.'),
('ps',31,6,'crampon1923','Entre tes mains je remets mon esprit; tu me délivreras, Yahweh, Dieu de vérité!'),
('ps',31,7,'crampon1923','Je hais ceux qui révèrent de vaines idoles: pour moi, c''est en Yahweh que je me confie.'),
('ps',31,8,'crampon1923','Je tressaillirai de joie et d''allégresse à cause de ta bonté, car tu as regardé ma misère, tu as vu les angoisses de mon âme,'),
('ps',31,9,'crampon1923','et tu ne m''as pas livré aux mains de l''ennemi; tu donnes à mes pieds un libre espace.'),
('ps',31,10,'crampon1923','Aie pitié de moi, Yahweh, car je suis dans la détresse; mon œil est usé par le chagrin, ainsi que mon âme et mes entrailles.'),
('ps',31,11,'crampon1923','Ma vie se consume dans la douleur, et mes années dans les gémissements; ma force est épuisée à cause de mon iniquité, et mes os dépérissent.'),
('ps',31,12,'crampon1923','Tous mes adversaires m''ont rendu un objet d''opprobre; un fardeau pour mes voisins, un objet d''effroi pour mes amis. Ceux qui me voient dehors s''enfuient loin de moi.'),
('ps',31,13,'crampon1923','Je suis en oubli, comme un mort, loin des cœurs; je suis comme un vase brisé.'),
('ps',31,14,'crampon1923','Car j''ai appris les mauvais propos de la foule, l''épouvante qui règne à l''entour, pendant qu''ils tiennent conseil contre moi: ils ourdissent des complots pour m''ôter la vie.'),
('ps',31,15,'crampon1923','Et moi, je me confie en toi, Yahweh; je dis: " Tu es mon Dieu! "'),
('ps',31,16,'crampon1923','Mes destinées sont dans ta main; délivre-moi de la main de mes ennemis et de mes persécuteurs!'),
('ps',31,17,'crampon1923','Fais luire ta face sur ton serviteur, sauve-moi par ta grâce!'),
('ps',31,18,'crampon1923','Yahweh, que je ne sois pas confondu quand je t''invoque! Que la confusion soit pour les méchants! Qu''ils descendent en silence au schéol!'),
('ps',31,19,'crampon1923','Qu''elles deviennent muettes les lèvres menteuses, qui parlent avec arrogance contre le juste, avec orgueil et mépris.'),
('ps',31,20,'crampon1923','Qu''elle est grande ta bonté, que tu tiens en réserve pour ceux qui te craignent, que tu témoignes à ceux qui mettent en toi leur refuge, à la vue des enfants des hommes!'),
('ps',31,21,'crampon1923','Tu les mets à couvert, dans l''asile de ta face, contre les machinations des hommes; tu les caches dans ta tente, à l''abri des langues qui les attaquent.'),
('ps',31,22,'crampon1923','Béni soit Yahweh! Car il a signalé sa grâce envers moi, en me mettant dans une ville forte.'),
('ps',31,23,'crampon1923','Je disais dans mon trouble: " Je suis rejeté loin de ton regard! " Mais tu as entendu la voix de mes supplications, quand j''ai crié vers toi.'),
('ps',31,24,'crampon1923','Aimez Yahweh, vous tous qui êtes pieux envers lui. Yahweh garde les fidèles, et il punit sévèrement les orgueilleux.'),
('ps',31,25,'crampon1923','Ayez courage, et que votre cœur s''affermisse, vous tous qui espérez en Yahweh!'),
('ps',32,1,'crampon1923','De David. — Pieuse méditation. Heureux celui dont la transgression a été remise, dont le péché est pardonné!'),
('ps',32,2,'crampon1923','Heureux l''homme à qui Yahweh n''impute pas l''iniquité, et dans l''esprit duquel il n''y a point de fraude!'),
('ps',32,3,'crampon1923','Tant que je me suis tu, mes os se consumaient dans mon gémissement, chaque jour.'),
('ps',32,4,'crampon1923','Car jour et nuit ta main s''appesantissait sur moi; la sève de ma vie se desséchait aux ardeurs de l''été. — Séla.'),
('ps',32,5,'crampon1923','Je t''ai fait connaître mon péché, je n''ai point caché mon iniquité; j''ai dit: " Je veux confesser à Yahweh mes transgressions " et toi, tu as remis l''iniquité de mon péché. — Séla.'),
('ps',32,6,'crampon1923','Que tout homme pieux te prie donc au temps favorable! Non! quand les grandes eaux déborderont, elles ne l''atteindront point.'),
('ps',32,7,'crampon1923','Tu es mon asile, tu me préserveras de la détresse; tu m''entoureras de chants de délivrance. — Séla.'),
('ps',32,8,'crampon1923','— " Je t''instruirai et te montrerai la voie que tu dois suivre; je serai ton conseiller, mon œil sera sur toi. " —'),
('ps',32,9,'crampon1923','Ne soyez pas comme le cheval ou le mulet sans intelligence; il faut les gouverner avec le mors et le frein, autrement, ils n''obéissent pas.'),
('ps',32,10,'crampon1923','De nombreuses douleurs sont la part du méchant, mais celui qui se confie en Yahweh est environné de sa grâce.'),
('ps',32,11,'crampon1923','Justes, réjouissez-vous en Yahweh et soyez dans l''allégresse! Poussez des cris de joie, vous tous qui avez le cœur droit!'),
('ps',33,1,'crampon1923','Justes, réjouissez-vous en Yahweh! Aux hommes droits sied la louange.'),
('ps',33,2,'crampon1923','Célébrez Yahweh avec la harpe, chantez-le sur le luth à dix cordes.'),
('ps',33,3,'crampon1923','Chantez à sa gloire un cantique nouveau; unissez avec art vos instruments et vos voix.'),
('ps',33,4,'crampon1923','Car la parole de Yahweh est droite, et toutes ses œuvres s''accomplissent dans la fidélité.'),
('ps',33,5,'crampon1923','il aime la justice et la droiture; la terre est remplie de la bonté de Yahweh.'),
('ps',33,6,'crampon1923','Par la parole de Yahweh les cieux ont été faits, et toute leur armée par le souffle de sa bouche.'),
('ps',33,7,'crampon1923','Il rassemble comme en un monceau les eaux de la mer; il met dans des réservoirs les flots de l''abîme.'),
('ps',33,8,'crampon1923','Que toute la terre craigne Yahweh! Que tous les habitants de l''univers tremblent devant lui!'),
('ps',33,9,'crampon1923','Car il a dit, et tout a été fait; il a ordonné, et tout a existé.'),
('ps',33,10,'crampon1923','Yahweh renverse les desseins des nations; il réduit à néant les pensées des peuples.'),
('ps',33,11,'crampon1923','Mais les desseins de Yahweh subsistent à jamais et les pensées de son cœur dans toutes les générations.'),
('ps',33,12,'crampon1923','Heureuse la nation dont Yahweh est le Dieu, heureux le peuple qu''il a choisi pour son héritage!'),
('ps',33,13,'crampon1923','Du haut des cieux Yahweh regarde, il voit tous les enfants des hommes;'),
('ps',33,14,'crampon1923','du lieu de sa demeure, il observe tous les habitants de la terre,'),
('ps',33,15,'crampon1923','lui qui forme leur cœur à tous, qui est attentif à toutes leurs actions.'),
('ps',33,16,'crampon1923','Ce n''est pas le nombre des soldats qui donne au roi la victoire, ce n''est pas une grande force qui fait triompher le guerrier.'),
('ps',33,17,'crampon1923','Le cheval est impuissant à procurer le salut, et toute sa vigueur n''assure pas la délivrance.'),
('ps',33,18,'crampon1923','L''œil de Yahweh est sur ceux qui le craignent, sur ceux qui espèrent en sa bonté,'),
('ps',33,19,'crampon1923','pour délivrer leur âme de la mort, et les faire vivre au temps de la famine.'),
('ps',33,20,'crampon1923','Notre âme attend avec confiance Yahweh; il est notre secours et notre bouclier;'),
('ps',33,21,'crampon1923','car en lui notre cœur met sa joie, car en son saint nom nous mettons notre confiance.'),
('ps',33,22,'crampon1923','Yahweh, que ta grâce soit sur nous, comme nous espérons en toi!'),
('ps',34,1,'crampon1923','De David: lorsqu''il contrefit l''insensé en présence d''Abimélech, et que, chassé par lui, il s''en alla.'),
('ps',34,2,'crampon1923','ALEPH. Je veux bénir Yahweh en tout temps; sa louange sera toujours dans ma bouche.'),
('ps',34,3,'crampon1923','BETH. En Yahweh mon âme se glorifiera: que les humbles entendent et se réjouissent!'),
('ps',34,4,'crampon1923','GHIMEL. Exaltez avec moi Yahweh, ensemble célébrons son nom!'),
('ps',34,5,'crampon1923','DALETH. J''ai cherché Yahweh, et il m''a exaucé, et il m''a délivré de toutes mes frayeurs.'),
('ps',34,6,'crampon1923','HÉ. Quand on regarde vers lui, on est rayonnant de joie, VAV. et le visage ne se couvre pas de honte.'),
('ps',34,7,'crampon1923','ZAÏN. Ce pauvre a crié, et Yahweh l''a entendu, et il l''a sauvé de toutes ses angoisses.'),
('ps',34,8,'crampon1923','HETH. L''ange de Yahweh campe autour de ceux qui le craignent, et il les sauve.'),
('ps',34,9,'crampon1923','TETH. Goûtez et voyez combien Yahweh est bon! Heureux l''homme qui met en lui son refuge!'),
('ps',34,10,'crampon1923','YOD. Craignez Yahweh, vous ses saints, car il n''y a point d''indigence pour ceux qui le craignent.'),
('ps',34,11,'crampon1923','CAPH. Les lionceaux peuvent connaître la disette et la faim, mais ceux qui cherchent Yahweh ne manquent d''aucun bien.'),
('ps',34,12,'crampon1923','LAMED. Venez, mes fils, écoutez-moi, je vous enseignerai la crainte de Yahweh.'),
('ps',34,13,'crampon1923','MEM. Quel est l''homme qui aime la vie, qui désire de longs jours pour jouir du bonheur? —'),
('ps',34,14,'crampon1923','NUN. Préserve ta langue du mal, et tes lèvres des paroles trompeuses;'),
('ps',34,15,'crampon1923','SAMECH. éloigne-toi du mal et fais le bien, recherche la paix, et poursuis-la.'),
('ps',34,16,'crampon1923','AIN. Les yeux de Yahweh sont sur les justes; et ses oreilles sont attentives à leurs cris.'),
('ps',34,17,'crampon1923','PHÉ. La face de Yahweh est contre ceux qui font le mal, pour retrancher de la terre leur souvenir.'),
('ps',34,18,'crampon1923','TSADÉ. Les justes crient, et Yahweh les entend, et il les délivre de toutes leurs angoisses.'),
('ps',34,19,'crampon1923','QOPH. Yahweh est près de ceux qui ont le cœur brisé, il sauve ceux dont l''esprit est abattu.'),
('ps',34,20,'crampon1923','RESCH. Nombreux sont les malheurs du juste, mais de tous Yahweh le délivre.'),
('ps',34,21,'crampon1923','SCHIN. Il garde tous ses os, aucun d''eux ne sera brisé.'),
('ps',34,22,'crampon1923','THAV. Le mal tue le méchant, et les ennemis du juste sont châtiés.'),
('ps',34,23,'crampon1923','Yahweh délivre l''âme de ses serviteurs, et tous ceux qui se réfugient en lui ne sont pas châtiés.'),
('ps',35,1,'crampon1923','De David. Yahweh, combats ceux qui me combattent, fais la guerre à ceux qui me font la guerre!'),
('ps',35,2,'crampon1923','Saisis le petit et le grand bouclier, et lève-toi pour me secourir!'),
('ps',35,3,'crampon1923','Tire la lance et barre le passage à mes persécuteurs; dis à mon âme: " Je suis ton salut! "'),
('ps',35,4,'crampon1923','Qu''ils soient honteux et confus ceux qui en veulent à ma vie; qu''ils reculent et rougissent ceux qui méditent ma perte!'),
('ps',35,5,'crampon1923','Qu''ils soient comme la paille au souffle du vent, et que l''ange de Yahweh les chasse devant lui!'),
('ps',35,6,'crampon1923','Que leur voie soit ténébreuse et glissante, et que l''ange de Yahweh les poursuive!'),
('ps',35,7,'crampon1923','Car sans cause ils ont caché leur filet pour ma ruine, sans cause ils ont creusé la fosse pour me faire périr.'),
('ps',35,8,'crampon1923','Que la ruine tombe sur lui à l''improviste, que le filet qu''il a caché le saisisse, qu''il y tombe et périsse!'),
('ps',35,9,'crampon1923','Et mon âme aura de la joie en Yahweh, de l''allégresse dans son salut.'),
('ps',35,10,'crampon1923','Tous mes os diront: " Yahweh, qui est semblable à toi, délivrant le malheureux d''un plus fort que lui, le malheureux et le pauvre de celui qui le dépouille? "'),
('ps',35,11,'crampon1923','Des témoins iniques se lèvent; ils m''accusent de choses que j''ignore.'),
('ps',35,12,'crampon1923','Ils me rendent le mal pour le bien; mon âme est dans l''abandon.'),
('ps',35,13,'crampon1923','Et moi, quand ils étaient malades, je revêtais un sac, j''affligeais mon âme par le jeûne, et ma prière retournait sur mon sein.'),
('ps',35,14,'crampon1923','Comme pour un ami, pour un frère, je me traînais lentement; comme pour le deuil d''une mère, je me courbais avec tristesse.'),
('ps',35,15,'crampon1923','Et maintenant que je chancelle, ils se réjouissent et s''assemblent, contre moi des calomniateurs s''assemblent à mon insu; ils me déchirent sans relâche.'),
('ps',35,16,'crampon1923','Comme d''impurs parasites à la langue moqueuse, ils grincent des dents contre moi.'),
('ps',35,17,'crampon1923','Seigneur, jusques à quand le verras-tu? Arrache mon âme à leurs persécutions, ma vie à la fureur de ces lions!'),
('ps',35,18,'crampon1923','Je te louerai dans la grande assemblée, je te célébrerai au milieu d''un peuple nombreux.'),
('ps',35,19,'crampon1923','Qu''ils ne se réjouissent pas à mon sujet, ceux qui m''attaquent sans raison! Qu''ils ne clignent pas des yeux, ceux qui me haïssent sans cause!'),
('ps',35,20,'crampon1923','Car leur langage n''est pas celui de la paix; ils méditent de perfides desseins contre les gens tranquilles du pays.'),
('ps',35,21,'crampon1923','Ils ouvrent toute large contre moi leur bouche, ils disent: " Ah! ah! notre œil a vu...! "'),
('ps',35,22,'crampon1923','Yahweh, tu le vois! Ne reste pas en silence, Seigneur, ne t''éloigne pas de moi!'),
('ps',35,23,'crampon1923','Eveille-toi, lève-toi pour me faire justice, mon Dieu et mon Seigneur, pour prendre en main ma cause!'),
('ps',35,24,'crampon1923','Juge-moi selon ta justice, Yahweh, mon Dieu, et qu''ils ne se réjouissent pas à mon sujet!'),
('ps',35,25,'crampon1923','Qu''ils ne disent pas dans leur cœur: " Notre âme est satisfaite! " qu''ils ne disent pas: " Nous l''avons englouti! "'),
('ps',35,26,'crampon1923','Qu''ils rougissent et soient confondus tous ensemble, ceux qui se réjouissent de mon malheur! Qu''ils soient couverts de honte et d''ignominie, ceux qui s''élèvent contre moi!'),
('ps',35,27,'crampon1923','Qu''ils soient dans la joie et l''allégresse, ceux qui désirent le triomphe de mon droit; et que sans cesse ils disent: " Gloire à Yahweh, qui veut la paix de son serviteur! "'),
('ps',35,28,'crampon1923','Et ma langue célébrera ta justice, ta louange tous les jours.'),
('ps',36,1,'crampon1923','Au maître de chant. De David, serviteur de Yahweh.'),
('ps',36,2,'crampon1923','L''iniquité parle au méchant dans le fond de son cœur; la crainte de Dieu n''est pas devant ses yeux.'),
('ps',36,3,'crampon1923','Car il se flatte lui-même, sous le regard divin, doutant que Dieu découvre jamais son crime et le déteste.'),
('ps',36,4,'crampon1923','Les paroles de sa bouche sont injustice et tromperie; il a cessé d''avoir l''intelligence, de faire le bien.'),
('ps',36,5,'crampon1923','Il médite l''iniquité sur sa couche; il se tient sur une voie qui n''est pas bonne; il ne rejette pas le mal.'),
('ps',36,6,'crampon1923','Yahweh, ta bonté atteint jusqu''aux cieux, ta fidélité jusqu''aux nues.'),
('ps',36,7,'crampon1923','Ta justice est comme les montagnes de Dieu, tes jugements sont comme le vaste abîme. Yahweh, tu gardes les hommes et les bêtes:'),
('ps',36,8,'crampon1923','combien est précieuse ta bonté, ô Dieu! A l''ombre de tes ailes les fils de l''homme cherchent un refuge.'),
('ps',36,9,'crampon1923','Ils s''enivrent de la graisse de ta maison, et tu les abreuves au torrent de tes délices.'),
('ps',36,10,'crampon1923','Car auprès de toi est la source de la vie, et dans ta lumière nous voyons la lumière.'),
('ps',36,11,'crampon1923','Continue ta bonté à ceux qui te connaissent, et ta justice à ceux qui ont le cœur droit.'),
('ps',36,12,'crampon1923','Que le pied de l''orgueilleux ne m''atteigne pas, et que la main des méchants ne me fasse pas fuir!'),
('ps',36,13,'crampon1923','Les voilà tombés, ceux qui commettent l''iniquité! Ils sont renversés, et ils ne peuvent se relever.'),
('ps',37,1,'crampon1923','De David. ALEPH. Ne t''irrite pas au sujet des méchants, ne porte pas envie à ceux qui font le mal.'),
('ps',37,2,'crampon1923','Car, comme l''herbe, ils seront vite coupés; comme la verdure du gazon, ils se dessécheront. BETH.'),
('ps',37,3,'crampon1923','Mets ta confiance en Yahweh, et fais le bien; habite le pays, et jouis de sa fidélité.'),
('ps',37,4,'crampon1923','Fais de Yahweh tes délices, et il te donnera ce que ton cœur désire. GHIMEL.'),
('ps',37,5,'crampon1923','Remets ton sort à Yahweh et confie-toi en lui: il agira:'),
('ps',37,6,'crampon1923','il fera resplendir ta justice comme la lumière, et ton droit comme le soleil à son midi. DALETH.'),
('ps',37,7,'crampon1923','Tiens-toi en silence devant Yahweh, et espère en lui; ne t''irrite pas au sujet de celui qui prospère dans ses voies; de l''homme qui réussit en ses intrigues. HÉ.'),
('ps',37,8,'crampon1923','Laisse la colère, abandonne la fureur; ne t''irrite pas, pour n''aboutir qu''au mal.'),
('ps',37,9,'crampon1923','Car les méchants seront retranchés, mais ceux qui espèrent en Yahweh posséderont le pays. VAV.'),
('ps',37,10,'crampon1923','Encore un peu de temps, et le méchant n''est plus; tu regardes sa place, et il a disparu.'),
('ps',37,11,'crampon1923','Mais les doux posséderont la terre, ils goûteront les délices d''une paix profonde. ZAÏN.'),
('ps',37,12,'crampon1923','Le méchant forme des projets contre le juste, il grince les dents contre lui.'),
('ps',37,13,'crampon1923','Le Seigneur se rit du méchant, car il voit que son jour arrive. HETH.'),
('ps',37,14,'crampon1923','Les méchants tirent le glaive, ils bandent leur arc; pour abattre le malheureux et le pauvre, pour égorger ceux dont la voie est droite.'),
('ps',37,15,'crampon1923','Leur glaive entrera dans leur propre cœur, et leurs arcs se briseront. TETH.'),
('ps',37,16,'crampon1923','Mieux vaut le peu du juste, que l''abondance de nombreux méchants;'),
('ps',37,17,'crampon1923','car les bras des méchants seront brisés, et Yahweh soutient les justes. YOD.'),
('ps',37,18,'crampon1923','Yahweh connaît les jours des hommes intègres, et leur héritage dure à jamais.'),
('ps',37,19,'crampon1923','Ils ne sont pas confondus au jour du malheur, et ils sont rassasiés aux jours de la famine. CAPH.'),
('ps',37,20,'crampon1923','Car les méchants périssent; les ennemis de Yahweh sont comme la gloire des prairies; ils s''évanouissent en fumée, ils s''évanouissent. LAMED.'),
('ps',37,21,'crampon1923','Le méchant emprunte, et il ne rend pas; Le juste est compatissant, et il donne.'),
('ps',37,22,'crampon1923','Car ceux que bénit Yahweh possèdent le pays, et ceux qu''il maudit sont retranchés. MEM.'),
('ps',37,23,'crampon1923','Yahweh affermit les pas de l''homme juste, et il prend plaisir à sa voie.'),
('ps',37,24,'crampon1923','S''il tombe, il n''est pas étendu par terre, car Yahweh soutient sa main. NUN.'),
('ps',37,25,'crampon1923','J''ai été jeune, me voilà vieux, et je n''ai point vu le juste abandonné; ni sa postérité mendiant son pain.'),
('ps',37,26,'crampon1923','Toujours il est compatissant, et il prête, et sa postérité est en bénédiction. SAMECH.'),
('ps',37,27,'crampon1923','Détourne-toi du mal et fais le bien; et habite à jamais ta demeure.'),
('ps',37,28,'crampon1923','Car Yahweh aime la justice, et il n''abandonne pas ses fidèles. Ils sont toujours sous sa garde, mais la postérité des méchants sera retranchée.'),
('ps',37,29,'crampon1923','Les justes posséderont le pays, et ils y habiteront à jamais. PHÉ.'),
('ps',37,30,'crampon1923','La bouche du juste annonce la sagesse, et sa langue proclame la justice.'),
('ps',37,31,'crampon1923','La loi de son Dieu est dans son cœur; ses pas ne chancellent point. TSADÉ.'),
('ps',37,32,'crampon1923','Le méchant épie le juste, et il cherche à le faire mourir.'),
('ps',37,33,'crampon1923','Yahweh ne l''abandonne pas entre ses mains, et il ne le condamne pas quand vient son jugement. QOPH.'),
('ps',37,34,'crampon1923','Attends Yahweh et garde sa voie, et il t''élèvera et tu posséderas le pays; quand les méchants seront retranchés, tu le verras. RESCH.'),
('ps',37,35,'crampon1923','J''ai vu l''impie au comble de la puissance; il s''étendait comme un arbre verdoyant.'),
('ps',37,36,'crampon1923','J''ai passé, et voici qu''il n''était plus; je l''ai cherché, et on ne l''a plus trouvé. SCHIN.'),
('ps',37,37,'crampon1923','Observe celui qui est intègre, et regarde celui qui est droit; car il y a une postérité pour l''homme de paix.'),
('ps',37,38,'crampon1923','Mais les rebelles seront tous anéantis, la postérité des méchants sera retranchée. THAV.'),
('ps',37,39,'crampon1923','De Yahweh vient le salut des justes; il est leur protecteur au temps de la détresse.'),
('ps',37,40,'crampon1923','Yahweh leur vient en aide et les délivre; il les délivre des méchants et les sauve, parce qu''ils ont mis en lui leur confiance.'),
('ps',38,1,'crampon1923','Psaume de David. Pour faire souvenir.'),
('ps',38,2,'crampon1923','Yahweh, ne me punis pas dans ta colère, et ne me châtie pas dans ta fureur.'),
('ps',38,3,'crampon1923','Car tes flèches m''ont atteint, et ta main s''est appesantie sur moi.'),
('ps',38,4,'crampon1923','Il n''y a rien de sain dans ma chair à cause de ta colère, il n''y a rien de sauf dans mes os à cause de mon péché.'),
('ps',38,5,'crampon1923','Car mes iniquités s''élèvent au-dessus de ma tête; comme un lourd fardeau, elles m''accablent de leur poids.'),
('ps',38,6,'crampon1923','Mes meurtrissures sont infectes et purulentes, par l''effet de ma folie.'),
('ps',38,7,'crampon1923','Je suis courbé, abattu à l''excès; tout le jour je marche dans le deuil.'),
('ps',38,8,'crampon1923','Un mal brûlant dévore mes reins, et il n''y a rien de sain dans ma chair.'),
('ps',38,9,'crampon1923','Je suis sans force, brisé outre mesure; le trouble de mon cœur m''arrache des gémissements.'),
('ps',38,10,'crampon1923','Seigneur, tous mes désirs sont devant toi, et mes soupirs ne te sont pas cachés.'),
('ps',38,11,'crampon1923','Mon cœur palpite, ma force m''abandonne, et la lumière même de mes yeux n''est plus avec moi.'),
('ps',38,12,'crampon1923','Mes amis et mes compagnons s''éloignent de ma plaie; et mes proches se tiennent à l''écart.'),
('ps',38,13,'crampon1923','Ceux qui en veulent à ma vie tendent leurs pièges; ceux qui cherchent mon malheur profèrent des menaces, et tout le jour ils méditent des embûches.'),
('ps',38,14,'crampon1923','Et moi, je suis comme un sourd, je n''entends pas; je suis comme un muet, qui n''ouvre pas la bouche.'),
('ps',38,15,'crampon1923','Je suis comme un homme qui n''entend pas, et dans la bouche duquel il n''y a point de réplique.'),
('ps',38,16,'crampon1923','C''est en toi, Yahweh, que j''espère; toi, tu répondras, Seigneur, mon Dieu!'),
('ps',38,17,'crampon1923','Car je dis: " Qu''ils ne se réjouissent pas à mon sujet, qu''ils ne s''élèvent pas contre moi, si mon pied chancelle. "'),
('ps',38,18,'crampon1923','Car je suis près de tomber, Et ma douleur est toujours devant moi.'),
('ps',38,19,'crampon1923','Car je confesse mon iniquité, Je suis dans la crainte à cause de mon péché.'),
('ps',38,20,'crampon1923','Et mes ennemis sont pleins de vie, ils sont puissants; Ceux qui me haïssent sans cause se sont multipliés.'),
('ps',38,21,'crampon1923','Ils me rendent le mal pour le bien; ils me sont hostiles, parce que je cherche la justice.'),
('ps',38,22,'crampon1923','Ne m''abandonne pas, Yahweh! Mon Dieu, ne t''éloigne pas de moi!'),
('ps',38,23,'crampon1923','Hâte-toi de me secourir, Seigneur, toi qui es mon salut!'),
('ps',39,1,'crampon1923','Au maître de chant, à Idithun. Chant de David.'),
('ps',39,2,'crampon1923','Je disais: " Je veillerai sur mes voies, de peur de pécher par la langue; je mettrai un frein à ma bouche, tant que le méchant sera devant moi. "'),
('ps',39,3,'crampon1923','Et je suis resté muet, dans le silence; je me suis tu, quoique privé de tout bien. Mais ma douleur s''est irritée,'),
('ps',39,4,'crampon1923','mon cœur s''est embrasé au-dedans de moi; dans mes réflexions un feu s''est allumé, et la parole est venue sur ma langue.'),
('ps',39,5,'crampon1923','Fais-moi connaître, Yahweh, quel est le terme de ma vie; quelle est la mesure de mes jours; que je sache combien je suis périssable.'),
('ps',39,6,'crampon1923','Tu as donné à mes jours la largeur de la main, et ma vie est comme un rien devant toi. Oui, tout homme vivant n''est qu''un souffle. — Séla.'),
('ps',39,7,'crampon1923','Oui, l''homme passe comme une ombre; oui, c''est en vain qu''il s''agite; il amasse, et il ignore qui recueillera.'),
('ps',39,8,'crampon1923','Maintenant, que puis-je attendre, Seigneur? Mon espérance est en toi.'),
('ps',39,9,'crampon1923','Délivre-moi de toutes mes transgressions; ne me rends pas l''opprobre de l''insensé.'),
('ps',39,10,'crampon1923','Je me tais, je n''ouvre plus la bouche, car c''est toi qui agis.'),
('ps',39,11,'crampon1923','Détourne de moi tes coups; sous la rigueur de ta main, je succombe!'),
('ps',39,12,'crampon1923','Quand tu châties l''homme, en le punissant de son iniquité, tu détruis, comme fait la teigne, ce qu''il a de plus cher. Oui, tout homme n''est qu''un souffle. — Séla.'),
('ps',39,13,'crampon1923','Ecoute ma prière, Yahweh, prête l''oreille à mes cris, ne sois pas insensible à mes larmes! Car je suis un étranger chez toi, un voyageur, comme tous mes pères.'),
('ps',39,14,'crampon1923','Détourne de moi le regard et laisse-moi respirer, avant que je m''en aille et que je ne sois plus!'),
('ps',40,1,'crampon1923','Du maître de chant. De David. Psaume.'),
('ps',40,2,'crampon1923','J''ai mis en Yahweh toute mon espérance: il s''est incliné vers moi, il a écouté mes cris.'),
('ps',40,3,'crampon1923','Il m''a retiré de la fosse de perdition, de la fange du bourbier; il a dressé mes pieds sur le rocher, il a affermi mes pas.'),
('ps',40,4,'crampon1923','Il a mis dans ma bouche un cantique nouveau, une louange à notre Dieu; beaucoup le voient, et ils révèrent Yahweh, ils se confient en lui.'),
('ps',40,5,'crampon1923','Heureux l''homme qui a mis en Yahweh sa confiance, et qui ne se tourne pas vers les orgueilleux, et vers ceux que le mensonge égare!'),
('ps',40,6,'crampon1923','Tu as multiplié, Yahweh, mon Dieu, tes merveilles et tes desseins en notre faveur: nul n''est comparable à toi. Je voudrais les publier et les proclamer; ils surpassent tout récit.'),
('ps',40,7,'crampon1923','Tu ne désires ni sacrifice ni oblation, tu m''as percé les oreilles; tu ne demandes ni holocauste ni victime expiatoire.'),
('ps',40,8,'crampon1923','Alors j''ai dit: " Voici que je viens, avec le rouleau du livre écrit pour moi.'),
('ps',40,9,'crampon1923','Je veux faire ta volonté, ô mon Dieu, et ta loi est au fond de mon cœur. "'),
('ps',40,10,'crampon1923','J''annoncerai la justice dans une grande assemblée; je ne fermerai pas mes lèvres, Yahweh, tu le sais.'),
('ps',40,11,'crampon1923','Je ne tiendrai pas ta justice cachée dans mon cœur; je publierai ta fidélité et ton salut, je ne tairai pas ta bonté et ta vérité à la grande assemblée.'),
('ps',40,12,'crampon1923','Toi, Yahweh, ne me ferme pas tes miséricordes; que ta bonté et ta vérité me gardent toujours!'),
('ps',40,13,'crampon1923','Car des maux sans nombre m''environnent; mes iniquités m''ont saisi, et je ne puis voir; elles sont plus nombreuses que les cheveux de ma tête, et mon cœur m''abandonne.'),
('ps',40,14,'crampon1923','Qu''il te plaise, Yahweh, de me délivrer! Yahweh, hâte-toi de me secourir!'),
('ps',40,15,'crampon1923','Qu''ils soient confus et honteux tous ensemble, ceux qui cherchent mon âme pour la perdre! Qu''ils reculent et rougissent, ceux qui désirent ma ruine!'),
('ps',40,16,'crampon1923','Qu''ils soient dans la stupeur à cause de leur honte, ceux qui me disent: " Ah! ah! "'),
('ps',40,17,'crampon1923','Qu''ils soient dans l''allégresse et se réjouissent en toi, tous ceux qui te cherchent! Qu''ils disent sans cesse: " Gloire à Yahweh, " ceux qui aiment ton salut!'),
('ps',40,18,'crampon1923','Moi, je suis pauvre et indigent, mais le Seigneur prendra soin de moi. Tu es mon aide et mon libérateur: mon Dieu, ne tarde pas!'),
('ps',41,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',41,2,'crampon1923','Heureux celui qui prend souci du pauvre! Au jour du malheur, Yahweh le délivrera.'),
('ps',41,3,'crampon1923','Yahweh le gardera et le fera vivre; il sera heureux sur la terre, et tu ne le livreras pas au désir de ses ennemis.'),
('ps',41,4,'crampon1923','Yahweh l''assistera sur son lit de douleur; tu retourneras toute sa couche dans sa maladie.'),
('ps',41,5,'crampon1923','Moi, je dis: " Yahweh, aie pitié de moi! guéris mon âme, car j''ai péché contre toi! "'),
('ps',41,6,'crampon1923','Et mes ennemis profèrent contre moi des malédictions: " Quand mourra-t-il? Quand périra son nom? "'),
('ps',41,7,'crampon1923','Si quelqu''un vient me visiter, il ne profère que mensonges; son cœur recueille l''iniquité; quand il s''en va, il parle au dehors.'),
('ps',41,8,'crampon1923','Tous mes ennemis chuchotent ensemble contre moi, contre moi ils méditent le malheur.'),
('ps',41,9,'crampon1923','" Un mal irrémédiable, disent-ils, a fondu sur lui; le voilà couché, il ne se relèvera plus! "'),
('ps',41,10,'crampon1923','Même l''homme qui était mon ami, qui avait ma confiance et qui mangeait mon pain, lève le talon contre moi.'),
('ps',41,11,'crampon1923','Toi, Yahweh, aie pitié de moi et relève-moi, et je leur rendrai ce qu''ils méritent.'),
('ps',41,12,'crampon1923','Je connaîtrai que tu m''aimes, si mon ennemi ne triomphe pas de moi.'),
('ps',41,13,'crampon1923','A cause de mon innocence, tu m''as soutenu, et tu m''as établi pour toujours en ta présence.'),
('ps',41,14,'crampon1923','Béni soit Yahweh, le Dieu d''Israël, dans les siècles des siècles! Amen! Amen!'),
('ps',42,1,'crampon1923','Au maître de chant. Cantique des fils de Coré.'),
('ps',42,2,'crampon1923','Comme le cerf soupire après les sources d''eau, ainsi mon âme soupire après toi, ô Dieu.'),
('ps',42,3,'crampon1923','Mon âme a soif de Dieu, du Dieu vivant: quand irai-je et paraîtrai-je devant la face de Dieu?'),
('ps',42,4,'crampon1923','Mes larmes sont ma nourriture jour et nuit, pendant qu''on me dit sans cesse: " Où est ton Dieu? "'),
('ps',42,5,'crampon1923','Je me rappelle, — et à ce souvenir mon âme se fond en moi, — quand je marchais entouré de la foule, et que je m''avançais vers la maison de Dieu, au milieu des cris de joie et des actions de grâces d''une multitude en fête!'),
('ps',42,6,'crampon1923','Pourquoi es-tu abattue, ô mon âme, et t''agites-tu en moi? Espère en Dieu, car je le louerai encore, lui, le salut de ma face et mon Dieu!'),
('ps',42,7,'crampon1923','Mon âme est abattue au dedans de moi; aussi je pense à toi, du pays du Jourdain, de l''Hermon, de la montagne de Misar.'),
('ps',42,8,'crampon1923','Un flot en appelle un autre, quand grondent tes cataractes: ainsi toutes tes vagues et tes torrents passent sur moi.'),
('ps',42,9,'crampon1923','Le jour, Yahweh commandait à sa grâce de me visiter; la nuit, son cantique était sur mes lèvres j''adressais une prière au Dieu de ma vie.'),
('ps',42,10,'crampon1923','Maintenant je dis à Dieu mon rocher: " Pourquoi m''oublies-tu? pourquoi me faut-il marcher dans la tristesse, sous l''oppression de l''ennemi? "'),
('ps',42,11,'crampon1923','Je sens mes os se briser, quand mes persécuteurs m''insultent, en me disant sans cesse: " Où est ton Dieu? " —'),
('ps',42,12,'crampon1923','Pourquoi es-tu abattue, ô mon âme, et t''agites-tu en moi? Espère en Dieu, car je le louerai encore, lui, le salut de ma face et mon Dieu!'),
('ps',43,1,'crampon1923','Rends-moi justice, ô Dieu, défends ma cause contre une nation infidèle; délivre-moi de l''homme de fraude et d''iniquité!'),
('ps',43,2,'crampon1923','Car tu es le Dieu de ma défense: pourquoi me repousses-tu? Pourquoi me faut-il marcher dans la tristesse, sous l''oppression de l''ennemi?'),
('ps',43,3,'crampon1923','Envoie ta lumière et ta fidélité; qu''elles me guident, qu''elles me conduisent à ta montagne sainte et à tes tabernacles!'),
('ps',43,4,'crampon1923','J''irai à l''autel de Dieu, au Dieu qui est ma joie et mon allégresse, et je te célébrerai sur la harpe, ô Dieu, mon Dieu! —'),
('ps',43,5,'crampon1923','Pourquoi es-tu abattue, ô mon âme, et t''agites-tu en moi? Espère en Dieu, car je le louerai encore, lui, le salut de ma face et mon Dieu!'),
('ps',44,1,'crampon1923','Au maître de chant. Des fils de Coré. Cantique.'),
('ps',44,2,'crampon1923','O Dieu, nous avons entendu de nos oreilles, nos pères nous ont raconté l''œuvre que tu as accomplie de leur temps, aux jours anciens.'),
('ps',44,3,'crampon1923','De ta main tu as chassé des nations pour les établir, tu as frappé des peuples pour les étendre.'),
('ps',44,4,'crampon1923','Car ce n''est point avec leur épée qu''ils ont conquis le pays, ce n''est point leur bras qui leur a donné la victoire; mais c''est ta droite, c''est ton bras, c''est la lumière de ta face, parce que tu les aimais.'),
('ps',44,5,'crampon1923','C''est toi qui es mon roi, ô Dieu: ordonne le salut de Jacob!'),
('ps',44,6,'crampon1923','Par toi nous renverserons nos ennemis, en ton nom nous écraserons nos adversaires.'),
('ps',44,7,'crampon1923','Car ce n''est pas en mon arc que j''ai confiance ce n''est pas mon épée qui me sauvera.'),
('ps',44,8,'crampon1923','Mais c''est toi qui nous délivres de nos ennemis, et qui confonds ceux qui nous haïssent.'),
('ps',44,9,'crampon1923','En Dieu nous nous glorifions chaque jour, et nous célébrons ton nom à jamais. — Séla.'),
('ps',44,10,'crampon1923','Cependant tu nous repousses et nous couvres de honte; tu ne sors plus avec nos armées.'),
('ps',44,11,'crampon1923','Tu nous fais reculer devant l''ennemi, et ceux qui nous haïssent nous dépouillent.'),
('ps',44,12,'crampon1923','Tu nous livres comme des brebis destinées à la boucherie, tu nous disperses parmi les nations;'),
('ps',44,13,'crampon1923','tu vends ton peuple à vil prix, tu ne l''estimes pas à une grande valeur.'),
('ps',44,14,'crampon1923','Tu fais de nous un objet d''opprobre pour nos voisins, de moquerie et de risée pour ceux qui nous entourent.'),
('ps',44,15,'crampon1923','Tu nous rends la fable des nations, et un sujet de hochements de tête parmi les peuples.'),
('ps',44,16,'crampon1923','Ma honte est toujours devant mes yeux, et la confusion couvre mon visage,'),
('ps',44,17,'crampon1923','à la voix de celui qui m''insulte et m''outrage, à la vue de l''ennemi et de celui qui respire la vengeance.'),
('ps',44,18,'crampon1923','Tout cela nous arrive sans que nous t''ayons oublié, sans que nous ayons été infidèles à ton alliance.'),
('ps',44,19,'crampon1923','Notre cœur ne s''est point détourné en arrière, nos pas ne se sont pas écartés de ton sentier,'),
('ps',44,20,'crampon1923','pour que tu nous écrases dans la retraite des chacals, et que tu nous couvres de l''ombre de la mort.'),
('ps',44,21,'crampon1923','Si nous avions oublié le nom de notre Dieu, et tendu les mains vers un dieu étranger,'),
('ps',44,22,'crampon1923','Dieu ne l''aurait-il pas aperçu, lui qui connaît les secrets du cœur?'),
('ps',44,23,'crampon1923','Mais c''est à cause de toi qu''on nous égorge tous les jours, qu''on nous traite comme des brebis destinées à la boucherie.'),
('ps',44,24,'crampon1923','Réveille-toi! Pourquoi dors-tu, Seigneur? Réveille-toi, et ne nous repousse pas à jamais!'),
('ps',44,25,'crampon1923','Pourquoi caches-tu ta face, oublies-tu notre misère et notre oppression?'),
('ps',44,26,'crampon1923','Car notre âme est affaissée jusqu''à la poussière, notre corps est attaché à la terre.'),
('ps',44,27,'crampon1923','Lève-toi pour nous secourir, délivre-nous à cause de ta bonté!'),
('ps',45,1,'crampon1923','Au maître de chant. Sur les lis. Cantique des fils de Coré. Chant d''amour.'),
('ps',45,2,'crampon1923','De mon cœur jaillit un beau chant; je dis: " Mon œuvre est pour un roi! " Ma langue est comme le roseau rapide du scribe,'),
('ps',45,3,'crampon1923','Tu es le plus beau des fils de l''homme, la grâce est répandue sur tes lèvres; c''est pourquoi Dieu t''a béni pour toujours.'),
('ps',45,4,'crampon1923','Ceins ton épée sur ta cuisse, ô héros, revêts ta splendeur et ta majesté.'),
('ps',45,5,'crampon1923','Et dans ta majesté avance-toi, monte sur ton char, combats pour la vérité, la douceur et la justice; et que ta droite te fasse accomplir des faits merveilleux.'),
('ps',45,6,'crampon1923','Tes flèches sont aiguës; des peuples tomberont à tes pieds; elles perceront le cœur des ennemis du roi.'),
('ps',45,7,'crampon1923','Ton trône, ô Dieu, est établi pour toujours; le sceptre de ta royauté est un sceptre de droiture.'),
('ps',45,8,'crampon1923','Tu aimes la justice et tu hais l''iniquité: c''est pourquoi Dieu, ton Dieu, t''a oint d''une huile d''allégresse, de préférence à tes compagnons.'),
('ps',45,9,'crampon1923','La myrrhe, l''aloès et la casse s''exhalent de tous tes vêtements; des palais d''ivoire, les lyres te réjouissent.'),
('ps',45,10,'crampon1923','Des filles de rois sont parmi tes bien-aimées; la reine est à ta droite, parée de l''or d''Ophir.'),
('ps',45,11,'crampon1923','" Ecoute, ma fille, regarde et prête l''oreille: oublie ton peuple et la maison de ton père,'),
('ps',45,12,'crampon1923','et le roi sera épris de ta beauté; car il est ton Seigneur: rends-lui tes hommages.'),
('ps',45,13,'crampon1923','La fille de Tyr, avec des présents, et les plus riches du peuple rechercheront ta faveur. "'),
('ps',45,14,'crampon1923','Toute resplendissante est la fille du roi dans l''intérieur; son vêtement est fait de tissus d''or.'),
('ps',45,15,'crampon1923','En robe de couleurs variées, elle est présentée au roi; après elles, des jeunes filles ses compagnes, te sont amenées.'),
('ps',45,16,'crampon1923','On les introduit au milieu des réjouissances et de l''allégresse; elles entrent dans le palais du Roi.'),
('ps',45,17,'crampon1923','Tes enfants prendront la place de tes pères; tu les établiras princes sur toute la terre.'),
('ps',45,18,'crampon1923','Je rappellerai ton nom dans tous les âges; et les peuples te loueront éternellement et à jamais.'),
('ps',46,1,'crampon1923','Au maître de chant. Des fils de Coré. Sur le ton des vierges. Cantique.'),
('ps',46,2,'crampon1923','Dieu est notre refuge et notre force; un secours que l''on rencontre toujours dans la détresse.'),
('ps',46,3,'crampon1923','Aussi sommes-nous sans crainte si la terre est bouleversée, si les montagnes s''abîment au sein de l''océan,'),
('ps',46,4,'crampon1923','si les flots de la mer s''agitent, bouillonnent, et, dans leur furie, ébranlent les montagnes. — Séla.'),
('ps',46,5,'crampon1923','Un fleuve réjouit de ses courants la cité de Dieu, le sanctuaire où habite le Très-Haut.'),
('ps',46,6,'crampon1923','Dieu est au milieu d''elle: elle est inébranlable; au lever de l''aurore, Dieu vient à son secours.'),
('ps',46,7,'crampon1923','Les nations s''agitent, les royaumes s''ébranlent; il fait entendre sa voix et la terre se fond d''épouvante.'),
('ps',46,8,'crampon1923','Yahweh des armées est avec nous; le Dieu de Jacob est pour nous une citadelle. — Séla.'),
('ps',46,9,'crampon1923','Venez, contemplez les œuvres de Yahweh, les dévastations qu''il a opérées sur la terre!'),
('ps',46,10,'crampon1923','Il a fait cesser les combats jusqu''au bout de ta terre, il a brisé l''arc, il a rompu la lance, il a consumé par le feu les chars de guerre:'),
('ps',46,11,'crampon1923','" Arrêtez et reconnaissez que je suis Dieu; je domine sur les nations, je domine sur la terre! "'),
('ps',46,12,'crampon1923','Yahweh des armées est avec nous, le Dieu de Jacob est pour nous une citadelle. — Séla.'),
('ps',47,1,'crampon1923','Au maître de chant. Des fils de Coré. Psaume.'),
('ps',47,2,'crampon1923','Vous tous, peuples, battez des mains, célébrez Dieu par des cris d''allégresse!'),
('ps',47,3,'crampon1923','Car Yahweh est très haut, redoutable, grand roi sur toute la terre.'),
('ps',47,4,'crampon1923','Il nous assujettit les peuples, il met les nations sous nos pieds.'),
('ps',47,5,'crampon1923','Il nous choisit notre héritage, la gloire de Jacob, son bien-aimé. — Séla.'),
('ps',47,6,'crampon1923','Dieu monte à son sanctuaire au milieu des acclamations; Yahweh, au son de la trompette.'),
('ps',47,7,'crampon1923','Chantez à Dieu, chantez! chantez à notre Roi, chantez!'),
('ps',47,8,'crampon1923','Car Dieu est roi de toute la terre; chantez un cantique de louange.'),
('ps',47,9,'crampon1923','Dieu règne sur les nations, il siège sur son trône saint.'),
('ps',47,10,'crampon1923','Les princes des peuples se réunissent pour former aussi un peuple du Dieu d''Abraham; car à Dieu sont les boucliers de la terre; Il est souverainement élevé.'),
('ps',48,1,'crampon1923','Cantique. Psaume des fils de Coré.'),
('ps',48,2,'crampon1923','Yahweh est grand, il est l''objet de toute louange, dans la cité de notre Dieu, sur sa montagne sainte.'),
('ps',48,3,'crampon1923','Elle s''élève gracieuse, joie de toute la terre, la montagne de Sion, aux extrémités du septentrion, la cité du grand Roi.'),
('ps',48,4,'crampon1923','Dieu, dans ses palais, s''est fait connaître comme un refuge.'),
('ps',48,5,'crampon1923','Car voici que les rois s''étaient réunis, ensemble ils s''étaient avancés.'),
('ps',48,6,'crampon1923','Ils ont vu, soudain ils ont été dans la stupeur; éperdus, ils ont pris la fuite.'),
('ps',48,7,'crampon1923','Là un tremblement les a saisis, une douleur comme celle de la femme qui enfante.'),
('ps',48,8,'crampon1923','Par le vent d''Orient tu brises les vaisseaux de Tharsis.'),
('ps',48,9,'crampon1923','Ce que nous avions entendu dire, nous l''avons vu dans la cité de Yahweh des armées; dans la cité de notre Dieu: Dieu l''affermit pour toujours. — Séla.'),
('ps',48,10,'crampon1923','O Dieu nous rappelons la mémoire de ta bonté, au milieu de ton temple.'),
('ps',48,11,'crampon1923','Comme ton nom, ô Dieu, ainsi ta louange arrive jusqu''aux extrémités de la terre. Ta droite est pleine de justice.'),
('ps',48,12,'crampon1923','Que la montagne de Sion se réjouisse, que les filles de Juda soient dans l''allégresse, à cause de tes jugements!'),
('ps',48,13,'crampon1923','Parcourez Sion et faites-en le tour, comptez ses forteresses;'),
('ps',48,14,'crampon1923','observez son rempart, examinez ses palais, pour le raconter à la génération future.'),
('ps',48,15,'crampon1923','Voilà le Dieu qui est notre Dieu à jamais et toujours; il sera notre guide dans tous les siècles.'),
('ps',49,1,'crampon1923','Au maître de chant. Psaume des fils de Coré.'),
('ps',49,2,'crampon1923','Ecoutez tous ceci, ô peuples; prêtez l''oreille vous tous habitants du monde,'),
('ps',49,3,'crampon1923','hommes du commun et hommes de condition, ensemble riches et pauvres.'),
('ps',49,4,'crampon1923','Ma bouche va faire entendre des paroles sages, et mon cœur a des pensées pleines de sens.'),
('ps',49,5,'crampon1923','Je prête l''oreille aux sentences que Dieu m''inspire; j''explique mon énigme au son de la harpe.'),
('ps',49,6,'crampon1923','Pourquoi craindrais-je aux jours du malheur, lorsque l''iniquité de mes persécuteurs m''assiège?'),
('ps',49,7,'crampon1923','Eux qui mettent leur confiance dans leurs biens, leur gloire dans leurs grandes richesses!'),
('ps',49,8,'crampon1923','Un homme ne peut racheter son frère, ni payer à Dieu sa rançon.'),
('ps',49,9,'crampon1923','Le rachat de leur vie est trop cher; il est à jamais impossible,'),
('ps',49,10,'crampon1923','pour qu''il vive éternellement, et qu''il ne voie jamais la fosse.'),
('ps',49,11,'crampon1923','Non, il la verra; les sages meurent, l''insensé et le stupide périssent également, laissant à d''autres leurs biens.'),
('ps',49,12,'crampon1923','Ils s''imaginent que leurs maisons seront éternelles, que leurs demeures subsisteront d''âge en âge, et ils donnent leurs noms à leurs domaines.'),
('ps',49,13,'crampon1923','Mais, même dans sa splendeur, l''homme ne dure pas; il est semblable aux biches qui périssent.'),
('ps',49,14,'crampon1923','Tel est leur sort, à ces hommes si confiants, et à ceux qui les suivent en approuvant leurs discours. — Séla.'),
('ps',49,15,'crampon1923','Comme un troupeau, ils sont poussés dans le schéol, la mort est leur pasteur; le matin, les hommes droits dominent sur eux, et leur ombre se consumera au schéol, sans autre demeure.'),
('ps',49,16,'crampon1923','Mais Dieu rachètera mon âme de la puissance du schéol, car il me prendra avec lui. — Séla.'),
('ps',49,17,'crampon1923','Ne crains donc pas, quand un homme s''enrichit, quand s''accroît l''opulence de sa maison.'),
('ps',49,18,'crampon1923','Car il n''emportera rien à sa mort, son opulence ne descendra pas avec lui.'),
('ps',49,19,'crampon1923','Il aura beau s''estimer heureux pendant sa vie; on aura beau te louer des jouissances que tu te donnes:'),
('ps',49,20,'crampon1923','Tu iras rejoindre la génération de tes pères, qui jamais ne reverront la lumière.'),
('ps',49,21,'crampon1923','L''homme, même dans sa splendeur, ne comprend pas, il est semblable aux bêtes qui périssent.'),
('ps',50,1,'crampon1923','Psaume d''Asaph. Dieu, Elohim, Yahweh parle et convoque la terre, du lever du soleil à son couchant.'),
('ps',50,2,'crampon1923','De Sion, beauté parfaite, Dieu resplendit.'),
('ps',50,3,'crampon1923','Il vient, notre Dieu, et il ne se taira point; devant lui est un feu dévorant, autour de lui se déchaîne la tempête.'),
('ps',50,4,'crampon1923','Il appelle les cieux en haut, et la terre, pour juger son peuple:'),
('ps',50,5,'crampon1923','" Rassemblez-moi mes fidèles, qui ont fait alliance avec moi sur le sacrifice. "'),
('ps',50,6,'crampon1923','Et les cieux proclament sa justice, car c''est Dieu qui va juger. — Séla.'),
('ps',50,7,'crampon1923','" Ecoute, mon peuple, et je parlerai; Israël, et je te reprendrai: je suis Elohim, ton Dieu.'),
('ps',50,8,'crampon1923','Ce n''est pas pour tes sacrifices que je te blâme; tes holocaustes sont constamment devant moi.'),
('ps',50,9,'crampon1923','je ne prendrai point un taureau dans ta maison, ni des boucs dans tes bergeries.'),
('ps',50,10,'crampon1923','Car à moi sont tous les animaux des forêts, toutes les bêtes des montagnes par milliers;'),
('ps',50,11,'crampon1923','je connais tous les oiseaux des montagnes, et ce qui se meut dans les champs est sous ma main.'),
('ps',50,12,'crampon1923','Si j''avais faim, je ne te le dirai pas, car le monde est à moi, et tout ce qu''il renferme.'),
('ps',50,13,'crampon1923','Est-ce que je mange la chair des taureaux? Est-ce que je bois le sang des boucs?'),
('ps',50,14,'crampon1923','Offre en sacrifice à Dieu l''action de grâces, et acquitte tes vœux envers le Très-Haut.'),
('ps',50,15,'crampon1923','Et invoque-moi au jour de la détresse: je te délivrerai, et tu me glorifieras. "'),
('ps',50,16,'crampon1923','Mais au méchant Dieu dit: " Quoi donc! tu énumères mes préceptes, et tu as mon alliance à la bouche,'),
('ps',50,17,'crampon1923','toi qui détestes la discipline, et qui jettes mes paroles derrière toi!'),
('ps',50,18,'crampon1923','Si tu vois un voleur, tu te plais avec lui, et tu fais cause commune avec les adultères.'),
('ps',50,19,'crampon1923','Tu abandonnes ta bouche au mal, et ta langue ourdit la fraude.'),
('ps',50,20,'crampon1923','Tu t''assieds, et tu parles contre ton frère, tu diffames le fils de ta mère.'),
('ps',50,21,'crampon1923','Voilà ce que tu as fait, et je me suis tu. Tu t''es imaginé que j''étais pareil à toi; mais je vais te reprendre et tout mettre sous tes yeux. "'),
('ps',50,22,'crampon1923','Prenez-y donc garde, vous qui oubliez Dieu, de peur que je ne déchire, sans que personne délivre.'),
('ps',50,23,'crampon1923','Celui qui offre en sacrifice l''action de grâces m''honore, et à celui qui dispose sa voie je ferai voir le salut de Dieu.'),
('ps',50,24,'crampon1923',''),
('ps',51,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',51,2,'crampon1923','Lorsque Nathan le prophète vint le trouver, après qu''il fut allé vers Bethsabée.'),
('ps',51,3,'crampon1923','Aie pitié de moi, ô Dieu, selon ta bonté; selon ta grande miséricorde efface mes transgressions.'),
('ps',51,4,'crampon1923','Lave-moi complètement de mon iniquité, et purifie-moi de mon péché.'),
('ps',51,5,'crampon1923','Car je reconnais mes transgressions, et mon péché est constamment devant moi.'),
('ps',51,6,'crampon1923','C''est contre toi seul que j''ai péché, j''ai fait ce qui est mal à tes yeux, afin que tu sois trouvé juste dans ta sentence, sans reproche dans ton jugement.'),
('ps',51,7,'crampon1923','Voici que je suis né dans l''iniquité et ma mère m''a conçu dans le péché.'),
('ps',51,8,'crampon1923','Voici que tu veux que la sincérité soit dans le cœur au dedans de moi fais-moi connaître la sagesse.'),
('ps',51,9,'crampon1923','Purifie-moi avec l''hysope, et je serai pur; lave-moi, et je serai plus blanc que la neige.'),
('ps',51,10,'crampon1923','Annonce-moi la joie et l''allégresse, et les os que tu as brisés se réjouiront.'),
('ps',51,11,'crampon1923','Détourne ta face de mes péchés, efface toutes mes iniquités.'),
('ps',51,12,'crampon1923','O Dieu, crée en moi un cœur pur, et renouvelle au dedans de moi un esprit ferme.'),
('ps',51,13,'crampon1923','Ne me rejette pas loin de ta face, ne me retire pas ton esprit saint.'),
('ps',51,14,'crampon1923','Rends-moi la joie de ton salut, et soutiens-moi par un esprit de bonne volonté.'),
('ps',51,15,'crampon1923','J''enseignerai tes voies à ceux qui les transgressent, et les pécheurs reviendront à toi.'),
('ps',51,16,'crampon1923','O Dieu, Dieu de mon salut, délivre-moi du sang versé, et ma langue célébrera ta justice.'),
('ps',51,17,'crampon1923','Seigneur, ouvre mes lèvres, et ma bouche publiera ta louange.'),
('ps',51,18,'crampon1923','Car tu ne désires pas de sacrifices, — je t''en offrirais, — tu ne prends pas plaisir aux holocaustes.'),
('ps',51,19,'crampon1923','Les sacrifices de Dieu, c''est un esprit brisé; ô Dieu, tu ne dédaignes pas un cœur brisé et contrit.'),
('ps',51,20,'crampon1923','Dans ta bonté, répands tes bienfaits sur Sion, bâtis les murs de Jérusalem!'),
('ps',51,21,'crampon1923','Alors tu agréeras les sacrifices de justice, l''holocauste et le don parfait; alors on offrira des taureaux sur ton autel.'),
('ps',52,1,'crampon1923','Au maître de chant. Cantique de David.'),
('ps',52,2,'crampon1923','Lorsque Doëg l''Edomite vint faire à Saül ce rapport: David s''est rendu dans la maison d''Achimélech.'),
('ps',52,3,'crampon1923','Pourquoi te glorifies-tu dans le mal, ô héros! — La bonté de Dieu subsiste toujours! —'),
('ps',52,4,'crampon1923','Ta langue ne médite que malice, comme une lame affilée, fourbe que tu es!'),
('ps',52,5,'crampon1923','Tu aimes le mal plutôt que le bien, le mensonge plutôt que la droiture. — Séla.'),
('ps',52,6,'crampon1923','Tu aimes toutes les paroles de perdition, ô langue menteuse!'),
('ps',52,7,'crampon1923','Aussi Dieu va te renverser pour toujours, il te saisira et t''arrachera de la tente, il te déracinera de la terre des vivants. — Séla.'),
('ps',52,8,'crampon1923','Les justes le verront et ils seront effrayés, et ils se riront de lui:'),
('ps',52,9,'crampon1923','" Voilà l''homme qui ne prenait pas Dieu pour sa forteresse, mais qui se confiait dans la grandeur de ses richesses, et se faisait fort de sa malice! "'),
('ps',52,10,'crampon1923','Et moi, je suis comme un olivier verdoyant; dans la maison de Dieu, je me confie dans la bonté de Dieu à tout jamais.'),
('ps',52,11,'crampon1923','Je te louerai sans cesse parce que tu as fait cela; et j''espérerai en ton nom, car il est bon, en présence de tes fidèles.'),
('ps',53,1,'crampon1923','Au maître de chant. Sur le ton plaintif. Cantique de David.'),
('ps',53,2,'crampon1923','L''insensé dit dans son cœur: " il n''y a pas de Dieu! " Ils sont corrompus, ils commettent des crimes abominables; il n''en est aucun qui fasse le bien.'),
('ps',53,3,'crampon1923','Dieu, du haut des cieux, regarde les fils de l''homme, pour voir s''il se trouve quelqu''un d''intelligent, quelqu''un qui cherche Dieu.'),
('ps',53,4,'crampon1923','Tous sont égarés, tous sont pervertis; il n''en est aucun qui fasse le bien, pas même un seul.'),
('ps',53,5,'crampon1923','N''ont-ils pas de connaissance ceux qui commettent l''iniquité? Ils dévorent mon peuple comme ils mangent du pain, ils n''invoquent point Dieu!'),
('ps',53,6,'crampon1923','Ils trembleront tout à coup d''épouvante, sans qu''il y ait sujet d''épouvante; car Dieu a dispersé les os de celui qui campait contre toi; tu les as confondus, car Dieu les a rejetés.'),
('ps',53,7,'crampon1923','Oh! puisse venir de Sion la délivrance d''Israël! Quand Dieu ramènera les captifs de son peuple, Jacob se réjouira, Israël sera dans l''allégresse.'),
('ps',54,1,'crampon1923','Au maître de chant. Avec instruments à cordes. Cantique de David.'),
('ps',54,2,'crampon1923','Lorsque les Ziphéens vinrent dire à Saül: David est caché parmi nous.'),
('ps',54,3,'crampon1923','O Dieu, sauve-moi par ton nom, et rends-moi justice par ta puissance.'),
('ps',54,4,'crampon1923','O Dieu, écoute ma prière, prête l''oreille aux paroles de ma bouche.'),
('ps',54,5,'crampon1923','Car des étrangers se sont levés contre moi, des hommes violents en veulent à ma vie; ils ne mettent pas Dieu devant leurs yeux. — Séla.'),
('ps',54,6,'crampon1923','Voici que Dieu est mon secours, le Seigneur est le soutien de mon âme.'),
('ps',54,7,'crampon1923','Il fera retomber le mal sur mes adversaires; dans ta vérité, anéantis-les!'),
('ps',54,8,'crampon1923','De tout cœur je t''offrirai des sacrifices; je louerai ton nom, Yahweh, car il est bon;'),
('ps',54,9,'crampon1923','il me délivre de toute angoisse, et mes yeux s''arrêtent avec joie sur mes ennemis.'),
('ps',55,1,'crampon1923','Au maître de chant, avec instruments à cordes. Cantique de David.'),
('ps',55,2,'crampon1923','O Dieu, prête l''oreille à ma prière, ne te dérobe pas à mes supplications.'),
('ps',55,3,'crampon1923','Ecoute-moi et réponds-moi! J''erre çà et là, plaintif et gémissant,'),
('ps',55,4,'crampon1923','devant les menaces de l''ennemi, devant l''oppression du méchant! Car ils font tomber sur moi le malheur, et ils me poursuivent avec colère.'),
('ps',55,5,'crampon1923','Mon cœur tremble au dedans de moi, et sur moi fondent les terreurs de la mort.'),
('ps',55,6,'crampon1923','La crainte et l''épouvante m''assaillent, et le frisson m''enveloppe.'),
('ps',55,7,'crampon1923','Et je dis: Oh! si j''avais les ailes de la colombe, je m''envolerais et m''établirais en repos;'),
('ps',55,8,'crampon1923','voici que je fuirais bien loin, et je demeurerais au désert; — Séla.'),
('ps',55,9,'crampon1923','je me hâterais de chercher un asile, loin du vent impétueux, loin de l''ouragan.'),
('ps',55,10,'crampon1923','Réduis-les à néant, Seigneur, divise leurs langues! car je vois dans la ville la violence et la discorde.'),
('ps',55,11,'crampon1923','Jour et nuit ils font le tour de ses remparts; l''iniquité et la vexation sont au milieu d''elle,'),
('ps',55,12,'crampon1923','la perversité est dans son sein, l''oppression et l''astuce ne quittent point ses places.'),
('ps',55,13,'crampon1923','Car ce n''est pas un ennemi qui m''outrage: je le supporterais; ce n''est pas un adversaire qui s''élève contre moi: je me cacherais devant lui.'),
('ps',55,14,'crampon1923','Mais toi, tu étais un autre moi-même, mon confident et mon ami.'),
('ps',55,15,'crampon1923','Nous vivions ensemble dans une douce intimité, nous allions avec la foule à la maison de Dieu.'),
('ps',55,16,'crampon1923','Que la mort les surprenne, qu''ils descendent vivants au schéol! Car la méchanceté est dans leur demeure, au milieu d''eux.'),
('ps',55,17,'crampon1923','Pour moi, je crie vers Dieu, et Yahweh me sauvera.'),
('ps',55,18,'crampon1923','Le soir, le matin, au milieu du jour, je me plains, je gémis, et il entendra ma voix.'),
('ps',55,19,'crampon1923','Il délivrera en paix mon âme du combat qui m''est livré, car ils sont nombreux ceux qui me font la guerre.'),
('ps',55,20,'crampon1923','Dieu entendra, et il les humiliera, lui qui siège éternellement sur son trône. — Séla. Car il n''y a point en eux de changement, et ils n''ont pas la crainte de Dieu.'),
('ps',55,21,'crampon1923','il porte la main sur ceux qui étaient en paix avec lui, il viole son alliance.'),
('ps',55,22,'crampon1923','De sa bouche sortent des paroles douces comme le lait, et la guerre est dans son cœur. Ses discours sont plus onctueux que l''huile, mais ce sont des épées nues.'),
('ps',55,23,'crampon1923','Remets ton sort à Yahweh, et il te soutiendra; il ne laissera pas à jamais chanceler le juste.'),
('ps',55,24,'crampon1923','Et toi, ô Dieu, tu les feras descendre dans la fosse de perdition; les hommes de sang et de ruse ne verront pas la moitié de leurs jours. Pour moi, je mets en toi ma confiance.'),
('ps',56,1,'crampon1923','Au maître de chant. Sur la Colombe muette des pays lointains. Hymne de David. Lorsque les Philistins le saisirent à Geth.'),
('ps',56,2,'crampon1923','Aie pitié de moi, ô Dieu, car l''homme s''acharne après moi; tout le jour on me fait la guerre, on me persécute.'),
('ps',56,3,'crampon1923','Tout le jour mes adversaires me harcèlent; car ils sont nombreux ceux qui me combattent le front levé.'),
('ps',56,4,'crampon1923','Quand je suis dans la crainte, je me confie en toi.'),
('ps',56,5,'crampon1923','Par le secours de Dieu, je célébrerai l''accomplissement de sa parole. Je me confie en Dieu, je ne crains rien: que peut me faire un faible mortel?'),
('ps',56,6,'crampon1923','Sans cesse ils enveniment mes paroles, toutes leurs pensées sont contre moi pour me perdre.'),
('ps',56,7,'crampon1923','Ils complotent, ils apostent des espions, ils observent mes traces, parce qu''ils en veulent à ma vie.'),
('ps',56,8,'crampon1923','Chargés de tant de crimes, échapperont-ils? Dans ta colère, ô Dieu, abats les peuples!'),
('ps',56,9,'crampon1923','Tu as compté les pas de ma vie errante, tu as recueilli mes larmes dans ton outre: ne sont-elles pas inscrites dans ton livre?'),
('ps',56,10,'crampon1923','Alors mes ennemis retourneront en arrière, au jour où je t''invoquerai; je le sais, Dieu est pour moi.'),
('ps',56,11,'crampon1923','Par le secours de Dieu, je célébrerai l''accomplissement de sa parole; par le secours de Yahweh, je célébrerai l''accomplissement de sa promesse.'),
('ps',56,12,'crampon1923','Je me confie en Dieu, je ne crains rien: Que peut me faire un faible mortel?'),
('ps',56,13,'crampon1923','Les vœux que je t''ai faits, ô Dieu, j''ai à les acquitter; je t''offrirai des sacrifices d''actions de grâces.'),
('ps',56,14,'crampon1923','Car tu as délivré mon âme de la mort, — n''as-tu pas préservé mes pieds de la chute? — afin que je marche devant Dieu à la lumière des vivants.'),
('ps',57,1,'crampon1923','Au maître de chant. " Ne détruis pas. " Hymne de David, lorsque, poursuivi par Saül, il se réfugia dans la caverne.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ps',57,2,'crampon1923','Aie pitié de moi, ô Dieu, aie pitié de moi, car en toi mon âme cherche un refuge; je m''abriterai à l''ombre de tes ailes, jusqu''à ce que la calamité soit passée.'),
('ps',57,3,'crampon1923','Je crie vers le Dieu Très-Haut, le Dieu qui fait tout pour moi.'),
('ps',57,4,'crampon1923','Il m''enverra du ciel le salut: — mon persécuteur m''accable d''outrages! — Séla. Dieu enverra sa bonté et sa vérité.'),
('ps',57,5,'crampon1923','Je couche au milieu des lions, des hommes qui vomissent la flamme, qui ont pour dents la lance et les flèches, et dont la langue est un glaive tranchant.'),
('ps',57,6,'crampon1923','Elève-toi au-dessus des cieux, ô Dieu, que ta gloire brille par toute la terre!'),
('ps',57,7,'crampon1923','Ils avaient tendu un piège devant mes pas, déjà mon âme se courbait; ils avaient creusé une fosse devant moi: ils y sont tombés! — Séla.'),
('ps',57,8,'crampon1923','Mon cœur est affermi, ô Dieu, mon cœur est affermi; je chanterai et ferai retentir de joyeux instruments.'),
('ps',57,9,'crampon1923','Eveille-toi, ma gloire! Eveillez-vous, ma lyre et ma harpe! Que j''éveille l''aurore!'),
('ps',57,10,'crampon1923','Je te louerai parmi les peuples, Seigneur, je te chanterai parmi les nations.'),
('ps',57,11,'crampon1923','Car ta fidélité atteint jusqu''aux cieux, et ta vérité jusqu''aux nues.'),
('ps',57,12,'crampon1923','Elève-toi au-dessus des cieux, ô Dieu, que ta gloire brille sur toute la terre!'),
('ps',58,1,'crampon1923','Au maître de chant. Ne détruis pas. Hymne de David.'),
('ps',58,2,'crampon1923','Est-ce donc en restant muets que vous rendez la justice? Est-ce selon le droit que vous jugez, fils des hommes?'),
('ps',58,3,'crampon1923','Non: au fond du cœur vous tramez vos desseins iniques, dans le pays vous vendez au poids la violence de vos mains.'),
('ps',58,4,'crampon1923','Les méchants sont pervertis dès le sein maternel, dès leur naissance, les fourbes se sont égarés.'),
('ps',58,5,'crampon1923','Leur venin est semblable au venin du serpent, de la vipère sourde qui ferme ses oreilles,'),
('ps',58,6,'crampon1923','et n''entend pas la voix de l''enchanteur, du charmeur habile dans son art.'),
('ps',58,7,'crampon1923','O Dieu brise leurs dents dans leur bouche; Yahweh, arrache les mâchoires des lionceaux!'),
('ps',58,8,'crampon1923','Qu''ils se dissipent comme le torrent qui s''écoule! S''ils ajustent des flèches, qu''elles s''émoussent!'),
('ps',58,9,'crampon1923','Qu''ils soient comme la limace qui va en se fondant! Comme l''avorton d''une femme, qu''ils ne voient point le soleil!'),
('ps',58,10,'crampon1923','Avant que vos chaudières sentent l''épine, verte ou enflammée, l''ouragan l''emportera.'),
('ps',58,11,'crampon1923','Le juste sera dans la joie, à la vue de la vengeance, il baignera ses pieds dans le sang des méchants.'),
('ps',58,12,'crampon1923','Et l''on dira: " Oui, il y a une récompense pour le juste; oui, il y a un Dieu qui juge sur la terre! "'),
('ps',59,1,'crampon1923','Au maître de chant. Ne détruis pas! Hymne de David. Lorsque Saül envoya garder sa maison pour le mettre à mort.'),
('ps',59,2,'crampon1923','Délivre-moi de mes ennemis, ô mon Dieu, protège-moi contre mes adversaires.'),
('ps',59,3,'crampon1923','Délivre-moi de ceux qui commettent l''iniquité, et sauve-moi des hommes de sang.'),
('ps',59,4,'crampon1923','Car voici qu''ils sont aux aguets pour m''ôter la vie; des hommes violents complotent contre moi; sans que je sois coupable, sans que j''aie péché, Yahweh'),
('ps',59,5,'crampon1923','malgré mon innocence ils accourent et s''embusquent. Éveille-toi, viens au-devant de moi et regarde.'),
('ps',59,6,'crampon1923','Toi, Yahweh, Dieu des armées, Dieu d''Israël, lève-toi pour châtier toutes les nations, sois sans pitié pour ces traîtres et ces malfaiteurs! — Séla.'),
('ps',59,7,'crampon1923','Ils reviennent le soir, ils grondent comme le chien, ils font le tour de la ville.'),
('ps',59,8,'crampon1923','Voici que leur bouche vomit l''injure, il y a des glaives sur leurs lèvres: " Qui est-ce qui entend? " disent-ils.'),
('ps',59,9,'crampon1923','Et toi, Yahweh, tu te ris d''eux, tu te moques de toutes les nations!'),
('ps',59,10,'crampon1923','Ma force, c''est vers toi que je regarderai, car Dieu est ma forteresse.'),
('ps',59,11,'crampon1923','Le Dieu qui m''est propice viendra au-devant de moi; Dieu me fera contempler mes ennemis.'),
('ps',59,12,'crampon1923','Ne les tue pas, de peur que mon peuple n''oublie; fais-les errer par ta puissance et renverse-les, ô Seigneur, notre bouclier.'),
('ps',59,13,'crampon1923','Leur bouche pèche à chaque parole de leurs lèvres; qu''ils soient pris dans leur propre orgueil, à cause des malédictions et des mensonges qu''ils profèrent!'),
('ps',59,14,'crampon1923','Détruis-les dans ta fureur, détruis-les, et qu''ils ne soient plus; qu''ils sachent que Dieu règne sur Jacob, jusqu''aux extrémités de la terre! — Séla.'),
('ps',59,15,'crampon1923','Ils reviennent le soir; ils grondent comme le chien, ils font le tour de la ville.'),
('ps',59,16,'crampon1923','Ils errent çà et là, cherchant leur proie, et ils grognent s''ils ne sont pas rassasiés.'),
('ps',59,17,'crampon1923','Et moi, je chanterai ta force, et le matin je célébrerai ta bonté; car tu es ma forteresse, un refuge au jour de mon angoisse.'),
('ps',59,18,'crampon1923','O ma force, je chanterai en ton honneur, car Dieu est ma forteresse, le Dieu qui m''est propice.'),
('ps',60,1,'crampon1923','Au maître de chant. Sur le Lys du témoignage. Hymne de David, à enseigner.'),
('ps',60,2,'crampon1923','Lorsqu''il fit la guerre aux Syriens de Mésopotamie et aux Syriens de Soba, et que Joab revint et battit Edom dans la vallée du Sel, lui tuant douze mille hommes.'),
('ps',60,3,'crampon1923','O Dieu, tu nous as rejetés, tu nous as dispersés: tu étais irrité: rends-nous ta faveur!'),
('ps',60,4,'crampon1923','Tu as ébranlé le pays, tu l''as déchiré: répare ses brèches, car il chancelle!'),
('ps',60,5,'crampon1923','Tu as fait voir à ton peuple de rudes épreuves, tu nous as fait boire un vin de vertige.'),
('ps',60,6,'crampon1923','Mais tu as donné à ceux qui te craignent une bannière, afin qu''elle s''élève à cause de ta vérité. — Séla.'),
('ps',60,7,'crampon1923','Afin que tes bien-aimés soient délivrés, sauve par ta droite, et exauce-moi.'),
('ps',60,8,'crampon1923','Dieu a parlé dans sa sainteté: " Je tressaillirai de joie. J''aurai Sichem en partage, et je mesurerai la vallée de Succoth.'),
('ps',60,9,'crampon1923','Galaad est à moi, à moi Manassé! Ephraïm est l''armure de ma tête, et Juda mon sceptre.'),
('ps',60,10,'crampon1923','Moab est le bassin où je me lave; sur Edom je jette ma sandale; terre des Philistins, pousse des acclamations en mon honneur! "'),
('ps',60,11,'crampon1923','Qui me mènera à la ville forte? Qui me conduira à Edom?'),
('ps',60,12,'crampon1923','N''est-ce pas toi, ô Dieu, qui nous avais rejetés, ô Dieu, qui ne sortais plus avec nos armées?'),
('ps',60,13,'crampon1923','Prête-nous ton secours contre l''oppresseur! Le secours de l''homme n''est que vanité.'),
('ps',60,14,'crampon1923','Avec Dieu nous accomplirons des exploits; il écrasera nos ennemis.'),
('ps',61,1,'crampon1923','Au maître de chant. Sur les instruments à cordes. De David.'),
('ps',61,2,'crampon1923','O Dieu, entends mes cris, sois attentif à ma prière.'),
('ps',61,3,'crampon1923','De l''extrémité de la terre je crie vers toi, dans l''angoisse de mon cœur; conduis-moi sur le rocher que je ne puis atteindre.'),
('ps',61,4,'crampon1923','Car tu es pour moi un refuge, une tour puissante contre l''ennemi.'),
('ps',61,5,'crampon1923','Je voudrais demeurer à jamais dans ta tente, me réfugier à l''abri de tes ailes! — Séla.'),
('ps',61,6,'crampon1923','Car toi, ô Dieu, tu exauces mes vœux, tu m''as donné l''héritage de ceux qui révèrent ton nom.'),
('ps',61,7,'crampon1923','Ajoute des jours aux jours du roi, que ses années se prolongent d''âge en âge!'),
('ps',61,8,'crampon1923','Qu''il demeure sur le trône éternellement devant Dieu! Ordonne à ta bonté et à ta vérité de le garder!'),
('ps',61,9,'crampon1923','Alors je célébrerai ton nom à jamais, et j''accomplirai mes vœux chaque jour.'),
('ps',62,1,'crampon1923','Au maître de chant... Idithun. Psaume de David.'),
('ps',62,2,'crampon1923','Oui, à Dieu mon âme en paix s''abandonne, de lui vient mon secours.'),
('ps',62,3,'crampon1923','Oui, il est mon rocher et mon salut; il est ma forteresse: je ne serai pas tout à fait ébranlé.'),
('ps',62,4,'crampon1923','Jusques à quand vous jetterez-vous sur un homme, pour l''abattre tous ensemble, comme une clôture qui penche, comme une muraille qui s''écroule?'),
('ps',62,5,'crampon1923','Oui, ils complotent pour le précipiter de sa hauteur; ils se plaisent au mensonge; ils bénissent de leur bouche, et ils maudissent dans leur cœur. — Séla.'),
('ps',62,6,'crampon1923','Oui, ô mon âme, à Dieu abandonne-toi en paix, car de lui vient mon espérance.'),
('ps',62,7,'crampon1923','Oui, il est mon rocher et mon salut; il est ma forteresse: je ne chancellerai point.'),
('ps',62,8,'crampon1923','Sur Dieu reposent mon salut et ma gloire; le rocher de ma force, mon refuge, est en Dieu.'),
('ps',62,9,'crampon1923','En tout temps, ô peuple, confie-toi en lui; épanchez devant lui vos cœurs: Dieu est notre refuge. — Séla.'),
('ps',62,10,'crampon1923','Oui les mortels sont vanité, les fils de l''homme sont mensonge; dans la balance ils monteraient, tous ensemble plus légers qu''un souffle.'),
('ps',62,11,'crampon1923','Ne vous confiez pas dans la violence, et ne mettez pas un vain espoir dans la rapine; Si vos richesses s''accroissent, n''y attachez pas votre cœur.'),
('ps',62,12,'crampon1923','Dieu a dit une parole, ou deux, que j''ai entendues: " La puissance est à Dieu;'),
('ps',62,13,'crampon1923','à toi aussi, Seigneur, la bonté. " Car tu rends à chacun selon ses œuvres.'),
('ps',63,1,'crampon1923','Psaume de David. Lorsqu''il était dans le désert de Juda.'),
('ps',63,2,'crampon1923','O Dieu, tu es mon Dieu, je te cherche dès l''aurore; mon âme a soif de toi, ma chair languit après toi, dans une terre aride, desséchée et sans eau.'),
('ps',63,3,'crampon1923','C''est ainsi que je te contemplais dans le sanctuaire, pour voir ta puissance et ta gloire.'),
('ps',63,4,'crampon1923','Car ta grâce est meilleure que la vie: que mes lèvres célèbrent tes louanges!'),
('ps',63,5,'crampon1923','Ainsi te bénirai-je toute ma vie, en ton nom j''élèverai mes mains.'),
('ps',63,6,'crampon1923','Mon âme est rassasiée, comme de moelle et de graisse, et, la joie sur les lèvres, ma bouche te loue.'),
('ps',63,7,'crampon1923','Quand je pense à toi sur ma couche, je médite sur toi pendant les veilles de la nuit.'),
('ps',63,8,'crampon1923','Car tu es mon secours, et je suis dans l''allégresse à l''ombre de tes ailes.'),
('ps',63,9,'crampon1923','Mon âme est attachée à toi, ta droite me soutient.'),
('ps',63,10,'crampon1923','Mais eux, cherchent à m''ôter la vie: ils iront dans les profondeurs de la terre.'),
('ps',63,11,'crampon1923','On les livrera au glaive, ils seront la proie des chacals.'),
('ps',63,12,'crampon1923','Et le roi se réjouira en Dieu; quiconque jure par lui se glorifiera, car la bouche des menteurs sera fermée.'),
('ps',64,1,'crampon1923','Au maître de Chant. Psaume de David.'),
('ps',64,2,'crampon1923','O Dieu, écoute ma voix, quand je fais entendre mes plaintes; défends ma vie contre un ennemi qui m''épouvante;'),
('ps',64,3,'crampon1923','protège-moi contre les complots des malfaiteurs, contre la troupe soulevée des hommes iniques,'),
('ps',64,4,'crampon1923','qui aiguisent leurs langues comme un glaive, qui préparent leurs flèches — leur parole amère! —'),
('ps',64,5,'crampon1923','pour les décocher dans l''ombre contre l''innocent; ils les décochent contre lui à l''improviste, sans rien craindre.'),
('ps',64,6,'crampon1923','Ils s''affermissent dans leurs desseins pervers, ils se concertent pour tendre leurs pièges; ils disent: " Qui les verra? "'),
('ps',64,7,'crampon1923','Ils ne méditent que forfaits: " Nous sommes prêts, disent-ils, notre plan est bien dressé. " L''intérieur de l''homme et son cœur sont un abîme!'),
('ps',64,8,'crampon1923','Mais Dieu a lancé sur eux ses traits: soudain les voilà blessés!'),
('ps',64,9,'crampon1923','On les jette par terre; les traits de leur langue retombent sur eux! Tous ceux qui les voient branlent la tête!'),
('ps',64,10,'crampon1923','Tous les hommes sont saisis de crainte, ils publient l''œuvre de Dieu, ils comprennent ce qu''il a fait.'),
('ps',64,11,'crampon1923','Le juste se réjouit en Yahweh et se confie en lui, tous ceux qui ont le cœur droit se glorifient.'),
('ps',65,1,'crampon1923','Au maître de chant. Psaume de David. Cantique.'),
('ps',65,2,'crampon1923','A toi est due la louange, ô Dieu, dans Sion; c''est en ton honneur qu''on accomplit les vœux.'),
('ps',65,3,'crampon1923','O toi, qui écoutes la prière, tous les hommes viennent à toi.'),
('ps',65,4,'crampon1923','Un amas d''iniquités pesait sur moi: tu pardonnes nos transgressions.'),
('ps',65,5,'crampon1923','Heureux celui que tu choisis et que tu rapproches de toi, pour qu''il habite dans tes parvis! Puissions-nous être rassasiés des biens de ta maison, de ton saint temple!'),
('ps',65,6,'crampon1923','Par des prodiges, tu nous exauces dans ta justice, Dieu de notre salut, espoir des extrémités de la terre, et des mers lointaines.'),
('ps',65,7,'crampon1923','— Il affermit les montagnes par sa force, il est ceint de sa puissance;'),
('ps',65,8,'crampon1923','il apaise la fureur des mers, la fureur de leurs flots, et le tumulte des peuples. —'),
('ps',65,9,'crampon1923','Les habitants des pays lointains craignent devant tes prodiges, tu réjouis les extrémités, l''Orient et l''Occident.'),
('ps',65,10,'crampon1923','Tu as visité la terre pour lui donner l''abondance, tu la combles de richesses; la source divine est remplie d''eau: tu prépares le blé, quand tu la fertilises ainsi.'),
('ps',65,11,'crampon1923','Arrosant ses sillons, aplanissant ses mottes, tu l''amollis par des ondées, tu bénis ses germes.'),
('ps',65,12,'crampon1923','Tu couronnes l''année de tes bienfaits, sur tes pas ruisselle la graisse.'),
('ps',65,13,'crampon1923','Les pâturages du désert sont abreuvés, et les collines se revêtent d''allégresse.'),
('ps',65,14,'crampon1923','Les prairies se couvrent de troupeaux, et les vallées se parent d''épis; tout se réjouit et chante.'),
('ps',66,1,'crampon1923','Au maître de chant. Cantique. Psaume. Pousse vers Dieu des cris de joie, terre entière!'),
('ps',66,2,'crampon1923','Chantez la gloire de son nom, célébrez magnifiquement ses louanges!'),
('ps',66,3,'crampon1923','Dites à Dieu: " Que tes œuvres sont redoutables! A cause de ta toute-puissance, tes ennemis te flattent.'),
('ps',66,4,'crampon1923','Que toute la terre se prosterne devant toi, qu''elle chante en ton honneur, qu''elle chante ton nom! " — Séla.'),
('ps',66,5,'crampon1923','Venez et contemplez les œuvres de Dieu! Il est redoutable dans ses desseins sur les fils de l''homme.'),
('ps',66,6,'crampon1923','Il a changé la mer en une terre sèche, on a passé le fleuve à pied; alors nous nous réjouîmes en lui.'),
('ps',66,7,'crampon1923','Il règne éternellement par sa puissance; ses yeux observent les nations: que les rebelles ne s''élèvent point! — Séla.'),
('ps',66,8,'crampon1923','Peuples, bénissez notre Dieu, faites retentir sa louange!'),
('ps',66,9,'crampon1923','Il a conservé la vie à notre âme, et n''a pas permis que notre pied chancelât.'),
('ps',66,10,'crampon1923','Car tu nous as éprouvés, ô Dieu, tu nous as fait passer au creuset, comme l''argent.'),
('ps',66,11,'crampon1923','Tu nous as conduits dans le filet, tu as mis sur nos reins un fardeau.'),
('ps',66,12,'crampon1923','Tu as fait marcher des hommes sur nos têtes; nous avons passé par le feu et par l''eau; mais tu nous en as tirés pour nous combler de biens.'),
('ps',66,13,'crampon1923','Je viens dans ta maison avec des holocaustes, pour m''acquitter envers toi de mes vœux,'),
('ps',66,14,'crampon1923','que mes lèvres ont proférés, que ma bouche a prononcés au jour de ma détresse.'),
('ps',66,15,'crampon1923','Je t''offre des brebis grasses en holocauste, avec la fumée des béliers; j''immole le taureau avec le jeune bouc. — Séla.'),
('ps',66,16,'crampon1923','Venez, écoutez, et je vous raconterai, à vous tous qui craignez Dieu, ce qu''il a fait à mon âme.'),
('ps',66,17,'crampon1923','J''ai crié vers lui de ma bouche, et sa louange était sur ma langue.'),
('ps',66,18,'crampon1923','Si j''avais vu l''iniquité dans mon cœur, le Seigneur ne m''exaucerait pas.'),
('ps',66,19,'crampon1923','Mais Dieu m''a exaucé, il a été attentif à la voix de ma prière.'),
('ps',66,20,'crampon1923','Béni soit Dieu, qui n''a pas repoussé ma prière, et n''a pas éloigné de moi sa grâce!'),
('ps',67,1,'crampon1923','Au maître de chant. Avec instruments à cordes. Psaume. Cantique.'),
('ps',67,2,'crampon1923','Que Dieu nous soit favorable et qu''il nous bénisse! qu''il fasse luire sur nous sa face, — Séla.'),
('ps',67,3,'crampon1923','afin que l''on connaisse sur la terre ta voie, et parmi toutes les nations ton salut!'),
('ps',67,4,'crampon1923','Que les peuples te louent, ô Dieu, que les peuples te louent tous!'),
('ps',67,5,'crampon1923','Que les nations se réjouissent, qu''elles soient dans l''allégresse! car tu juges les peuples avec droiture, et tu conduis les nations sur la terre. — Séla.'),
('ps',67,6,'crampon1923','Que les peuples te louent, ô Dieu, que les peuples te louent tous!'),
('ps',67,7,'crampon1923','La terre a donné ses produits; que Dieu, notre Dieu, nous bénisse!'),
('ps',67,8,'crampon1923','Que Dieu nous bénisse, et que toutes les extrémités de la terre le révèrent!'),
('ps',68,1,'crampon1923','Au maître de chant. Psaume de David. Cantique.'),
('ps',68,2,'crampon1923','Que Dieu se lève, et que ses ennemis soient dispersés, et que ceux qui le haïssent fuient devant sa face!'),
('ps',68,3,'crampon1923','Comme se dissipe la fumée, dissipe-les; comme la cire se fond au feu, que les méchants disparaissent devant Dieu!'),
('ps',68,4,'crampon1923','Mais que les justes se réjouissent et tressaillent devant Dieu; qu''ils soient transportés d''allégresse!'),
('ps',68,5,'crampon1923','Chantez à Dieu, célébrez son nom! Frayez le chemin à celui qui s''avance à travers les plaines! Yahweh est son nom; tressaillez devant lui!'),
('ps',68,6,'crampon1923','Il est père des orphelins et juge des veuves, Dieu dans sa sainte demeure.'),
('ps',68,7,'crampon1923','Aux abandonnés Dieu donne une maison; il délivre les captifs et les rend au bonheur; seuls les rebelles restent au désert brûlant.'),
('ps',68,8,'crampon1923','O Dieu, quand tu sortais à la tête de ton peuple, quand tu t''avançais dans le désert, — Séla.'),
('ps',68,9,'crampon1923','la terre fut ébranlée, les cieux eux-mêmes se fondirent devant Dieu; le Sinaï trembla devant Dieu, le Dieu d''Israël.'),
('ps',68,10,'crampon1923','Tu fis tomber, ô Dieu, une pluie de bienfaits; ton héritage était épuisé, tu le réconfortas.'),
('ps',68,11,'crampon1923','Envoyés par toi, des animaux vinrent s''y abattre; dans ta bonté, ô Dieu, tu prépares leur aliment aux malheureux.'),
('ps',68,12,'crampon1923','Le Seigneur a fait entendre sa parole; les femmes qui annoncent la victoire sont une troupe nombreuse.'),
('ps',68,13,'crampon1923','" Les rois des armées fuient, fuient, et celle qui habite la maison partage le butin. "'),
('ps',68,14,'crampon1923','Quand vous étiez couchés au milieu des bercails, les ailes de la colombe étaient recouvertes d''argent, et ses plumes brillaient de l''éclat de l''or.'),
('ps',68,15,'crampon1923','Lorsque le Tout-Puissant dispersait les rois dans le pays, la neige tombait sur le Selmon.'),
('ps',68,16,'crampon1923','Montagne de Dieu, montagne de Basan, montagne aux cimes élevées, montagne de Basan,'),
('ps',68,17,'crampon1923','pourquoi regardez-vous avec envie, montagnes aux cimes élevées, la montagne que Dieu a voulue pour séjour? Oui, Yahweh y habitera à jamais!'),
('ps',68,18,'crampon1923','Le char de Dieu, ce sont des milliers et des milliers; le Seigneur vient du Sinaï dans son sanctuaire.'),
('ps',68,19,'crampon1923','Tu montes sur la hauteur emmenant la foule des captifs; tu reçois les présents des hommes, Même les rebelles habiteront près de Yahweh Dieu!'),
('ps',68,20,'crampon1923','Béni soit le Seigneur! Chaque jour il porte notre fardeau; il est le Dieu qui nous sauve. — Séla.'),
('ps',68,21,'crampon1923','Dieu est pour nous le Dieu des délivrances; Yahweh, le Seigneur, peut retirer de la mort.'),
('ps',68,22,'crampon1923','Oui, Dieu brisera la tête de ses ennemis, le front chevelu de celui qui marche dans l''iniquité.'),
('ps',68,23,'crampon1923','Le Seigneur a dit: " Je les ramènerai de Basan, je les ramènerai du fond de la mer,'),
('ps',68,24,'crampon1923','afin que tu plonges ton pied dans le sang, et que la langue de tes chiens ait sa part des ennemis. "'),
('ps',68,25,'crampon1923','On voit tes marches, ô Dieu, les marches de mon Dieu, de mon roi, au sanctuaire.'),
('ps',68,26,'crampon1923','En avant sont les chanteurs, puis les musiciens, au milieu, des jeunes filles battant du tambourin.'),
('ps',68,27,'crampon1923','" Bénissez Dieu dans les assemblées, le Seigneur, vous qui êtes de la source d''Israël. "'),
('ps',68,28,'crampon1923','Voici Benjamin, le plus petit, qui domine sur eux; voici les princes de Juda avec leur troupe, les princes de Zabulon, les princes de Nephthali.'),
('ps',68,29,'crampon1923','Commande, ô Dieu, à ta puissance, affermis, ô Dieu, ce que tu as fait pour nous.'),
('ps',68,30,'crampon1923','A ton sanctuaire, qui s''élève au-dessus de Jérusalem, les rois t''offriront des présents.'),
('ps',68,31,'crampon1923','Menace la bête des roseaux, la troupe des taureaux avec les veaux des peuples, afin qu''ils se prosternent avec des pièces d''argent. Disperse les nations qui se plaisent aux combats!'),
('ps',68,32,'crampon1923','Que les grands viennent de l''Egypte, que l''Ethiopie s''empresse de tendre les mains vers Dieu.'),
('ps',68,33,'crampon1923','Royaumes de la terre, chantez à Dieu, célébrez le Seigneur! — Séla.'),
('ps',68,34,'crampon1923','Chantez à celui qui est porté sur les cieux, les cieux antiques. Voici qu''il fait entendre sa voix, voix puissante!...'),
('ps',68,35,'crampon1923','Reconnaissez la puissance de Dieu! Sa majesté est sur Israël, et sa puissance est dans les nuées.'),
('ps',68,36,'crampon1923','De ton sanctuaire, ô Dieu, tu es redoutable! Le Dieu d''Israël donne à son peuple force et puissance. Béni soit Dieu!'),
('ps',69,1,'crampon1923','Au maître de chant. Sur les lys. De David.'),
('ps',69,2,'crampon1923','Sauve-moi, ô Dieu, car les eaux montent jusqu''à mon âme.'),
('ps',69,3,'crampon1923','Je suis enfoncé dans une fange profonde, et il n''y a pas où poser le pied. Je suis tombé dans un gouffre d''eau, et les flots me submergent.'),
('ps',69,4,'crampon1923','Je m''épuise à crier; mon gosier est en feu; mes yeux se consument dans l''attente de mon Dieu.'),
('ps',69,5,'crampon1923','Ils sont plus nombreux que les cheveux de ma tête, ceux qui me haïssent sans cause; ils sont puissants ceux qui veulent me perdre, qui sont sans raison mes ennemis. Ce que je n''ai pas dérobé, il faut que je le rende.'),
('ps',69,6,'crampon1923','O Dieu, tu connais ma folie, et mes fautes ne te sont pas cachées.'),
('ps',69,7,'crampon1923','Que ceux qui espèrent en toi n''aient pas à rougir à cause de moi, Seigneur, Yahweh des armées! Que ceux qui te cherchent ne soient pas confondus à mon sujet, Dieu d''Israël!'),
('ps',69,8,'crampon1923','Car c''est pour toi que je porte l''opprobre, que la honte couvre mon visage.'),
('ps',69,9,'crampon1923','Je suis devenu un étranger pour mes frères, un inconnu pour les fils de ma mère.'),
('ps',69,10,'crampon1923','Car le zèle de ta maison me dévore, et les outrages de ceux qui t''insultent retombent sur moi.'),
('ps',69,11,'crampon1923','Je verse des larmes et je jeûne: on m''en fait un sujet d''opprobre.'),
('ps',69,12,'crampon1923','Je prends un sac pour vêtement, et je suis l''objet de leurs sarcasmes.'),
('ps',69,13,'crampon1923','Ceux qui sont assis à la porte parlent de moi, et les buveurs de liqueurs fortes font sur moi des chansons.'),
('ps',69,14,'crampon1923','Et moi, je t''adresse ma prière, Yahweh; dans le temps favorable, ô Dieu, selon ta grande bonté, exauce-moi, selon la vérité de ton salut.'),
('ps',69,15,'crampon1923','Retire-moi de la boue, et que je n''y reste plus enfoncé; que je sois délivré de mes ennemis et des eaux profondes!'),
('ps',69,16,'crampon1923','Que les flots ne me submergent plus, que l''abîme ne m''engloutisse pas, que la fosse ne se ferme pas sur moi!'),
('ps',69,17,'crampon1923','Exauce-moi, Yahweh, car ta bonté est compatissante; dans ta grande miséricorde tourne-toi vers moi,'),
('ps',69,18,'crampon1923','Et ne cache pas ta face à ton serviteur; je suis dans l''angoisse, hâte-toi de m''exaucer.'),
('ps',69,19,'crampon1923','Approche-toi de mon âme, délivre-la; sauve-moi à cause de mes ennemis.'),
('ps',69,20,'crampon1923','Tu connais mon opprobre, ma honte, mon ignominie; tous mes persécuteurs sont devant toi.'),
('ps',69,21,'crampon1923','L''opprobre a brisé mon cœur et je suis malade; j''attends de la pitié, mais en vain; des consolateurs, et je n''en trouve aucun.'),
('ps',69,22,'crampon1923','Pour nourriture ils me donnent l''herbe amère; dans ma soif, ils m''abreuvent de vinaigre.'),
('ps',69,23,'crampon1923','Que leur table soit pour eux un piège, un filet au sein de leur sécurité!'),
('ps',69,24,'crampon1923','Que leurs yeux s''obscurcissent pour ne plus voir; fais chanceler leurs reins pour toujours.'),
('ps',69,25,'crampon1923','Déverse sur eux ta colère, et que le feu de ton courroux les atteigne!'),
('ps',69,26,'crampon1923','Que leur demeure soit dévastée, qu''il n''y ait plus d''habitants dans leurs tentes!'),
('ps',69,27,'crampon1923','Car ils persécutent celui que tu frappes, ils racontent les souffrances de celui que tu blesses.'),
('ps',69,28,'crampon1923','Ajoute l''iniquité à leur iniquité, et qu''ils n''aient point part à ta justice.'),
('ps',69,29,'crampon1923','Qu''ils soient effacés du livre de vie et qu''ils ne soient point inscrits avec les justes.'),
('ps',69,30,'crampon1923','Moi, je suis malheureux et souffrant; que ton secours, ô Dieu, me relève!'),
('ps',69,31,'crampon1923','Je célébrerai le nom de Dieu par des cantiques, je l''exalterai par des actions de grâces;'),
('ps',69,32,'crampon1923','Et Yahweh les aura pour plus agréables qu''un taureau, qu''un jeune taureau avec cornes et sabots.'),
('ps',69,33,'crampon1923','Les malheureux, en le voyant, se réjouiront, et vous qui cherchez Dieu, votre cœur revivra.'),
('ps',69,34,'crampon1923','Car Yahweh écoute les pauvres, et il ne méprise point ses captifs.'),
('ps',69,35,'crampon1923','Que les cieux et la terre le célèbrent, les mers et tout ce qui s''y meut!'),
('ps',69,36,'crampon1923','Car Dieu sauvera Sion et bâtira les villes de Juda, on s''y établira et l''on en prendra possession;'),
('ps',69,37,'crampon1923','La race de ses serviteurs l''aura en héritage, et ceux qui aiment son nom y auront leur demeure.'),
('ps',70,1,'crampon1923','Au maître de chant. De David. Pour faire souvenir.'),
('ps',70,2,'crampon1923','O Dieu, hâte-toi de me délivrer! Seigneur, hâte-toi de me secourir!'),
('ps',70,3,'crampon1923','Qu''ils soient honteux et confus, ceux qui cherchent mon âme! Qu''ils reculent et rougissent ceux qui désirent ma perte!'),
('ps',70,4,'crampon1923','Qu''ils retournent en arrière à cause de leur honte, ceux qui disent: " Ah! ah! "'),
('ps',70,5,'crampon1923','Qu''ils soient dans l''allégresse et se réjouissent en toi tous ceux qui te cherchent! Qu''ils disent sans cesse: " Gloire à Dieu ", ceux qui aiment ton salut!'),
('ps',70,6,'crampon1923','Moi, je suis pauvre et indigent: ô Dieu, hâte-toi vers moi! Tu es mon aide et mon libérateur: Yahweh, ne tarde pas!'),
('ps',71,1,'crampon1923','Yahweh, en toi j''ai placé mon refuge; que jamais je ne sois confondu!'),
('ps',71,2,'crampon1923','Dans ta justice délivre-moi et sauve-moi! Incline vers moi ton oreille et secours-moi!'),
('ps',71,3,'crampon1923','Sois pour moi un rocher inaccessible, où je puisse toujours me retirer. Tu as commandé de me sauver, car tu es mon rocher et ma forteresse.'),
('ps',71,4,'crampon1923','Mon Dieu, délivre-moi de la main du méchant, de la main de l''homme inique et cruel.'),
('ps',71,5,'crampon1923','Car tu es mon espérance, Seigneur Yahweh, l''objet de ma confiance depuis ma jeunesse.'),
('ps',71,6,'crampon1923','C''est sur toi que je m''appuie depuis ma naissance, toi qui m''as fait sortir du sein maternel: tu es ma louange à jamais!'),
('ps',71,7,'crampon1923','Je suis pour la foule comme un prodige, mais toi, tu es mon puissant refuge.'),
('ps',71,8,'crampon1923','Que ma bouche soit pleine de ta louange, que chaque jour elle exalte ta magnificence!'),
('ps',71,9,'crampon1923','Ne me rejette pas aux jours de ma vieillesse; au déclin de mes forces ne m''abandonne pas.'),
('ps',71,10,'crampon1923','Car mes ennemis conspirent contre moi, et ceux qui épient mon âme se concertent entre eux,'),
('ps',71,11,'crampon1923','disant: " Dieu l''a abandonné! Poursuivez-le; saisissez-le; il n''y a personne pour le défendre! "'),
('ps',71,12,'crampon1923','O Dieu, ne t''éloigne pas de moi; mon Dieu, hâte-toi de me secourir!'),
('ps',71,13,'crampon1923','Qu''ils soient confus, qu''ils périssent, ceux qui en veulent à ma vie! Qu''ils soient couverts de honte et d''opprobre, ceux qui cherchent ma perte!'),
('ps',71,14,'crampon1923','Pour moi, j''espérerai toujours; à toutes tes louanges, j''en ajouterai de nouvelles.'),
('ps',71,15,'crampon1923','Ma bouche publiera ta justice, tout le jour tes faveurs; car je n''en connais pas le nombre.'),
('ps',71,16,'crampon1923','Je dirai tes œuvres puissantes, Seigneur Yahweh; je rappellerai ta justice, la tienne seule.'),
('ps',71,17,'crampon1923','O Dieu, tu m''as instruit dès ma jeunesse, et jusqu''à ce jour je proclame tes merveilles.'),
('ps',71,18,'crampon1923','Encore jusqu''à la vieillesse et aux cheveux blancs, O Dieu, ne m''abandonne pas, afin que je fasse connaître ta force à la génération présente, ta puissance à la génération future.'),
('ps',71,19,'crampon1923','Ta justice, ô Dieu, atteint jusqu''au ciel, toi qui accomplis de grandes choses, — ô Dieu, qui est semblable à toi? —'),
('ps',71,20,'crampon1923','toi qui nous a causé des épreuves nombreuses et terribles. Mais tu nous rendras la vie, et des abîmes de la terre tu nous feras remonter.'),
('ps',71,21,'crampon1923','Tu relèveras ma grandeur et de nouveau tu me consoleras.'),
('ps',71,22,'crampon1923','Et je louerai au son du luth, je chanterai ta fidélité, ô mon Dieu, je te célébrerai avec la harpe, Saint d''Israël.'),
('ps',71,23,'crampon1923','L''allégresse sera sur mes lèvres, quand je te chanterai, et dans mon âme, que tu as délivrée.'),
('ps',71,24,'crampon1923','Et ma langue chaque jour publiera ta justice, car ils seront confus et ils rougiront, ceux qui cherchent ma perte.'),
('ps',72,1,'crampon1923','De Salomon. O Dieu, donne tes jugements au roi, et ta justice au fils du roi.'),
('ps',72,2,'crampon1923','Qu''il dirige ton peuple avec justice, et tes malheureux avec équité!'),
('ps',72,3,'crampon1923','Que les montagnes produisent la paix au peuple, ainsi que les collines, par la justice.'),
('ps',72,4,'crampon1923','Qu''il fasse droit aux malheureux de son peuple, qu''il assiste les enfants du pauvre, et qu''il écrase l''oppresseur!'),
('ps',72,5,'crampon1923','Qu''on te révère, tant que subsistera le soleil, tant que brillera la lune, d''âge en âge!'),
('ps',72,6,'crampon1923','Qu''il descende comme la pluie sur le gazon, comme les ondées qui arrosent la terre!'),
('ps',72,7,'crampon1923','Qu''en ses jours le juste fleurisse, avec l''abondance de la paix, jusqu''à ce qu''il n''y ait plus de lune!'),
('ps',72,8,'crampon1923','Il dominera d''une mer à l''autre, du Fleuve aux extrémités de la terre.'),
('ps',72,9,'crampon1923','Devant lui se prosterneront les habitants du désert, et ses ennemis mordront la poussière.'),
('ps',72,10,'crampon1923','Les rois de Tharsis et des îles paieront des tributs; les rois de Saba et de Méroé offriront des présents.'),
('ps',72,11,'crampon1923','Tous les rois se prosterneront devant lui; toutes les nations le serviront.'),
('ps',72,12,'crampon1923','Car il délivrera le pauvre qui crie vers lui, et le malheureux dépourvu de tout secours.'),
('ps',72,13,'crampon1923','Il aura pitié du misérable et de l''indigent, et il sauvera la vie du pauvre.'),
('ps',72,14,'crampon1923','Il les affranchira de l''oppression et de la violence, et leur sang aura du prix à ses yeux.'),
('ps',72,15,'crampon1923','Ils vivront, et lui donneront de l''or de Saba; ils feront sans cesse des vœux pour lui, ils le béniront chaque jour.'),
('ps',72,16,'crampon1923','Que les blés abondent dans le pays, jusqu''au sommet des montagnes! Que leurs épis s''agitent comme les arbres du Liban! Que les hommes fleurissent dans la ville comme l''herbe des champs!'),
('ps',72,17,'crampon1923','Que son nom dure à jamais! Tant que brillera le soleil, que son nom se propage! Qu''on cherche en lui la bénédiction! Que toutes les nations le proclament heureux!'),
('ps',72,18,'crampon1923','Béni soit Yahweh Dieu, le Dieu d''Israël, qui seul fait des prodiges!'),
('ps',72,19,'crampon1923','Béni soit à jamais son nom glorieux! Que toute la terre soit remplie de sa gloire! Amen! Amen!'),
('ps',72,20,'crampon1923','Fin des prières de David, fils d''Isaï.'),
('ps',73,1,'crampon1923','Psaume d''Asaph. Oui, Dieu est bon pour Israël, pour ceux qui ont le cœur pur!'),
('ps',73,2,'crampon1923','Toutefois j''étais sur le point de fléchir, mon pied a presque glissé.'),
('ps',73,3,'crampon1923','Car je m''indignais contre les impies, en voyant le bonheur des méchants.'),
('ps',73,4,'crampon1923','Pour eux, point de douleurs jusqu''à la mort; leur corps est plein de vigueur.'),
('ps',73,5,'crampon1923','Ils n''ont point de part au labeur des mortels, ils ne sont point frappés avec le reste des hommes.'),
('ps',73,6,'crampon1923','Aussi l''orgueil est la parure de leur cou, et la violence, la robe précieuse qui les couvre.'),
('ps',73,7,'crampon1923','L''iniquité sort de leurs entrailles, les pensées de leur cœur se font jour.'),
('ps',73,8,'crampon1923','Ils raillent, ils parlent iniquité et violence, ils profèrent des discours hautains.'),
('ps',73,9,'crampon1923','Ils dirigent leur bouche contre le ciel même, et leur langue s''exerce sur la terre.'),
('ps',73,10,'crampon1923','C''est pourquoi mon peuple se tourne de leur côté, il avale l''eau à grands traits.'),
('ps',73,11,'crampon1923','Ils disent: " Comment Dieu saurait-il? Comment le Très-Haut connaîtrait-il? "'),
('ps',73,12,'crampon1923','Tels sont les méchants: toujours heureux, ils accroissent leurs richesses.'),
('ps',73,13,'crampon1923','C''est donc en vain que j''ai gardé mon cœur pur, que j''ai lavé mes mains dans l''innocence;'),
('ps',73,14,'crampon1923','tout le jour je suis frappé, chaque matin mon châtiment est là. "'),
('ps',73,15,'crampon1923','Si j''avais dit: " Je veux parler comme eux ", j''aurai trahi la race de tes enfants.'),
('ps',73,16,'crampon1923','J''ai réfléchi pour comprendre ces choses, la difficulté a été grande à mes yeux,'),
('ps',73,17,'crampon1923','jusqu''à ce que j''aie pénétré dans le sanctuaire de Dieu, et pris garde à leur sort final.'),
('ps',73,18,'crampon1923','Oui, tu les places sur des voies glissantes; tu les fais tomber, et ils ne sont plus que ruines.'),
('ps',73,19,'crampon1923','Eh quoi! En un instant les voilà détruits! Ils sont anéantis, ils disparaissent dans des catastrophes!'),
('ps',73,20,'crampon1923','Comme on fait d''un songe au réveil, Seigneur, à ton réveil, tu repousses leur image.'),
('ps',73,21,'crampon1923','Lorsque mon cœur s''aigrissait, et que je me sentais profondément ému,'),
('ps',73,22,'crampon1923','j''étais stupide et sans intelligence, j''étais comme une brute devant toi.'),
('ps',73,23,'crampon1923','Mais je serai à jamais avec toi: tu m''as saisi la main droite,'),
('ps',73,24,'crampon1923','par ton conseil tu me conduiras, et tu me recevras ensuite dans la gloire.'),
('ps',73,25,'crampon1923','Quel autre que toi ai-je au ciel? Avec toi, je ne désire rien sur la terre.'),
('ps',73,26,'crampon1923','Ma chair et mon cœur se consument: le rocher de mon cœur et mon partage, c''est Dieu à jamais.'),
('ps',73,27,'crampon1923','Voici que ceux qui s''éloignent de toi périssent; tu extermines tous ceux qui te sont infidèles.'),
('ps',73,28,'crampon1923','Pour moi, être uni à Dieu, c''est mon bonheur; dans le Seigneur Yahweh je mets ma confiance, afin de raconter toutes tes œuvres.'),
('ps',74,1,'crampon1923','Cantique d''Asaph. Pourquoi, ô Dieu, nous as-tu rejetés pour toujours? Pourquoi ta colère est-elle allumée contre le troupeau de ton pâturage?'),
('ps',74,2,'crampon1923','Souviens-toi de ton peuple que tu as acquis aux jours anciens, que tu as racheté pour être la tribu de ton héritage! Souviens-toi de ta montagne de Sion où tu faisais ta résidence,'),
('ps',74,3,'crampon1923','porte tes pas vers ces ruines irréparables; l''ennemi a tout ravagé dans le sanctuaire.'),
('ps',74,4,'crampon1923','Tes adversaires ont rugi au milieu de tes saints parvis; ils ont établi pour emblèmes leurs emblèmes.'),
('ps',74,5,'crampon1923','On les a vus, pareils au bûcheron, qui lève la cognée dans une épaisse forêt.'),
('ps',74,6,'crampon1923','Et maintenant, toutes les sculptures ensemble; ils les ont brisées à coups de hache et de marteau.'),
('ps',74,7,'crampon1923','Ils ont livré au feu ton sanctuaire; ils ont abattu et profané la demeure de ton nom.'),
('ps',74,8,'crampon1923','Ils disaient dans leur cœur: " Détruisons-les tous ensemble! " Ils ont brûlé dans le pays tous les lieux saints.'),
('ps',74,9,'crampon1923','Nous ne voyons plus nos signes; il n''y a plus de prophète, et personne parmi nous qui sache jusques à quand...'),
('ps',74,10,'crampon1923','Jusques à quand, ô Dieu, l''oppresseur insultera-t-il, l''ennemi blasphémera-t-il sans cesse ton nom?'),
('ps',74,11,'crampon1923','Pourquoi retires-tu ta main et ta droite? Tire-la de ton sein et détruis-les!'),
('ps',74,12,'crampon1923','Pourtant Dieu est mon roi dès les temps anciens, lui qui a opéré tant de délivrances sur la terre.'),
('ps',74,13,'crampon1923','C''est toi qui as divisé la mer par ta puissance, toi qui as brisé la tête des monstres dans les eaux.'),
('ps',74,14,'crampon1923','C''est toi qui as écrasé les têtes de Léviathan, et l''as donné en pâture au peuple du désert.'),
('ps',74,15,'crampon1923','C''est toi qui as fait jaillir la source et le torrent, toi qui as mis à sec les fleuves qui ne tarissent pas.'),
('ps',74,16,'crampon1923','A toi est le jour, à toi est la nuit; c''est toi qui as créé la lune et le soleil.'),
('ps',74,17,'crampon1923','C''est toi qui as fixé toutes les limites de la terre; l''été et l''hiver, c''est toi qui les as établis.'),
('ps',74,18,'crampon1923','Souviens-toi: l''ennemi insulte Yahweh, un peuple insensé blasphème ton nom!'),
('ps',74,19,'crampon1923','Ne livre pas aux bêtes l''âme de ta tourterelle, n''oublie pas pour toujours la vie de tes pauvres.'),
('ps',74,20,'crampon1923','Prends garde à ton alliance! car tous les coins du pays sont pleins de repaires de violence.'),
('ps',74,21,'crampon1923','Que l''opprimé ne s''en retourne pas confus, que le malheureux et le pauvre puissent bénir ton nom!'),
('ps',74,22,'crampon1923','Lève-toi, ô Dieu, prends en main ta cause; souviens-toi des outrages que t''adresse chaque jour l''insensé.'),
('ps',74,23,'crampon1923','N''oublie pas les clameurs de tes adversaires, l''insolence toujours croissante de ceux qui te haïssent.'),
('ps',75,1,'crampon1923','Au maître de chant. " Ne détruis pas! " Psaume d''Asaph. Cantique.'),
('ps',75,2,'crampon1923','Nous te louons, ô Dieu, nous te louons; ton nom est proche: on raconte tes merveilles.'),
('ps',75,3,'crampon1923','" Quand le temps sera venu, je jugerai avec justice.'),
('ps',75,4,'crampon1923','La terre est ébranlée avec tous ceux qui l''habitent; moi, j''affermis ses colonnes. " — Séla.'),
('ps',75,5,'crampon1923','Je dis aux orgueilleux: Ne vous enorgueillissez pas! et aux méchants: Ne levez pas la tête!'),
('ps',75,6,'crampon1923','Ne levez pas si haut la tête, ne parlez pas avec tant d''arrogance!'),
('ps',75,7,'crampon1923','Car ce n''est ni de l''orient, ni de l''occident; ni du désert des montagnes!...'),
('ps',75,8,'crampon1923','Non; c''est Dieu qui exerce le jugement: il abaisse l''un et il élève l''autre.'),
('ps',75,9,'crampon1923','Car il y a dans la main de Yahweh une coupe, où bouillonne un vin plein d''aromates. Et il en verse: oui, ils en suceront la lie, ils boiront, tous les méchants de la terre.'),
('ps',75,10,'crampon1923','Et moi, je publierai à jamais, je chanterai les louanges du Dieu de Jacob.'),
('ps',75,11,'crampon1923','Et j''abattrai toutes les cornes des méchants; et les cornes du juste seront élevées.'),
('ps',76,1,'crampon1923','Au maître de chant. Avec instruments à cordes. Psaume d''Asaph, cantique.'),
('ps',76,2,'crampon1923','Dieu s''est fait connaître en Juda, en Israël son nom est grand.'),
('ps',76,3,'crampon1923','Il a son tabernacle à Salem, et sa demeure en Sion.'),
('ps',76,4,'crampon1923','C''est là qu''il a brisé les éclairs de l''arc, le bouclier, l''épée et la guerre. — Séla.'),
('ps',76,5,'crampon1923','Tu resplendis dans ta majesté, sur les montagnes d''où tu fonds sur ta proie.'),
('ps',76,6,'crampon1923','Ils ont été dépouillés, ces héros pleins de cœur; ils se sont endormis de leur sommeil, ils n''ont pas su, tous ces vaillants, se servir de leurs bras.'),
('ps',76,7,'crampon1923','A ta menace, Dieu de Jacob, char et coursier sont restés immobiles.'),
('ps',76,8,'crampon1923','Tu es redoutable, toi! Qui peut se tenir devant toi, quand ta colère éclate?'),
('ps',76,9,'crampon1923','Du haut du ciel tu as proclamé la sentence; la terre a tremblé et s''est tue,'),
('ps',76,10,'crampon1923','lorsque Dieu s''est levé pour faire justice, pour sauver tous les malheureux du pays. — Séla.'),
('ps',76,11,'crampon1923','Ainsi la fureur de l''homme tourne à la gloire et les restes de la colère...'),
('ps',76,12,'crampon1923','Faites des vœux et acquittez-les à Yahweh, votre Dieu; que tous ceux qui l''environnent apportent des dons au Dieu terrible!'),
('ps',76,13,'crampon1923','Il abat l''orgueil des puissants, il est redoutable aux rois de la terre.'),
('ps',77,1,'crampon1923','Au maître de chant,... Idithun. Psaume d''Asaph.'),
('ps',77,2,'crampon1923','Ma voix s''élève vers Dieu, et je crie; ma voix s''élève vers Dieu: qu''il m''entende!'),
('ps',77,3,'crampon1923','Au jour de ma détresse, je cherche le Seigneur; mes mains sont étendues la nuit sans se lasser; mon âme refuse toute consolation.'),
('ps',77,4,'crampon1923','Je me souviens de Dieu, et je gémis; je médite, et mon esprit est abattu. — Séla.'),
('ps',77,5,'crampon1923','Tu tiens mes paupières ouvertes; et, dans mon agitation, je ne puis parler.'),
('ps',77,6,'crampon1923','Alors je pense aux jours anciens, aux années d''autrefois.'),
('ps',77,7,'crampon1923','Je me rappelle mes cantiques pendant la nuit, je réfléchis au dedans de mon cœur, et mon esprit se demande:'),
('ps',77,8,'crampon1923','" Le Seigneur rejettera-t-il pour toujours, ne sera-t-il plus favorable?'),
('ps',77,9,'crampon1923','Sa bonté est-elle épuisée pour jamais, en est-ce fait de ses promesses pour les âges futurs?'),
('ps',77,10,'crampon1923','Dieu a-t-il oublié sa clémence, a-t-il, dans sa colère, retiré sa miséricorde? " — Séla.'),
('ps',77,11,'crampon1923','Je dis: " Ce qui fait ma souffrance, c''est que la droite du Très-Haut a changé! "'),
('ps',77,12,'crampon1923','Je veux rappeler les œuvres de Yahweh, car je me souviens de tes merveilles d''autrefois,'),
('ps',77,13,'crampon1923','Je veux réfléchir sur toutes tes œuvres, et méditer sur tes hauts faits.'),
('ps',77,14,'crampon1923','O Dieu, tes voies sont saintes: quel Dieu est grand comme notre Dieu?'),
('ps',77,15,'crampon1923','Tu es le Dieu qui fait des prodiges; tu as manifesté ta puissance parmi les nations.'),
('ps',77,16,'crampon1923','Par ton bras, tu as délivré ton peuple, les fils de Jacob et de Joseph. — Séla.'),
('ps',77,17,'crampon1923','Les eaux t''ont vu, ô Dieu, les eaux t''ont vu, et elles ont tremblé; les abîmes se sont émus.'),
('ps',77,18,'crampon1923','Les nuées déversèrent leurs eaux, les nues firent entendre leur voix, et tes flèches volèrent de toutes parts.'),
('ps',77,19,'crampon1923','Ton tonnerre retentit dans le tourbillon; les éclairs illuminèrent le monde; la terre frémit et trembla.'),
('ps',77,20,'crampon1923','La mer fut ton chemin, les grandes eaux ton sentier, et l''on ne put reconnaître tes traces.'),
('ps',77,21,'crampon1923','Tu as conduit ton peuple comme un troupeau, par la main de Moïse et d''Aaron.'),
('ps',78,1,'crampon1923','Cantique d''Asaph. Ecoute, ô mon peuple, mon enseignement; prête l''oreille aux paroles de ma bouche.'),
('ps',78,2,'crampon1923','Je vais ouvrir ma bouche pour dire des sentences, je publierai les mystères des temps anciens.'),
('ps',78,3,'crampon1923','Ce que nous avons entendu, ce que nous avons appris, ce que nos pères nous ont raconté,'),
('ps',78,4,'crampon1923','nous ne le cacherons pas à leurs enfants; nous dirons à la génération future les louanges de Yahweh, et sa puissance, et les prodiges qu''il a opérés.'),
('ps',78,5,'crampon1923','Il a mis une règle en Jacob, il a établi une loi en Israël, qu''il a enjoint à nos pères d''apprendre à leurs enfants,'),
('ps',78,6,'crampon1923','pour qu''elles soient connues des générations suivantes, des enfants qui naîtraient et qui se lèveraient, pour les raconter à leur tour à leurs enfants.'),
('ps',78,7,'crampon1923','Ainsi ils mettraient en Dieu leur confiance, ils n''oublieraient point les œuvres de Dieu, et ils observeraient ses préceptes;'),
('ps',78,8,'crampon1923','ils ne seraient point, comme leurs pères, une race indocile et rebelle, une race au cœur volage, dont l''esprit n''est pas fidèle à Dieu.'),
('ps',78,9,'crampon1923','Les fils d''Ephraïm, archers habiles à tirer de l''arc, ont tourné le dos au jour du combat;'),
('ps',78,10,'crampon1923','ils n''ont pas gardé l''alliance de Dieu, ils ont refusé de marcher selon sa loi;'),
('ps',78,11,'crampon1923','ils ont mis en oubli ses grandes œuvres, et les merveilles qu''il leur avait montrées.'),
('ps',78,12,'crampon1923','Devant leurs pères, il avait fait des prodiges, au pays de l''Egypte, dans les campagnes de Tanis.'),
('ps',78,13,'crampon1923','Il ouvrit la mer pour les faire passer; Il retint les eaux dressées comme un monceau'),
('ps',78,14,'crampon1923','Il les conduisit le jour par la nuée, et toute la nuit par un feu brillant.'),
('ps',78,15,'crampon1923','Il fendit les rochers dans le désert, et il donna à boire comme des flots abondants.'),
('ps',78,16,'crampon1923','Du rocher il fit jaillir des ruisseaux, et couler l''eau par torrents.'),
('ps',78,17,'crampon1923','Mais ils continuèrent de pécher contre lui, de se révolter contre le Très-Haut dans le désert.'),
('ps',78,18,'crampon1923','Ils tentèrent Dieu dans leur cœur, en demandant de la nourriture selon leur convoitise.'),
('ps',78,19,'crampon1923','Ils parlèrent contre Dieu et dirent: " Dieu pourra-t-il dresser une table dans le désert?'),
('ps',78,20,'crampon1923','Voici qu''il a frappé le rocher, et des eaux ont coulé, et des torrents se sont répandus; pourra-t-il aussi nous donner du pain ou bien procurer de la viande à son peuple? "'),
('ps',78,21,'crampon1923','Yahweh entendit et il fut irrité, un feu s''alluma contre Jacob, et la colère s''éleva contre Israël,'),
('ps',78,22,'crampon1923','parce qu''ils n''avaient pas eu foi en Dieu et n''avaient pas espéré en son secours.'),
('ps',78,23,'crampon1923','Cependant il commanda aux nuées d''en haut, et il ouvrit les portes du ciel;'),
('ps',78,24,'crampon1923','il fit pleuvoir sur eux la manne pour les nourrir, et leur donna le froment du ciel.'),
('ps',78,25,'crampon1923','Chacun mangea le pain des forts, Il leur envoya de la nourriture à satiété.'),
('ps',78,26,'crampon1923','Il fit souffler dans le ciel le vent d''orient, il amena par sa puissance le vent du midi;'),
('ps',78,27,'crampon1923','il fit pleuvoir sur eux la viande comme de la poussière, et les oiseaux ailés comme le sable des mers.'),
('ps',78,28,'crampon1923','Il les fit tomber au milieu de leur camp, autour de leurs tentes.'),
('ps',78,29,'crampon1923','Ils mangèrent et se rassasièrent à l''excès; Dieu leur donna ce qu''ils avaient désiré.'),
('ps',78,30,'crampon1923','Ils n''avaient pas encore satisfait leur convoitise, et leur nourriture était encore à leur bouche,'),
('ps',78,31,'crampon1923','quand la colère de Dieu s''éleva contre eux; il frappa de mort les mieux repus, il abattit les jeunes hommes d''Israël.'),
('ps',78,32,'crampon1923','Après tout cela, ils péchèrent encore, et n''eurent pas foi dans ses prodiges.'),
('ps',78,33,'crampon1923','Alors il dissipa leurs jours comme un souffle, et leurs années par une fin soudaine.'),
('ps',78,34,'crampon1923','Quand il les frappait de mort, ils le cherchaient, ils revenaient, empressés à retrouver Dieu,'),
('ps',78,35,'crampon1923','ils se rappelaient que Dieu était leur rocher, et le Dieu Très-Haut leur libérateur.'),
('ps',78,36,'crampon1923','Mais ils le trompaient par leurs paroles, et leur langue lui mentait;'),
('ps',78,37,'crampon1923','leur cœur n''était pas ferme avec lui, ils n''étaient pas fidèles à son alliance.'),
('ps',78,38,'crampon1923','Mais lui est miséricordieux: il pardonne le péché et ne détruit pas; souvent il retint sa colère, et ne se livra pas à toute sa fureur.'),
('ps',78,39,'crampon1923','Il se souvenait qu''ils n''étaient que chair, un souffle qui s''en va et ne revient plus.'),
('ps',78,40,'crampon1923','Que de fois ils se révoltèrent contre lui dans le désert, ils l''irritèrent dans la solitude!'),
('ps',78,41,'crampon1923','Ils ne cessèrent de tenter Dieu et de provoquer le Saint d''Israël.'),
('ps',78,42,'crampon1923','Ils ne se souvinrent plus de sa puissance, du jour où il les délivra de l''oppresseur,'),
('ps',78,43,'crampon1923','où il montra ses prodiges en Egypte, ses actions merveilleuses dans les campagnes de Tanis.'),
('ps',78,44,'crampon1923','Il changea leurs fleuves en sang, et ils ne purent boire à leurs ruisseaux.'),
('ps',78,45,'crampon1923','Il envoya contre eux le moucheron qui les dévora, et la grenouille qui les fit périr.'),
('ps',78,46,'crampon1923','Il livra leurs récoltes à la sauterelle, le produit de leur travail à ses essaims.'),
('ps',78,47,'crampon1923','Il détruisit leurs vignes par la grêle, et leurs sycomores par les grêlons.'),
('ps',78,48,'crampon1923','Il abandonna leur bétail à la grêle, et leurs troupeaux aux coups de la foudre.'),
('ps',78,49,'crampon1923','Il déchaîna contre eux le feu de son courroux, la fureur, la rage et la détresse, toute une armée d''anges de malheur.'),
('ps',78,50,'crampon1923','Il donna libre carrière à sa colère, il ne sauva pas leur âme de la mort, il livra leur vie à la destruction.'),
('ps',78,51,'crampon1923','Il frappa tous les premiers-nés en Egypte, les prémices de la force sous les tentes de Cham.'),
('ps',78,52,'crampon1923','Il fit partir son peuple comme des brebis, il les mena comme un troupeau dans le désert.'),
('ps',78,53,'crampon1923','Il les dirigea sûrement, sans qu''ils eussent rien à craindre, et la mer engloutit leurs ennemis.'),
('ps',78,54,'crampon1923','Il les fit arriver jusqu''à sa frontière sainte, jusqu''à la montagne que sa droite a conquise.'),
('ps',78,55,'crampon1923','Il chassa les nations devant eux, leur assigna par le sort leur part d''héritage, et fit habiter dans leurs tentes les tribus d''Israël.'),
('ps',78,56,'crampon1923','Cependant ils ont encore tenté et provoqué le Dieu Très-Haut, et ils n''ont pas observé ses ordonnances.'),
('ps',78,57,'crampon1923','Ils se sont détournés et ont été infidèles comme leurs pères, ils se sont détournés comme un arc trompeur.'),
('ps',78,58,'crampon1923','Ils l''ont irrité par leurs hauts lieux, ils ont excité sa jalousie par leurs idoles.'),
('ps',78,59,'crampon1923','Dieu entendit et s''indigna, il prit Israël en grande aversion.'),
('ps',78,60,'crampon1923','Il dédaigna la demeure de Silo, la tente où il habitait parmi les hommes.'),
('ps',78,61,'crampon1923','Il livra sa force à la captivité, et sa majesté aux mains de l''ennemi.'),
('ps',78,62,'crampon1923','Il abandonna son peuple au glaive, et il s''indigna contre son héritage.'),
('ps',78,63,'crampon1923','Le feu dévora ses jeunes hommes, et ses vierges n''entendirent point le chant nuptial.'),
('ps',78,64,'crampon1923','Ses prêtres tombèrent par l''épée, et ses veuves ne se lamentèrent point.'),
('ps',78,65,'crampon1923','Le Seigneur se réveilla, comme un homme endormi, pareil au guerrier subjugué par le vin.'),
('ps',78,66,'crampon1923','Il frappa ses ennemis par derrière, il leur infligea une honte éternelle.'),
('ps',78,67,'crampon1923','Mais il prit en aversion la tente de Joseph, et il répudia la tribu d''Ephraïm.'),
('ps',78,68,'crampon1923','Il choisit la tribu de Juda, la montagne de Sion qu''il aimait.'),
('ps',78,69,'crampon1923','Et il bâtit son sanctuaire comme les hauteurs du ciel, comme la terre qu''il a fondée pour toujours.'),
('ps',78,70,'crampon1923','Il choisit David, son serviteur, et le tira des bergeries;'),
('ps',78,71,'crampon1923','Il le prit derrière les brebis mères, pour paître Jacob, son peuple, et Israël, son héritage.'),
('ps',78,72,'crampon1923','Et David les guida dans la droiture de son cœur, et il les conduisit d''une main habile.'),
('ps',79,1,'crampon1923','Psaume d''Asaph. O Dieu, les nations ont envahi ton héritage, elles ont profané ton saint temple, elles ont fait de Jérusalem un monceau de pierres.'),
('ps',79,2,'crampon1923','Elles ont livré les cadavres de tes serviteurs en pâture aux oiseaux du ciel, et la chair de tes fidèles aux bêtes de la terre.'),
('ps',79,3,'crampon1923','Elles ont versé leur sang comme de l''eau, tout autour de Jérusalem, et personne pour leur donner la sépulture!'),
('ps',79,4,'crampon1923','Nous sommes devenus un objet d''opprobre pour nos voisins, de risée et de moquerie pour ceux qui nous entourent.'),
('ps',79,5,'crampon1923','Jusques à quand, Yahweh, seras-tu irrité pour toujours, et ta colère s''allumera-t-elle comme le feu?'),
('ps',79,6,'crampon1923','Répands ta fureur sur les nations qui ne te connaissent pas, sur les royaumes qui n''invoquent pas ton nom.'),
('ps',79,7,'crampon1923','Car ils ont dévoré Jacob, et ravagé sa demeure.'),
('ps',79,8,'crampon1923','Ne te souviens plus contre nous des iniquités de nos pères; que ta compassion vienne en hâte au-devant de nous, car notre misère est au comble.'),
('ps',79,9,'crampon1923','Secours-nous, Dieu de notre salut, pour la gloire de ton nom, délivre-nous et pardonne nos péchés à cause de ton nom.'),
('ps',79,10,'crampon1923','Pourquoi les nations diraient-elles: " Où est leur Dieu? " Qu''on connaisse parmi les nations, et sous nos yeux, la vengeance que tu tires du sang de tes serviteurs, quand il est répandu!'),
('ps',79,11,'crampon1923','Que les gémissements des captifs montent jusqu''à toi; selon la grandeur de ton bras, sauve ceux qui vont périr!'),
('ps',79,12,'crampon1923','Fais retomber sept fois dans le sein de nos voisins les outrages qu''ils t''ont faits, Seigneur!'),
('ps',79,13,'crampon1923','Et nous, ton peuple, le troupeau de ton pâturage, nous te rendrons gloire à jamais; d''âge en âge, nous publierons tes louanges.'),
('ps',80,1,'crampon1923','Au maître de chant. Sur les lis du témoignage. Psaume d''Asaph.'),
('ps',80,2,'crampon1923','Pasteur d''Israël, prête l''oreille, toi qui conduis Joseph comme un troupeau; toi qui trônes sur les Chérubins, parais avec splendeur.'),
('ps',80,3,'crampon1923','Devant Ephraïm, Benjamin et Manassé, réveille ta force, et viens à notre secours.'),
('ps',80,4,'crampon1923','O Dieu, rétablis-nous; fais briller ta face, et nous serons sauvés.'),
('ps',80,5,'crampon1923','Yahweh, Dieu des armées, jusques à quand seras-tu irrité contre la prière de ton peuple?'),
('ps',80,6,'crampon1923','Tu les as nourris d''un pain de larmes, tu les as abreuvés de larmes abondantes.'),
('ps',80,7,'crampon1923','Tu as fait de nous un objet de dispute pour nos voisins, et nos ennemis se raillent de nous.'),
('ps',80,8,'crampon1923','Dieu des armées, rétablis-nous; fais briller sur nous ta face, et nous serons sauvés.'),
('ps',80,9,'crampon1923','Tu as arraché de l''Egypte une vigne; tu as chassé les nations et tu l''as plantée.'),
('ps',80,10,'crampon1923','Tu as ménagé de la place devant elle, elle a enfoncé ses racines et rempli la terre.'),
('ps',80,11,'crampon1923','Son ombre couvrait les montagnes, et ses rameaux les cèdres de Dieu;'),
('ps',80,12,'crampon1923','elle étendait ses branches jusqu''à la Mer, et ses rejetons jusqu''au Fleuve.'),
('ps',80,13,'crampon1923','Pourquoi as-tu rompu ses clôtures, en sorte que tous les passants la dévastent?'),
('ps',80,14,'crampon1923','Le sanglier de la forêt la dévore, et les bêtes des champs en font leur pâture.'),
('ps',80,15,'crampon1923','Dieu des armées, reviens, regarde du haut du ciel et vois, considère cette vigne!'),
('ps',80,16,'crampon1923','Protège ce que ta droite a planté, et le fils que tu t''es choisi!...'),
('ps',80,17,'crampon1923','Elle est brûlée par le feu, elle est coupée; devant ta face menaçante, tout périt.'),
('ps',80,18,'crampon1923','Que ta main soit sur l''homme de ta droite, sur le fils de l''homme que tu t''es choisi.'),
('ps',80,19,'crampon1923','Et nous ne nous éloignerons plus de toi; rends-nous la vie, et nous invoquerons ton nom.'),
('ps',80,20,'crampon1923','Yahweh, Dieu des armées, rétablis-nous; fais briller sur nous ta face, et nous serons sauvés.'),
('ps',81,1,'crampon1923','Au maître de chant. Sur la Gitthienne. D''Asaph.'),
('ps',81,2,'crampon1923','Chantez avec allégresse en l''honneur de Dieu, notre force; poussez des cris de joie en l''honneur du Dieu de Jacob!'),
('ps',81,3,'crampon1923','Entonnez l''hymne, au son du tambourin, de la harpe harmonieuse et du luth!'),
('ps',81,4,'crampon1923','Sonnez de la trompette à la nouvelle lune, à la pleine lune, pour le jour de notre fête.'),
('ps',81,5,'crampon1923','Car c''est un précepte pour Israël, une ordonnance du Dieu de Jacob.'),
('ps',81,6,'crampon1923','Il en fit une loi pour Joseph, quand il marcha contre le pays d''Egypte. J''entends une voix qui m''est inconnue:'),
('ps',81,7,'crampon1923','" J''ai déchargé son épaule du fardeau, et ses mains ont quitté la corbeille.'),
('ps',81,8,'crampon1923','Tu as crié dans la détresse, et je t''ai délivré; je t''ai répondu du sein de la nuée orageuse; je t''ai éprouvé aux eaux de Mériba. — Séla.'),
('ps',81,9,'crampon1923','" Ecoute, mon peuple, je veux te donner un avertissement; Israël, puisses-tu m''écouter!'),
('ps',81,10,'crampon1923','Qu''il n''y ait point au milieu de toi de dieu étranger: n''adore pas le dieu d''un autre peuple.'),
('ps',81,11,'crampon1923','" C''est moi, Yahweh, ton Dieu, qui t''ai fait monter du pays d''Egypte. Ouvre la bouche, et je la remplirai.'),
('ps',81,12,'crampon1923','" Mais mon peuple n''a pas écouté ma voix, Israël ne m''a pas obéi.'),
('ps',81,13,'crampon1923','Alors je l''ai abandonné à l''endurcissement de son cœur, et ils ont suivi leurs propres conseils.'),
('ps',81,14,'crampon1923','" Ah! si mon peuple m''écoutait, si Israël marchait dans mes voies!...'),
('ps',81,15,'crampon1923','Bientôt je confondrais leurs ennemis; je tournerais ma main contre leurs oppresseurs.'),
('ps',81,16,'crampon1923','" Ceux qui haïssent Yahweh le flatteraient, et la durée d''Israël serait assurée pour toujours.'),
('ps',81,17,'crampon1923','Je le nourrirais de la fleur de froment, et je le rassasierais du miel du rocher. "'),
('ps',82,1,'crampon1923','Cantique d''Asaph. Dieu se tient dans l''assemblée du Tout-Puissant; au milieu des dieux il rend son arrêt:'),
('ps',82,2,'crampon1923','" Jusques à quand jugerez-vous injustement, et prendrez-vous parti pour les méchants? — Séla.'),
('ps',82,3,'crampon1923','" Rendez justice au faible et à l''orphelin, faites droit au malheureux et au pauvre,'),
('ps',82,4,'crampon1923','sauvez le misérable et l''indigent, délivrez-les de la main des méchants.'),
('ps',82,5,'crampon1923','" Ils n''ont ni savoir ni intelligence, ils marchent dans les ténèbres; tous les fondements de la terre sont ébranlés.'),
('ps',82,6,'crampon1923','" J''ai dit: Vous êtes des dieux, vous êtes tous les fils du Très-Haut.'),
('ps',82,7,'crampon1923','Cependant, vous mourrez comme des hommes, vous tomberez comme le premier venu des princes. "'),
('ps',82,8,'crampon1923','Lève-toi, ô Dieu, juge la terre, car toutes les nations t''appartiennent.'),
('ps',83,1,'crampon1923','Cantique. Psaume d''Asaph.'),
('ps',83,2,'crampon1923','O Dieu, ne reste pas dans l''inaction; ne te tais pas et ne te repose pas, ô Dieu!'),
('ps',83,3,'crampon1923','Car voici que tes ennemis s''agitent bruyamment, ceux qui te haïssent lèvent la tête.'),
('ps',83,4,'crampon1923','Ils forment contre ton peuple un dessein perfide, ils conspirent contre ceux que tu protèges:'),
('ps',83,5,'crampon1923','" Venez, disent-ils, exterminons-les d''entre les nations, et qu''on ne prononce plus le nom d''Israël! "'),
('ps',83,6,'crampon1923','Ils se concertent tous d''un même cœur, contre toi ils forment une alliance,'),
('ps',83,7,'crampon1923','les tentes d''Edom et les Ismaélites, Moab et les Agaréniens,'),
('ps',83,8,'crampon1923','Gébal, Ammon et Amalec, les Philistins avec les habitants de Tyr;'),
('ps',83,9,'crampon1923','Assur aussi se joint à eux et prête son bras aux enfants de Lot. — Séla.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ps',83,10,'crampon1923','Traite-les comme Madian, comme Sisara, comme Jabin au torrent de Cison.'),
('ps',83,11,'crampon1923','Ils ont été anéantis à Endor, ils ont servi d''engrais à la terre.'),
('ps',83,12,'crampon1923','Traite leurs chefs comme Oreb et Zeb, et tous leurs princes comme Zébée et Salmana.'),
('ps',83,13,'crampon1923','Car ils disent: " Emparons-nous des demeures de Dieu! "'),
('ps',83,14,'crampon1923','Mon Dieu, rends-les semblables au tourbillon, au chaume qu''emporte le vent!'),
('ps',83,15,'crampon1923','Comme le feu dévore la forêt, comme la flamme embrase les montagnes,'),
('ps',83,16,'crampon1923','ainsi poursuis-les dans ta tempête, épouvante-les dans ton ouragan.'),
('ps',83,17,'crampon1923','Couvre leurs faces d''ignominie, afin qu''ils cherchent ton nom, Yahweh.'),
('ps',83,18,'crampon1923','Qu''ils soient à jamais dans la confusion et l''épouvante, dans la honte et dans la ruine!'),
('ps',83,19,'crampon1923','Qu''ils sachent que toi, — ton nom est Yahweh, — tu es seul le Très-Haut sur toute la terre!'),
('ps',84,1,'crampon1923','Au maître de chant. Sur la Gitthienne. Psaume des fils de Coré.'),
('ps',84,2,'crampon1923','Que tes demeures sont aimables, Yahweh des armées!'),
('ps',84,3,'crampon1923','Mon âme s''épuise en soupirant après les parvis de Yahweh; mon cœur et ma chair tressaillent vers le Dieu vivant.'),
('ps',84,4,'crampon1923','Le passereau même trouve une demeure, et l''hirondelle un nid où elle repose ses petits: Tes autels, Yahweh des armées, mon roi et mon Dieu!'),
('ps',84,5,'crampon1923','Heureux ceux qui habitent ta maison! Ils peuvent te louer encore. — Séla.'),
('ps',84,6,'crampon1923','Heureux les hommes qui ont en toi leur force; ils ne pensent qu''aux saintes montées.'),
('ps',84,7,'crampon1923','Lorsqu''ils traversent la vallée des Larmes ils la changent en un lieu plein de sources, et la pluie d''automne la couvre aussi de bénédictions.'),
('ps',84,8,'crampon1923','Pendant la marche s''accroît la vigueur, et ils paraissent devant Dieu à Sion:'),
('ps',84,9,'crampon1923','" Yahweh, Dieu des armées, disent-ils, écoute ma prière; prête l''oreille, Dieu de Jacob. " — Séla.'),
('ps',84,10,'crampon1923','Toi qui es notre bouclier, vois, ô Dieu, et regarde la face de ton Oint!'),
('ps',84,11,'crampon1923','Car un jour dans tes parvis vaut mieux que mille; je préfère me tenir sur le seuil de la maison de mon Dieu, plutôt que d''habiter sous les tentes des méchants.'),
('ps',84,12,'crampon1923','Car Yahweh Dieu est un soleil et un bouclier; Yahweh donne la grâce et la gloire, il ne refuse aucun bien à ceux qui marchent dans l''innocence.'),
('ps',84,13,'crampon1923','Yahweh des armées, heureux celui qui se confie en toi!'),
('ps',85,1,'crampon1923','Au maître de chant. Psaume des fils de Coré.'),
('ps',85,2,'crampon1923','Tu as été favorable à ton pays, Yahweh, tu as ramené les captifs de Jacob;'),
('ps',85,3,'crampon1923','tu as pardonné l''iniquité à ton peuple, tu as couvert tous ses péchés; — Séla.'),
('ps',85,4,'crampon1923','tu as retiré toute ton indignation, tu es revenu de l''ardeur de ta colère.'),
('ps',85,5,'crampon1923','Rétablis-nous, Dieu de notre salut; mets fin à ton sentiment contre nous.'),
('ps',85,6,'crampon1923','Seras-tu toujours irrité contre nous, prolongeras-tu ton courroux éternellement?'),
('ps',85,7,'crampon1923','Ne nous feras-tu pas revenir à la vie, afin que ton peuple se réjouisse en toi?'),
('ps',85,8,'crampon1923','Yahweh, fais-nous voir ta bonté, et accorde-nous ton salut.'),
('ps',85,9,'crampon1923','Je veux écouter ce que dira le Dieu Yahweh: — Il a des paroles de paix pour son peuple et pour ses fidèles; pourvu qu''ils ne retournent pas à leur folie. —'),
('ps',85,10,'crampon1923','Oui, son salut est proche de ceux qui le craignent, et la gloire habitera de nouveau dans notre pays.'),
('ps',85,11,'crampon1923','La bonté et la vérité vont se rencontrer, la justice et la paix s''embrasseront.'),
('ps',85,12,'crampon1923','La vérité germera de la terre, et la justice regardera du haut du ciel.'),
('ps',85,13,'crampon1923','Yahweh lui-même accordera tout bien, et notre terre donnera son fruit.'),
('ps',85,14,'crampon1923','La justice marchera devant lui, et tracera le chemin à ses pas.'),
('ps',86,1,'crampon1923','Prière de David. Prête l''oreille, Yahweh, exauce-moi, car je suis malheureux et indigent.'),
('ps',86,2,'crampon1923','Garde mon âme, car je suis pieux; sauve ton serviteur, ô mon Dieu; il met sa confiance en toi.'),
('ps',86,3,'crampon1923','Aie pitié de moi, Seigneur, car je crie vers toi tout le jour.'),
('ps',86,4,'crampon1923','Réjouis l''âme de ton serviteur, car vers toi, Seigneur, j''élève mon âme.'),
('ps',86,5,'crampon1923','Car tu es bon, Seigneur, et clément, et plein de compassion pour tous ceux qui t''invoquent.'),
('ps',86,6,'crampon1923','Yahweh, prête l''oreille à ma prière, sois attentif à la voix de mes supplications.'),
('ps',86,7,'crampon1923','Je t''invoque au jour de ma détresse, et tu m''exauceras.'),
('ps',86,8,'crampon1923','Nul ne t''égale parmi les dieux, Seigneur, rien ne ressemble à tes œuvres.'),
('ps',86,9,'crampon1923','Toutes les nations que tu as faites viendront se prosterner devant toi, Seigneur, et rendre gloire à ton nom.'),
('ps',86,10,'crampon1923','Car tu es grand et tu opères des prodiges; toi seul, tu es Dieu.'),
('ps',86,11,'crampon1923','Enseigne-moi tes voies Yahweh; je veux marcher dans ta fidélité; attache mon cœur à la crainte de ton nom.'),
('ps',86,12,'crampon1923','Je te louerai de tout mon cœur, Seigneur, mon Dieu; et je glorifierai ton nom à jamais.'),
('ps',86,13,'crampon1923','Car ta bonté est grande envers moi, tu as tiré mon âme du fond du schéol.'),
('ps',86,14,'crampon1923','O Dieu, des orgueilleux se sont élevés contre moi, une troupe d''hommes violents en veulent à ma vie, sans tenir aucun compte de toi.'),
('ps',86,15,'crampon1923','Mais toi, Seigneur, tu es un Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité.'),
('ps',86,16,'crampon1923','Tourne vers moi tes regards et aie pitié de moi; donne ta force à ton serviteur, et sauve le fils de ta servante.'),
('ps',86,17,'crampon1923','Signale ta bonté envers moi: que mes ennemis le voient et soient confondus! Car c''est toi, Yahweh, qui m''assistes et me consoles.'),
('ps',87,1,'crampon1923','Psaume des fils de Coré. Cantique. Il l''a fondée sur les saintes montagnes!'),
('ps',87,2,'crampon1923','Yahweh aime les portes de Sion, plus que toutes les demeures de Jacob.'),
('ps',87,3,'crampon1923','Des choses glorieuses ont été dites sur toi, cité de Dieu! — Séla.'),
('ps',87,4,'crampon1923','" Je nommerai Rahab et Babylone parmi ceux qui me connaissent; voici les Philistins, et Tyr, avec l''Ethiopie: c''est là qu''ils sont nés. "'),
('ps',87,5,'crampon1923','Et l''on dira de Sion: Celui-ci et celui-là y est né; c''est Lui, le Très-Haut, qui l''a fondée.'),
('ps',87,6,'crampon1923','Yahweh inscrira au rôle des peuples: " Celui-ci est né là. " — Séla.'),
('ps',87,7,'crampon1923','Et chanteurs et musiciens disent: " Toutes mes sources sont en toi. "'),
('ps',88,1,'crampon1923','Cantiques. Psaume des fils de Coré. Au maître de chant. A chanter sur le ton plaintif. Cantique d''Héman l''Ezrahite.'),
('ps',88,2,'crampon1923','Yahweh, Dieu de mon salut, quand je crie la nuit devant toi,'),
('ps',88,3,'crampon1923','que ma prière arrive en ta présence, prête l''oreille à mes supplications!'),
('ps',88,4,'crampon1923','Car mon âme est rassasiée de maux, et ma vie touche au schéol.'),
('ps',88,5,'crampon1923','On me compte parmi ceux qui descendent dans la fosse, je suis comme un homme à bout de forces.'),
('ps',88,6,'crampon1923','je suis comme délaissé parmi les morts, pareil aux cadavres étendus dans le sépulcre, dont tu n''as plus le souvenir, et qui sont soustraits à ta main.'),
('ps',88,7,'crampon1923','Tu m''as jeté au fond de la fosse, dans les ténèbres, dans les abîmes.'),
('ps',88,8,'crampon1923','Sur moi s''appesantit ta fureur, tu m''accables de tous tes flots. — Séla.'),
('ps',88,9,'crampon1923','Tu as éloigné de moi mes amis, tu m''as rendu pour eux un objet d''horreur; je suis emprisonné sans pouvoir sortir;'),
('ps',88,10,'crampon1923','mes yeux se consument dans la souffrance. Je t''invoque tout le jour, Yahweh, j''étends les mains vers toi.'),
('ps',88,11,'crampon1923','Feras-tu un miracle pour les morts; ou bien les ombres se lèveront-elles pour te louer? — Séla.'),
('ps',88,12,'crampon1923','Publie-t-on ta bonté dans le sépulcre, ta fidélité dans l''abîme?'),
('ps',88,13,'crampon1923','Tes prodiges sont-ils connus dans la région des ténèbres et ta justice dans la terre de l''oubli?'),
('ps',88,14,'crampon1923','Et moi, Yahweh, je crie vers toi, ma prière va au-devant de toi dès le matin.'),
('ps',88,15,'crampon1923','Pourquoi, Yahweh, repousses-tu mon âme, me caches-tu ta face?'),
('ps',88,16,'crampon1923','Je suis malheureux et moribond depuis ma jeunesse; sous le poids de tes terreurs, je ne sais que devenir.'),
('ps',88,17,'crampon1923','Tes fureurs passent sur moi, tes épouvantes m''accablent.'),
('ps',88,18,'crampon1923','Comme des eaux débordées elles m''environnent tout le jour; elles m''assiègent toutes ensemble.'),
('ps',88,19,'crampon1923','Tu as éloigné de moi mes amis et mes proches; mes compagnons, ce sont les ténèbres de la tombe.'),
('ps',89,1,'crampon1923','Cantique d''Ethan l''Ezrahite.'),
('ps',89,2,'crampon1923','Je veux chanter à jamais les bontés de Yahweh; à toutes les générations ma bouche fera connaître ta fidélité.'),
('ps',89,3,'crampon1923','Car je dis: La bonté est un édifice éternel, dans les cieux tu as établi ta fidélité.'),
('ps',89,4,'crampon1923','" J''ai contracté alliance avec mon élu; j''ai fait ce serment à David, mon serviteur:'),
('ps',89,5,'crampon1923','je veux affermir ta race pour toujours, établir ton trône pour toutes les générations. " — Séla.'),
('ps',89,6,'crampon1923','Les cieux célèbrent tes merveilles, Yahweh, et ta fidélité dans l''assemblée des saints.'),
('ps',89,7,'crampon1923','Car qui pourrait, dans le ciel, se comparer à Yahweh? Qui est semblable à Yahweh parmi les fils de Dieu?'),
('ps',89,8,'crampon1923','Dieu est terrible dans la grande assemblée des saints, il est redoutable pour tous ceux qui l''entourent.'),
('ps',89,9,'crampon1923','Yahweh, Dieu des armées, qui est comme toi? Tu es puissant, Yahweh, et ta fidélité t''environne.'),
('ps',89,10,'crampon1923','C''est toi qui domptes l''orgueil de la mer; quand ses flots se soulèvent, c''est toi qui les apaises.'),
('ps',89,11,'crampon1923','C''est toi qui écrasas Rahab comme un cadavre, qui dispersas tes ennemis par la force de ton bras.'),
('ps',89,12,'crampon1923','A toi sont les cieux, à toi aussi la terre; le monde et ce qu''il contient, c''est toi qui l''as fondé.'),
('ps',89,13,'crampon1923','Tu as créé le nord et le midi; le Thabor et l''Hermon tressaillent à ton nom.'),
('ps',89,14,'crampon1923','Ton bras est armé de puissance, ta main est forte, ta droite élevée.'),
('ps',89,15,'crampon1923','La justice et l''équité sont le fondement de ton trône, la bonté et la fidélité se tiennent devant ta face.'),
('ps',89,16,'crampon1923','Heureux le peuple qui connaît les joyeuses acclamations, qui marche à la clarté de ta face, Yahweh!'),
('ps',89,17,'crampon1923','Il se réjouit sans cesse en ton nom, et il s''élève par ta justice.'),
('ps',89,18,'crampon1923','Car tu es sa gloire et sa puissance, et ta faveur élève notre force.'),
('ps',89,19,'crampon1923','Car de Yahweh vient notre bouclier, et du Saint d''Israël notre roi.'),
('ps',89,20,'crampon1923','Tu parlas jadis dans une vision à ton bien-aimé, en disant: " J''ai prêté assistance à un héros, j''ai élevé un jeune homme du milieu du peuple.'),
('ps',89,21,'crampon1923','J''ai trouvé David, mon serviteur, je l''ai oint de mon huile sainte.'),
('ps',89,22,'crampon1923','Ma main sera constamment avec lui, et mon bras le fortifiera.'),
('ps',89,23,'crampon1923','" L''ennemi ne le surprendra pas, et le fils d''iniquité ne l''emportera pas sur lui.'),
('ps',89,24,'crampon1923','J''écraserai devant lui ses adversaires, et je frapperai ceux qui le haïssent.'),
('ps',89,25,'crampon1923','Ma fidélité et ma bonté seront avec lui, et par mon nom grandira sa puissance.'),
('ps',89,26,'crampon1923','J''étendrai sa main sur la mer et sa droite sur les fleuves.'),
('ps',89,27,'crampon1923','" Il m''invoquera: Tu es mon père, mon Dieu et le rocher de mon salut.'),
('ps',89,28,'crampon1923','Et moi je ferai de lui le premier-né, le plus élevé des rois de la terre.'),
('ps',89,29,'crampon1923','Je lui conserverai ma bonté à jamais, et mon alliance lui sera fidèle.'),
('ps',89,30,'crampon1923','J''établirai sa postérité pour jamais, et son trône aura les jours des cieux.'),
('ps',89,31,'crampon1923','" Si ses fils abandonnent ma loi, et ne marchent pas selon mes ordonnances;'),
('ps',89,32,'crampon1923','s''ils violent mes préceptes, et n''observent pas mes commandements;'),
('ps',89,33,'crampon1923','je punirai de la verge leurs transgressions, et par des coups leurs iniquités;'),
('ps',89,34,'crampon1923','mais je ne lui retirerai pas ma bonté, et je ne ferai pas mentir ma fidélité.'),
('ps',89,35,'crampon1923','" Je ne violerai pas mon alliance, et je ne changerai pas la parole sortie de mes lèvres.'),
('ps',89,36,'crampon1923','Je l''ai juré une fois par ma sainteté; non, je ne mentirai pas à David.'),
('ps',89,37,'crampon1923','Sa postérité subsistera éternellement, son trône sera devant moi comme le soleil;'),
('ps',89,38,'crampon1923','comme la lune, il est établi pour toujours, et le témoin qui est au ciel est fidèle. " — Séla.'),
('ps',89,39,'crampon1923','Et toi, tu as rejeté, et tu as dédaigné, et tu t''es irrité contre ton Oint!'),
('ps',89,40,'crampon1923','Tu as pris en dégoût l''alliance avec son serviteur, tu as jeté à terre son diadème profané.'),
('ps',89,41,'crampon1923','Tu as renversé toutes ses murailles, tu as mis en ruines ses forteresses.'),
('ps',89,42,'crampon1923','Tous les passants le dépouillent; il est devenu l''opprobre de ses voisins.'),
('ps',89,43,'crampon1923','Tu as élevé la droite de ses oppresseurs, tu as réjoui tous ses ennemis.'),
('ps',89,44,'crampon1923','Tu as fait retourner en arrière le tranchant de son glaive, et tu ne l''as pas soutenu dans le combat.'),
('ps',89,45,'crampon1923','Tu l''as dépouillé de sa splendeur, et tu as jeté par terre son trône.'),
('ps',89,46,'crampon1923','Tu as abrégé les jours de sa jeunesse, et tu l''as couvert d''ignominie. — Séla.'),
('ps',89,47,'crampon1923','Jusques à quand, Yahweh, te cacheras-tu pour toujours, et ta fureur s''embrasera-t-elle comme le feu?'),
('ps',89,48,'crampon1923','Rappelle-toi la brièveté de ma vie, et pour quelle vanité tu as créé les fils de l''homme!'),
('ps',89,49,'crampon1923','Quel est le vivant qui ne verra pas la mort, qui soustraira son âme au pouvoir du schéol? — Séla.'),
('ps',89,50,'crampon1923','Où sont, Seigneur, tes bontés d''autrefois, que tu juras à David dans ta fidélité?'),
('ps',89,51,'crampon1923','Souviens-toi, Seigneur, de l''opprobre de tes serviteurs; souviens-toi que je porte dans mon sein les outrages de tant de peuples nombreux;'),
('ps',89,52,'crampon1923','souviens-toi des outrages de tes ennemis, Yahweh, de leurs outrages contre les pas de ton Oint.'),
('ps',89,53,'crampon1923','Béni soit à jamais Yahweh! Amen! Amen!'),
('ps',90,1,'crampon1923','Prière de Moïse, homme de Dieu. Seigneur, tu as été pour nous un refuge d''âge en âge.'),
('ps',90,2,'crampon1923','Avant que les montagnes fussent nées, et que tu eusses enfanté la terre et le monde, de l''éternité à l''éternité tu es, ô Dieu!'),
('ps',90,3,'crampon1923','Tu réduis les mortels en poussière, et tu dis: " Retournez, fils de l''homme! "'),
('ps',90,4,'crampon1923','Car mille ans sont, à tes yeux, comme le jour d''hier, quand il passe, et comme une veille de la nuit.'),
('ps',90,5,'crampon1923','Tu les emportes, semblables à un songe; le matin, comme l''herbe, ils repoussent:'),
('ps',90,6,'crampon1923','le matin, elle fleurit et pousse; le soir, elle se flétrit et se dessèche.'),
('ps',90,7,'crampon1923','Ainsi nous sommes consumés par ta colère, et ta fureur nous terrifie.'),
('ps',90,8,'crampon1923','Tu mets devant toi nos iniquités, nos fautes cachées à la lumière de ta face.'),
('ps',90,9,'crampon1923','Tous nos jours disparaissent par ton courroux, nous voyons nos années s''évanouir comme un son léger.'),
('ps',90,10,'crampon1923','Nos jours s''élèvent à soixante-dix ans, et dans leur pleine mesure à quatre-vingts ans; et leur splendeur n''est que peine et misère, car ils passent vite, et nous nous envolons!'),
('ps',90,11,'crampon1923','Qui comprend la puissance de ta colère, et ton courroux, selon la crainte qui t''est due?'),
('ps',90,12,'crampon1923','Enseigne-nous à bien compter nos jours. afin que nous acquérions un cœur sage.'),
('ps',90,13,'crampon1923','Reviens, Yahweh; jusques à quand? Aie pitié de tes serviteurs.'),
('ps',90,14,'crampon1923','Rassasie-nous le matin de ta bonté, et nous serons tous nos jours dans la joie et l''allégresse.'),
('ps',90,15,'crampon1923','Réjouis-nous autant de jours que tu nous as humiliés, autant d''années que nous avons connu le malheur.'),
('ps',90,16,'crampon1923','Que ton œuvre se manifeste à tes serviteurs, ainsi que ta gloire, pour leurs enfants!'),
('ps',90,17,'crampon1923','Que la faveur de Yahweh, notre Dieu, soit sur nous! Affermis pour nous l''ouvrage de nos mains; oui, affermis l''ouvrage de nos mains!'),
('ps',91,1,'crampon1923','Celui qui s''abrite sous la protection du Très-Haut repose à l''ombre du Tout-Puissant.'),
('ps',91,2,'crampon1923','Je dis à Yahweh: " Tu es mon refuge et ma forteresse, mon Dieu en qui je me confie. "'),
('ps',91,3,'crampon1923','Car c''est lui qui te délivre du filet de l''oiseleur et de la peste funeste.'),
('ps',91,4,'crampon1923','Il te couvrira de ses ailes, et sous ses plumes tu trouveras un refuge. Sa fidélité est un bouclier et une cuirasse.'),
('ps',91,5,'crampon1923','Tu n''auras à craindre ni les terreurs de la nuit, ni la flèche qui vole pendant le jour,'),
('ps',91,6,'crampon1923','ni la peste qui marche dans les ténèbres, ni la contagion qui ravage en plein midi.'),
('ps',91,7,'crampon1923','Que mille tombent à ton côté, et dix mille à ta droite, tu ne seras pas atteint.'),
('ps',91,8,'crampon1923','De tes yeux seulement tu regarderas, et tu verras la rétribution des méchants.'),
('ps',91,9,'crampon1923','Car tu as dit: " Tu es mon refuge, Yahweh! " tu as fait du Très-Haut ton asile.'),
('ps',91,10,'crampon1923','Le malheur ne viendra pas jusqu''à toi, aucun fléau n''approchera de ta tente.'),
('ps',91,11,'crampon1923','Car il ordonnera à ses anges de te garder dans toutes tes voies.'),
('ps',91,12,'crampon1923','Ils te porteront sur leurs mains, de peur que ton pied ne heurte contre la pierre.'),
('ps',91,13,'crampon1923','Tu marcheras sur le lion et sur l''aspic, tu fouleras le lionceau et le dragon. —'),
('ps',91,14,'crampon1923','" Puisqu''il s''est attaché à moi, je le délivrerai; je le protégerai, puisqu''il connaît mon nom.'),
('ps',91,15,'crampon1923','Il m''invoquera et je l''exaucerai; je serai avec lui dans la détresse. " Je le délivrerai et le glorifierai.'),
('ps',91,16,'crampon1923','Je le rassasierai de longs jours, et je lui ferai voir mon salut. "'),
('ps',92,1,'crampon1923','Psaume. Cantique pour le jour du sabbat.'),
('ps',92,2,'crampon1923','Il est bon de louer Yahweh, et de célébrer ton nom, ô Très-Haut,'),
('ps',92,3,'crampon1923','de publier le matin ta bonté, et ta fidélité pendant la nuit,'),
('ps',92,4,'crampon1923','sur l''instrument à dix cordes et sur le luth, avec les accords de la harpe.'),
('ps',92,5,'crampon1923','Tu me réjouis, Yahweh, par tes œuvres, et je tressaille devant les ouvrages de tes mains.'),
('ps',92,6,'crampon1923','Que tes œuvres sont grandes, Yahweh, que tes pensées sont profondes!'),
('ps',92,7,'crampon1923','L''homme stupide n''y connaît rien, et l''insensé n''y peut rien comprendre.'),
('ps',92,8,'crampon1923','Quand les méchants croissent comme l''herbe, et que fleurissent tous ceux qui font le mal, c''est pour être exterminés à jamais.'),
('ps',92,9,'crampon1923','Mais toi, tu es élevé pour l''éternité, Yahweh!'),
('ps',92,10,'crampon1923','Car voici que tes ennemis, Yahweh, voici que tes ennemis périssent, tous ceux qui font le mal sont dispersés.'),
('ps',92,11,'crampon1923','Et tu élèves ma corne, comme celle du buffle, je suis arrosé avec une huile fraîche.'),
('ps',92,12,'crampon1923','Mon œil se plaît à contempler mes ennemis, et mon oreille à entendre les méchants qui s''élèvent contre moi.'),
('ps',92,13,'crampon1923','Le juste croîtra comme le palmier, il s''élèvera comme le cèdre du Liban.'),
('ps',92,14,'crampon1923','Plantés dans la maison de Yahweh, ils fleuriront dans les parvis de notre Dieu.'),
('ps',92,15,'crampon1923','Ils porteront encore des fruits dans la vieillesse; ils seront pleins de sève et verdoyants,'),
('ps',92,16,'crampon1923','pour proclamer que Yahweh est juste: il est mon rocher, et il n''y a pas en lui d''injustice.'),
('ps',93,1,'crampon1923','Yahweh est roi, il est revêtu de majesté, Yahweh est revêtu, il est ceint de force: aussi le monde est ferme, il ne chancelle pas.'),
('ps',93,2,'crampon1923','Ton trône est établi dès l''origine, tu es dès l''éternité.'),
('ps',93,3,'crampon1923','Les fleuves élèvent, ô Yahweh, les fleuves élèvent leurs voix, les fleuves élèvent leurs flots retentissants.'),
('ps',93,4,'crampon1923','Plus que la voix des grandes eaux, des vagues puissantes de la mer, Yahweh est magnifique dans les hauteurs!'),
('ps',93,5,'crampon1923','Tes témoignages sont immuables; la sainteté convient à ta maison, Yahweh, pour toute la durée des jours.'),
('ps',94,1,'crampon1923','Dieu des vengeances, Yahweh, Dieu des vengeances, parais!'),
('ps',94,2,'crampon1923','Lève-toi, juge de la terre, rends aux superbes selon leurs œuvres!'),
('ps',94,3,'crampon1923','Jusques à quand les méchants, Yahweh, jusques à quand les méchants triompheront-ils?'),
('ps',94,4,'crampon1923','Ils se répandent en discours arrogants, ils se glorifient, tous ces artisans d''iniquité.'),
('ps',94,5,'crampon1923','Yahweh, ils écrasent ton peuple, ils oppriment ton héritage,'),
('ps',94,6,'crampon1923','ils égorgent la veuve et l''étranger, ils massacrent les orphelins.'),
('ps',94,7,'crampon1923','Et ils disent: " Yahweh ne regarde pas, le Dieu de Jacob ne fait pas attention. "'),
('ps',94,8,'crampon1923','Comprenez-donc, stupides enfants du peuple! Insensés, quand aurez-vous l''intelligence?'),
('ps',94,9,'crampon1923','Celui qui a planté l''oreille n''entendrait-il pas? Celui qui a formé l''œil ne verrait-il pas?'),
('ps',94,10,'crampon1923','Celui qui châtie les nations ne punirait-il pas? Celui qui donne à l''homme l''intelligence ne reconnaîtrait-il pas?'),
('ps',94,11,'crampon1923','Yahweh connaît les pensées des hommes, il sait qu''elles sont vaines.'),
('ps',94,12,'crampon1923','Heureux l''homme que tu instruis, Yahweh, et à qui tu donnes l''enseignement de ta loi,'),
('ps',94,13,'crampon1923','pour l''apaiser aux jours du malheur, jusqu''à ce que la fosse soit creusée pour le méchant.'),
('ps',94,14,'crampon1923','Car Yahweh ne rejettera pas son peuple, il n''abandonnera pas son héritage;'),
('ps',94,15,'crampon1923','mais le jugement redeviendra conforme à la justice, et tous les hommes au cœur droit y applaudiront.'),
('ps',94,16,'crampon1923','Qui se lèvera pour moi contre les méchants? Qui me soutiendra contre ceux qui font le mal?'),
('ps',94,17,'crampon1923','Si Yahweh n''était pas mon secours, mon âme habiterait bientôt le séjour du silence.'),
('ps',94,18,'crampon1923','Quand je dis: " Mon pied chancelle, " ta bonté, Yahweh, me soutient.'),
('ps',94,19,'crampon1923','Quand les angoisses s''agitent en foule dans ma pensée, tes consolations réjouissent mon âme.'),
('ps',94,20,'crampon1923','A-t-il rien de commun avec toi le tribunal de perdition, qui fait le mal dans les formes légales?'),
('ps',94,21,'crampon1923','Ils s''empressent contre la vie du juste, et ils condamnent le sang innocent.'),
('ps',94,22,'crampon1923','Mais Yahweh est ma forteresse, mon Dieu est le rocher où je m''abrite.'),
('ps',94,23,'crampon1923','Il fera retomber sur eux leur iniquité, il les exterminera par leur propre malice, il les exterminera, Yahweh, notre Dieu!'),
('ps',95,1,'crampon1923','Venez, chantons avec allégresse à Yahweh! Poussons des cris de joie vers le Rocher de notre salut!'),
('ps',95,2,'crampon1923','Allons au-devant de lui avec des louanges, faisons retentir des hymnes en son honneur.'),
('ps',95,3,'crampon1923','Car c''est un grand Dieu que Yahweh, un grand roi au-dessus de tous les dieux.'),
('ps',95,4,'crampon1923','Il tient dans sa main les fondements de la terre, et les sommets des montagnes sont à lui.'),
('ps',95,5,'crampon1923','A lui la mer, car c''est lui qui l''a faite; la terre aussi: ses mains l''ont formée.'),
('ps',95,6,'crampon1923','Venez, prosternons-nous et adorons, fléchissons le genou devant Yahweh, notre Créateur.'),
('ps',95,7,'crampon1923','Car il est notre Dieu, et nous, nous sommes le peuple de son pâturage, le troupeau que sa main conduit. Oh! si vous pouviez écouter aujourd''hui sa voix!'),
('ps',95,8,'crampon1923','N''endurcissez pas votre cœur comme à Mériba, comme à la journée de Massa, dans le désert,'),
('ps',95,9,'crampon1923','où vos pères m''ont tenté, m''ont éprouvé, quoiqu''ils eussent vu mes œuvres.'),
('ps',95,10,'crampon1923','Pendant quarante ans j''eus cette race en dégoût, et je dis: C''est un peuple au cœur égaré; et ils n''ont pas connu mes voies.'),
('ps',95,11,'crampon1923','Aussi je jurai dans ma colère: ils n''entreront pas dans mon repos.'),
('ps',96,1,'crampon1923','Chantez à Yahweh un cantique nouveau! Chantez à Yahweh, vous habitants de toute la terre!'),
('ps',96,2,'crampon1923','Chantez à Yahweh, bénissez son nom! Annoncez de jour en jour son salut,'),
('ps',96,3,'crampon1923','Racontez sa gloire parmi les nations, ses merveilles parmi tous les peuples.'),
('ps',96,4,'crampon1923','Car Yahweh est grand et digne de toute louange, il est redoutable par dessus tous les dieux,'),
('ps',96,5,'crampon1923','car tous les dieux des peuples sont néant. Mais Yahweh a fait les cieux.'),
('ps',96,6,'crampon1923','La splendeur et la magnificence sont devant lui, la puissance et la majesté sont dans son sanctuaire.'),
('ps',96,7,'crampon1923','Rendez à Yahweh, famille des peuples, rendez à Yahweh gloire et puissance!'),
('ps',96,8,'crampon1923','Rendez à Yahweh la gloire due à son nom! Apportez l''offrande et venez dans ses parvis.'),
('ps',96,9,'crampon1923','Prosternez-vous devant Yahweh avec l''ornement sacré; tremblez devant lui, vous, habitants de toute la terre!'),
('ps',96,10,'crampon1923','Dites parmi les nations: " Yahweh est roi; aussi le monde sera stable et ne chancellera pas; il jugera les peuples avec droiture. "'),
('ps',96,11,'crampon1923','Que les cieux se réjouissent et que la terre soit dans l''allégresse! Que la mer s''agite avec tout ce qu''elle contient!'),
('ps',96,12,'crampon1923','Que la campagne s''égaie avec tout ce qu''elle renferme, que tous les arbres des forêts poussent des cris de joie,'),
('ps',96,13,'crampon1923','devant Yahweh, car il vient! Car il vient pour juger la terre; il jugera le monde avec justice, et les peuples selon sa fidélité.'),
('ps',97,1,'crampon1923','Yahweh est roi: que la terre soit dans l''allégresse, que les îles nombreuses se réjouissent!'),
('ps',97,2,'crampon1923','La nuée et l''ombre l''environnent, la justice et l''équité sont la base de son trône.'),
('ps',97,3,'crampon1923','Le feu s''avance devant lui, et dévore à l''entour ses adversaires.'),
('ps',97,4,'crampon1923','Ses éclairs illuminent le monde; la terre le voit et tremble.'),
('ps',97,5,'crampon1923','Les montagnes se fondent, comme la cire, devant Yahweh, devant le Seigneur de toute la terre.'),
('ps',97,6,'crampon1923','Les cieux proclament sa justice, et tous les peuples contemplent sa gloire.'),
('ps',97,7,'crampon1923','Ils seront confondus tous les adorateurs d''images, qui sont fiers de leurs idoles. Tous les dieux se prosternent devant lui.'),
('ps',97,8,'crampon1923','Sion a entendu et s''est réjouie, les filles de Juda sont dans l''allégresse, à cause de tes jugements, Yahweh.'),
('ps',97,9,'crampon1923','Car toi, Yahweh, tu es le Très-Haut sur toute la terre, tu es souverainement élevé au dessus de tous les dieux.'),
('ps',97,10,'crampon1923','Vous qui aimez Yahweh, haïssez le mal! Il garde les âmes de ses fidèles, il les délivre de la main des méchants.'),
('ps',97,11,'crampon1923','La lumière est semée pour le juste, et la joie pour ceux qui ont le cœur droit.'),
('ps',97,12,'crampon1923','Justes, réjouissez-vous en Yahweh, et rendez gloire à son saint nom.'),
('ps',98,1,'crampon1923','Psaume. Chantez à Yahweh un cantique nouveau, car il a fait des prodiges; sa droite et son bras saints lui ont donné la victoire.'),
('ps',98,2,'crampon1923','Yahweh a manifesté son salut, il a révélé sa justice aux yeux des nations.'),
('ps',98,3,'crampon1923','Il s''est souvenu de sa bonté et de sa fidélité envers la maison d''Israël; toutes les extrémités de la terre ont vu le salut de notre Dieu.'),
('ps',98,4,'crampon1923','Poussez vers Yahweh des cris de joie, vous, habitants de toute la terre, faites éclater votre allégresse au son des instruments!'),
('ps',98,5,'crampon1923','Célébrez Yahweh sur la harpe, sur la harpe et au son des cantiques!'),
('ps',98,6,'crampon1923','Avec les trompettes et au son du cor, poussez des cris de joie devant le Roi Yahweh!'),
('ps',98,7,'crampon1923','Que la mer s''agite avec tout ce qu''elle renferme, que la terre et ses habitants fassent éclater leurs transports.'),
('ps',98,8,'crampon1923','Que les fleuves applaudissent, qu''ensemble les montagnes poussent des cris de joie,'),
('ps',98,9,'crampon1923','devant Yahweh — car il vient pour juger la terre; il jugera le monde avec justice, et les peuples avec équité.'),
('ps',99,1,'crampon1923','Yahweh est roi: les peuples tremblent; il est assis sur les Chérubins; la terre chancelle.'),
('ps',99,2,'crampon1923','Yahweh est grand dans Sion, il est élevé au dessus de tous les peuples.'),
('ps',99,3,'crampon1923','Qu''on célèbre ton nom grand et redoutable! — Il est saint!'),
('ps',99,4,'crampon1923','Qu''on célèbre la puissance du Roi qui aime la justice! Tu affermis la droiture, tu exerces en Jacob la justice et l''équité.'),
('ps',99,5,'crampon1923','Exaltez Yahweh, notre Dieu, et prosternez-vous devant l''escabeau de ses pieds. — Il est saint!'),
('ps',99,6,'crampon1923','Moïse et Aaron étaient parmi ses prêtres, et Samuel parmi ceux qui invoquaient son nom. Ils invoquaient Yahweh, et il les exauçait,'),
('ps',99,7,'crampon1923','il leur parlait dans la colonne de nuée. Ils observaient ses commandements, et la loi qu''il leur avait donnée.'),
('ps',99,8,'crampon1923','Yahweh, notre Dieu, tu les exauças, tu fus pour eux un Dieu clément, et tu les punis de leurs fautes.'),
('ps',99,9,'crampon1923','Exaltez Yahweh, notre Dieu, et prosternez-vous devant sa montagne sainte, car il est saint, Yahweh notre Dieu!'),
('ps',100,1,'crampon1923','Psaume de louange. Poussez des cris de joie vers Yahweh, vous, habitants de toute la terre!'),
('ps',100,2,'crampon1923','Servez Yahweh avec joie, venez en sa présence avec allégresse!'),
('ps',100,3,'crampon1923','Reconnaissez que Yahweh est Dieu. C''est lui qui nous a faits et nous lui appartenons; nous sommes son peuple et le troupeau de son pâturage.'),
('ps',100,4,'crampon1923','Venez à ses portiques avec des louanges, à ses parvis avec des cantiques; célébrez-le, bénissez son nom.'),
('ps',100,5,'crampon1923','Car Yahweh est bon, sa miséricorde est éternelle, et sa fidélité demeure d''âge en âge.'),
('ps',101,1,'crampon1923','Psaume de David Je veux chanter la bonté et la justice; C''est toi, Yahweh, que je veux célébrer.'),
('ps',101,2,'crampon1923','Je prendrai garde à la voie de l''innocence. — Quand viendras-tu à moi? — Je marcherai dans l''intégrité de mon cœur, au milieu de ma maison.'),
('ps',101,3,'crampon1923','Je ne mettrai devant mes yeux aucune action mauvaise. Je hais la conduite perverse; elle ne s''attachera point à moi.'),
('ps',101,4,'crampon1923','Un cœur faux ne sera jamais le mien; je ne veux pas connaître le mal.'),
('ps',101,5,'crampon1923','Le détracteur qui déchire en secret son prochain, je l''exterminerai; L''homme au regard hautain et au cœur gonflé d''orgueil, je ne le supporterai pas.'),
('ps',101,6,'crampon1923','J''aurai les yeux sur les hommes fidèles du pays, pour qu''ils demeurent auprès de moi; celui qui marche dans une voie intègre sera mon serviteur.'),
('ps',101,7,'crampon1923','Il n''aura point de place dans ma maison, celui qui agit avec fourberie; celui qui profère le mensonge ne subsistera pas devant mes yeux.'),
('ps',101,8,'crampon1923','Chaque matin j''exterminerai tous les méchants du pays, afin de retrancher de la cité de Yahweh tous ceux qui commettent l''iniquité.'),
('ps',101,9,'crampon1923',''),
('ps',102,1,'crampon1923','Prière du malheureux, lorsqu''il est accablé et qu''il répand sa plainte devant Yahweh.'),
('ps',102,2,'crampon1923','Yahweh écoute ma prière, et que mon cri arrive jusqu''à toi.'),
('ps',102,3,'crampon1923','Ne me cache pas ton visage, au jour de ma détresse; incline vers moi ton oreille, quand je crie, hâte-toi de m''exaucer.'),
('ps',102,4,'crampon1923','Car mes jours s''évanouissent comme en fumée, et mes os sont embrasés comme par un feu.'),
('ps',102,5,'crampon1923','Frappé comme l''herbe, mon cœur se dessèche; j''oublie même de manger mon pain.'),
('ps',102,6,'crampon1923','A force de crier et de gémir, mes os s''attachent à ma chair.'),
('ps',102,7,'crampon1923','Je ressemble au pélican du désert, je suis devenu comme le hibou des ruines.'),
('ps',102,8,'crampon1923','Je passe les nuits sans sommeil, comme l''oiseau solitaire sur le toit.'),
('ps',102,9,'crampon1923','Tout le jour mes adversaires m''outragent, mes ennemis furieux jurent ma ruine.'),
('ps',102,10,'crampon1923','Je mange la cendre comme du pain, et je mêle mes larmes à mon breuvage,'),
('ps',102,11,'crampon1923','à cause de ta colère et de ton indignation, car tu m''as soulevé et jeté au loin.'),
('ps',102,12,'crampon1923','Mes jours sont comme l''ombre qui s''allonge, et je me dessèche comme l''herbe.'),
('ps',102,13,'crampon1923','Mais toi, Yahweh, tu es assis sur un trône éternel, et ta mémoire vit d''âge en âge.'),
('ps',102,14,'crampon1923','Tu te lèveras, tu auras pitié de Sion, car le temps de lui faire grâce, le moment fixé est venu.'),
('ps',102,15,'crampon1923','Car tes serviteurs en chérissent les pierres, ils s''attendrissent sur sa poussière.'),
('ps',102,16,'crampon1923','Alors les nations révéreront le nom de Yahweh, et tous les rois de la terre ta majesté,'),
('ps',102,17,'crampon1923','parce que Yahweh a rebâti Sion; il s''est montré dans sa gloire.'),
('ps',102,18,'crampon1923','Il s''est tourné vers la prière du misérable, il n''a pas dédaigné sa supplication.'),
('ps',102,19,'crampon1923','Que cela soit écrit pour la génération future, et que le peuple qui sera créé célèbre Yahweh,'),
('ps',102,20,'crampon1923','parce qu''il a regardé de sa sainte hauteur, parce que Yahweh a regardé des cieux sur la terre,'),
('ps',102,21,'crampon1923','pour écouter les gémissements des captifs, pour délivrer ceux qui sont voués à la mort,'),
('ps',102,22,'crampon1923','afin qu''ils publient dans Sion le nom de Yahweh, et sa louange dans Jérusalem,'),
('ps',102,23,'crampon1923','quand s''assembleront tous les peuples, et les royaumes pour servir Yahweh.'),
('ps',102,24,'crampon1923','Il a brisé ma force sur le chemin, il a abrégé mes jours.'),
('ps',102,25,'crampon1923','Je dis: Mon Dieu, ne m''enlève pas au milieu de mes jours, toi, dont les années durent d''âge en âge.'),
('ps',102,26,'crampon1923','Au commencement tu as fondé la terre, et les cieux sont l''ouvrage de tes mains.'),
('ps',102,27,'crampon1923','Ils périront, mais toi, tu subsistes. Ils s''useront tous comme un vêtement; Tu les changeras comme un manteau, et ils seront changés:'),
('ps',102,28,'crampon1923','mais toi, tu restes le même, et tes années n''ont point de fin.'),
('ps',102,29,'crampon1923','Les fils de tes serviteurs habiteront leur pays, et leur postérité sera stable devant toi.'),
('ps',103,1,'crampon1923','De David. Mon âme, bénis Yahweh, et que tout ce qui est en moi bénisse son saint nom!'),
('ps',103,2,'crampon1923','Mon âme, bénis Yahweh, et n''oublie pas ses nombreux bienfaits.'),
('ps',103,3,'crampon1923','C''est lui qui pardonne toutes tes iniquités, qui guérit toutes tes maladies;'),
('ps',103,4,'crampon1923','C''est lui qui délivre ta vie de la fosse, qui te couronne de bonté et de miséricorde.'),
('ps',103,5,'crampon1923','C''est lui qui comble de biens tes désirs; et ta jeunesse renouvelée a la vigueur de l''aigle.'),
('ps',103,6,'crampon1923','Yahweh exerce la justice, il fait droit à tous les opprimés.'),
('ps',103,7,'crampon1923','Il a manifesté ses voies à Moïse, ses grandes œuvres aux enfants d''Israël.'),
('ps',103,8,'crampon1923','Yahweh est miséricordieux et compatissant, lent à la colère et riche en bonté.'),
('ps',103,9,'crampon1923','Ce n''est pas pour toujours qu''il réprimande, il ne garde pas à jamais sa colère.'),
('ps',103,10,'crampon1923','Il ne nous traite pas selon nos péchés, et ne nous châtie pas selon nos iniquités.'),
('ps',103,11,'crampon1923','Car autant les cieux sont élevés au-dessus de la terre, autant sa bonté est grande envers ceux qui le craignent.'),
('ps',103,12,'crampon1923','Autant l''orient est loin de l''occident, autant il éloigne de nous nos transgressions.'),
('ps',103,13,'crampon1923','Comme un père a compassion de ses enfants, Yahweh a compassion de ceux qui le craignent.'),
('ps',103,14,'crampon1923','Car il sait de quoi nous sommes formés, il se souvient que nous sommes poussière.'),
('ps',103,15,'crampon1923','L''homme! Ses jours sont comme l''herbe, il fleurit comme la fleur des champs.'),
('ps',103,16,'crampon1923','Qu''un souffle passe sur lui, il n''est plus, et le lieu qu''il occupait ne le connaît plus.'),
('ps',103,17,'crampon1923','Mais la bonté de Yahweh dure à jamais pour ceux qui le craignent, et sa justice pour les enfants de leurs enfants,'),
('ps',103,18,'crampon1923','pour ceux qui gardent son alliance, et se souviennent de ses commandements pour les observer.'),
('ps',103,19,'crampon1923','Yahweh a établi son trône dans les cieux, et son empire s''étend sur toutes choses.'),
('ps',103,20,'crampon1923','Bénissez Yahweh, vous ses anges, qui êtes puissants et forts, et qui exécutez ses ordres, en obéissant à la voix de sa parole.'),
('ps',103,21,'crampon1923','Bénissez Yahweh vous toutes ses armées, qui êtes ses serviteurs et qui exécutez sa volonté!'),
('ps',103,22,'crampon1923','Bénissez Yahweh, vous toutes, ses œuvres, dans tous les lieux de sa domination! Mon âme, bénis Yahweh!'),
('ps',104,1,'crampon1923','Mon âme, bénis Yahweh! Yahweh, mon Dieu, tu es infiniment grand, Tu es revêtu de majesté et de splendeur!'),
('ps',104,2,'crampon1923','Il s''enveloppe de lumière comme d''un manteau, il déploie les cieux comme une tente.'),
('ps',104,3,'crampon1923','Dans les eaux du ciel il bâtit sa demeure, des nuées il fait son char, il s''avance sur les ailes du vent,'),
('ps',104,4,'crampon1923','Des vents il fait ses messagers, des flammes de feu ses serviteurs.'),
('ps',104,5,'crampon1923','Il a affermi la terre sur ses bases: elle est à jamais inébranlable.'),
('ps',104,6,'crampon1923','Tu l''avais enveloppée de l''abîme comme d''un vêtement; les eaux recouvraient les montagnes.'),
('ps',104,7,'crampon1923','Elles s''enfuirent devant ta menace; au bruit de ton tonnerre, elles reculèrent épouvantées.'),
('ps',104,8,'crampon1923','Les montagnes surgirent, les vallées se creusèrent, au lieu que tu leur avais assigné.'),
('ps',104,9,'crampon1923','Tu poses une limite que les eaux ne franchiront plus: elles ne reviendront plus couvrir la terre.'),
('ps',104,10,'crampon1923','Il envoie les sources dans les vallées; elles s''écoulent entre les montagnes.'),
('ps',104,11,'crampon1923','Elles abreuvent tous les animaux des champs, les onagres viennent y étancher leur soif.'),
('ps',104,12,'crampon1923','Les oiseaux du ciel habitent sur leurs bords, et font résonner leur voix dans le feuillage.'),
('ps',104,13,'crampon1923','De sa haute demeure il arrose les montagnes; la terre se rassasie du fruit de tes œuvres.'),
('ps',104,14,'crampon1923','Il fait croître l''herbe pour les troupeaux, et les plantes pour l''usage de l''homme; Il tire le pain du sein de la terre,'),
('ps',104,15,'crampon1923','et le vin qui réjouit le cœur de l''homme; il lui donne l''huile qui brille sur sa face, et le pain qui affermit son cœur.'),
('ps',104,16,'crampon1923','Les arbres de Yahweh sont pleins de sève, et les cèdres du Liban qu''il a plantés.'),
('ps',104,17,'crampon1923','C''est là que les oiseaux font leurs nids, et la cigogne qui habite dans les cyprès.'),
('ps',104,18,'crampon1923','Les montagnes élevées sont pour les chamois, les rochers sont l''abri des gerboises.'),
('ps',104,19,'crampon1923','Il a fait la lune pour marquer les temps, et le soleil qui connaît l''heure de son coucher.'),
('ps',104,20,'crampon1923','Il amène les ténèbres, et il est nuit; aussitôt se mettent en mouvement toutes les bêtes de la forêt.'),
('ps',104,21,'crampon1923','Les lionceaux rugissent après la proie, et demandent à Dieu leur nourriture.'),
('ps',104,22,'crampon1923','Le soleil se lève: ils se retirent, et se couchent dans leurs tanières.'),
('ps',104,23,'crampon1923','L''homme sort alors pour sa tâche, et pour son travail jusqu''au soir.'),
('ps',104,24,'crampon1923','Que tes œuvres sont nombreuses, Yahweh! Tu les as toutes faites avec sagesse; La terre est remplie de tes biens.'),
('ps',104,25,'crampon1923','Voici la mer, large et vaste: là fourmillent sans nombre des animaux petits et grands;'),
('ps',104,26,'crampon1923','là se promènent les navires, et le léviathan que tu as formé pour se jouer dans les flots.'),
('ps',104,27,'crampon1923','Tous attendent de toi que tu leur donnes la nourriture en son temps.'),
('ps',104,28,'crampon1923','Tu la leur donnes, et ils la recueillent; Tu ouvres ta main, et ils se rassasient de tes biens.'),
('ps',104,29,'crampon1923','Tu caches ta face: ils sont dans l''épouvante; tu leur retire le souffle: ils expirent, et retournent dans leur poussière.'),
('ps',104,30,'crampon1923','Tu envoies ton souffle: ils sont créés, et tu renouvelles la face de la terre.'),
('ps',104,31,'crampon1923','Que la gloire de Yahweh subsiste à jamais! Que Yahweh se réjouisse de ses œuvres!'),
('ps',104,32,'crampon1923','Il regarde la terre et elle tremble; il touche les montagnes, et elles fument.'),
('ps',104,33,'crampon1923','Je veux chanter Yahweh tant que je vivrai, célébrer mon Dieu tant que j''existerai.'),
('ps',104,34,'crampon1923','Puisse mon cantique lui être agréable! Moi, je mets ma joie en Yahweh.'),
('ps',104,35,'crampon1923','Que les pécheurs disparaissent de la terre, et que les méchants ne soient plus! Mon âme, bénis Yahweh! Alleluia!'),
('ps',105,1,'crampon1923','Célébrez Yahweh, invoquez son nom, faites connaître parmi les nations ses grandes œuvres.'),
('ps',105,2,'crampon1923','Chantez-le, célébrez-le! Proclamez toutes ses merveilles.'),
('ps',105,3,'crampon1923','Glorifiez-vous de son saint nom; joyeux soit le cœur de ceux qui cherchent Yahweh!'),
('ps',105,4,'crampon1923','Cherchez Yahweh et sa force, ne cessez pas de chercher sa face.'),
('ps',105,5,'crampon1923','Souvenez-vous des merveilles qu''il a opérées, de ses prodiges et des jugements sortis de sa bouche,'),
('ps',105,6,'crampon1923','race d''Abraham, son serviteur, enfants de Jacob, ses élus.'),
('ps',105,7,'crampon1923','Lui, Yahweh, est notre Dieu; ses jugements atteignent toute la terre.'),
('ps',105,8,'crampon1923','Il se souvient éternellement de son alliance, de la parole qu''il a affirmée pour mille générations,'),
('ps',105,9,'crampon1923','de l''alliance qu''il a contractée avec Abraham, et du serment qu''il a fait à Isaac.'),
('ps',105,10,'crampon1923','Il l''a érigé pour Jacob en loi, pour Israël en alliance éternelle,'),
('ps',105,11,'crampon1923','disant: " Je te donnerai le pays de Chanaan comme la part de ton héritage. "'),
('ps',105,12,'crampon1923','Comme ils étaient alors en petit nombre, peu nombreux et étrangers dans le pays,'),
('ps',105,13,'crampon1923','qu''ils allaient d''une nation à l''autre, et d''un royaume vers un autre peuple,'),
('ps',105,14,'crampon1923','il ne permit à personne de les opprimer, et il châtia les rois à cause d''eux:'),
('ps',105,15,'crampon1923','" Ne touchez pas à mes oints, et ne faites pas de mal à mes prophètes! "'),
('ps',105,16,'crampon1923','Il appela la famine sur le pays, il les priva du pain qui les soutenait.'),
('ps',105,17,'crampon1923','Il envoya devant eux un homme: Joseph fut vendu comme esclave.'),
('ps',105,18,'crampon1923','On serra ses pieds dans des liens, on le jeta dans les fers,'),
('ps',105,19,'crampon1923','jusqu''au jour où s''accomplit sa prédiction, et où la parole de Dieu le justifia.'),
('ps',105,20,'crampon1923','Le roi envoya ôter ses liens, le souverain des peuples le mit en liberté.'),
('ps',105,21,'crampon1923','Il l''établit seigneur sur sa maison, et gouverneur de tous ses domaines,'),
('ps',105,22,'crampon1923','afin de lier les princes, selon son gré, et pour enseigner la sagesse à ses anciens.'),
('ps',105,23,'crampon1923','Alors Israël vint en Egypte, et Jacob séjourna dans le pays de Cham.'),
('ps',105,24,'crampon1923','Dieu accrut grandement son peuple, et le rendit plus puissant que ses oppresseurs.'),
('ps',105,25,'crampon1923','Il changea leur cœur, au point qu''ils haïrent son peuple, et usèrent de perfidie envers ses serviteurs.'),
('ps',105,26,'crampon1923','Il envoya Moïse, son serviteur, et Aaron qu''il avait choisi.'),
('ps',105,27,'crampon1923','Ils accomplirent ses prodiges parmi eux, ils firent des miracles dans le pays de Cham.'),
('ps',105,28,'crampon1923','Il envoya des ténèbres et il fit la nuit, et ils ne furent pas rebelles à sa parole.'),
('ps',105,29,'crampon1923','Il changea leurs eaux en sang, et fit périr leurs poissons.'),
('ps',105,30,'crampon1923','Leur pays fourmilla de grenouilles, jusque dans les chambres de leurs rois.'),
('ps',105,31,'crampon1923','Il dit, et vint une nuée d''insectes, des moucherons sur tout leur territoire.'),
('ps',105,32,'crampon1923','Il leur donna pour pluie de la grêle, des flammes de feu dans leur pays.'),
('ps',105,33,'crampon1923','Il frappa leurs vignes et leurs figuiers, et brisa les arbres de leur contrée.'),
('ps',105,34,'crampon1923','Il dit, et arriva la sauterelle, des sauterelles sans nombre;'),
('ps',105,35,'crampon1923','elle dévorèrent toute l''herbe de leur pays, elles dévorèrent les produits de leurs champs.'),
('ps',105,36,'crampon1923','Il frappa tous les premiers-nés de leurs pays, les prémices de toute leur vigueur.'),
('ps',105,37,'crampon1923','Il fit sortir son peuple avec de l''argent et de l''or, et nul dans ses tribus ne chancela.'),
('ps',105,38,'crampon1923','Les Egyptiens se réjouirent de leur départ, car la crainte d''Israël les avait saisis.'),
('ps',105,39,'crampon1923','Il étendit la nuée pour les couvrir, et le feu pour les éclairer la nuit.'),
('ps',105,40,'crampon1923','A leur demande, il fit venir des cailles, et il les rassasia du pain du ciel.'),
('ps',105,41,'crampon1923','Il ouvrit le rocher, et des eaux jaillirent; elles coulèrent comme un fleuve dans le désert.'),
('ps',105,42,'crampon1923','Car il se souvint de sa parole sainte, d''Abraham, son serviteur.'),
('ps',105,43,'crampon1923','Il fit sortir son peuple dans l''allégresse, ses élus au milieu des cris de joie.'),
('ps',105,44,'crampon1923','Il leur donna les terres des nations, et ils possédèrent le fruit du travail des peuples,'),
('ps',105,45,'crampon1923','à la condition de garder ses préceptes, et d''observer ses lois. Alleluia!'),
('ps',106,1,'crampon1923','Alleluia! Célébrez Yahweh, car il est bon, car sa miséricorde est éternelle.'),
('ps',106,2,'crampon1923','Qui dira les hauts faits de Yahweh! Qui publiera toute sa gloire?'),
('ps',106,3,'crampon1923','Heureux ceux qui observent la loi, qui accomplissent la justice en tout temps!'),
('ps',106,4,'crampon1923','Souviens-toi de moi, Yahweh, dans ta bonté pour ton peuple, visite-moi avec ton secours,'),
('ps',106,5,'crampon1923','afin que je voie le bonheur de tes élus, que je me réjouisse de la joie de ton peuple, et que je me glorifie avec ton héritage.'),
('ps',106,6,'crampon1923','Nous avons péché comme nos pères, nous avons commis l''iniquité, nous avons fait le mal.'),
('ps',106,7,'crampon1923','Nos pères en Egypte n''eurent pas d''égard à tes prodiges, ils ne se souvinrent pas de la multitude de tes grâces, ils se sont révoltés à la mer, à la mer Rouge.'),
('ps',106,8,'crampon1923','Il les sauva pourtant à cause de son nom, pour faire éclater sa puissance.'),
('ps',106,9,'crampon1923','Il menaça la mer Rouge, et elle se dessécha; et il les fit marcher à travers l''abîme comme dans un désert.'),
('ps',106,10,'crampon1923','Il les sauva de la main de celui qui les haïssait, il les délivra de la main de l''oppresseur.'),
('ps',106,11,'crampon1923','Les flots couvrirent leurs adversaires, pas un seul n''échappa.'),
('ps',106,12,'crampon1923','Ils crurent alors à ses paroles, ils chantèrent ses louanges.'),
('ps',106,13,'crampon1923','Mais ils oublièrent bientôt ses œuvres, ils n''attendirent pas qu''il exécutât ses desseins.'),
('ps',106,14,'crampon1923','Ils furent pris de convoitise dans le désert, et ils tentèrent Dieu dans la solitude.'),
('ps',106,15,'crampon1923','Il leur accorda ce qu''ils demandaient, mais il les frappa de consomption.'),
('ps',106,16,'crampon1923','Puis ils furent jaloux de Moïse dans le camp, et d''Aaron, le saint de Yahweh.'),
('ps',106,17,'crampon1923','La terre s''ouvrit et engloutit Dathan, et elle se referma sur la troupe d''Abiron;'),
('ps',106,18,'crampon1923','Le feu dévora leur troupe, la flamme consuma les méchants.'),
('ps',106,19,'crampon1923','Ils firent un veau au mont Horeb, ils se prosternèrent devant une image de métal fondu;'),
('ps',106,20,'crampon1923','Ils échangèrent leur gloire contre la figure d''un bœuf qui mange l''herbe.'),
('ps',106,21,'crampon1923','Ils oublièrent Dieu, leur sauveur, qui avait fait de grandes choses en Egypte,'),
('ps',106,22,'crampon1923','des miracles dans le pays de Cham, des prodiges à la mer Rouge.'),
('ps',106,23,'crampon1923','Il parlait de les exterminer, si Moïse, son élu, ne se fût tenu sur la brèche devant lui, pour empêcher sa colère de les détruire.'),
('ps',106,24,'crampon1923','Ils dédaignèrent la terre de délices, ils ne crurent pas à la parole de Yahweh;'),
('ps',106,25,'crampon1923','ils murmurèrent dans leurs tentes, et n''obéirent pas à sa voix.'),
('ps',106,26,'crampon1923','Alors il leva la main contre eux, jurant de les faire périr dans le désert,'),
('ps',106,27,'crampon1923','de faire périr leur race parmi les nations, et de les disperser en d''autres contrées.'),
('ps',106,28,'crampon1923','Ils s''attachèrent à Béelphégor et mangèrent des victimes offertes aux morts.'),
('ps',106,29,'crampon1923','Ils irritèrent Yahweh par leurs actions, et un fléau fit irruption parmi eux.'),
('ps',106,30,'crampon1923','Phinées se leva et donna satisfaction, et le fléau fut arrêté.'),
('ps',106,31,'crampon1923','Cette action fut imputée à justice, d''âge en âge, à jamais.'),
('ps',106,32,'crampon1923','Ils irritèrent Yahweh aux eaux de Mériba, et Moïse eut à souffrir à cause d''eux;'),
('ps',106,33,'crampon1923','car ils aigrirent son esprit, et il prononça des paroles inconsidérées.'),
('ps',106,34,'crampon1923','Ils n''exterminèrent point les peuples que Yahweh leur avait ordonné de détruire.'),
('ps',106,35,'crampon1923','Ils se mêlèrent aux nations, et ils apprirent leurs œuvres.'),
('ps',106,36,'crampon1923','Ils servirent leurs idoles, qui furent pour eux un piège.'),
('ps',106,37,'crampon1923','Ils immolèrent leurs fils et leurs filles aux démons.'),
('ps',106,38,'crampon1923','Ils versèrent le sang innocent, le sang de leurs fils et de leurs filles, qu''ils sacrifiaient aux idoles de Chanaan; et le pays fut profané par des meurtres.'),
('ps',106,39,'crampon1923','Ils se souillèrent par leurs œuvres, ils se prostituèrent par leurs actions.'),
('ps',106,40,'crampon1923','La colère de Yahweh s''alluma contre son peuple, et il prit en horreur son héritage.'),
('ps',106,41,'crampon1923','Il les livra entre les mains des nations, ceux qui les haïssaient dominèrent sur eux.'),
('ps',106,42,'crampon1923','Leurs ennemis les opprimèrent, et ils furent humiliés sous leur main.'),
('ps',106,43,'crampon1923','Bien des fois il les délivra, mais ils furent rebelles dans leurs desseins, et se perdirent par leurs iniquités.'),
('ps',106,44,'crampon1923','Néanmoins, il regarda leur détresse, lorsqu''il entendit leurs supplications.'),
('ps',106,45,'crampon1923','Il se souvint en leur faveur de son alliance, il eut pitié d''eux selon sa grande bonté,'),
('ps',106,46,'crampon1923','et il en fit l''objet de ses miséricordes, devant tous ceux qui les tenaient captifs.'),
('ps',106,47,'crampon1923','Sauve-nous Yahweh, notre Dieu, et rassemble-nous du milieu des nations, afin que nous célébrions ton saint nom, et que nous mettions notre gloire à te louer.'),
('ps',106,48,'crampon1923','Béni soit Yahweh, Dieu d''Israël, d''éternité en éternité! Et que tout le peuple dise: Amen! Alleluia!'),
('ps',107,1,'crampon1923','Célébrez Yahweh, car il est bon, car sa miséricorde est éternelle.'),
('ps',107,2,'crampon1923','Qu''ainsi disent les rachetés de Yahweh, ceux qu''il a rachetés des mains de l''ennemi,'),
('ps',107,3,'crampon1923','et qu''il a rassemblés de tous les pays, de l''orient et de l''occident, du nord et de la mer!'),
('ps',107,4,'crampon1923','Ils erraient dans le désert, dans un chemin solitaire, sans trouver une ville à habiter.'),
('ps',107,5,'crampon1923','En proie à la faim, à la soif, ils sentaient leur âme défaillir.'),
('ps',107,6,'crampon1923','Dans leur détresse, ils crièrent vers Yahweh, et il les délivra de leurs angoisses.'),
('ps',107,7,'crampon1923','Il les mena par le droit chemin, pour les faire arriver à une ville habitable.'),
('ps',107,8,'crampon1923','Qu''ils louent Yahweh pour sa bonté, et pour ses merveilles en faveur du fils de l''homme.'),
('ps',107,9,'crampon1923','Car il a désaltéré l''âme altérée, et comblé de biens l''âme affamée.'),
('ps',107,10,'crampon1923','Ils habitaient les ténèbres et l''ombre de la mort, prisonniers dans la souffrance et dans les fers.'),
('ps',107,11,'crampon1923','Parce qu''ils s''étaient révoltés contre les oracles du Dieu, et qu''ils avaient méprisé le conseil du Très-Haut,'),
('ps',107,12,'crampon1923','il humilia leur cœur par la souffrance; ils s''affaissèrent, et personne ne les secourut.'),
('ps',107,13,'crampon1923','Dans leur détresse, ils crièrent vers Yahweh, et il les sauva de leurs angoisses.'),
('ps',107,14,'crampon1923','Il les tira des ténèbres et de l''ombre de la mort, et il brisa leurs chaînes.'),
('ps',107,15,'crampon1923','Qu''ils louent Yahweh pour sa bonté, et pour ses merveilles en faveur des fils de l''homme.'),
('ps',107,16,'crampon1923','Car il a brisé les portes d''airain et mis en pièces les verrous de fer.'),
('ps',107,17,'crampon1923','Les insensés! par leur conduite criminelle, et par leurs iniquités, ils avaient attiré sur eux la souffrance.'),
('ps',107,18,'crampon1923','Leur âme avait en horreur toute nourriture, et ils touchaient aux portes de la mort.'),
('ps',107,19,'crampon1923','Dans leur détresse, ils crièrent vers Yahweh, et il les sauva de leurs angoisses.'),
('ps',107,20,'crampon1923','Il envoya sa parole et il les guérit, et il les fit échapper de leurs tombeaux.'),
('ps',107,21,'crampon1923','Qu''ils louent Yahweh pour sa bonté, et pour ses merveilles en faveur des fils de l''homme!'),
('ps',107,22,'crampon1923','Qu''ils offrent des sacrifices d''actions de grâce, et qu''ils publient ses œuvres avec des cris de joie!'),
('ps',107,23,'crampon1923','Ils étaient descendus sur la mer dans des navires, pour faire le négoce sur les vastes eaux:'),
('ps',107,24,'crampon1923','— ceux là ont vu les œuvres de Yahweh, et ses merveilles au milieu de l''abîme —'),
('ps',107,25,'crampon1923','Il dit, et il fit lever un vent de tempête, qui souleva les flots de la mer.'),
('ps',107,26,'crampon1923','Ils montaient jusqu''aux cieux, ils descendaient dans les abîmes; leur âme défaillait dans la peine.'),
('ps',107,27,'crampon1923','Saisis de vertige, ils chancelaient comme un homme ivre, et toute leur sagesse était anéantie.'),
('ps',107,28,'crampon1923','Dans leur détresse, ils crièrent vers Yahweh, et il les tira de leurs angoisses.'),
('ps',107,29,'crampon1923','Il changea l''ouragan en brise légère, et les vagues de la mer se turent.'),
('ps',107,30,'crampon1923','Ils se réjouirent en les voyant apaisées, et Yahweh les conduisit au port désiré.'),
('ps',107,31,'crampon1923','Qu''ils louent Yahweh pour sa bonté, et pour ses merveilles en faveur des fils de l''homme!'),
('ps',107,32,'crampon1923','Qu''ils l''exaltent dans l''assemblée du peuple, et qu''ils le célèbrent dans le conseil des anciens!'),
('ps',107,33,'crampon1923','Il a changé les fleuves en désert, et les sources d''eau en sol aride;'),
('ps',107,34,'crampon1923','Le pays fertile en plaine de sel, à cause de la méchanceté de ses habitants.'),
('ps',107,35,'crampon1923','Il a fait du désert un bassin d''eau, et de la terre aride un sol plein de sources.'),
('ps',107,36,'crampon1923','Il y établit les affamés, et ils fondèrent une ville pour l''habiter.'),
('ps',107,37,'crampon1923','Ils ensemencèrent des champs, et ils plantèrent des vignes, et ils recueillirent d''abondantes récoltes.'),
('ps',107,38,'crampon1923','Il les bénit, et ils se multiplièrent beaucoup, et il ne laissa pas diminuer leurs troupeaux.'),
('ps',107,39,'crampon1923','Ils avaient été réduits à un petit nombre et humiliés, sous l''accablement du malheur et de la souffrance.'),
('ps',107,40,'crampon1923','Il avait répandu la honte sur leurs princes, il les avait fait errer dans des déserts sans chemins.'),
('ps',107,41,'crampon1923','Mais il a relevé le malheureux de la misère, et il a rendu les familles pareilles à des troupeaux.'),
('ps',107,42,'crampon1923','Les hommes droits le voient et se réjouissent, et tous les méchants ferment la bouche.'),
('ps',107,43,'crampon1923','Que celui qui est sage prenne garde à ces choses, et qu''il comprenne les bontés de Yahweh!')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ps',108,1,'crampon1923','Cantique. Psaume de David.'),
('ps',108,2,'crampon1923','Mon cœur est affermi, ô Dieu, je chanterai et ferai retentir de joyeux instruments. Debout, ma gloire!'),
('ps',108,3,'crampon1923','Éveillez-vous, ma lyre et ma harpe! Que j''éveille l''aurore!'),
('ps',108,4,'crampon1923','Je te louerai parmi les peuples, Yahweh, je te chanterai parmi les nations.'),
('ps',108,5,'crampon1923','Car ta bonté s''élève au-dessus des cieux, et ta fidélité jusqu''aux nues.'),
('ps',108,6,'crampon1923','Élève-toi au-dessus des cieux, ô Dieu; que ta gloire brille sur toute la terre!'),
('ps',108,7,'crampon1923','Afin que tes bien-aimés soient délivrés, sauve par ta droite et exauce-moi.'),
('ps',108,8,'crampon1923','Dieu a parlé dans sa sainteté: " Je tressaillirai de joie! J''aurai Sichem en partage, je mesurerai la vallée de Succoth.'),
('ps',108,9,'crampon1923','Galaad est à moi, à moi Manassé; Ephraïm est l''armure de ma tête, et Judas mon sceptre.'),
('ps',108,10,'crampon1923','Moab est le bassin où je me lave; sur Edom je jette ma sandale; sur la terre des Philistins je pousse des cris de joie. "'),
('ps',108,11,'crampon1923','Qui me mènera à la ville forte! Qui me conduira à Edom?'),
('ps',108,12,'crampon1923','N''est-ce pas toi, ô Dieu, qui nous avais rejetés, ô Dieu qui ne sortais plus avec nos armées?'),
('ps',108,13,'crampon1923','Prête-nous ton secours contre l''oppresseur! Le secours de l''homme n''est que vanité.'),
('ps',108,14,'crampon1923','Avec Dieu nous accomplirons des exploits; il écrasera nos ennemis.'),
('ps',109,1,'crampon1923','Au maître de chant. Psaume de David. Dieu de ma louange, ne garde pas le silence!'),
('ps',109,2,'crampon1923','Car la bouche du méchant, la bouche du perfide, s''ouvre contre moi. Ils parlent contre moi avec une langue de mensonge,'),
('ps',109,3,'crampon1923','ils m''assiègent de paroles haineuses, et ils me font la guerre sans motif.'),
('ps',109,4,'crampon1923','En retour de mon affection, ils me combattent, et moi, je ne fais que prier.'),
('ps',109,5,'crampon1923','Ils me rendent le mal pour le bien, et la haine pour l''amour.'),
('ps',109,6,'crampon1923','Mets-le au pouvoir d''un méchant, et que l''accusateur se tienne à sa droite!'),
('ps',109,7,'crampon1923','Quand on le jugera, qu''il sorte coupable, et que sa prière soit réputée péché!'),
('ps',109,8,'crampon1923','Que ses jours soient abrégés, et qu''un autre prenne sa charge!'),
('ps',109,9,'crampon1923','Que ses enfants deviennent orphelins, que son épouse soit veuve!'),
('ps',109,10,'crampon1923','Que ses enfants soient vagabonds et mendiants, cherchant leur pain loin de leurs maisons en ruines!'),
('ps',109,11,'crampon1923','Que le créancier s''empare de tout ce qui est à lui, et que les étrangers pillent ce qu''il a gagné par son travail!'),
('ps',109,12,'crampon1923','Qu''il n''ait personne qui lui garde son affection, que nul n''ait pitié de ses orphelins!'),
('ps',109,13,'crampon1923','Que ses descendants soient voués à la ruine, et que leur nom soit effacé à la seconde génération!'),
('ps',109,14,'crampon1923','Que l''iniquité de ses pères reste en souvenir devant Yahweh, et que la faute de leur mère ne soit point effacée!'),
('ps',109,15,'crampon1923','Qu''elles soient toujours devant Yahweh, et qu''il retranche de la terre leur mémoire!'),
('ps',109,16,'crampon1923','Parce qu''il ne s''est pas souvenu d''exercer la miséricorde, parce qu''il a persécuté le malheureux et l''indigent, et l''homme au cœur brisé pour le faire mourir.'),
('ps',109,17,'crampon1923','Il aimait la malédiction: elle tombe sur lui; il dédaignait la bénédiction: elle s''éloigne de lui.'),
('ps',109,18,'crampon1923','Il s''est revêtu de la malédiction comme d''un vêtement; comme l''eau elle entre au-dedans de lui, et comme l''huile elle pénètre dans ses os.'),
('ps',109,19,'crampon1923','Qu''elle soit pour lui le vêtement qui l''enveloppe, la ceinture qui ne cesse de l''entourer!'),
('ps',109,20,'crampon1923','Tel soit, de la part de Yahweh le salaire de mes adversaires, et de ceux qui parlent méchamment contre moi.'),
('ps',109,21,'crampon1923','Et toi, Seigneur Yahweh, prends ma défense à cause de ton nom; dans ta grande bonté, délivre-moi.'),
('ps',109,22,'crampon1923','Car je suis malheureux et indigent, et mon cœur est blessé au-dedans de moi.'),
('ps',109,23,'crampon1923','Je m''en vais comme l''ombre à son déclin, je suis emporté comme la sauterelle.'),
('ps',109,24,'crampon1923','A force de jeûne mes genoux chancellent, et mon corps est épuisé de maigreur.'),
('ps',109,25,'crampon1923','Je suis pour eux un objet d''opprobre; ils me regardent et branlent de la tête.'),
('ps',109,26,'crampon1923','Secours-moi, Yahweh, mon Dieu! Sauve-moi dans ta bonté!'),
('ps',109,27,'crampon1923','Qu''ils sachent que c''est ta main, que c''est toi, Yahweh, qui l''a fait!'),
('ps',109,28,'crampon1923','Eux, ils maudissent; mais toi, tu béniras; ils se lèvent, mais ils seront confondus, et ton serviteur sera dans la joie.'),
('ps',109,29,'crampon1923','Mes adversaires seront revêtus d''ignominie, ils seront enveloppés de leur honte comme d''un manteau.'),
('ps',109,30,'crampon1923','Mes lèvres loueront hautement Yahweh; je le célébrerai au milieu de la multitude;'),
('ps',109,31,'crampon1923','car il se tient à la droite du pauvre, pour le sauver de ceux qui le condamnent.'),
('ps',110,1,'crampon1923','Psaume de David. Yahweh a dit à mon Seigneur: " Assieds-toi à ma droite, jusqu''à ce que je fasse de tes ennemis l''escabeau de tes pieds. "'),
('ps',110,2,'crampon1923','Yahweh étendra de Sion le sceptre de ta puissance: Règne en maître au milieu de tes ennemis!'),
('ps',110,3,'crampon1923','Ton peuple accourt à toi au jour où tu rassembles ton armée, avec des ornements sacrés; du sein de l''aurore vient à toi la rosée de tes jeunes guerriers.'),
('ps',110,4,'crampon1923','Le Seigneur l''a juré, il ne s''en repentira point: " Tu es prêtre pour toujours à la manière de Melchisédech. "'),
('ps',110,5,'crampon1923','Le Seigneur, est à droite, Il brisera les rois au jour de sa colère.'),
('ps',110,6,'crampon1923','Il exerce son jugement parmi les nations: tout est rempli de cadavres; il brise les têtes de la terre entière.'),
('ps',110,7,'crampon1923','Il boit au torrent sur le chemin, c''est pourquoi il relève la tête.'),
('ps',111,1,'crampon1923','Alleluia! ALEPH. Je veux louer Yahweh de tout mon cœur, BETH. dans la réunion des justes et dans l''assemblée.'),
('ps',111,2,'crampon1923','GHIMEL. Grandes sont les œuvres de Yahweh, DALETH. recherchées pour toutes les délices qu''elles procurent.'),
('ps',111,3,'crampon1923','HÉ. Son œuvre n''est que splendeur et magnificence, VAV. et sa justice subsiste à jamais.'),
('ps',111,4,'crampon1923','ZAÏN. Il a laissé un souvenir de ses merveilles; HETH. Yahweh est miséricordieux et compatissant.'),
('ps',111,5,'crampon1923','TETH. Il a donné une nourriture à ceux qui le craignent; YOD. il se souvient pour toujours de son alliance.'),
('ps',111,6,'crampon1923','CAPH. Il a manifesté à son peuple la puissance de ses œuvres, LAMED. en lui livrant l''héritage des nations.'),
('ps',111,7,'crampon1923','MEM. Les œuvres de ses mains sont vérité et justice, NUN. tous ses commandements sont immuables,'),
('ps',111,8,'crampon1923','SAMECH. affermis pour l''éternité, AÏN. faits selon la vérité et la droiture.'),
('ps',111,9,'crampon1923','PHÉ.Il a envoyé la délivrance à son peuple, TSADÉ. il a établi pour toujours son alliance; QOPH. son nom est saint et redoutable.'),
('ps',111,10,'crampon1923','RESCH. La crainte de Yahweh est le commencement de la sagesse; SCHIN. ceux-là sont vraiment intelligents, qui observent sa loi. THAV. Sa louange demeure à jamais.'),
('ps',112,1,'crampon1923','Alleluia! ALEPH. Heureux l''homme qui craint Yahweh, BETH. qui met toute sa joie à observer ses préceptes!'),
('ps',112,2,'crampon1923','GHIMEL. Sa postérité sera puissante sur la terre, DALETH. la race des justes sera bénie.'),
('ps',112,3,'crampon1923','HÉ. Il a dans sa maison bien-être et richesse, VAV. et sa justice subsiste à jamais.'),
('ps',112,4,'crampon1923','ZAÏN. La lumière se lève dans les ténèbres pour les hommes droits, HETH. pour celui qui est miséricordieux, compatissant et juste.'),
('ps',112,5,'crampon1923','TETH. Heureux l''homme qui exerce la miséricorde et qui prête: YOD. en justice il fait prévaloir sa cause.'),
('ps',112,6,'crampon1923','CAPH. Car il ne sera jamais ébranlé; LAMED. le juste laissera une mémoire éternelle.'),
('ps',112,7,'crampon1923','MEM. Il ne craint pas les funestes nouvelles; NUN. son cœur est ferme, confiant en Yahweh.'),
('ps',112,8,'crampon1923','SAMECH. Son cœur est inébranlable, il ne craint pas, AÏN. jusqu''à ce qu''il voie ses ennemis abattus.'),
('ps',112,9,'crampon1923','PHÉ. Il sème l''aumône, il donne à l''indigent; TSADÉ. sa justice subsiste à jamais, QOPH. sa corne s''élève avec gloire.'),
('ps',112,10,'crampon1923','RESCH. Le méchant le voit et s''irrite, SCHIN. il grince des dents et l''envie le consume: THAV. le désir des méchants périra.'),
('ps',113,1,'crampon1923','Alleluia! Louez, serviteurs de Yahweh, louez le nom de Yahweh,'),
('ps',113,2,'crampon1923','Que le nom de Yahweh soit béni, dès maintenant et à jamais!'),
('ps',113,3,'crampon1923','Du lever du soleil jusqu''à son couchant, loué soit le nom de Yahweh!'),
('ps',113,4,'crampon1923','Yahweh est élevé au-dessus de toutes les nations, sa gloire est au-dessus des cieux.'),
('ps',113,5,'crampon1923','Qui est semblable à Yahweh, notre Dieu? Il siège dans les hauteurs,'),
('ps',113,6,'crampon1923','et il regarde en bas, dans les cieux et sur la terre.'),
('ps',113,7,'crampon1923','Il relève le malheureux de la poussière, il retire le pauvre du fumier,'),
('ps',113,8,'crampon1923','pour les faire asseoir avec les princes, avec les princes de son peuple.'),
('ps',113,9,'crampon1923','Il donne une demeure à la stérile de la maison, il en fait une mère joyeuse au milieu de ses enfants. Alleluia!'),
('ps',114,1,'crampon1923','Quand Israël sortit d''Egypte, quand la maison de Jacob s''éloigna d''un peuple barbare,'),
('ps',114,2,'crampon1923','Juda devint son sanctuaire, Israël son domaine.'),
('ps',114,3,'crampon1923','La mer le vit et s''enfuit, le Jourdain retourna en arrière;'),
('ps',114,4,'crampon1923','les montagnes bondirent comme des béliers, les collines comme des agneaux.'),
('ps',114,5,'crampon1923','Qu''as-tu, mer, pour t''enfuir? Jourdain, pour retourner en arrière?'),
('ps',114,6,'crampon1923','Qu''avez-vous, montagnes, pour bondir comme des béliers, et vous, collines, comme des agneaux?'),
('ps',114,7,'crampon1923','Tremble, ô terre, devant la face du Seigneur, devant la face du Dieu de Jacob,'),
('ps',114,8,'crampon1923','qui change le rocher en étang, le roc en source d''eaux.'),
('ps',115,1,'crampon1923','Non pas à nous, Yahweh, non pas à nous, mais à ton nom donne la gloire, à cause de ta bonté, à cause de ta fidélité!'),
('ps',115,2,'crampon1923','Pourquoi les nations diraient-elles: « Où donc est leur Dieu? »'),
('ps',115,3,'crampon1923','Notre Dieu est dans le ciel; tout ce qu''il veut, il le fait.'),
('ps',115,4,'crampon1923','Leurs idoles sont de l''argent et de l''or, ouvrage de la main des hommes.'),
('ps',115,5,'crampon1923','Elles ont une bouche, et ne parlent point; elles ont des yeux, et ne voient point.'),
('ps',115,6,'crampon1923','Elles ont des oreilles, et n''entendent point; elles ont des narines, et ne sentent point.'),
('ps',115,7,'crampon1923','Elles ont des mains, et ne touchent point; elles ont des pieds, et ne marchent point; de leur gosier elles ne font entendre aucun son.'),
('ps',115,8,'crampon1923','Qu''ils leur ressemblent ceux qui les font, et quiconque se confie à elles!'),
('ps',115,9,'crampon1923','Israël, mets ta confiance en Yahweh! Il est leur secours et leur bouclier.'),
('ps',115,10,'crampon1923','Maison d''Aaron, mets ta confiance en Yahweh! Il est leur secours et leur bouclier.'),
('ps',115,11,'crampon1923','Vous qui craignez Yahweh, mettez votre confiance en Yahweh! Il est leur secours et leur bouclier.'),
('ps',115,12,'crampon1923','Yahweh s''est souvenu de nous: il bénira! Il bénira la maison d''Israël; il bénira la maison d''Aaron;'),
('ps',115,13,'crampon1923','il bénira ceux qui craignent Yahweh, les petits avec les grands.'),
('ps',115,14,'crampon1923','Que Yahweh multiplie sur vous ses faveurs, sur vous et sur vos enfants!'),
('ps',115,15,'crampon1923','Soyez bénis de Yahweh, qui a fait les cieux et la terre!'),
('ps',115,16,'crampon1923','Les cieux sont les cieux de Yahweh, mais il a donné la terre aux fils de l''homme.'),
('ps',115,17,'crampon1923','Ce ne sont pas les morts qui louent Yahweh, ceux qui descendent dans le lieu du silence;'),
('ps',115,18,'crampon1923','mais nous, nous bénirons Yahweh, dès maintenant et à jamais. Alleluia!'),
('ps',116,1,'crampon1923','Je l''aime, car Yahweh entend ma voix, mes supplications.'),
('ps',116,2,'crampon1923','Car il a incliné vers moi son oreille, et toute ma vie, je l''invoquerai.'),
('ps',116,3,'crampon1923','Les liens de la mort m''entouraient, et les angoisses du schéol m''avaient saisi; j''étais en proie à la détresse et à l''affliction.'),
('ps',116,4,'crampon1923','Et j''ai invoqué le nom de Yahweh: « Yahweh, sauve mon âme! »'),
('ps',116,5,'crampon1923','Yahweh est miséricordieux et juste, notre Dieu est compatissant.'),
('ps',116,6,'crampon1923','Yahweh garde les faibles; j''étais malheureux, et il m''a sauvé.'),
('ps',116,7,'crampon1923','Mon âme, retourne à ton repos; car Yahweh te comble de biens.'),
('ps',116,8,'crampon1923','Oui, tu as sauvé mon âme de la mort, mon œil des larmes, mes pieds de la chute.'),
('ps',116,9,'crampon1923','Je marcherai encore devant Yahweh, dans la terre des vivants.'),
('ps',116,10,'crampon1923','J''ai confiance, alors même que je dis: « je suis malheureux à l''excès. »'),
('ps',116,11,'crampon1923','Je disais dans mon abattement: « Tout homme est menteur. »'),
('ps',116,12,'crampon1923','Que rendrai-je à Yahweh pour tous ses bienfaits à mon égard!'),
('ps',116,13,'crampon1923','J''élèverai la coupe du salut, et j''invoquerai le nom de Yahweh.'),
('ps',116,14,'crampon1923','J''accomplirai mes vœux envers Yahweh en présence de tout son peuple.'),
('ps',116,15,'crampon1923','Elle a du prix aux yeux de Yahweh, la mort de ses fidèles.'),
('ps',116,16,'crampon1923','Ah! Yahweh, parce que je suis ton serviteur, ton serviteur, fils de ta servante, tu as détaché mes liens.'),
('ps',116,17,'crampon1923','Je t''offrirai un sacrifice d''actions de grâces, et j''invoquerai le nom de Yahweh.'),
('ps',116,18,'crampon1923','J''accomplirai mes vœux envers Yahweh, en présence de tout son peuple,'),
('ps',116,19,'crampon1923','dans les parvis de la maison de Yahweh, dans ton enceinte, Jérusalem. Alleluia!'),
('ps',117,1,'crampon1923','Nations, louez toutes Yahweh; peuples, célébrez-le tous!'),
('ps',117,2,'crampon1923','Car sa bonté pour nous est grande, et la vérité de Yahweh subsiste à jamais. Alleluia!'),
('ps',118,1,'crampon1923','Célébrez Yahweh, car il est bon, car sa miséricorde est éternelle.'),
('ps',118,2,'crampon1923','Qu''Israël dise: « Oui, sa miséricorde est éternelle! »'),
('ps',118,3,'crampon1923','Que la maison d''Aaron dise: « Oui, sa miséricorde est éternelle! »'),
('ps',118,4,'crampon1923','Que ceux qui craignent Yahweh disent: « Oui, sa miséricorde est éternelle! » Pendant le trajet.'),
('ps',118,5,'crampon1923','Du sein de ma détresse j''ai invoqué Yahweh: Yahweh m''a exaucé et m''a mis au large.'),
('ps',118,6,'crampon1923','Yahweh est pour moi, je ne crains rien: que peuvent me faire des hommes?'),
('ps',118,7,'crampon1923','Yahweh est pour moi parmi ceux qui me secourent; je verrai la ruine de ceux qui me haïssent.'),
('ps',118,8,'crampon1923','Mieux vaut chercher un refuge en Yahweh, que de se confier aux hommes.'),
('ps',118,9,'crampon1923','Mieux vaut chercher un refuge en Yahweh, que de se confier aux princes.'),
('ps',118,10,'crampon1923','Toutes les nations m''environnaient: au nom de Yahweh, je les taille en pièces.'),
('ps',118,11,'crampon1923','Elles m''environnaient et m''enveloppaient: au nom de Yahweh, je les taille en pièces.'),
('ps',118,12,'crampon1923','Elles m''environnaient comme des abeilles: elles s''éteignent comme un feu d''épines; au nom de Yahweh, je les taille en pièces.'),
('ps',118,13,'crampon1923','Tu me poussais violemment pour me faire tomber, mais Yahweh m''a secouru.'),
('ps',118,14,'crampon1923','Yahweh est ma force et l''objet de mes chants; il a été mon salut.'),
('ps',118,15,'crampon1923','Des cris de triomphe et de délivrance retentissent dans les tentes des justes. La droite de Yahweh a déployé sa force;'),
('ps',118,16,'crampon1923','la droite de Yahweh est élevée, la droite de Yahweh a déployé sa force.'),
('ps',118,17,'crampon1923','Je ne mourrai pas, je vivrai, et je raconterai les œuvres de Yahweh.'),
('ps',118,18,'crampon1923','Yahweh m''a durement châtié, mais il ne m''a pas livré à la mort. Le chef, arrivé devant le temple.'),
('ps',118,19,'crampon1923','Ouvrez-moi les portes de la justice, afin que j''entre et que je loue Yahweh. Les prêtres.'),
('ps',118,20,'crampon1923','C''est la porte de Yahweh; les justes peuvent y entrer. Le chef du peuple.'),
('ps',118,21,'crampon1923','Je te célébrerai, parce que tu m''as exaucé, et que tu as été mon salut.'),
('ps',118,22,'crampon1923','La pierre rejetée par ceux qui bâtissaient est devenue la pierre angulaire. Les prêtres'),
('ps',118,23,'crampon1923','C''est l''œuvre de Yahweh, c''est une chose merveilleuse à nos yeux. Le peuple, en entrant.'),
('ps',118,24,'crampon1923','Voici le jour que Yahweh a fait; livrons-nous à l''allégresse et à la joie.'),
('ps',118,25,'crampon1923','O Yahweh, donne le salut! O Yahweh, donne la prospérité! Les prêtres, au chef.'),
('ps',118,26,'crampon1923','Béni soit celui qui vient au nom de Yahweh! Nous vous bénissons de la maison de Yahweh!'),
('ps',118,27,'crampon1923','Yahweh est Dieu, il fait briller sur nous la lumière. Les prêtres, au peuple. Attachez la victime avec des liens, jusqu''aux cornes de l''autel. Le peuple.'),
('ps',118,28,'crampon1923','Tu es mon Dieu, et je te célébrerai; mon Dieu, et je t''exalterai. Tous ensemble.'),
('ps',118,29,'crampon1923','Célébrez Yahweh, car il est bon, car sa miséricorde est éternelle.'),
('ps',119,1,'crampon1923','Heureux ceux qui sont irréprochables dans leur voie, qui marchent selon la loi de Yahweh!'),
('ps',119,2,'crampon1923','Heureux ceux qui gardent ses enseignements, qui le cherchent de tout leur cœur,'),
('ps',119,3,'crampon1923','qui ne commettent pas l''iniquité et qui marchent dans ses voies!'),
('ps',119,4,'crampon1923','Tu as prescrit tes ordonnances, pour qu''on les observe avec soin.'),
('ps',119,5,'crampon1923','Puissent mes voies être dirigées, pour que j''observe tes lois!'),
('ps',119,6,'crampon1923','Alors je n''aurai point à rougir, à la vue de tous tes commandements.'),
('ps',119,7,'crampon1923','Je te louerai dans la droiture de mon cœur, en apprenant les préceptes de ta justice.'),
('ps',119,8,'crampon1923','Je veux garder tes lois: ne me délaisse pas complètement. BETH.'),
('ps',119,9,'crampon1923','Comment le jeune homme rendra-t-il pur son sentier? En se gardant selon ta parole.'),
('ps',119,10,'crampon1923','Je te cherche de tout mon cœur: ne me laisse pas errer loin de tes commandements.'),
('ps',119,11,'crampon1923','Je garde ta parole cachée dans mon cœur, afin de ne pas pécher contre toi.'),
('ps',119,12,'crampon1923','Béni sois-tu, Yahweh! Enseigne-moi tes lois.'),
('ps',119,13,'crampon1923','De mes lèvres j''énumère tous les préceptes de ta bouche.'),
('ps',119,14,'crampon1923','J''ai de la joie à suivre tes enseignements, comme si je possédais tous les trésors.'),
('ps',119,15,'crampon1923','Je veux méditer tes ordonnances, avoir les yeux sur tes sentiers.'),
('ps',119,16,'crampon1923','Je fais mes délices de tes lois, je n''oublierai pas ta parole. GHIMEL.'),
('ps',119,17,'crampon1923','Use de bonté envers ton serviteur, afin que je vive, et j''observerai ta parole.'),
('ps',119,18,'crampon1923','Ouvre mes yeux, pour que je contemple les merveilles de ta loi.'),
('ps',119,19,'crampon1923','Je suis un étranger sur la terre: ne me cache pas tes commandements.'),
('ps',119,20,'crampon1923','Mon âme est brisée par le désir, qui toujours la porte vers tes préceptes.'),
('ps',119,21,'crampon1923','Tu menaces les orgueilleux, ces maudits, qui s''égarent loin de tes commandements.'),
('ps',119,22,'crampon1923','Eloigne de moi la honte et le mépris, car j''observe tes enseignements.'),
('ps',119,23,'crampon1923','Que les princes siègent et parlent contre moi: ton serviteur méditera tes lois.'),
('ps',119,24,'crampon1923','Oui, tes enseignements font mes délices, ce sont les hommes de mon conseil. DALETH.'),
('ps',119,25,'crampon1923','Mon âme est attachée à la poussière: rends-moi la vie, selon ta parole!'),
('ps',119,26,'crampon1923','Je t''ai exposé mes voies, et tu m''as répondu: enseigne-moi tes lois.'),
('ps',119,27,'crampon1923','Fais-moi comprendre la voie de tes ordonnances, et je méditerai sur tes merveilles.'),
('ps',119,28,'crampon1923','Mon âme, attristée, se fond en larmes: relève-moi selon ta parole.'),
('ps',119,29,'crampon1923','Eloigne de moi la voie du mensonge, et accorde-moi la faveur de ta loi.'),
('ps',119,30,'crampon1923','J''ai choisi la voie de la fidélité, je place tes préceptes sous mes yeux.'),
('ps',119,31,'crampon1923','Je me suis attaché à tes enseignements: Yahweh, ne permets pas que je sois confondu.'),
('ps',119,32,'crampon1923','Je cours dans la voie de tes commandements, car tu élargis mon cœur. HÉ.'),
('ps',119,33,'crampon1923','Enseigne-moi, Yahweh, la voie de tes préceptes, afin que je la garde jusqu''à la fin de ma vie.'),
('ps',119,34,'crampon1923','Donne-moi l''intelligence pour que je garde ta loi, et que je l''observe de tout mon cœur.'),
('ps',119,35,'crampon1923','Conduis-moi dans le sentier de tes commandements, car j''y trouve le bonheur.'),
('ps',119,36,'crampon1923','Incline mon cœur vers tes enseignements, et non vers le gain.'),
('ps',119,37,'crampon1923','Détourne mes yeux pour qu''ils ne voient point la vanité, fais-moi vivre dans ta voie.'),
('ps',119,38,'crampon1923','Accomplis envers ton serviteur ta promesse, que tu as faite à ceux qui te craignent.'),
('ps',119,39,'crampon1923','Ecarte de moi l''opprobre que je redoute, car tes préceptes sont bons.'),
('ps',119,40,'crampon1923','Je désire ardemment pratiquer tes ordonnances: par ta justice, fais-moi vivre. VAV.'),
('ps',119,41,'crampon1923','Que vienne sur moi ta miséricorde, Yahweh, et ton salut, selon ta parole!'),
('ps',119,42,'crampon1923','Et je pourrai répondre à celui qui m''outrage, car je me confie en ta parole.'),
('ps',119,43,'crampon1923','N''ôte pas entièrement de ma bouche la parole de vérité, car j''espère en tes préceptes.'),
('ps',119,44,'crampon1923','Je veux garder ta loi constamment, toujours et à perpétuité.'),
('ps',119,45,'crampon1923','Je marcherai au large, car je recherche tes ordonnances.'),
('ps',119,46,'crampon1923','Je parlerai de tes enseignements devant les rois, et je n''aurai point de honte.'),
('ps',119,47,'crampon1923','Je ferai mes délices de tes commandements, car je les aime.'),
('ps',119,48,'crampon1923','J''élèverai mes mains vers tes commandements que j''aime, et je méditerai tes lois. ZAÏN.'),
('ps',119,49,'crampon1923','Souviens-toi de la parole donnée à ton serviteur, sur laquelle tu fais reposer mon espérance.'),
('ps',119,50,'crampon1923','C''est ma consolation dans la misère, que ta parole me rende la vie.'),
('ps',119,51,'crampon1923','Des orgueilleux me prodiguent leurs railleries: je ne m''écarte point de ta loi.'),
('ps',119,52,'crampon1923','Je pense à tes préceptes des temps passés, Yahweh, et je me console.'),
('ps',119,53,'crampon1923','L''indignation me saisit à cause des méchants, qui abandonnent ta loi.'),
('ps',119,54,'crampon1923','Tes lois sont le sujet de mes cantiques, dans le lieu de mon pèlerinage.'),
('ps',119,55,'crampon1923','La nuit je me rappelle ton nom, Yahweh, et j''observe ta loi.'),
('ps',119,56,'crampon1923','Voici la part qui m''est donnée: je garde tes ordonnances. HETH.'),
('ps',119,57,'crampon1923','Ma part, Yahweh, je le dis, c''est de garder tes paroles.'),
('ps',119,58,'crampon1923','Je t''implore de tout mon cœur; aie pitié de moi selon ta parole.'),
('ps',119,59,'crampon1923','Je réfléchis à mes voies, et je ramène mes pas vers tes enseignements.'),
('ps',119,60,'crampon1923','Je me hâte, je ne diffère point d''observer tes commandements.'),
('ps',119,61,'crampon1923','Les pièges des méchants m''environnent, et je n''oublie point ta loi.'),
('ps',119,62,'crampon1923','Au milieu de la nuit, je me lève pour te louer, à cause des jugements de ta justice.'),
('ps',119,63,'crampon1923','Je suis l''ami de tous ceux qui te craignent, et de ceux qui gardent tes ordonnances.'),
('ps',119,64,'crampon1923','La terre est pleine de ta bonté, Yahweh: enseigne-moi tes lois. TETH.'),
('ps',119,65,'crampon1923','Tu as usé de bonté envers ton serviteur, Yahweh, selon ta parole.'),
('ps',119,66,'crampon1923','Enseigne-moi le sens droit et l''intelligence, car j''ai foi en tes commandements.'),
('ps',119,67,'crampon1923','Avant d''avoir été humilié, je m''égarais; maintenant, j''observe ta parole.'),
('ps',119,68,'crampon1923','Tu es bon et bienfaisant: enseigne-moi tes lois.'),
('ps',119,69,'crampon1923','Des orgueilleux imaginent contre moi des mensonges; moi, je garde de tout cœur tes ordonnances.'),
('ps',119,70,'crampon1923','Leur cœur est insensible comme la graisse; moi, je fais mes délices de ta loi.'),
('ps',119,71,'crampon1923','Il m''est bon d''avoir été humilié, afin que j''apprenne tes préceptes.'),
('ps',119,72,'crampon1923','Mieux vaut pour moi la loi de ta bouche; que des monceaux d''or et d''argent. YOD.'),
('ps',119,73,'crampon1923','Ce sont tes mains qui m''ont fait et qui m''ont façonné: donne-moi l''intelligence pour apprendre tes commandements.'),
('ps',119,74,'crampon1923','Ceux qui te craignent, en me voyant, se réjouiront, car j''ai confiance en ta parole.'),
('ps',119,75,'crampon1923','Je sais, Yahweh, que tes jugements sont justes; c''est dans ta fidélité que tu m''as humilié.'),
('ps',119,76,'crampon1923','Que ta bonté soit ma consolation, selon ta parole donnée à ton serviteur!'),
('ps',119,77,'crampon1923','Que ta compassion vienne sur moi, et que je vive, car ta loi fait mes délices!'),
('ps',119,78,'crampon1923','Qu''ils soient confondus les orgueilleux qui me maltraitent injustement! Moi, je médite tes ordonnances.'),
('ps',119,79,'crampon1923','Qu''ils se tournent vers moi ceux qui te craignent, et ceux qui connaissent tes enseignements!'),
('ps',119,80,'crampon1923','Que mon cœur soit tout entier à tes lois, afin que je ne sois pas confondu! CAPH.'),
('ps',119,81,'crampon1923','Mon âme languit après ton salut, j''espère en ta parole.'),
('ps',119,82,'crampon1923','Mes yeux languissent après ta promesse, je dis: « Quand me consoleras-tu? »'),
('ps',119,83,'crampon1923','Car je suis comme une outre exposée à la fumée, mais je n''oublie pas tes lois.'),
('ps',119,84,'crampon1923','Quel est le nombre des jours de ton serviteur? Quand donc feras-tu justice de ceux qui me poursuivent?'),
('ps',119,85,'crampon1923','Des orgueilleux creusent des fosses pour me perdre; ils sont les adversaires de ta loi.'),
('ps',119,86,'crampon1923','Tous tes commandements sont fidélité; ils me persécutent sans cause: secours-moi.'),
('ps',119,87,'crampon1923','Ils ont failli m''anéantir dans le pays; et moi je n''abandonne pas tes ordonnances.'),
('ps',119,88,'crampon1923','Rends-moi la vie dans ta bonté, et j''observerai l''enseignement de ta bouche. LAMED.'),
('ps',119,89,'crampon1923','A jamais, Yahweh, ta parole est établie dans les cieux.'),
('ps',119,90,'crampon1923','D''âge en âge ta fidélité demeure; tu as fondé la terre, et elle subsiste.'),
('ps',119,91,'crampon1923','C''est d''après tes lois que tout subsiste jusqu''à ce jour, car tout obéit à tes ordres.'),
('ps',119,92,'crampon1923','Si ta loi ne faisait mes délices, déjà j''aurais péri dans ma misère.'),
('ps',119,93,'crampon1923','Je n''oublierai jamais tes ordonnances, car c''est par elles que tu m''as rendu la vie.'),
('ps',119,94,'crampon1923','Je suis à toi: sauve-moi, car je recherche tes préceptes.'),
('ps',119,95,'crampon1923','Les méchants m''attendent pour me faire périr: je suis attentif à tes enseignements.'),
('ps',119,96,'crampon1923','J''ai vu des bornes à tout ce qui est parfait; ton commandement n''a point de limites. MEM.'),
('ps',119,97,'crampon1923','Combien j''aime ta loi! Elle est tout le jour l''objet de ma méditation.'),
('ps',119,98,'crampon1923','Par tes commandements, tu me rends plus sage que mes ennemis, car je les ai toujours avec moi.'),
('ps',119,99,'crampon1923','Je suis plus sage que tous mes maîtres, car tes enseignements sont l''objet de ma méditation.'),
('ps',119,100,'crampon1923','J''ai plus d''intelligence que les vieillards, car j''observe tes ordonnances.'),
('ps',119,101,'crampon1923','Je retiens mon pied loin de tout sentier mauvais, afin de garder ta parole.'),
('ps',119,102,'crampon1923','Je ne m''écarte pas de tes préceptes, car c''est toi qui m''as instruit.'),
('ps',119,103,'crampon1923','Que ta parole est douce à mon palais, plus que le miel à ma bouche!'),
('ps',119,104,'crampon1923','Par tes ordonnances je deviens intelligent, aussi je hais tous les sentiers du mensonge. NUN.'),
('ps',119,105,'crampon1923','Ta parole est un flambeau devant mes pas, une lumière sur mon sentier.'),
('ps',119,106,'crampon1923','J''ai juré, et j''y serai fidèle, — d''observer les préceptes de ta justice.'),
('ps',119,107,'crampon1923','Je suis réduit à une extrême affliction: Yahweh, rends-moi la vie, selon ta parole.'),
('ps',119,108,'crampon1923','Agrée, Yahweh, l''offrande de mes lèvres, et enseigne-moi tes préceptes.'),
('ps',119,109,'crampon1923','Ma vie est continuellement dans mes mains, et je n''oublie point ta loi.'),
('ps',119,110,'crampon1923','Les méchants me tendent des pièges, et je ne m''égare pas loin de tes ordonnances.'),
('ps',119,111,'crampon1923','J''ai tes enseignements pour toujours en héritage, car ils sont la joie de mon cœur.'),
('ps',119,112,'crampon1923','J''ai incliné mon cœur à observer tes lois, toujours, jusqu''à la fin. SAMECH.'),
('ps',119,113,'crampon1923','Je hais les hommes au cœur double, et j''aime ta loi.'),
('ps',119,114,'crampon1923','Tu es mon refuge et mon bouclier; j''ai confiance en ta parole.'),
('ps',119,115,'crampon1923','Retirez-vous de moi, méchants, et j''observerai les commandements de mon Dieu.'),
('ps',119,116,'crampon1923','Soutiens-moi selon ta promesse, afin que je vive, et ne permets pas que je sois confondu dans mon espérance.'),
('ps',119,117,'crampon1923','Sois mon appui, et je serai sauvé, et j''aurai toujours tes lois sous les yeux.'),
('ps',119,118,'crampon1923','Tu méprises tous ceux qui s''écartent de tes lois, car leur ruse n''est que mensonge.'),
('ps',119,119,'crampon1923','Tu rejettes comme des scories tous les méchants de la terre; c''est pourquoi j''aime tes enseignements.'),
('ps',119,120,'crampon1923','Ma chair frissonne de frayeur devant toi, et je redoute tes jugements. AÏN.'),
('ps',119,121,'crampon1923','J''observe le droit et la justice: ne m''abandonne pas à mes oppresseurs.'),
('ps',119,122,'crampon1923','Prends sous ta garantie le bien de ton serviteur; et que les orgueilleux ne m''oppriment pas!'),
('ps',119,123,'crampon1923','Mes yeux languissent après ton salut, et après la promesse de ta justice.'),
('ps',119,124,'crampon1923','Agis envers ton serviteur selon ta bonté, et enseigne-moi tes lois.'),
('ps',119,125,'crampon1923','Je suis ton serviteur: donne-moi l''intelligence, pour que je connaisse tes enseignements.'),
('ps',119,126,'crampon1923','Il est temps pour Yahweh d''intervenir: ils violent ta loi.'),
('ps',119,127,'crampon1923','C''est pourquoi j''aime tes commandements, plus que l''or et que l''or fin.'),
('ps',119,128,'crampon1923','C''est pourquoi je trouve justes toutes tes ordonnances, je hais tout sentier de mensonge. PHÉ.'),
('ps',119,129,'crampon1923','Tes enseignements sont merveilleux, aussi mon âme les observe.'),
('ps',119,130,'crampon1923','La révélation de tes paroles illumine, elle donne l''intelligence aux simples.'),
('ps',119,131,'crampon1923','J''ouvre la bouche et j''aspire, car je suis avide de tes commandements.'),
('ps',119,132,'crampon1923','Tourne vers moi ta face et aie pitié de moi; c''est justice envers ceux qui aiment ton nom.'),
('ps',119,133,'crampon1923','Affermis mes pas dans ta parole, et ne laisse aucune iniquité dominer sur moi.'),
('ps',119,134,'crampon1923','Délivre-moi de l''oppression des hommes, et je garderai tes ordonnances.'),
('ps',119,135,'crampon1923','Fais luire ta face sur ton serviteur, et enseigne-moi tes lois.'),
('ps',119,136,'crampon1923','Mes yeux répandent des torrents de larmes, parce qu''on n''observe pas ta loi. TSADÉ.'),
('ps',119,137,'crampon1923','Tu es juste, Yahweh, et tes jugements sont équitables.'),
('ps',119,138,'crampon1923','Tu as donné tes enseignements, selon la justice et une parfaite fidélité.'),
('ps',119,139,'crampon1923','Mon zèle me consume, parce que mes adversaires oublient tes paroles.'),
('ps',119,140,'crampon1923','Ta parole est entièrement éprouvée, et ton serviteur l''aime.'),
('ps',119,141,'crampon1923','Je suis petit et méprisé; mais je n''oublie point tes ordonnances.'),
('ps',119,142,'crampon1923','Ta justice est une justice éternelle, et ta loi est vérité.'),
('ps',119,143,'crampon1923','La détresse et l''angoisse m''ont atteint; tes commandements font mes délices.'),
('ps',119,144,'crampon1923','Tes enseignements sont éternellement justes; donne-moi l''intelligence, pour que je vive. QOPH.'),
('ps',119,145,'crampon1923','Je t''invoque de tout mon cœur; exauce-moi, Yahweh, afin que je garde tes lois.'),
('ps',119,146,'crampon1923','Je t''invoque, sauve-moi, afin que j''observe tes enseignements.'),
('ps',119,147,'crampon1923','Je devance l''aurore, et je crie vers toi; j''espère en ta parole.'),
('ps',119,148,'crampon1923','Mes yeux devancent les veilles de la nuit, pour méditer ta parole.'),
('ps',119,149,'crampon1923','Ecoute ma voix selon ta bonté; Yahweh, rends-moi la vie selon ton jugement.'),
('ps',119,150,'crampon1923','Ils s''approchent, ceux qui poursuivent le crime, qui se sont éloignés de ta loi.'),
('ps',119,151,'crampon1923','Tu es proche, Yahweh, et tous tes commandements sont la vérité.'),
('ps',119,152,'crampon1923','Dès longtemps je sais, au sujet de tes enseignements, que tu les as établis pour toujours. RESCH.'),
('ps',119,153,'crampon1923','Vois ma misère, et délivre-moi, car je n''oublie pas ta loi.'),
('ps',119,154,'crampon1923','Défends ma cause et sois mon vengeur, rends-moi la vie selon ta parole.'),
('ps',119,155,'crampon1923','Le salut est loin des méchants, car ils ne s''inquiètent pas de tes lois.'),
('ps',119,156,'crampon1923','Tes miséricordes sont nombreuses, Yahweh; rends-moi la vie selon tes jugements.'),
('ps',119,157,'crampon1923','Nombreux sont mes persécuteurs et mes ennemis; je ne m''écarte point de tes enseignements.'),
('ps',119,158,'crampon1923','A la vue des infidèles, j''ai ressenti de l''horreur, parce qu''ils n''observent pas ta parole.'),
('ps',119,159,'crampon1923','Considère que j''aime tes ordonnances; Yahweh, rends-moi la vie selon ta bonté.'),
('ps',119,160,'crampon1923','Le résumé de ta parole est la vérité, et toutes les lois de ta justice sont éternelles. SIN, SCHIN.'),
('ps',119,161,'crampon1923','Des princes me persécutent sans cause: c''est de tes paroles que mon cœur a de la crainte.'),
('ps',119,162,'crampon1923','Je me réjouis de ta parole, comme si j''avais trouvé de riches dépouilles.'),
('ps',119,163,'crampon1923','Je hais le mensonge, je l''ai en horreur; j''aime ta loi.'),
('ps',119,164,'crampon1923','Sept fois le jour je te loue, à cause des lois de ta justice.'),
('ps',119,165,'crampon1923','Il y a une grande paix pour ceux qui aiment ta loi, et rien ne leur est une cause de chute.'),
('ps',119,166,'crampon1923','J''espère en ton salut, Yahweh, et je pratique tes commandements.'),
('ps',119,167,'crampon1923','Mon âme observe tes enseignements, et elle en est éprise.'),
('ps',119,168,'crampon1923','Je garde tes ordonnances et tes enseignements, car toutes mes voies sont devant toi. THAV.'),
('ps',119,169,'crampon1923','Que mon cri arrive jusqu''à toi, Yahweh! Selon ta parole, donne-moi l''intelligence.'),
('ps',119,170,'crampon1923','Que ma supplication parvienne jusqu''à toi! Selon ta parole, délivre-moi.'),
('ps',119,171,'crampon1923','Que mes lèvres profèrent ta louange, car tu m''as enseigné tes lois!'),
('ps',119,172,'crampon1923','Que ma langue publie ta parole, car tous tes commandements sont justes!'),
('ps',119,173,'crampon1923','Que ta main s''étende pour me secourir, car j''ai choisi tes ordonnances!'),
('ps',119,174,'crampon1923','Je soupire après ton salut, Yahweh, et ta loi fait mes délices.'),
('ps',119,175,'crampon1923','Que mon âme vive pour te louer, et que tes jugements me viennent en aide!'),
('ps',119,176,'crampon1923','Je suis errant comme une brebis égarée: cherche ton serviteur; car je n''oublie pas tes commandements.'),
('ps',120,1,'crampon1923','Cantique des montées. Vers Yahweh, dans ma détresse, j''ai crié, et il m''a exaucé:'),
('ps',120,2,'crampon1923','« Yahweh délivre mon âme de la lèvre de mensonge, de la langue astucieuse! »'),
('ps',120,3,'crampon1923','Que te sera-t-il donné, quel sera ton profit, langue perfide?'),
('ps',120,4,'crampon1923','Les flèches aiguës du Tout-Puissant, avec les charbons ardents du genêt.'),
('ps',120,5,'crampon1923','Malheureux que je suis de séjourner dans Mések, d''habiter sous les tentes de Cédar!'),
('ps',120,6,'crampon1923','Trop longtemps j''ai demeuré avec ceux qui haïssent la paix.'),
('ps',120,7,'crampon1923','Je suis un homme de paix et, quand je leur parle, ils sont pour la guerre.'),
('ps',121,1,'crampon1923','Cantique pour les montées. Je lève les yeux vers les montagnes: d''où me viendra le secours?'),
('ps',121,2,'crampon1923','Mon secours viendra de Yahweh, qui a fait le ciel et la terre.'),
('ps',121,3,'crampon1923','Il ne permettra pas que ton pied trébuche; celui qui te garde ne sommeillera pas.'),
('ps',121,4,'crampon1923','Non, il ne sommeille ni ne dort, celui qui garde Israël.'),
('ps',121,5,'crampon1923','Yahweh est ton gardien; Yahweh est ton abri, toujours à ta droite.'),
('ps',121,6,'crampon1923','Pendant le jour le soleil ne te frappera point, ni la lune pendant la nuit.'),
('ps',121,7,'crampon1923','Yahweh te gardera de tout mal, il gardera ton âme:'),
('ps',121,8,'crampon1923','Yahweh gardera ton départ et ton arrivée maintenant et à jamais.'),
('ps',122,1,'crampon1923','Cantique des montées. De David. J''ai été dans la joie quand on m''a dit: « Allons à la maison de Yahweh! »'),
('ps',122,2,'crampon1923','Enfin! Nos pieds s''arrêtent à tes portes, Jérusalem!'),
('ps',122,3,'crampon1923','Jérusalem, tu es bâtie comme une ville où tout se tient ensemble.'),
('ps',122,4,'crampon1923','Là montent les tribus, les tribus de Yahweh, selon la loi d''Israël, pour louer le nom de Yahweh.'),
('ps',122,5,'crampon1923','Là sont établis des sièges pour le jugement, les sièges de la maison de David.'),
('ps',122,6,'crampon1923','Faites des vœux pour Jérusalem: Qu''ils soient heureux ceux qui t''aiment!'),
('ps',122,7,'crampon1923','Que la paix règne dans tes murs, la prospérité dans tes palais!'),
('ps',122,8,'crampon1923','A cause de mes frères et de mes amis, je demande pour toi la paix;'),
('ps',122,9,'crampon1923','à cause de la maison de Yahweh, notre Dieu, je désire pour toi le bonheur.'),
('ps',123,1,'crampon1923','Cantique des montées. J''élève mes yeux vers toi, ô toi qui siège dans les cieux!'),
('ps',123,2,'crampon1923','Comme l''œil du serviteur est fixé sur la main de son maître, et l''œil de la servante sur la main de sa maîtresse, ainsi nos yeux sont fixés sur Yahweh, notre Dieu, jusqu''à ce qu''il ait pitié de nous.'),
('ps',123,3,'crampon1923','Aie pitié de nous, Yahweh, aie pitié de nous, car nous n''avons été que trop rassasiés d''opprobres.'),
('ps',123,4,'crampon1923','Notre âme n''a été que trop rassasiée de la moquerie des superbes, du mépris des orgueilleux.'),
('ps',124,1,'crampon1923','Cantique des montées. De David. Si Yahweh n''eût été pour nous, — qu''Israël le proclame, —'),
('ps',124,2,'crampon1923','si Yahweh n''eût été pour nous, quand les hommes se sont élevés contre nous!...'),
('ps',124,3,'crampon1923','Ils nous auraient dévorés tout vivants, quand leur colère s''est allumée contre nous;'),
('ps',124,4,'crampon1923','les eaux nous auraient engloutis, le torrent eût passé sur notre âme;'),
('ps',124,5,'crampon1923','sur notre âme auraient passé les eaux impétueuses.'),
('ps',124,6,'crampon1923','Béni soit Yahweh, qui ne nous a pas livrés à leurs dents!'),
('ps',124,7,'crampon1923','Notre âme, comme le passereau, s''est échappée du filet de l''oiseleur; le filet s''est rompu, et nous avons été délivrés.'),
('ps',124,8,'crampon1923','Notre secours est dans le nom de Yahweh, qui a fait les cieux et la terre.'),
('ps',125,1,'crampon1923','Cantique des montées. Ceux qui se confient en Yahweh sont comme la montagne de Sion: elle ne chancelle point, elle est établie pour toujours.'),
('ps',125,2,'crampon1923','Jérusalem a autour d''elle une ceinture de montagnes: ainsi Yahweh entoure son peuple, dès maintenant et à jamais.'),
('ps',125,3,'crampon1923','Le sceptre des méchants ne restera pas sur l''héritage des justes, afin que les justes ne portent pas aussi leurs mains vers l''iniquité.'),
('ps',125,4,'crampon1923','Yahweh, répands tes bontés sur les bons, et sur ceux qui ont le cœur droit.'),
('ps',125,5,'crampon1923','Mais sur ceux qui se détournent en des voies tortueuses, que Yahweh les abandonne avec ceux qui font le mal! Paix sur Israël!'),
('ps',126,1,'crampon1923','Cantique des montées. Quand Yahweh ramena les captifs de Sion, ce fut pour nous comme un songe.'),
('ps',126,2,'crampon1923','Alors notre bouche fit entendre des cris joyeux, notre langue, des chants d''allégresse. Alors on répéta parmi les nations: « Yahweh a fait pour eux de grandes choses. »'),
('ps',126,3,'crampon1923','Oui, Yahweh a fait pour nous de grandes choses; nous sommes dans la joie.'),
('ps',126,4,'crampon1923','Yahweh, ramène nos captifs, comme tu fais couler les torrents dans le Négéb.'),
('ps',126,5,'crampon1923','Ceux qui sèment dans les larmes, moissonneront dans l''allégresse.'),
('ps',126,6,'crampon1923','Ils vont, ils vont en pleurant, portant et jetant la semence; ils reviendront avec des cris de joie, portant les gerbes de leur moisson.'),
('ps',127,1,'crampon1923','Cantique des montées. De Salomon. Si Yahweh ne bâtit pas la maison, en vain travaillent ceux qui la bâtissent; si Yahweh ne garde pas la cité, en vain la sentinelle veille à ses portes.'),
('ps',127,2,'crampon1923','C''est en vain que vous vous levez avant le jour, et que vous retardez votre repos, mangeant le pain de la douleur: il en donne autant à son bien-aimé pendant son sommeil.'),
('ps',127,3,'crampon1923','Voici, c''est un héritage de Yahweh, que les enfants; une récompense, que les fruits d''un sein fécond.'),
('ps',127,4,'crampon1923','Comme les flèches dans la main d''un guerrier, ainsi sont les fils de la jeunesse.'),
('ps',127,5,'crampon1923','Heureux l''homme qui en a rempli son carquois! Ils ne rougiront pas quand ils répondront aux ennemis, à la porte de la ville.'),
('ps',128,1,'crampon1923','Cantique des montées. Heureux l''homme qui craint Yahweh, qui marche dans ses voies!'),
('ps',128,2,'crampon1923','Tu te nourris alors du travail de tes mains; tu es heureux et comblé de biens.'),
('ps',128,3,'crampon1923','Ton épouse est comme une vigne féconde, dans l''intérieur de ta maison; tes fils, comme de jeunes plants d''olivier, autour de ta table.'),
('ps',128,4,'crampon1923','Voilà comment sera béni l''homme qui craint Yahweh.'),
('ps',128,5,'crampon1923','Que Yahweh te bénisse de Sion! Puisse-tu voir Jérusalem florissante tous les jours de ta vie!'),
('ps',128,6,'crampon1923','Puisses-tu voir les enfants de tes enfants! Que la paix soit sur Israël!'),
('ps',129,1,'crampon1923','Cantique des montées. Ils m''ont cruellement opprimé dès ma jeunesse, — qu''Israël le dise! —'),
('ps',129,2,'crampon1923','Ils m''ont cruellement opprimé dès ma jeunesse, mais ils n''ont pas prévalu contre moi.'),
('ps',129,3,'crampon1923','Ils ont labouré mon dos, ils y ont tracé de longs sillons.'),
('ps',129,4,'crampon1923','Mais Yahweh est juste: il a coupé les liens des méchants.'),
('ps',129,5,'crampon1923','Qu''ils soient confondus et qu''ils reculent en arrière, tous ceux qui haïssent Sion!'),
('ps',129,6,'crampon1923','Qu''ils soient comme l''herbe des toits, qui sèche avant qu''on l''arrache.'),
('ps',129,7,'crampon1923','Le moissonneur n''en remplit pas sa main, ni celui qui lie les gerbes, son giron;'),
('ps',129,8,'crampon1923','et les passants ne disent pas: « Que la bénédiction de Yahweh soit sur vous! » — « Nous vous bénissons au nom de Yahweh. »'),
('ps',130,1,'crampon1923','Cantique des montées. Du fond de l''abîme je crie vers toi, Yahweh.'),
('ps',130,2,'crampon1923','Seigneur, écoute ma voix; que tes oreilles soient attentives aux accents de ma prière!'),
('ps',130,3,'crampon1923','Si tu gardes le souvenir de l''iniquité, Yahweh, Seigneur, qui pourra subsister?'),
('ps',130,4,'crampon1923','Mais auprès de toi est le pardon, afin qu''on te révère.'),
('ps',130,5,'crampon1923','J''espère en Yahweh; mon âme espère, et j''attends sa parole.'),
('ps',130,6,'crampon1923','Mon âme aspire après le Seigneur plus que les guetteurs n''aspirent après l''aurore.'),
('ps',130,7,'crampon1923','Israël, mets ton espoir en Yahweh! Car avec Yahweh est la miséricorde, avec lui une surabondante délivrance.'),
('ps',130,8,'crampon1923','C''est lui qui rachètera Israël de toutes ses iniquités.'),
('ps',131,1,'crampon1923','Cantique des montées. De David. Yahweh, mon cœur ne s''est pas enflé d''orgueil, et mes regards n''ont pas été hautains. Je ne recherche point les grandes choses, ni ce qui est élevé au-dessus de moi.'),
('ps',131,2,'crampon1923','Non! Je tiens mon âme dans le calme et le silence. Comme un enfant sevré sur le sein de sa mère, comme l''enfant sevré mon âme est en moi.'),
('ps',131,3,'crampon1923','Israël, mets ton espoir en Yahweh! Maintenant et toujours!'),
('ps',132,1,'crampon1923','Cantique des montées. Souviens-toi, Yahweh, de David, de toutes ses peines!'),
('ps',132,2,'crampon1923','Il fit ce serment à Yahweh, ce vœu au Fort de Jacob:'),
('ps',132,3,'crampon1923','« Je n''entrerai pas dans la tente où j''habite, je ne monterai pas sur le lit où je repose;'),
('ps',132,4,'crampon1923','je n''accorderai point de sommeil à mes yeux, ni d''assoupissement à mes paupières,'),
('ps',132,5,'crampon1923','jusqu''à ce que j''aie trouvé un lieu pour Yahweh, une demeure pour le Fort de Jacob. »'),
('ps',132,6,'crampon1923','Voici, entendions-nous dire, qu''elle est à Ephrata; nous l''avons trouvée dans les champs de Jaar.'),
('ps',132,7,'crampon1923','Allons au tabernacle de Yahweh, prosternons-nous devant l''escabeau de ses pieds.'),
('ps',132,8,'crampon1923','Lève-toi, Yahweh, viens au lieu de ton repos, toi et l''arche de ta majesté!'),
('ps',132,9,'crampon1923','Que tes prêtres soient revêtus de justice, et que tes fidèles poussent des cris d''allégresse!'),
('ps',132,10,'crampon1923','A cause de David, ton serviteur, ne repousse pas la face de ton Oint!'),
('ps',132,11,'crampon1923','Yahweh a juré à David la vérité, il ne s''en départira pas: « C''est du fruit de tes entrailles, que je mettrai sur ton trône.'),
('ps',132,12,'crampon1923','Si tes fils gardent mon alliance, et les préceptes que je leur enseignerai, leurs fils aussi, à tout jamais, seront assis sur ton trône. »'),
('ps',132,13,'crampon1923','Car Yahweh a choisi Sion, il l''a désirée pour sa demeure.'),
('ps',132,14,'crampon1923','« C''est le lieu de mon repos pour toujours; j''y habiterai, car je l''ai désirée.'),
('ps',132,15,'crampon1923','Je répandrai de riches bénédictions sur sa subsistance, je rassasierai de pain ses pauvres.'),
('ps',132,16,'crampon1923','Je revêtirai de salut ses prêtres, et ses fidèles pousseront des cris d''allégresse.'),
('ps',132,17,'crampon1923','Là je ferai grandir la puissance de David, je préparerai un flambeau à mon Oint.'),
('ps',132,18,'crampon1923','Je revêtirai de honte ses ennemis, et sur son front resplendira son diadème. »'),
('ps',133,1,'crampon1923','Cantique des montées. De David. Ah! Qu''il est bon, qu''il est doux pour des frères d''habiter ensemble!'),
('ps',133,2,'crampon1923','C''est comme l''huile précieuse qui, répandue sur la tête, coule sur la barbe, sur la barbe d''Aaron, qui descend sur le bord de son vêtement.'),
('ps',133,3,'crampon1923','C''est comme la rosée de l''Hermon, qui descend sur les sommets de Sion. Car c''est là que Yahweh a établi la bénédiction, la vie, pour toujours.'),
('ps',134,1,'crampon1923','Cantique des montées. Voici donc, bénissez Yahweh, vous tous, serviteurs de Yahweh, qui êtes de service dans la maison de Yahweh, pendant les nuits!...'),
('ps',134,2,'crampon1923','Levez les mains vers le sanctuaire, et bénissez Yahweh.'),
('ps',134,3,'crampon1923','Que Yahweh te bénisse de Sion, lui qui a fait les cieux et la terre!'),
('ps',135,1,'crampon1923','Alleluia. Louez le nom de Yahweh, louez-le, serviteurs de Yahweh,'),
('ps',135,2,'crampon1923','vous qui êtes de service dans la maison de Yahweh, dans les parvis de la maison de notre Dieu.'),
('ps',135,3,'crampon1923','Louez Yahweh, car Yahweh est bon; chantez son nom sur la harpe, car il est plein de douceur.'),
('ps',135,4,'crampon1923','Car Yahweh s''est choisi Jacob, il s''est choisi Israël pour en faire son héritage.'),
('ps',135,5,'crampon1923','Oui, je le sais, Yahweh est grand, notre Seigneur est au-dessus de tous les dieux.'),
('ps',135,6,'crampon1923','Tout ce que veut Yahweh, il le fait, dans les cieux et sur la terre, dans la mer et dans tous les abîmes.'),
('ps',135,7,'crampon1923','Il fait monter les nuages des extrémités de la terre, il produit les éclairs avec la pluie, il tire le vent de ses trésors.'),
('ps',135,8,'crampon1923','Il frappa jadis les premiers-nés de l''Egypte, depuis l''homme jusqu''à l''animal.'),
('ps',135,9,'crampon1923','Il fit éclater des signes et des prodiges au milieu de toi, ô Egypte, contre Pharaon et tous ses serviteurs.'),
('ps',135,10,'crampon1923','Il frappa des nations nombreuses, et fit mourir des rois puissants:'),
('ps',135,11,'crampon1923','Séhon, roi des Amorrhéens, Og, roi de Basan, et tous les rois de Chanaan.'),
('ps',135,12,'crampon1923','Et il donna leur pays en héritage, en héritage à Israël, son peuple.'),
('ps',135,13,'crampon1923','Yahweh, ton nom subsiste à jamais; Yahweh, ton souvenir dure d''âge en âge.'),
('ps',135,14,'crampon1923','Car Yahweh fait droit à son peuple, et il a compassion de ses serviteurs.'),
('ps',135,15,'crampon1923','Les idoles des nations sont de l''argent et de l''or, ouvrage de la main des hommes.'),
('ps',135,16,'crampon1923','Elles ont une bouche et ne parlent pas; elles ont des yeux et ne voient pas.'),
('ps',135,17,'crampon1923','Elles ont des oreilles et n''entendent pas; Il n''y a pas même un souffle dans leur bouche.'),
('ps',135,18,'crampon1923','Qu''ils leur ressemblent ceux qui les font, quiconque se confie en elles!'),
('ps',135,19,'crampon1923','Maison d''Israël, bénissez Yahweh! Maison d''Aaron, bénissez Yahweh!'),
('ps',135,20,'crampon1923','Maison de Lévi, bénissez Yahweh! Vous qui craignez Yahweh, bénissez Yahweh!'),
('ps',135,21,'crampon1923','Que de Sion soit béni Yahweh, qui habite Jérusalem! Alleluia!'),
('ps',136,1,'crampon1923','Célébrez Yahweh, car il est bon, car sa miséricorde est éternelle.'),
('ps',136,2,'crampon1923','Célébrez le Dieu des dieux, car sa miséricorde est éternelle.'),
('ps',136,3,'crampon1923','Célébrez le Seigneur des seigneurs, car sa miséricorde est éternelle.'),
('ps',136,4,'crampon1923','A celui qui seul opère de grands prodiges, car sa miséricorde est éternelle.'),
('ps',136,5,'crampon1923','Qui a fait les cieux avec sagesse, car sa miséricorde est éternelle.'),
('ps',136,6,'crampon1923','Qui a étendu la terre sur les eaux, car sa miséricorde est éternelle.'),
('ps',136,7,'crampon1923','Qui a fait les grands luminaires, car sa miséricorde est éternelle.'),
('ps',136,8,'crampon1923','Le soleil pour dominer sur le jour, car sa miséricorde est éternelle.'),
('ps',136,9,'crampon1923','La lune et les étoiles pour dominer sur la nuit, car sa miséricorde est éternelle.'),
('ps',136,10,'crampon1923','A celui qui frappa les Egyptiens dans leurs premiers-nés, car sa miséricorde est éternelle.'),
('ps',136,11,'crampon1923','Il fit sortir Israël du milieu d''eux, car sa miséricorde est éternelle.'),
('ps',136,12,'crampon1923','D''une main forte et d''un bras étendu, car sa miséricorde est éternelle.'),
('ps',136,13,'crampon1923','A celui qui divisa en deux la mer Rouge, car sa miséricorde est éternelle.'),
('ps',136,14,'crampon1923','Qui fit passer Israël au travers, car sa miséricorde est éternelle.'),
('ps',136,15,'crampon1923','Et précipita Pharaon et son armée dans la mer Rouge, car sa miséricorde est éternelle.'),
('ps',136,16,'crampon1923','A celui qui conduisit son peuple dans le désert, car sa miséricorde est éternelle.'),
('ps',136,17,'crampon1923','Qui frappa de grands rois, car sa miséricorde est éternelle.'),
('ps',136,18,'crampon1923','Et fit périr des rois puissants, car sa miséricorde est éternelle.'),
('ps',136,19,'crampon1923','Séhon, roi des Amorrhéens, car sa miséricorde est éternelle.'),
('ps',136,20,'crampon1923','Et Og, roi de Basan, car sa miséricorde est éternelle.'),
('ps',136,21,'crampon1923','Qui donna leur pays en héritage, car sa miséricorde est éternelle.'),
('ps',136,22,'crampon1923','En héritage à Israël, son serviteur, car sa miséricorde est éternelle.'),
('ps',136,23,'crampon1923','A celui qui se souvint de nous quand nous étions humiliés, car sa miséricorde est éternelle.'),
('ps',136,24,'crampon1923','Et nous délivra de nos oppresseurs, car sa miséricorde est éternelle.'),
('ps',136,25,'crampon1923','A celui qui donne à tout ce qui vit la nourriture, car sa miséricorde est éternelle.'),
('ps',136,26,'crampon1923','Célébrez le Dieu des cieux, car sa miséricorde est éternelle.'),
('ps',137,1,'crampon1923','Au bord des fleuves de Babylone nous étions assis et nous pleurions, en nous souvenant de Sion.'),
('ps',137,2,'crampon1923','Aux saules de ses vallées nous avions suspendu nos harpes.'),
('ps',137,3,'crampon1923','Car là, ceux qui nous tenaient captifs nous demandaient des hymnes et des cantiques, nos oppresseurs, des chants joyeux: « Chantez-nous un cantique de Sion! »'),
('ps',137,4,'crampon1923','Comment chanterions-nous le cantique de Yahweh, sur la terre de l''étranger?'),
('ps',137,5,'crampon1923','Si jamais je t''oublie, Jérusalem, que ma droite oublie de se mouvoir!...'),
('ps',137,6,'crampon1923','Que ma langue s''attache à mon palais, si je cesse de penser à toi, si je ne mets pas Jérusalem au premier rang de mes joies!'),
('ps',137,7,'crampon1923','Souviens-toi, Yahweh, des enfants d''Edom, quand au jour de Jérusalem, ils disaient: « Détruisez, détruisez-la, jusqu''en ses fondements! »'),
('ps',137,8,'crampon1923','Fille de Babylone, vouée à la ruine, heureux celui qui te rendra le mal que tu nous as fait!'),
('ps',137,9,'crampon1923','Heureux celui qui saisira et brisera tes petits enfants contre la pierre!'),
('ps',138,1,'crampon1923','De David. Je veux te louer de tout mon cœur, te chanter sur la harpe, en présence des dieux.'),
('ps',138,2,'crampon1923','Je veux me prosterner dans ton saint temple, et célébrer ton nom, à cause de ta bonté et de ta fidélité, parce que tu as fait une promesse magnifique, au-dessus de toutes les gloires de ton nom.'),
('ps',138,3,'crampon1923','Le jour où je t''ai invoqué, tu m''as exaucé, tu as rendu à mon âme la force et le courage.'),
('ps',138,4,'crampon1923','Tous les rois de la terre te loueront, Yahweh, quand ils auront appris les oracles de ta bouche.'),
('ps',138,5,'crampon1923','Ils célébreront les voies de Yahweh, car la gloire de Yahweh est grande.'),
('ps',138,6,'crampon1923','Car Yahweh est élevé, et il voit les humbles, et il connaît de loin les orgueilleux.'),
('ps',138,7,'crampon1923','Si je marche en pleine détresse, tu me rends la vie, tu étends ta main pour arrêter la colère de mes ennemis, et ta droite ma sauve.'),
('ps',138,8,'crampon1923','Yahweh achèvera ce qu''il a fait pour moi. Yahweh, ta bonté est éternelle: n''abandonne pas l''ouvrage de tes mains!'),
('ps',139,1,'crampon1923','Au maître de chant. Psaume de David. Yahweh, tu me sondes et tu me connais,'),
('ps',139,2,'crampon1923','tu sais quand je suis assis ou levé, tu découvres ma pensée de loin.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('ps',139,3,'crampon1923','Tu m''observes quand je suis en marche ou couché, et toutes mes voies te sont familières.'),
('ps',139,4,'crampon1923','La parole n''est pas encore sur ma langue, que déjà, Yahweh, tu la connais entièrement.'),
('ps',139,5,'crampon1923','En avant et en arrière tu m''entoures, et tu mets ta main sur moi:'),
('ps',139,6,'crampon1923','Science trop merveilleuse pour moi, elle est trop élevée pour que j''y puisse atteindre!'),
('ps',139,7,'crampon1923','Où aller loin de ton esprit, où fuir loin de ta face?'),
('ps',139,8,'crampon1923','Si je monte aux cieux, tu y es; si je me couche dans le schéol, te voilà!'),
('ps',139,9,'crampon1923','Si je prends les ailes de l''aurore, et que j''aille habiter aux confins de la mer,'),
('ps',139,10,'crampon1923','là encore ta main me conduira, et ta droite me saisira.'),
('ps',139,11,'crampon1923','Et je dis: Au moins les ténèbres me couvriront, et la nuit sera la seule lumière qui m''entoure!...'),
('ps',139,12,'crampon1923','Les ténèbres mêmes n''ont pas pour toi d''obscurité; pour toi la nuit brille comme le jour, et les ténèbres comme la lumière.'),
('ps',139,13,'crampon1923','C''est toi qui as formé mes reins, et qui m''as tissé dans le sein de ma mère.'),
('ps',139,14,'crampon1923','Je te loue d''avoir fait de moi une créature si merveilleuse; tes œuvres sont admirables, et mon âme se plaît à le reconnaître.'),
('ps',139,15,'crampon1923','Ma substance n''était pas cachée devant toi, lorsque j''étais formé dans le secret, tissé avec art dans les profondeurs de la terre.'),
('ps',139,16,'crampon1923','Je n''étais qu''un germe informe, et tes yeux me voyaient, et sur ton livre étaient tous inscrits les jours qui m''étaient destinés, avant qu''aucun d''eux fût encore.'),
('ps',139,17,'crampon1923','O Dieu, que tes pensées me semblent ravissantes! Que le nombre en est grand!'),
('ps',139,18,'crampon1923','Si je compte, elles surpassent en nombre les grains de sable: je m''éveille, et je suis encore avec toi!'),
('ps',139,19,'crampon1923','O Dieu, ne feras-tu pas périr le méchant? Hommes de sang, éloignez-vous de moi!'),
('ps',139,20,'crampon1923','Ils parlent de toi d''une manière criminelle, ils prennent ton nom en vain, eux, tes ennemis!'),
('ps',139,21,'crampon1923','Ne dois-je pas, Yahweh, haïr ceux qui te haïssent, avoir en horreur ceux qui s''élèvent contre toi?'),
('ps',139,22,'crampon1923','Oui, je les hais d''une haine complète, ils sont pour moi des ennemis.'),
('ps',139,23,'crampon1923','Sonde-moi, ô Dieu, et connais mon cœur; éprouve-moi, et connais mes pensées.'),
('ps',139,24,'crampon1923','Regarde si je suis sur une voie funeste, et conduis-moi dans la voie éternelle.'),
('ps',140,1,'crampon1923','Au maître de chant. Psaume de David.'),
('ps',140,2,'crampon1923','Yahweh, délivre-moi de l''homme méchant, préserve-moi des hommes de violence,'),
('ps',140,3,'crampon1923','qui méditent de mauvais desseins dans leur cœur, qui excitent sans cesse la guerre contre moi,'),
('ps',140,4,'crampon1923','qui aiguisent leur langue comme le serpent, et qui ont sous leurs lèvres le venin de l''aspic. — Séla.'),
('ps',140,5,'crampon1923','Yahweh, garde-moi des mains du méchant, préserve-moi des hommes de violence, qui méditent de me faire trébucher.'),
('ps',140,6,'crampon1923','Des orgueilleux me dressent un piège et des filets, ils placent des rets le long de mon sentier, ils me tendent des embûches. — Séla.'),
('ps',140,7,'crampon1923','Je dis à Yahweh: Tu es mon Dieu! Ecoute, Yahweh, la voix de mes supplications!'),
('ps',140,8,'crampon1923','Seigneur Yahweh, mon puissant sauveur, tu couvres ma tête au jour du combat.'),
('ps',140,9,'crampon1923','Yahweh, n''accomplis pas les désirs du méchant, ne laisse pas réussir ses desseins: il en serait trop fier! — Séla.'),
('ps',140,10,'crampon1923','Que sur la tête de ceux qui m''assiègent retombe l''iniquité de leurs lèvres,'),
('ps',140,11,'crampon1923','que des charbons ardents soient secoués sur eux! Que Dieu les précipite dans le feu, dans les abîmes d''où ils ne se relèvent plus!'),
('ps',140,12,'crampon1923','Non, le calomniateur ne prospérera pas sur la terre, et le malheur poursuivra sans merci l''homme violent.'),
('ps',140,13,'crampon1923','Je sais que Yahweh fait droit au misérable, et justice au pauvre.'),
('ps',140,14,'crampon1923','Oui, les justes célébreront ton nom, et les hommes droits habiteront devant ta face.'),
('ps',141,1,'crampon1923','Psaume de David. Yahweh, je t''invoque; hâte-toi de venir vers moi; prête l''oreille à ma voix, quand je t''invoque.'),
('ps',141,2,'crampon1923','Que ma prière soit devant ta face comme l''encens, et l''élévation de mes mains comme l''offrande du soir!'),
('ps',141,3,'crampon1923','Yahweh, mets une garde à ma bouche, une sentinelle à la porte de mes lèvres.'),
('ps',141,4,'crampon1923','N''incline pas mon cœur vers des choses mauvaises; ne l''incline pas à se livrer à des actes de méchanceté avec les hommes qui commettent l''iniquité; que je ne prenne aucune part à leurs festins!'),
('ps',141,5,'crampon1923','Que le juste me frappe, c''est une faveur; qu''il me reprenne, c''est un parfum sur ma tête; ma tête ne le refusera pas, car alors je n''opposerai que ma prière à leurs mauvais desseins.'),
('ps',141,6,'crampon1923','Mais bientôt leurs chefs seront précipités le long des rochers; et l''on écoutera mes paroles, car elles sont agréables.'),
('ps',141,7,'crampon1923','Comme lorsqu''on laboure et que l''on ameublit la terre, ainsi nos ossements sont semés au bord du schéol.'),
('ps',141,8,'crampon1923','Car vers toi, Seigneur Yahweh, je tourne mes yeux; auprès de toi je cherche un refuge: n''abandonne pas mon âme!'),
('ps',141,9,'crampon1923','Préserve-moi des pièges qu''ils me tendent, des embûches de ceux qui font le mal!'),
('ps',141,10,'crampon1923','Que les méchants tombent dans leurs propres filets, et que j''échappe en même temps!'),
('ps',142,1,'crampon1923','Cantique de David. Lorsqu''il était dans la caverne. Prière.'),
('ps',142,2,'crampon1923','De ma voix je crie à Yahweh, de ma voix j''implore Yahweh;'),
('ps',142,3,'crampon1923','Je répands ma plainte en sa présence, devant lui j''expose ma détresse.'),
('ps',142,4,'crampon1923','Lorsqu''en moi mon esprit défaille, toi tu connais mon sentier; tu sais que, dans la route où je marche, ils me tendent des pièges.'),
('ps',142,5,'crampon1923','Jette les yeux à ma droite et vois: personne ne me reconnaît; tout refuge me fait défaut, nul n''a souci de mon âme.'),
('ps',142,6,'crampon1923','Je crie vers toi, Yahweh, je dis: Tu es mon refuge, mon partage sur la terre des vivants!'),
('ps',142,7,'crampon1923','Prête l''oreille à ma plainte, car je suis malheureux à l''excès; délivre-moi de ceux qui me poursuivent, car ils sont plus forts que moi.'),
('ps',142,8,'crampon1923','Tire mon âme de cette prison, afin que je célèbre ton nom; les justes triompheront avec moi de ce que tu m''auras fait du bien.'),
('ps',143,1,'crampon1923','Psaume de David. Yahweh, écoute ma prière; prête l''oreille à mes supplications; exauce-moi dans ta vérité et dans ta justice.'),
('ps',143,2,'crampon1923','N''entre pas en jugement avec ton serviteur, car aucun homme vivant n''est juste devant toi.'),
('ps',143,3,'crampon1923','L''ennemi en veut à mon âme, il foule à terre ma vie; il me relègue dans les lieux ténébreux, comme ceux qui sont morts depuis longtemps.'),
('ps',143,4,'crampon1923','Mon esprit défaille en moi, mon cœur est troublé dans mon sein.'),
('ps',143,5,'crampon1923','Je pense aux jours d''autrefois, je médite sur toutes tes œuvres, je réfléchis sur l''ouvrage de tes mains.'),
('ps',143,6,'crampon1923','j''étends vers toi mes mains, et mon âme, comme une terre desséchée, soupire après toi. — Séla.'),
('ps',143,7,'crampon1923','Hâte-toi de m''exaucer, Yahweh, mon esprit défaille; ne me cache pas ta face, je deviens semblable à ceux qui descendent dans la fosse.'),
('ps',143,8,'crampon1923','Fais-moi de bonne heure sentir ta bonté, car c''est en toi que j''espère; fais-moi connaître la voie où je dois marcher, car c''est vers toi que j''élève mon âme.'),
('ps',143,9,'crampon1923','Délivre-moi de mes ennemis, Yahweh, je me réfugie auprès de toi.'),
('ps',143,10,'crampon1923','Apprends-moi à faire ta volonté, car tu es mon Dieu. Que ton bon esprit me conduise dans la voie droite!'),
('ps',143,11,'crampon1923','A cause de ton nom, Yahweh, rends-moi la vie; dans ta justice, retire mon âme de la détresse.'),
('ps',143,12,'crampon1923','Dans ta bonté, anéantis mes ennemis, et fais périr tous ceux qui m''oppriment, car je suis ton serviteur.'),
('ps',144,1,'crampon1923','De David. Béni soit Yahweh, mon rocher, qui a dressé mes mains au combat, et mes doigts à la guerre,'),
('ps',144,2,'crampon1923','mon bienfaiteur et ma forteresse, ma haute retraite et mon libérateur, mon bouclier, celui qui est mon refuge, qui range mon peuple sous moi!'),
('ps',144,3,'crampon1923','Yahweh, qu''est-ce que l''homme pour que tu le connaisses, le fils de l''homme, pour que tu prennes garde à lui?'),
('ps',144,4,'crampon1923','L''homme est semblable à un souffle, ses jours sont comme l''ombre qui passe.'),
('ps',144,5,'crampon1923','Yahweh, abaisse tes cieux et descends; touche les montagnes, et qu''elles s''embrasent;'),
('ps',144,6,'crampon1923','fais briller les éclairs, et disperse les ennemis; lance tes flèches, et mets-les en déroute.'),
('ps',144,7,'crampon1923','Etends tes mains d''en haut, délivre-moi et sauve-moi des grandes eaux, de la main des fils de l''étranger,'),
('ps',144,8,'crampon1923','dont la bouche profère le mensonge, et dont la droite est une droite parjure.'),
('ps',144,9,'crampon1923','O Dieu, je te chanterai un cantique nouveau, je te célébrerai sur le luth à dix cordes.'),
('ps',144,10,'crampon1923','Toi qui donnes aux rois la victoire, qui sauves du glaive meurtrier David, ton serviteur,'),
('ps',144,11,'crampon1923','délivre-moi et sauve-moi de la main des fils de l''étranger, dont la bouche profère le mensonge, et dont la droite est une droite parjure.'),
('ps',144,12,'crampon1923','Que nos fils, comme des plants vigoureux, grandissent en leur jeunesse! Que nos filles soient comme les colonnes angulaires, sculptées à la façon de celles d''un temple!'),
('ps',144,13,'crampon1923','Que nos greniers soient remplis, et regorgent de toutes sortes de provisions! Que nos brebis, dans nos pâturages, se multiplient par milliers et par myriades!'),
('ps',144,14,'crampon1923','Que nos génisses soient fécondes! Qu''il n''y ait dans nos murs ni brèche, ni reddition! Ni cri d''alarme dans nos places publiques!'),
('ps',144,15,'crampon1923','Heureux le peuple qui jouit de ces biens! Heureux le peuple dont Yahweh est le Dieu!'),
('ps',145,1,'crampon1923','Chant de louange. De David. ALEPH. Je veux t''exalter, mon Dieu, ô Roi, et bénir ton nom à jamais et toujours.'),
('ps',145,2,'crampon1923','BETH. Je veux chaque jour te bénir, et célébrer ton nom toujours et à jamais.'),
('ps',145,3,'crampon1923','GHIMEL. Yahweh est grand et digne de toute louange, et sa grandeur est insondable.'),
('ps',145,4,'crampon1923','DALETH. Chaque âge dira au suivant la louange de tes œuvres, on publiera tes prodiges.'),
('ps',145,5,'crampon1923','HÉ. Je chanterai l''éclat glorieux de ta majesté, et tes œuvres prodigieuses.'),
('ps',145,6,'crampon1923','WAV. Et l''on parlera de ta puissance redoutable, et je raconterai ta grandeur.'),
('ps',145,7,'crampon1923','ZAÏN. On proclamera le souvenir de ton immense bonté, et on célébrera ta justice.'),
('ps',145,8,'crampon1923','HETH. Yahweh est miséricordieux et compatissant, lent à la colère et plein de bonté.'),
('ps',145,9,'crampon1923','TETH. Yahweh est bon envers tous, et sa miséricorde s''étend sur toutes ses créatures.'),
('ps',145,10,'crampon1923','YOD. Toutes tes œuvres te louent, Yahweh, et tes fidèles te bénissent.'),
('ps',145,11,'crampon1923','CAPH. Ils disent la gloire de ton règne, et proclament ta puissance,'),
('ps',145,12,'crampon1923','LAMED. afin de faire connaître aux fils des hommes ses prodiges, et le glorieux éclat de son règne.'),
('ps',145,13,'crampon1923','MEM. Ton règne est un règne éternel, et ta domination subsiste dans tous les âges.'),
('ps',145,14,'crampon1923','SAMECH. Yahweh soutient tous ceux qui tombent, il redresse tous ceux qui sont courbés.'),
('ps',145,15,'crampon1923','AÏN. Les yeux de tous les êtres sont tournés vers toi dans l''attente, et tu leur donnes leur nourriture en son temps.'),
('ps',145,16,'crampon1923','PHÉ. Tu ouvres ta main, et tu rassasies de tes biens tout ce qui respire.'),
('ps',145,17,'crampon1923','TSADÉ. Yahweh est juste dans toutes ses voies, et miséricordieux dans toutes ses œuvres.'),
('ps',145,18,'crampon1923','QOPH. Yahweh est près de tous ceux qui l''invoquent, de tous ceux qui l''invoquent d''un cœur sincère.'),
('ps',145,19,'crampon1923','RESCH. Il accomplit les désirs de ceux qui le craignent, il entend leur cri et il les sauve.'),
('ps',145,20,'crampon1923','SCHIN. Yahweh garde tous ceux qui l''aiment, et il détruit tous les méchants.'),
('ps',145,21,'crampon1923','THAV. Que ma bouche publie la louange de Yahweh, et que toute chair bénisse son saint nom, toujours, à jamais!'),
('ps',146,1,'crampon1923','Alleluia! Mon âme, loue Yahweh!'),
('ps',146,2,'crampon1923','Toute ma vie, je veux louer Yahweh, tant que je serai, je veux chanter mon Dieu.'),
('ps',146,3,'crampon1923','Ne mettez pas votre confiance dans les princes, dans le fils de l''homme, qui ne peut sauver.'),
('ps',146,4,'crampon1923','Son souffle s''en va, il retourne à sa poussière, et, ce même jour, ses desseins s''évanouissent.'),
('ps',146,5,'crampon1923','Heureux celui qui a pour secours le Dieu de Jacob, qui met son espoir en Yahweh, son Dieu!'),
('ps',146,6,'crampon1923','Yahweh a fait le ciel et la terre, la mer et tout ce qu''elle renferme; il garde à jamais sa fidélité.'),
('ps',146,7,'crampon1923','Il rend justice aux opprimés, il donne la nourriture à ceux qui ont faim. Yahweh délivre les captifs,'),
('ps',146,8,'crampon1923','Yahweh ouvre les yeux des aveugles, Yahweh relève ceux qui sont courbés, Yahweh aime les justes.'),
('ps',146,9,'crampon1923','Yahweh garde les étrangers, il soutient l''orphelin et la veuve; mais il rend tortueuse la voie des méchants.'),
('ps',146,10,'crampon1923','Yahweh est roi pour l''éternité, ton Dieu, ô Sion, d''âge en âge. Alleluia!'),
('ps',147,1,'crampon1923','Alleluia — Louez Yahweh, car il est bon de célébrer notre Dieu, car il est doux, il est bienséant de le louer.'),
('ps',147,2,'crampon1923','Yahweh rebâtit Jérusalem, il rassemble les dispersés d''Israël.'),
('ps',147,3,'crampon1923','Il guérit ceux qui ont le cœur brisé, et il panse leurs blessures.'),
('ps',147,4,'crampon1923','Il compte le nombre des étoiles, il les appelle toutes par leur nom.'),
('ps',147,5,'crampon1923','Notre Seigneur est grand, et sa force est infinie, et son intelligence n''a pas de limites.'),
('ps',147,6,'crampon1923','Yahweh vient en aide aux humbles, il abaisse les méchants jusqu''à terre.'),
('ps',147,7,'crampon1923','Chantez à Yahweh un cantique d''actions de grâces; célébrez notre Dieu sur la harpe!'),
('ps',147,8,'crampon1923','Il couvre les cieux de nuages, et prépare la pluie pour la terre; il fait croître l''herbe sur les montagnes.'),
('ps',147,9,'crampon1923','Il donne la nourriture au bétail, aux petits du corbeau qui crient vers lui.'),
('ps',147,10,'crampon1923','Ce n''est pas dans la vigueur du cheval qu''il se complaît, ni dans les jambes de l''homme qu''il met son plaisir;'),
('ps',147,11,'crampon1923','Yahweh met son plaisir en ceux qui le craignent, en ceux qui espèrent en sa bonté.'),
('ps',147,12,'crampon1923','Jérusalem, célèbre Yahweh; Sion, loue ton Dieu.'),
('ps',147,13,'crampon1923','Car il affermit les verrous de tes portes, il bénit tes fils au milieu de toi;'),
('ps',147,14,'crampon1923','il assure la paix à tes frontières, il te rassasie de la fleur du froment.'),
('ps',147,15,'crampon1923','Il envoie ses ordres à la terre; sa parole court avec vitesse.'),
('ps',147,16,'crampon1923','Il fait tomber la neige comme de la laine, il répand le givre comme de la cendre.'),
('ps',147,17,'crampon1923','Il jette ses glaçons par morceaux: qui peut tenir devant ses frimas?'),
('ps',147,18,'crampon1923','Il envoie sa parole, et il les fond; il fait souffler son vent, et les eaux coulent.'),
('ps',147,19,'crampon1923','C''est lui qui a révélé sa parole à Jacob, ses lois et ses ordonnances à Israël.'),
('ps',147,20,'crampon1923','Il n''a pas fait de même pour toutes les autres nations; elles ne connaissent pas ses ordonnances. Alleluia!'),
('ps',148,1,'crampon1923','Alleluia! Louez Yahweh du haut des cieux, louez-le dans les hauteurs!'),
('ps',148,2,'crampon1923','Louez-le, vous tous, ses anges; louez-le, vous toutes, ses armées!'),
('ps',148,3,'crampon1923','Louez-le, soleil et lune; louez-le, vous toutes, étoiles brillantes!'),
('ps',148,4,'crampon1923','Louez-le, cieux des cieux, et vous, eaux, qui êtes au-dessus des cieux!'),
('ps',148,5,'crampon1923','Qu''ils louent le nom de Yahweh; car il a commandé, et ils ont été créés.'),
('ps',148,6,'crampon1923','Il les a établis pour toujours et à jamais; il a posé une loi qu''on ne transgressera pas.'),
('ps',148,7,'crampon1923','De la terre, louez Yahweh, monstres marins, et vous tous, océans,'),
('ps',148,8,'crampon1923','feu et grêle, neige et vapeurs, vents impétueux, qui exécutez ses ordres,'),
('ps',148,9,'crampon1923','montagnes, et vous toutes, collines, arbres fruitiers, et vous tous, cèdres.'),
('ps',148,10,'crampon1923','Animaux sauvages et troupeaux de toutes sortes, reptiles et oiseaux ailés,'),
('ps',148,11,'crampon1923','rois de la terre et tous les peuples, princes, et vous tous, juges de la terre,'),
('ps',148,12,'crampon1923','jeunes hommes et jeunes vierges, vieillards et enfants.'),
('ps',148,13,'crampon1923','Qu''ils louent le nom de Yahweh, car son nom seul est grand, sa gloire est au-dessus du ciel et de la terre.'),
('ps',148,14,'crampon1923','Il a relevé la puissance de son peuple, sujet de louange pour tous ses fidèles, pour les enfants d''Israël, le peuple qui est près de lui, Alleluia!'),
('ps',149,1,'crampon1923','Alleluia! Chantez à Yahweh un cantique nouveau; que sa louange retentisse dans l''assemblée des saints!'),
('ps',149,2,'crampon1923','Qu''Israël se réjouisse en son Créateur, que les fils de Sion tressaillent en leur Roi!'),
('ps',149,3,'crampon1923','Qu''ils louent son nom dans leurs danses, qu''ils le chantent avec le tambourin et la harpe!'),
('ps',149,4,'crampon1923','Car Yahweh se complaît dans son peuple, il glorifie les humbles en les sauvant.'),
('ps',149,5,'crampon1923','Les fidèles triomphent dans la gloire, ils tressaillent de joie sur leur couche.'),
('ps',149,6,'crampon1923','Les louanges de Dieu sont dans leur bouche, et ils ont dans leurs mains un glaive à deux tranchants.'),
('ps',149,7,'crampon1923','Pour exercer la vengeance sur les nations, et porter le châtiment chez les peuples;'),
('ps',149,8,'crampon1923','pour lier leurs rois avec des chaînes, et leurs grands avec des ceps de fer;'),
('ps',149,9,'crampon1923','pour exécuter contre eux l''arrêt écrit: c''est là la gloire réservée à tous ses fidèles. Alleluia!'),
('ps',150,1,'crampon1923','Alleluia! Louez Dieu dans son sanctuaire! Louez-le dans le séjour de sa puissance!'),
('ps',150,2,'crampon1923','Louez-le pour ses hauts faits! Louez-le selon l''immensité de sa grandeur!'),
('ps',150,3,'crampon1923','Louez-le au son de la trompette! Louez-le sur la harpe et la cithare!'),
('ps',150,4,'crampon1923','Louez-le dans vos danses, avec le tambourin! Louez-le avec les instruments à cordes et le chalumeau!'),
('ps',150,5,'crampon1923','Louez-le avec les cymbales au son clair! Louez-le avec les cymbales retentissantes!'),
('ps',150,6,'crampon1923','Que tout ce qui respire loue Yahweh!'),
('pr',1,1,'crampon1923','Proverbes de Salomon, fils de David, roi d''Israël:'),
('pr',1,2,'crampon1923','pour connaître la sagesse et l''instruction; pour comprendre les discours sensés;'),
('pr',1,3,'crampon1923','pour acquérir une instruction éclairée, la justice, l''équité et la droiture;'),
('pr',1,4,'crampon1923','pour donner aux simples le discernement; au jeune homme la connaissance et la réflexion.'),
('pr',1,5,'crampon1923','Que le sage écoute, et il gagnera en savoir; l''homme intelligent connaîtra les conseils prudents,'),
('pr',1,6,'crampon1923','il comprendra les proverbes et les sens mystérieux, les maximes des sages et leurs énigmes.'),
('pr',1,7,'crampon1923','La crainte de Yahweh est le commencement de la sagesse; les insensés méprisent la sagesse et l''instruction.'),
('pr',1,8,'crampon1923','Ecoute, mon fils, l''instruction de ton père, et ne rejette pas l''enseignement de ta mère;'),
('pr',1,9,'crampon1923','car c''est une couronne de grâce pour ta tête, et une parure pour ton cou.'),
('pr',1,10,'crampon1923','Mon fils, si des pécheurs veulent te séduire, ne donne pas ton acquiescement.'),
('pr',1,11,'crampon1923','S''ils disent: « Viens avec nous, dressons des embûches pour répandre le sang, tendons sans raison des pièges à l''innocent.'),
('pr',1,12,'crampon1923','Engloutissons-les tout vifs, comme fait le schéol, tout entiers, comme ceux qui descendent dans la fosse.'),
('pr',1,13,'crampon1923','Nous trouverons toutes sortes de biens précieux, nous remplirons de butin nos maisons;'),
('pr',1,14,'crampon1923','tu tireras ta part au sort avec nous, il n''y aura qu''une bourse pour nous tous. » —'),
('pr',1,15,'crampon1923','Mon fils, ne va pas avec eux sur le chemin, détourne ton pied de leur sentier;'),
('pr',1,16,'crampon1923','car leurs pieds courent au mal, ils se hâtent pour répandre le sang.'),
('pr',1,17,'crampon1923','C''est vainement qu''on jette le filet devant les yeux de tout ce qui a des ailes;'),
('pr',1,18,'crampon1923','eux, c''est contre leur propre sang qu''ils dressent des embûches; c''est à leur âme qu''ils tendent des pièges.'),
('pr',1,19,'crampon1923','Telles sont les voies de tout homme âpre au gain; le gain cause la perte de ceux qui le détiennent.'),
('pr',1,20,'crampon1923','La sagesse crie dans les rues, elle élève sa voix sur les places.'),
('pr',1,21,'crampon1923','Elle prêche dans des carrefours bruyants; à l''entrée des portes, dans la ville, elle dit ses paroles:'),
('pr',1,22,'crampon1923','« Jusques à quand, simples, aimerez-vous la simplicité? Jusques à quand les railleurs se plairont-ils à la raillerie, et les insensés haïront-ils la science?'),
('pr',1,23,'crampon1923','Retournez-vous pour entendre ma réprimande; voici que je répandrai sur vous mon esprit, je vous ferai connaître mes paroles.'),
('pr',1,24,'crampon1923','« Puisque j''appelle et que vous résistez, que j''étends ma main et que personne n''y prend garde,'),
('pr',1,25,'crampon1923','puisque vous négligez tous mes conseils et que vous ne voulez pas de ma réprimande,'),
('pr',1,26,'crampon1923','moi aussi je rirai de votre malheur, je me moquerai quand viendra sur vous l''épouvante,'),
('pr',1,27,'crampon1923','quand l''épouvante viendra sur vous comme une tempête, que le malheur fondra sur vous comme un tourbillon, que viendront sur vous la détresse et l''angoisse.'),
('pr',1,28,'crampon1923','« Alors ils m''appelleront, et je ne répondrai pas; ils me chercheront, et ils ne me trouveront pas.'),
('pr',1,29,'crampon1923','Parce qu''ils ont haï la science, et qu''ils n''ont pas désiré la crainte de Yahweh,'),
('pr',1,30,'crampon1923','parce qu''ils n''ont pas voulu de mes conseils, et qu''ils ont dédaigné toutes mes réprimandes,'),
('pr',1,31,'crampon1923','ils mangeront du fruit de leur voie, et ils se rassasieront de leurs propres conseils.'),
('pr',1,32,'crampon1923','Car l''égarement des simples les tue, et la sécurité des insensés les perd.'),
('pr',1,33,'crampon1923','Mais celui qui m''écoute reposera avec sécurité, il vivra tranquille, sans craindre le malheur. »'),
('pr',2,1,'crampon1923','Mon fils, si tu reçois mes paroles; et si tu gardes avec toi mes préceptes;'),
('pr',2,2,'crampon1923','rendant ton oreille attentive à la sagesse, et inclinant ton cœur vers l''intelligence;'),
('pr',2,3,'crampon1923','oui, si tu appelles la prudence, et si tu élèves ta voix vers l''intelligence,'),
('pr',2,4,'crampon1923','si tu la cherches comme l''argent, et si tu la creuses comme pour découvrir un trésor; —'),
('pr',2,5,'crampon1923','alors tu comprendras la crainte de Yahweh, et tu trouveras la connaissance de Dieu.'),
('pr',2,6,'crampon1923','Car Yahweh donne la sagesse, de sa bouche sortent la science et la prudence;'),
('pr',2,7,'crampon1923','il garde le bonheur pour les hommes droits, il est un bouclier pour ceux qui marchent dans la perfection;'),
('pr',2,8,'crampon1923','il protège les sentiers de l''équité, il veille sur la voie de ses fidèles. —'),
('pr',2,9,'crampon1923','Alors tu comprendras la justice, l''équité, la droiture et tous les sentiers du bien.'),
('pr',2,10,'crampon1923','Lorsque la sagesse viendra dans ton cœur, et que la science fera les délices de ton âme,'),
('pr',2,11,'crampon1923','la réflexion veillera sur toi, et l''intelligence te gardera,'),
('pr',2,12,'crampon1923','pour te délivrer de la voie du mal, de l''homme qui tient des discours pervers,'),
('pr',2,13,'crampon1923','de ceux qui abandonnent les droits sentiers, afin de marcher dans des chemins ténébreux,'),
('pr',2,14,'crampon1923','qui se réjouissent de faire le mal, et mettent leur plaisir dans les pires perversités,'),
('pr',2,15,'crampon1923','dont les sentiers sont tortueux et qui suivent des voies obliques; —'),
('pr',2,16,'crampon1923','pour te délivrer de la femme qui est à un autre, de l''étrangère qui use de paroles doucereuses,'),
('pr',2,17,'crampon1923','qui abandonne le compagnon de sa jeunesse, et oublie l''alliance de son Dieu;'),
('pr',2,18,'crampon1923','car elle penche avec sa maison vers la mort, et sa route conduit aux enfers;'),
('pr',2,19,'crampon1923','de tous ceux qui vont à elle, nul ne revient, aucun ne retrouve les sentiers de la vie.'),
('pr',2,20,'crampon1923','Ainsi tu marcheras dans la voie des hommes de bien, et tu garderas les sentiers des justes.'),
('pr',2,21,'crampon1923','Car les hommes droits habiteront la terre et les hommes intègres y demeureront;'),
('pr',2,22,'crampon1923','mais les méchants seront retranchés de la terre, et les infidèles en seront arrachés.'),
('pr',3,1,'crampon1923','Mon fils, n''oublie pas mes enseignements, et que ton cœur garde mes préceptes.'),
('pr',3,2,'crampon1923','Ils te procureront de longs jours, des années de vie et la paix.'),
('pr',3,3,'crampon1923','Que la miséricorde et la vérité ne t''abandonnent pas; attache-les à ton cou, grave-les sur la table de ton cœur.'),
('pr',3,4,'crampon1923','Ainsi tu trouveras faveur et auras la vraie sagesse, aux yeux de Dieu et des hommes.'),
('pr',3,5,'crampon1923','Confie-toi de tout ton cœur en Yahweh, et ne t''appuie pas sur ta propre intelligence.'),
('pr',3,6,'crampon1923','Pense à lui dans toutes tes voies, et il aplanira tes sentiers.'),
('pr',3,7,'crampon1923','Ne sois pas sage à tes propres yeux; crains Yahweh et détourne-toi du mal.'),
('pr',3,8,'crampon1923','Ce sera la santé pour ton corps, et un rafraîchissement pour tes os.'),
('pr',3,9,'crampon1923','Fais honneur à Dieu de tes biens, des prémices de tout ton revenu.'),
('pr',3,10,'crampon1923','Alors tes greniers seront abondamment remplis, et tes cuves déborderont de vin nouveau.'),
('pr',3,11,'crampon1923','Mon fils, ne méprise pas la correction de Yahweh, et n''aie pas d''aversion pour ses châtiments.'),
('pr',3,12,'crampon1923','Car Yahweh châtie celui qu''il aime, comme un père châtie l''enfant qu''il chérit.'),
('pr',3,13,'crampon1923','Heureux l''homme qui a trouvé la sagesse, et l''homme qui a acquis l''intelligence!'),
('pr',3,14,'crampon1923','Son acquisition vaut mieux que celle de l''argent, sa possession que celle de l''or pur.'),
('pr',3,15,'crampon1923','Elle est plus précieuse que les perles, tous les joyaux ne l''égalent pas.'),
('pr',3,16,'crampon1923','Dans sa droite est une longue vie, dans sa gauche, la richesse et la gloire.'),
('pr',3,17,'crampon1923','Ses voies sont des voies agréables, tous ses sentiers, des sentiers de paix.'),
('pr',3,18,'crampon1923','Elle est un arbre de vie pour ceux qui la saisissent et celui qui s''y attache est heureux.'),
('pr',3,19,'crampon1923','C''est par la sagesse que Yahweh a fondé la terre, par l''intelligence qu''il a affermi les cieux.'),
('pr',3,20,'crampon1923','C''est par sa science que les abîmes se sont ouverts, et que les nuages distillent la rosée.'),
('pr',3,21,'crampon1923','Mon fils, qu''elles ne s''éloignent pas de tes yeux, garde la sagesse et la réflexion;'),
('pr',3,22,'crampon1923','elles seront la vie de ton âme, et l''ornement de ton cou.'),
('pr',3,23,'crampon1923','Alors tu marcheras en sécurité dans ton chemin, et ton pied ne heurtera pas.'),
('pr',3,24,'crampon1923','Si tu te couches, tu seras sans crainte; et quand tu seras couché, ton sommeil sera doux.'),
('pr',3,25,'crampon1923','Tu n''auras à redouter ni une terreur subite, ni une attaque qui vienne des méchants.'),
('pr',3,26,'crampon1923','Car Yahweh sera ton assurance, et il préservera ton pied de tout piège.'),
('pr',3,27,'crampon1923','Ne refuse pas un bienfait à ceux à qui il est dû, quand il est en ton pouvoir de l''accorder.'),
('pr',3,28,'crampon1923','Ne dis pas à ton prochain: « Va et reviens, demain je donnerai, » quand tu peux donner sur l''heure.'),
('pr',3,29,'crampon1923','Ne médite pas le mal contre ton prochain, lorsqu''il reste tranquille près de toi.'),
('pr',3,30,'crampon1923','Ne conteste pas sans motif avec quelqu''un, lorsqu''il ne t''a point fait de mal.'),
('pr',3,31,'crampon1923','Ne porte pas envie à l''homme de violence, et ne choisis aucune de ses voies:'),
('pr',3,32,'crampon1923','car Yahweh a en horreur les hommes pervers, mais avec les cœurs droits est son intimité.'),
('pr',3,33,'crampon1923','La malédiction de Yahweh est dans la maison du méchant, mais il bénit le toit des justes.'),
('pr',3,34,'crampon1923','Il se moque des moqueurs, et il donne la grâce aux humbles.'),
('pr',3,35,'crampon1923','La gloire sera le partage des sages, mais les insensés ont pour leur part l''ignominie.'),
('pr',4,1,'crampon1923','Ecoutez, mes fils, l''instruction d''un père, et soyez attentifs, pour apprendre l''intelligence;'),
('pr',4,2,'crampon1923','car je vous donne une bonne doctrine: n''abandonnez pas mon enseignement.'),
('pr',4,3,'crampon1923','Moi aussi j''ai été un fils pour mon père, un fils tendre et unique auprès de ma mère.'),
('pr',4,4,'crampon1923','Il m''instruisait et il me disait: « Que ton cœur retienne mes paroles, observe mes préceptes, et tu vivras.'),
('pr',4,5,'crampon1923','Acquiers la sagesse, acquiers l''intelligence; n''oublie pas les paroles de ma bouche, et ne t''en détourne pas.'),
('pr',4,6,'crampon1923','Ne l''abandonne pas, et elle te gardera; aime-la, et elle te conservera.'),
('pr',4,7,'crampon1923','Voici le commencement de la sagesse: acquiers la sagesse; au prix de tout ce que tu possèdes, acquiers l''intelligence.'),
('pr',4,8,'crampon1923','Tiens-la en haute estime, et elle t''exaltera; elle fera ta gloire, si tu l''embrasses.'),
('pr',4,9,'crampon1923','Elle mettra sur ta tête une couronne de grâce, elle t''ornera d''un magnifique diadème. »'),
('pr',4,10,'crampon1923','Ecoute, mon fils, et reçois mes paroles, et les années de ta vie se multiplieront.'),
('pr',4,11,'crampon1923','Je t''enseigne la voie de la sagesse, je te conduis dans les sentiers de la droiture.'),
('pr',4,12,'crampon1923','Si tu marches, tes pas ne seront point à l''étroit, et si tu cours, tu ne trébucheras pas.'),
('pr',4,13,'crampon1923','Retiens l''instruction, ne l''abandonne pas; garde-la, car elle est ta vie.'),
('pr',4,14,'crampon1923','N''entre pas dans le sentier des méchants, et ne marche pas dans la voie des hommes mauvais.'),
('pr',4,15,'crampon1923','Evite-la, n''y passe point, détourne-t''en et passe.'),
('pr',4,16,'crampon1923','Car ils ne dorment pas, s''ils ne font le mal; leur sommeil s''enfuit s''ils ne font tomber personne.'),
('pr',4,17,'crampon1923','Car ils mangent le pain du crime, ils boivent le vin de la violence.'),
('pr',4,18,'crampon1923','Le sentier des justes est comme la brillante lumière du matin, dont l''éclat va croissant jusqu''à ce que paraisse le jour.'),
('pr',4,19,'crampon1923','La voie des méchants est comme les ténèbres; ils n''aperçoivent pas ce qui les fera tomber.'),
('pr',4,20,'crampon1923','Mon fils, sois attentif à mes paroles, prête l''oreille à mes discours.'),
('pr',4,21,'crampon1923','Qu''ils ne s''éloignent pas de tes yeux, garde-les au milieu de ton cœur.'),
('pr',4,22,'crampon1923','Car ils sont vie pour ceux qui les trouvent, santé pour tout leur corps.'),
('pr',4,23,'crampon1923','Garde ton cœur avant toute chose, car de lui jaillissent les sources de la vie.'),
('pr',4,24,'crampon1923','Ecarte de ta bouche les paroles tortueuses, et éloigne de tes lèvres la fausseté.'),
('pr',4,25,'crampon1923','Que tes yeux regardent en face, et que tes paupières se dirigent devant toi.'),
('pr',4,26,'crampon1923','Fais à tes pieds un chemin uni, et que toutes tes voies soient droites.'),
('pr',4,27,'crampon1923','N''incline ni à droite ni à gauche, et détourne ton pied du mal.'),
('pr',5,1,'crampon1923','Mon fils, sois attentif à ma sagesse, et prête l''oreille à mon intelligence,'),
('pr',5,2,'crampon1923','afin que tu conserves la réflexion, et que tes lèvres gardent la science.'),
('pr',5,3,'crampon1923','Car les lèvres de l''étrangère distillent le miel, et son palais est plus doux que l''huile.'),
('pr',5,4,'crampon1923','Mais à la fin elle est amère comme l''absinthe, aiguë comme un glaive à deux tranchants.'),
('pr',5,5,'crampon1923','Ses pieds descendent vers la mort, ses pas vont droit au schéol.'),
('pr',5,6,'crampon1923','Elle ne considère pas le chemin de la vie, ses pas s''en vont incertains elle ne sait où.'),
('pr',5,7,'crampon1923','Et maintenant, mes fils, écoutez-moi, et ne vous écartez pas des paroles de ma bouche.'),
('pr',5,8,'crampon1923','Eloigne d''auprès d''elle ton chemin, ne t''approche pas de la porte de sa maison,'),
('pr',5,9,'crampon1923','de peur que tu ne livres à d''autres la fleur de ta jeunesse, et tes années au tyran cruel;'),
('pr',5,10,'crampon1923','de peur que des étrangers ne se rassasient de tes biens, et que le fruit de ton travail ne passe dans la maison d''autrui;'),
('pr',5,11,'crampon1923','de peur que tu ne gémisses à la fin, quand ta chair et ton corps seront consumés,'),
('pr',5,12,'crampon1923','et que tu ne dises: Comment donc ai-je pu haïr la correction, et comment mon cœur a-t-il dédaigné la réprimande?'),
('pr',5,13,'crampon1923','Comment ai-je pu ne pas écouter la voix de mes maîtres, ne pas prêter l''oreille à ceux qui m''instruisaient?'),
('pr',5,14,'crampon1923','J''ai failli en venir au comble du malheur, au milieu du peuple et de l''assemblée.'),
('pr',5,15,'crampon1923','Bois l''eau de ta citerne, les ruisseaux qui sortent de ton puits.'),
('pr',5,16,'crampon1923','Que tes sources se répandent au dehors, que tes ruisseaux coulent sur les places publiques!'),
('pr',5,17,'crampon1923','Qu''ils soient pour toi seul, et non pour des étrangers avec toi!'),
('pr',5,18,'crampon1923','Que ta source soit bénie, et mets ta joie dans la femme de ta jeunesse.'),
('pr',5,19,'crampon1923','Biche charmante, gracieuse gazelle, — que ses charmes t''enivrent en tout temps, sois toujours épris de son amour!'),
('pr',5,20,'crampon1923','Pourquoi, mon fils, t''éprendrais-tu d''une étrangère, et embrasserais-tu le sein d''une inconnue?'),
('pr',5,21,'crampon1923','Car devant les yeux de Yahweh sont les voies de l''homme, il considère tous ses sentiers.'),
('pr',5,22,'crampon1923','Le méchant est pris dans ses propres iniquités, il est saisi par les liens de son péché.'),
('pr',5,23,'crampon1923','Il mourra faute de correction, il sera trompé par l''excès de sa folie.'),
('pr',6,1,'crampon1923','Mon fils, si tu t''es rendu caution pour ton ami, si tu t''es engagé pour un étranger,'),
('pr',6,2,'crampon1923','si tu es lié par les paroles de ta bouche, si tu es pris par les paroles de ta bouche,'),
('pr',6,3,'crampon1923','fais donc ceci, mon ami: dégage-toi! Puisque tu es tombé aux mains de ton prochain, va, prosterne-toi et presse-le vivement!'),
('pr',6,4,'crampon1923','Ne donne ni sommeil à tes yeux, ni assoupissement à tes paupières;'),
('pr',6,5,'crampon1923','dégage-toi, comme la gazelle de la main du chasseur, comme l''oiseau de la main de l''oiseleur.'),
('pr',6,6,'crampon1923','Va vers la fourmi ô paresseux; considère ses voies et deviens sage.'),
('pr',6,7,'crampon1923','Elle qui n''a ni chef, ni inspecteur de travaux, ni souverain,'),
('pr',6,8,'crampon1923','elle amasse en été de quoi manger, elle recueille pendant la moisson sa nourriture.'),
('pr',6,9,'crampon1923','Jusques à quand, ô paresseux, seras-tu couché, quand te lèveras-tu de ton sommeil?'),
('pr',6,10,'crampon1923','« Un peu de sommeil, un peu d''assoupissement, un peu croiser les mains sur son lit. »'),
('pr',6,11,'crampon1923','Et ta pauvreté viendra comme un voyageur, et ta disette comme un homme en armes!'),
('pr',6,12,'crampon1923','Un homme pervers, un homme inique, marche la perversité dans la bouche;'),
('pr',6,13,'crampon1923','il cligne les yeux, gratte du pied, fait des signes avec les doigts.'),
('pr',6,14,'crampon1923','La perversité est dans son cœur, il médite le mal en tout temps, il suscite des querelles.'),
('pr',6,15,'crampon1923','Aussi sa ruine viendra subitement; il sera brisé tout d''un coup et sans remède.'),
('pr',6,16,'crampon1923','Il y a six choses que hait Yahweh, il y en a sept qu''il a en horreur:'),
('pr',6,17,'crampon1923','les yeux altiers, la langue menteuse, les mains qui font couler le sang innocent,'),
('pr',6,18,'crampon1923','le cœur qui médite des projets coupables, les pieds empressés à courir au mal,'),
('pr',6,19,'crampon1923','le faux témoin qui profère des mensonges, et celui qui sème la discorde entre frères.'),
('pr',6,20,'crampon1923','Mon fils, garde le précepte de ton père, et ne rejette pas l''enseignement de ta mère.'),
('pr',6,21,'crampon1923','Lie-les constamment sur ton cœur, attache-les à ton cou.'),
('pr',6,22,'crampon1923','Il te dirigera dans ta marche, il te gardera dans ton sommeil; à ton réveil, il conversera avec toi.'),
('pr',6,23,'crampon1923','Car le précepte est une lampe, et la loi une lumière, et les avertissements qui instruisent sont le chemin de la vie.'),
('pr',6,24,'crampon1923','Ils te préserveront de la femme perverse, de la langue doucereuse de l''étrangère.'),
('pr',6,25,'crampon1923','Ne convoite pas sa beauté dans ton cœur, et qu''elle ne te séduise pas par ses paupières.'),
('pr',6,26,'crampon1923','Car pour la courtisane on se réduit à un morceau de pain, et la femme mariée prend au piège une vie précieuse.'),
('pr',6,27,'crampon1923','Se peut-il qu''un homme mette du feu dans son sein, sans que ses vêtements s''enflamment?'),
('pr',6,28,'crampon1923','Ou bien un homme marchera-t-il sur des charbons ardents sans que ses pieds soient brûlés?'),
('pr',6,29,'crampon1923','Ainsi en est-il de celui qui va vers la femme de son prochain: quiconque la touche ne saurait rester impuni.'),
('pr',6,30,'crampon1923','On ne méprise pas un voleur qui dérobe pour satisfaire sa faim, quand il n''a rien à manger:'),
('pr',6,31,'crampon1923','surpris, il rend sept fois autant, il donne tout ce qu''il a dans sa maison.'),
('pr',6,32,'crampon1923','Mais celui qui corrompt une femme est dépourvu de sens; il se perd lui-même, celui qui agit de la sorte;'),
('pr',6,33,'crampon1923','il ne recueille que plaie et ignominie, et son opprobre ne s''effacera pas.'),
('pr',6,34,'crampon1923','Car la jalousie excite la fureur de l''homme outragé; il est sans pitié au jour de la vengeance;'),
('pr',6,35,'crampon1923','il n''a égard à aucune rançon; il n''en veut pas, quand même tu multiplierais les présents.'),
('pr',7,1,'crampon1923','Mon fils, retiens mes paroles, et garde avec toi mes préceptes.'),
('pr',7,2,'crampon1923','Observe mes préceptes, et tu vivras, garde mon enseignement comme la prunelle de tes yeux.'),
('pr',7,3,'crampon1923','Lie-les sur tes doigts, écris-les sur la table de ton cœur.'),
('pr',7,4,'crampon1923','Dis à la sagesse: Tu es ma sœur! et appelle l''intelligence ton amie,'),
('pr',7,5,'crampon1923','pour qu''elle te préserve de la femme d''autrui, de l''étrangère qui fait entendre de douces paroles.'),
('pr',7,6,'crampon1923','Etant à la fenêtre de ma maison, je regardais à travers le treillis.'),
('pr',7,7,'crampon1923','J''aperçus parmi les insensés, je remarquai parmi les jeunes gens un garçon dépourvu de sens.'),
('pr',7,8,'crampon1923','Il passait dans la rue, près du logis d''une étrangère, et il s''avançait vers sa demeure.'),
('pr',7,9,'crampon1923','C''était au crépuscule, à la chute du jour, au milieu de la nuit et de l''obscurité.'),
('pr',7,10,'crampon1923','Et voilà qu''une femme l''aborde, ayant la mise d''une courtisane et la dissimulation dans le cœur.'),
('pr',7,11,'crampon1923','Elle est impétueuse et indomptable; ses pieds ne peuvent se reposer dans sa maison;'),
('pr',7,12,'crampon1923','tantôt dans la rue, tantôt sur les places, et près de tous les angles, elle se tient aux aguets.'),
('pr',7,13,'crampon1923','Elle saisit le jeune homme et l''embrasse, et avec un visage effronté lui dit:'),
('pr',7,14,'crampon1923','« Je devais offrir des victimes pacifiques, aujourd''hui j''ai accompli mes vœux.'),
('pr',7,15,'crampon1923','C''est pourquoi je suis sortie à ta rencontre, pour te chercher, et je t''ai trouvé.'),
('pr',7,16,'crampon1923','J''ai garni mon lit de couvertures, de tapis de fil d''Egypte.'),
('pr',7,17,'crampon1923','J''ai parfumé ma couche de myrrhe, d''aloès et de cinnamome.'),
('pr',7,18,'crampon1923','Viens, enivrons-nous d''amour jusqu''au matin, livrons-nous aux délices de la volupté.'),
('pr',7,19,'crampon1923','Car mon mari n''est pas à la maison, il est parti pour un lointain voyage;'),
('pr',7,20,'crampon1923','il a pris avec lui le sac de l''argent, il ne reviendra à la maison qu''à la pleine lune. »'),
('pr',7,21,'crampon1923','Elle le séduit à force de paroles, elle l''entraîne par les paroles de ses lèvres;'),
('pr',7,22,'crampon1923','il se met aussitôt à la suivre, comme le bœuf qui va à la boucherie, comme l''insensé qui court au châtiment des entraves,'),
('pr',7,23,'crampon1923','jusqu''à ce qu''une flèche lui perce le foie, comme l''oiseau qui se précipite dans le filet, sans savoir qu''il y va pour lui de sa vie.'),
('pr',7,24,'crampon1923','Et maintenant, mes fils, écoutez-moi, et soyez attentifs aux paroles de ma bouche.'),
('pr',7,25,'crampon1923','Que ton cœur ne se détourne pas vers ses voies, ne t''égare pas dans ses sentiers.'),
('pr',7,26,'crampon1923','Car elle a fait de nombreux blessés, et nombreuses ont été ses victimes.'),
('pr',7,27,'crampon1923','Sa maison est le chemin du schéol, qui descend au séjour de la mort.'),
('pr',8,1,'crampon1923','La sagesse ne crie-t-elle pas, l''intelligence n''élève-t-elle pas sa voix?'),
('pr',8,2,'crampon1923','C''est au sommet des hauteurs, sur la route, à la jonction des chemins, qu''elle se place;'),
('pr',8,3,'crampon1923','près des portes, aux abords de la ville, à l''entrée des portes, elle fait entendre sa voix:'),
('pr',8,4,'crampon1923','« Hommes, c''est à vous que je crie, et ma voix s''adresse aux enfants des hommes.'),
('pr',8,5,'crampon1923','Simples, apprenez la prudence; insensés, apprenez l''intelligence.'),
('pr',8,6,'crampon1923','Ecoutez, car j''ai à dire des choses magnifiques, et mes lèvres s''ouvrent pour enseigner ce qui est droit.'),
('pr',8,7,'crampon1923','« Car ma bouche proclame la vérité, et mes lèvres ont l''iniquité en horreur.'),
('pr',8,8,'crampon1923','Toutes les paroles de ma bouche sont justes; il n''y a en elles rien de faux ni de tortueux.'),
('pr',8,9,'crampon1923','Toutes sont justes pour celui qui est intelligent, et droites pour ceux qui ont trouvé la science.'),
('pr',8,10,'crampon1923','Recevez mon instruction plutôt que l''argent, et la science plutôt que l''or pur.'),
('pr',8,11,'crampon1923','Car la sagesse vaut mieux que les perles, et les objets les plus précieux ne l''égalent pas.'),
('pr',8,12,'crampon1923','« Moi, la sagesse, j''habite avec la prudence, et je possède la science de la réflexion.'),
('pr',8,13,'crampon1923','La crainte de Yahweh, c''est la haine du mal; l''arrogance et l''orgueil, la voie du mal et la bouche perverse, voilà ce que je hais.'),
('pr',8,14,'crampon1923','Le conseil et le succès m''appartiennent; je suis l''intelligence, la force est à moi.'),
('pr',8,15,'crampon1923','Par moi les rois règnent, et les princes ordonnent ce qui est juste.'),
('pr',8,16,'crampon1923','Par moi gouvernent les chefs, et les grands, — tous les juges de la terre.'),
('pr',8,17,'crampon1923','J''aime ceux qui m''aiment, et ceux qui me cherchent avec empressement me trouvent.'),
('pr',8,18,'crampon1923','Avec moi sont les richesses et la gloire, les biens durables et la justice.'),
('pr',8,19,'crampon1923','Mon fruit vaut mieux que l''or, que l''or pur, et ce qui vient de moi mieux que l''argent éprouvé.'),
('pr',8,20,'crampon1923','Je marche dans le chemin de la justice, au milieu des sentiers du jugement,'),
('pr',8,21,'crampon1923','pour donner des biens à ceux qui m''aiment, et combler leurs trésors.'),
('pr',8,22,'crampon1923','« Yahweh m''a possédée au commencement de ses voies, avant ses œuvres les plus anciennes.'),
('pr',8,23,'crampon1923','J''ai été fondée dès l''éternité, dès le commencement, avant les origines de la terre.'),
('pr',8,24,'crampon1923','Il n''y avait point d''abîmes quand je fus enfantée, point de sources chargées d''eaux.'),
('pr',8,25,'crampon1923','Avant que les montagnes fussent affermies, avant les collines, j''étais enfantée,'),
('pr',8,26,'crampon1923','lorsqu''il n''avait encore fait ni la terre, ni les plaines, ni les premiers éléments de la poussière du globe.'),
('pr',8,27,'crampon1923','Lorsqu''il disposa les cieux, j''étais là, lorsqu''il traça un cercle à la surface de l''abîme,'),
('pr',8,28,'crampon1923','lorsqu''il affermit les nuages en haut, et qu''il dompta les sources de l''abîme,'),
('pr',8,29,'crampon1923','lorsqu''il fixa sa limite à la mer, pour que les eaux n''en franchissent pas les bords, lorsqu''il posa les fondements de la terre.'),
('pr',8,30,'crampon1923','J''étais à l''œuvre auprès de lui, me réjouissant chaque jour, et jouant sans cesse en sa présence,'),
('pr',8,31,'crampon1923','jouant sur le globe de sa terre, et trouvant mes délices parmi les enfants des hommes.'),
('pr',8,32,'crampon1923','« Et maintenant, mes fils, écoutez-moi; heureux ceux qui gardent mes voies!'),
('pr',8,33,'crampon1923','Ecoutez l''instruction pour devenir sages; ne la rejetez pas.'),
('pr',8,34,'crampon1923','Heureux l''homme qui m''écoute, qui veille chaque jour à mes portes, et qui en garde les montants!'),
('pr',8,35,'crampon1923','Car celui qui me trouve a trouvé la vie, et il obtient la faveur de Yahweh.'),
('pr',8,36,'crampon1923','Mais celui qui m''offense blesse son âme; tous ceux qui me haïssent aiment la mort. »'),
('pr',9,1,'crampon1923','La sagesse a bâti sa maison, elle a taillé ses sept colonnes.'),
('pr',9,2,'crampon1923','Elle a immolé ses victimes, mêlé son vin, et dressé sa table.'),
('pr',9,3,'crampon1923','Elle a envoyé ses servantes, elle appelle, au sommet des hauteurs de la ville:'),
('pr',9,4,'crampon1923','« Que celui qui est simple entre ici! » Elle dit à celui qui est dépourvu de sens:'),
('pr',9,5,'crampon1923','« Venez, mangez de mon pain, et buvez du vin que j''ai mêlé;'),
('pr',9,6,'crampon1923','quittez l''ignorance, et vous vivrez, et marchez dans la voie de l''intelligence. »'),
('pr',9,7,'crampon1923','Celui qui reprend le moqueur s''attire la raillerie, et celui qui réprimande le méchant s''attire l''outrage.'),
('pr',9,8,'crampon1923','Ne reprends pas le moqueur, de peur qu''il ne te haïsse; reprends le sage, et il t''aimera.'),
('pr',9,9,'crampon1923','Donne au sage, et il deviendra plus sage; instruis le juste, et il augmentera son savoir.'),
('pr',9,10,'crampon1923','Le commencement de la sagesse, c''est la crainte de Yahweh; et l''intelligence, c''est la science du Saint.'),
('pr',9,11,'crampon1923','Car par moi tes jours se multiplieront, par moi s''augmenteront les années de ta vie.'),
('pr',9,12,'crampon1923','Si tu es sage, tu es sage à ton profit; si tu es moqueur, tu en porteras seul la peine.'),
('pr',9,13,'crampon1923','La folie est une femme bruyante, stupide et ne sachant rien.'),
('pr',9,14,'crampon1923','Elle s''est assise, à la porte de sa maison, sur un siège, dans les hauteurs de la ville,'),
('pr',9,15,'crampon1923','pour inviter les passants qui vont droit leur chemin:'),
('pr',9,16,'crampon1923','« Que celui qui est simple entre ici! » Elle dit à celui qui est dépourvu de sens:'),
('pr',9,17,'crampon1923','« Les eaux dérobées sont plus douces, et le pain du mystère est plus agréable! »'),
('pr',9,18,'crampon1923','Et il ne sait pas qu''il y a là des ombres, et que ses invités sont déjà dans les profondeurs du schéol.'),
('pr',10,1,'crampon1923','Paraboles de Salomon. Le fils sage fait la joie de son père, et le fils insensé le chagrin de sa mère.'),
('pr',10,2,'crampon1923','Les trésors acquis par le crime ne profitent pas, mais la justice délivre de la mort.'),
('pr',10,3,'crampon1923','Yahweh ne laisse pas le juste souffrir de la faim, mais il repousse la convoitise du méchant.'),
('pr',10,4,'crampon1923','Il s''appauvrit celui qui travaille d''une main paresseuse, mais la main des diligents amasse des richesses.'),
('pr',10,5,'crampon1923','Celui qui recueille pendant l''été est un fils prudent; celui qui dort au temps de la moisson est un fils de confusion.'),
('pr',10,6,'crampon1923','La bénédiction vient sur la tête du juste, mais l''injustice couvre la bouche des méchants.'),
('pr',10,7,'crampon1923','La mémoire du juste est en bénédiction, mais le nom des méchants tombe en pourriture.'),
('pr',10,8,'crampon1923','Celui qui est sage de cœur reçoit les préceptes, mais celui qui est insensé des lèvres va à sa perte.'),
('pr',10,9,'crampon1923','Celui qui marche dans l''intégrité marche en confiance, mais celui qui prend des voies tortueuses sera découvert.'),
('pr',10,10,'crampon1923','Celui qui cligne les yeux sera une cause de chagrin, et celui qui est insensé des lèvres va à sa perte.'),
('pr',10,11,'crampon1923','La bouche du juste est une source de vie, mais l''injustice couvre la bouche du méchant.'),
('pr',10,12,'crampon1923','La haine suscite des querelles, mais l''amour couvre toutes les fautes.'),
('pr',10,13,'crampon1923','Sur les lèvres de l''homme intelligent se trouve la sagesse, mais la verge est pour le dos de celui qui manque de sens.'),
('pr',10,14,'crampon1923','Les sages tiennent la sagesse en réserve, mais la bouche de l''insensé est un malheur prochain.'),
('pr',10,15,'crampon1923','La fortune est pour le riche sa place forte, le malheur des misérables, c''est leur pauvreté.'),
('pr',10,16,'crampon1923','L''œuvre du juste est pour la vie, le gain du méchant est pour le péché.'),
('pr',10,17,'crampon1923','Celui qui prend garde à l''instruction prend le chemin de la vie; mais celui qui oublie la réprimande s''égare.'),
('pr',10,18,'crampon1923','Celui qui cache la haine a des lèvres menteuses, et celui qui répand la calomnie est un insensé.'),
('pr',10,19,'crampon1923','L''abondance de paroles ne va pas sans péché, mais celui qui retient ses lèvres est un homme prudent.'),
('pr',10,20,'crampon1923','La langue du juste est un argent de choix; le cœur des méchants est de peu de prix.'),
('pr',10,21,'crampon1923','Les lèvres du juste nourrissent beaucoup d''hommes, mais les insensés meurent par défaut d''intelligence.'),
('pr',10,22,'crampon1923','C''est la bénédiction du Seigneur qui procure la richesse, et la peine que l''on prend n''y ajoute rien.'),
('pr',10,23,'crampon1923','Commettre le crime paraît un jeu à l''insensé; il en est de même de la sagesse pour l''homme intelligent.'),
('pr',10,24,'crampon1923','Ce que redoute le méchant lui arrive, et Dieu accorde au juste ce qu''il désire.'),
('pr',10,25,'crampon1923','Comme passe le tourbillon, le méchant disparaît; le juste est établi sur un fondement éternel.'),
('pr',10,26,'crampon1923','Ce que le vinaigre est aux dents et la fumée aux yeux, tel est le paresseux pour ceux qui l''envoient.'),
('pr',10,27,'crampon1923','La crainte de Yahweh augmente les jours, mais les années des méchants sont abrégées.'),
('pr',10,28,'crampon1923','L''attente des justes n''est que joie, mais l''espérance des méchants périra.'),
('pr',10,29,'crampon1923','La voie de Yahweh est un rempart pour le juste, mais elle est une ruine pour ceux qui font le mal.'),
('pr',10,30,'crampon1923','Le juste ne chancellera jamais, mais les méchants n''habiteront pas la terre.'),
('pr',10,31,'crampon1923','La bouche du juste produit la sagesse, et la langue perverse sera arrachée.'),
('pr',10,32,'crampon1923','Les lèvres du juste connaissent la grâce, et la bouche des méchants la perversité.'),
('pr',11,1,'crampon1923','La balance fausse est en horreur à Yahweh, mais le poids juste lui est agréable.'),
('pr',11,2,'crampon1923','Si l''orgueil vient, viendra aussi l''ignominie; mais la sagesse est avec les humbles.'),
('pr',11,3,'crampon1923','L''innocence des hommes droits les dirige, mais les détours des perfides les ruinent.'),
('pr',11,4,'crampon1923','Au jour de la colère, la richesse ne sert de rien, mais la justice délivre de la mort.'),
('pr',11,5,'crampon1923','La justice de l''homme intègre dirige ses voies, mais le méchant tombe par sa méchanceté.'),
('pr',11,6,'crampon1923','La justice des hommes droits les délivre, mais les perfides sont pris par leur propre malice.'),
('pr',11,7,'crampon1923','Quand meurt le méchant, son espoir périt, et l''attente du pervers est anéantie.'),
('pr',11,8,'crampon1923','Le juste est délivré de l''angoisse, et le méchant y tombe à sa place.'),
('pr',11,9,'crampon1923','Par sa bouche l''impie prépare la ruine de son prochain, mais les justes seront délivrés par la science.'),
('pr',11,10,'crampon1923','Quand les justes sont heureux, la ville se réjouit; quand les méchants périssent, on pousse des cris de joie.'),
('pr',11,11,'crampon1923','Par la bénédiction des hommes droits la ville prospère; elle est renversée par la bouche des impies.'),
('pr',11,12,'crampon1923','Celui qui méprise son prochain est dépourvu de sens, mais l''homme intelligent se tait.'),
('pr',11,13,'crampon1923','Le médisant dévoile les secrets, mais l''homme au cœur fidèle tient la chose cachée.'),
('pr',11,14,'crampon1923','Quand la direction fait défaut, le peuple tombe; le salut est le grand nombre des conseillers.'),
('pr',11,15,'crampon1923','Qui cautionne un inconnu s''en repent, mais celui qui craint de s''engager est en sécurité.'),
('pr',11,16,'crampon1923','La femme qui a de la grâce obtient la gloire, les hommes énergiques acquièrent la richesse.'),
('pr',11,17,'crampon1923','L''homme charitable fait du bien à son âme, mais l''homme cruel afflige sa propre chair.'),
('pr',11,18,'crampon1923','Le méchant fait un travail trompeur, mais celui qui sème la justice a une récompense assurée.'),
('pr',11,19,'crampon1923','La justice conduit à la vie, mais celui qui poursuit le mal va à la mort.'),
('pr',11,20,'crampon1923','Les hommes au cœur pervers sont en abomination à Yahweh, mais ceux qui sont intègres en leur voie sont l''objet de ses complaisances.'),
('pr',11,21,'crampon1923','Non, le méchant ne restera pas impuni, mais la postérité des justes sera sauvée.'),
('pr',11,22,'crampon1923','Un anneau d''or au nez d''un pourceau, telle est la femme belle et dépourvue de sens.'),
('pr',11,23,'crampon1923','Le désir des justes, c''est uniquement le bien; l''attente des méchants, c''est la fureur.'),
('pr',11,24,'crampon1923','Celui-ci donne libéralement et s''enrichit; cet autre épargne outre mesure et s''appauvrit.'),
('pr',11,25,'crampon1923','L''âme bienfaisante sera rassasiée, et celui qui arrose sera lui-même arrosé.'),
('pr',11,26,'crampon1923','Celui qui retient le blé est maudit du peuple, mais la bénédiction est sur la tête de celui qui le vend.'),
('pr',11,27,'crampon1923','Celui qui recherche le bien trouve la faveur, mais celui qui cherche le mal, le mal l''atteindra.'),
('pr',11,28,'crampon1923','Celui qui se confie dans sa richesse tombera, mais les justes germeront comme le feuillage.'),
('pr',11,29,'crampon1923','Celui qui trouble sa maison héritera le vent, et l''insensé sera l''esclave de l''homme sage.'),
('pr',11,30,'crampon1923','Le fruit du juste est un arbre de vie, et qui fait la conquête des âmes est sage.'),
('pr',11,31,'crampon1923','Si le juste reçoit sur la terre une rétribution de peines, combien plus le méchant et le pécheur!'),
('pr',12,1,'crampon1923','Celui qui aime l''instruction aime la science; celui qui hait la réprimande est insensé.'),
('pr',12,2,'crampon1923','Celui qui est bon obtient la faveur de Yahweh, mais Yahweh condamne l''homme de malice.'),
('pr',12,3,'crampon1923','L''homme ne s''affermit pas par la méchanceté, mais la racine des justes ne sera pas ébranlée.'),
('pr',12,4,'crampon1923','Une femme vertueuse est la couronne de son mari, mais la femme sans honneur est comme la carie dans ses os.'),
('pr',12,5,'crampon1923','Les pensées des justes sont l''équité; les conseils des méchants, la fraude.'),
('pr',12,6,'crampon1923','Les paroles des méchants sont des pièges de mort, mais la bouche des hommes droits les sauve.'),
('pr',12,7,'crampon1923','Le méchant fait un tour, et il n''est plus; mais la maison des justes reste debout.'),
('pr',12,8,'crampon1923','L''homme est estimé dans la mesure de son intelligence; mais l''homme au cœur pervers sera méprisé.'),
('pr',12,9,'crampon1923','Mieux vaut un homme humble qui suffit à ses besoins, qu''un glorieux manquant de pain.'),
('pr',12,10,'crampon1923','Le juste s''occupe de son bétail, mais les entrailles des méchants sont cruelles.'),
('pr',12,11,'crampon1923','Celui qui cultive son champ est rassasié de pain, mais celui qui poursuit des choses inutiles est dépourvu de sens.'),
('pr',12,12,'crampon1923','Le méchant convoite la proie des méchants, mais la racine des justes donne son fruit.'),
('pr',12,13,'crampon1923','Il y a dans le péché des lèvres un piège funeste, mais le juste se tire de la détresse.'),
('pr',12,14,'crampon1923','C''est par le fruit de sa bouche qu''on est rassasié de biens, et il sera rendu à chacun suivant l''œuvre de ses mains.'),
('pr',12,15,'crampon1923','La voie de l''insensé est droite à ses yeux, mais le sage écoute les conseils.'),
('pr',12,16,'crampon1923','L''insensé laisse voir aussitôt sa colère, mais l''homme prudent sait dissimuler un outrage.'),
('pr',12,17,'crampon1923','Celui qui proclame la vérité dit ce qui est juste, et le faux témoin profère la perfidie.'),
('pr',12,18,'crampon1923','Tel qui parle inconsidérément blesse comme un glaive, mais la langue des sages procure la guérison.'),
('pr',12,19,'crampon1923','La langue véridique restera toujours, mais la langue mensongère est confondue en un clin d''œil.'),
('pr',12,20,'crampon1923','La fraude est dans le cœur de ceux qui méditent le mal, mais la joie est pour ceux qui conseillent la paix.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('pr',12,21,'crampon1923','Aucun malheur n''arrive au juste, mais les méchants sont accablés de maux.'),
('pr',12,22,'crampon1923','Les lèvres menteuses sont en horreur à Yahweh, mais ceux qui agissent selon la vérité lui sont agréables.'),
('pr',12,23,'crampon1923','L''homme prudent cache sa science, mais le cœur de l''insensé publie sa folie.'),
('pr',12,24,'crampon1923','La main vigilante dominera, mais la main indolente sera tributaire.'),
('pr',12,25,'crampon1923','Le chagrin dans le cœur de l''homme l''abat, mais une bonne parole le réjouit.'),
('pr',12,26,'crampon1923','Le juste montre la voie à son ami, mais la voie des méchants les égare.'),
('pr',12,27,'crampon1923','Le paresseux ne rôtit pas son gibier, mais l''activité est pour l''homme un précieux trésor.'),
('pr',12,28,'crampon1923','Dans le sentier de la justice est la vie, et dans le chemin qu''elle trace l''immortalité.'),
('pr',13,1,'crampon1923','Le fils sage révèle l''instruction de son père, mais le moqueur n''écoute pas la réprimande.'),
('pr',13,2,'crampon1923','Du fruit de sa bouche l''homme goûte le bien, mais le désir des perfides, c''est la violence.'),
('pr',13,3,'crampon1923','Celui qui veille sur sa bouche garde son âme; celui qui ouvre trop ses lèvres court à sa perte.'),
('pr',13,4,'crampon1923','Le paresseux à des désirs, et ils ne sont pas satisfaits, mais le désir des hommes diligents sera rassasié.'),
('pr',13,5,'crampon1923','Le juste déteste les paroles mensongères; le méchant procure la honte et la confusion.'),
('pr',13,6,'crampon1923','La justice garde la voie de l''homme intègre, mais la méchanceté cause la ruine du pécheur.'),
('pr',13,7,'crampon1923','Tel fait le riche qui n''a rien, tel fait le pauvre qui a de grands biens.'),
('pr',13,8,'crampon1923','La richesse d''un homme est rançon de sa vie, mais le pauvre n''entend même pas la menace.'),
('pr',13,9,'crampon1923','La lumière du juste brille joyeusement, mais la lampe des méchants s''éteint.'),
('pr',13,10,'crampon1923','L''orgueil ne produit que des querelles; mais la sagesse est avec ceux qui se laissent conseiller.'),
('pr',13,11,'crampon1923','La richesse mal acquise s''évanouit, mais celui qui l''amasse peu à peu l''augmente.'),
('pr',13,12,'crampon1923','L''espoir différé rend le cœur malade, mais le désir accompli est un arbre de vie.'),
('pr',13,13,'crampon1923','Celui qui méprise la parole se perd, mais celui qui respecte le précepte sera récompensé.'),
('pr',13,14,'crampon1923','L''enseignement du sage est une source de vie, pour échapper aux pièges de la mort.'),
('pr',13,15,'crampon1923','Une intelligence cultivée produit la grâce, mais la voie des perfides est rude.'),
('pr',13,16,'crampon1923','Tout homme prudent agit avec réflexion, mais l''insensé étale sa folie.'),
('pr',13,17,'crampon1923','Un envoyé méchant tombe dans le malheur, mais un messager fidèle procure la guérison.'),
('pr',13,18,'crampon1923','Misère et honte à qui rejette la correction; celui qui reçoit la réprimande est honoré.'),
('pr',13,19,'crampon1923','Le désir satisfait réjouit l''âme, et s''éloigner du mal fait horreur aux insensés.'),
('pr',13,20,'crampon1923','Celui qui fréquente les sages devient sage, mais celui qui se plaît avec les insensés devient méchant.'),
('pr',13,21,'crampon1923','Le malheur poursuit les pécheurs, mais le bonheur récompense les justes.'),
('pr',13,22,'crampon1923','L''homme de bien laisse sont héritage aux enfants de ses enfants; mais la richesse du pécheur est réservée au juste.'),
('pr',13,23,'crampon1923','Dans le champ défriché par le pauvre abonde la nourriture, mais il en est qui périssent faute de justice.'),
('pr',13,24,'crampon1923','Celui qui ménage sa verge hait son fils, mais celui qui l''aime le corrige de bonne heure.'),
('pr',13,25,'crampon1923','Le juste mange et satisfait son appétit, mais le ventre des méchants éprouve la disette.'),
('pr',14,1,'crampon1923','La femme sage bâtit sa maison, et la femme insensée la renverse de ses propres mains.'),
('pr',14,2,'crampon1923','Celui-là marche dans sa droiture qui craint Yahweh, et celui qui le méprise est pervers dans sa voie.'),
('pr',14,3,'crampon1923','Dans la bouche de l''insensé est la verge de son orgueil, mais les lèvres des sages les gardent.'),
('pr',14,4,'crampon1923','Où il n''y a pas de bœufs, la crèche est vide, mais la vigueur des bœufs procure des revenus abondants.'),
('pr',14,5,'crampon1923','Le témoin fidèle ne ment pas, mais le faux témoin profère des mensonges.'),
('pr',14,6,'crampon1923','Le moqueur cherche la sagesse et ne la trouve pas, mais pour l''homme intelligent la science est facile.'),
('pr',14,7,'crampon1923','Eloigne-toi de l''insensé; car tu sais que la science n''est pas sur ses lèvres.'),
('pr',14,8,'crampon1923','La sagesse de l''homme prudent est de comprendre sa voie; la folie des insensés, c''est la tromperie.'),
('pr',14,9,'crampon1923','L''insensé se rit du péché, mais parmi les hommes droits est la bienveillance.'),
('pr',14,10,'crampon1923','Le cœur connaît ses propres chagrins, et un étranger ne peut partager sa joie.'),
('pr',14,11,'crampon1923','La maison des méchants sera détruite, mais la tente des hommes droits fleurira.'),
('pr',14,12,'crampon1923','Telle voie paraît droite à un homme, mais son issue, c''est la voie de la mort.'),
('pr',14,13,'crampon1923','Même dans le rire le cœur trouve la douleur, et la joie se termine par le deuil.'),
('pr',14,14,'crampon1923','L''impie sera rassasié de ses voies, et l''homme de bien de ses fruits.'),
('pr',14,15,'crampon1923','L''homme simple croit à toute parole, mais l''homme prudent veille sur ses pas.'),
('pr',14,16,'crampon1923','Le sage craint et se détourne du mal, mais l''insensé s''emporte et reste en sécurité.'),
('pr',14,17,'crampon1923','L''homme prompt à s''irriter fait des sottises, et le malicieux s''attire la haine.'),
('pr',14,18,'crampon1923','Les simples ont en partage la folie, et les prudents se font de la science une couronne.'),
('pr',14,19,'crampon1923','Les méchants s''inclinent devant les bons, et les impies aux portes du juste.'),
('pr',14,20,'crampon1923','Le pauvre est odieux même à son ami; mais les amis du riche sont nombreux.'),
('pr',14,21,'crampon1923','Celui qui méprise son prochain commet un péché; mais heureux celui qui a pitié des malheureux!'),
('pr',14,22,'crampon1923','Ne s''égarent-ils pas ceux qui méditent le mal, et la faveur et la vérité ne sont-elles pas pour ceux qui méditent le bien?'),
('pr',14,23,'crampon1923','Tout travail produit l''abondance, mais les paroles vaines mènent à la disette.'),
('pr',14,24,'crampon1923','La richesse est une couronne pour les sages; la folie des insensés est toujours folie.'),
('pr',14,25,'crampon1923','Le témoin véridique délivre des âmes, l''astuce profère des mensonges.'),
('pr',14,26,'crampon1923','Celui qui craint Yahweh trouve un appui solide, et ses enfants ont un sûr refuge.'),
('pr',14,27,'crampon1923','La crainte de Yahweh est une source de vie, pour échapper aux pièges de la mort.'),
('pr',14,28,'crampon1923','Le peuple nombreux est la gloire du roi; le manque de sujets, c''est la ruine du prince.'),
('pr',14,29,'crampon1923','Celui qui est lent à la colère a une grande intelligence; mais celui qui est prompt à s''emporter publie sa folie.'),
('pr',14,30,'crampon1923','Un cœur tranquille est la vie du corps, mais l''envie est la carie des os.'),
('pr',14,31,'crampon1923','Celui qui opprime le pauvre outrage celui qui l''a fait; mais il l''honore celui qui a pitié de l''indigent.'),
('pr',14,32,'crampon1923','Par sa propre malice le méchant est renversé; jusque dans sa mort le juste a confiance.'),
('pr',14,33,'crampon1923','Dans le cœur de l''homme intelligent repose la sagesse, et au milieu des insensés on la reconnaît.'),
('pr',14,34,'crampon1923','La justice élève une nation, mais le péché est l''opprobre des peuples.'),
('pr',14,35,'crampon1923','La faveur du roi est pour le serviteur intelligent, et sa colère pour celui qui fait honte.'),
('pr',15,1,'crampon1923','Une réponse douce calme la fureur, mais une parole dure excite la colère.'),
('pr',15,2,'crampon1923','La langue des sages rend la science aimable; de la bouche des insensés déborde la folie.'),
('pr',15,3,'crampon1923','Les yeux de Yahweh sont en tout lieu, observant les méchants et les bons.'),
('pr',15,4,'crampon1923','la parole douce est un arbre de vie, mais la langue perverse brise le cœur.'),
('pr',15,5,'crampon1923','L''insensé méprise l''instruction de son père, mais celui qui profite de la réprimande devient plus sage.'),
('pr',15,6,'crampon1923','Il y a grande richesse dans la maison du juste, mais il y a du trouble dans les gains du méchant.'),
('pr',15,7,'crampon1923','Les lèvres du sage répandent la science, mais non le cœur de l''insensé.'),
('pr',15,8,'crampon1923','Le sacrifice des méchants est en horreur à Yahweh, mais la prière des hommes droits lui plaît.'),
('pr',15,9,'crampon1923','La voie du méchant est en abomination à Yahweh, mais il aime celui qui poursuit la justice.'),
('pr',15,10,'crampon1923','Une correction sévère frappe celui qui abandonne le sentier; celui qui hait la réprimande mourra.'),
('pr',15,11,'crampon1923','Le schéol et l''abîme sont à nu devant Yahweh: combien plus les cœurs des enfants des hommes!'),
('pr',15,12,'crampon1923','Le moqueur n''aime pas qu''on le reprenne, il ne va pas vers les sages.'),
('pr',15,13,'crampon1923','Un cœur joyeux rend le visage serein, mais, quand le cœur est triste, l''esprit est abattu.'),
('pr',15,14,'crampon1923','Le cœur intelligent cherche la science, mais la bouche des insensés se repaît de folie.'),
('pr',15,15,'crampon1923','Tous les jours de l''affligé sont mauvais, mais le cœur content est un festin perpétuel.'),
('pr',15,16,'crampon1923','Mieux vaut peu avec la crainte de Yahweh, qu''un grand trésor avec le trouble.'),
('pr',15,17,'crampon1923','Mieux vaut des légumes avec de l''affection, qu''un bœuf gras avec de la haine.'),
('pr',15,18,'crampon1923','L''homme violent excite des querelles, mais le patient apaise les disputes.'),
('pr',15,19,'crampon1923','Le chemin du paresseux est comme une haie d''épines, mais le sentier des hommes droits est aplani.'),
('pr',15,20,'crampon1923','Un fils sage fait la joie de son père, et l''insensé méprise sa mère.'),
('pr',15,21,'crampon1923','La folie est une joie pour l''homme dépourvu de sens, mais un homme intelligent suit le droit chemin.'),
('pr',15,22,'crampon1923','Les projets échouent faute de délibération, mais ils réussissent quand il y a de nombreux conseillers.'),
('pr',15,23,'crampon1923','L''homme a de la joie pour une bonne réponse de sa bouche, et combien est agréable une parole dite à propos!'),
('pr',15,24,'crampon1923','Le sage suit un sentier de vie qui mène en haut, pour se détourner du schéol qui est en bas.'),
('pr',15,25,'crampon1923','Yahweh renverse la maison des orgueilleux, mais il affermit les bornes de la veuve.'),
('pr',15,26,'crampon1923','Les pensées mauvaises sont en horreur à Yahweh, mais les paroles bienveillantes sont pures à ses yeux.'),
('pr',15,27,'crampon1923','Celui qui est âpre au gain trouble sa maison, mais celui qui hait les présents vivra.'),
('pr',15,28,'crampon1923','Le cœur du juste médite ce qu''il doit répondre, mais le mal jaillit de la bouche des méchants.'),
('pr',15,29,'crampon1923','Yahweh est loin des méchants, mais il écoute la prière des justes.'),
('pr',15,30,'crampon1923','Un regard bienveillant réjouit le cœur; une bonne nouvelle engraisse les os.'),
('pr',15,31,'crampon1923','L''oreille qui écoute les réprimandes salutaires a sa demeure parmi les sages.'),
('pr',15,32,'crampon1923','Celui qui rejette la correction méprise son âme, mais celui qui écoute la réprimande acquiert la sagesse.'),
('pr',15,33,'crampon1923','La crainte de Yahweh est l''école de la sagesse, et l''humilité précède la gloire.'),
('pr',16,1,'crampon1923','A l''homme de former des projets dans son cœur, mais la réponse de la langue vient de Yahweh.'),
('pr',16,2,'crampon1923','Toutes les voies de l''homme sont pures à ses yeux, mais Yahweh pèse les esprits.'),
('pr',16,3,'crampon1923','Recommande tes œuvres à Yahweh, et tes projets réussiront.'),
('pr',16,4,'crampon1923','Yahweh a tout fait pour son but, et le méchant lui-même pour le jour du malheur.'),
('pr',16,5,'crampon1923','Quiconque a le cœur hautain est en abomination à Yahweh; sûrement, il ne sera pas impuni.'),
('pr',16,6,'crampon1923','Par la bonté et la fidélité on expie l''iniquité, et par la crainte de Yahweh on se détourne du mal.'),
('pr',16,7,'crampon1923','Quand Yahweh a pour agréables les voies d''un homme, il réconcilie avec lui ses ennemis mêmes.'),
('pr',16,8,'crampon1923','Mieux vaut peu avec la justice, que de grands revenus avec l''injustice.'),
('pr',16,9,'crampon1923','Le cœur de l''homme médite sa voie, mais c''est Yahweh qui dirige ses pas.'),
('pr',16,10,'crampon1923','Des oracles sont sur les lèvres du roi; que sa bouche ne pèche pas quand il juge!'),
('pr',16,11,'crampon1923','La balance et les plateaux justes sont de Yahweh, tous les poids du sac sont son ouvrage.'),
('pr',16,12,'crampon1923','C''est une abomination pour les rois de faire le mal, car c''est par la justice que le trône s''affermit.'),
('pr',16,13,'crampon1923','Les lèvres justes jouissent de la faveur des rois, et ils aiment celui qui parle avec droiture.'),
('pr',16,14,'crampon1923','La fureur du roi est un messager de mort, mais un homme sage l''apaise.'),
('pr',16,15,'crampon1923','La sérénité du visage du roi donne la vie, et sa faveur est comme la pluie du printemps.'),
('pr',16,16,'crampon1923','Acquérir la sagesse vaut bien mieux que l''or; acquérir l''intelligence est bien préférable à l''argent.'),
('pr',16,17,'crampon1923','Le grand chemin des hommes droits, c''est d''éviter le mal; celui-là garde son âme qui veille sur sa voie.'),
('pr',16,18,'crampon1923','L''orgueil précède la ruine, et la fierté précède la chute.'),
('pr',16,19,'crampon1923','Mieux vaut être humble avec les petits que de partager le butin avec les orgueilleux.'),
('pr',16,20,'crampon1923','Celui qui est attentif à la parole trouve le bonheur, et celui qui se confie en Yahweh est heureux.'),
('pr',16,21,'crampon1923','Celui qui est sage de cœur est appelé intelligent, et la douceur des lèvres augmente le savoir.'),
('pr',16,22,'crampon1923','La sagesse est une source de vie pour celui qui la possède, et le châtiment de l''insensé, c''est sa folie.'),
('pr',16,23,'crampon1923','Le cœur du sage donne la sagesse à sa bouche, et sur ses lèvres accroît le savoir.'),
('pr',16,24,'crampon1923','Les bonnes paroles sont un rayon de miel, douces à l''âme et salutaires au corps.'),
('pr',16,25,'crampon1923','Telle voie paraît droite à un homme, mais son issue, c''est la voie de la mort.'),
('pr',16,26,'crampon1923','Le travailleur travaille pour lui, car sa bouche l''y excite.'),
('pr',16,27,'crampon1923','L''homme pervers prépare le malheur, et il y a sur ses lèvres comme un feu ardent.'),
('pr',16,28,'crampon1923','L''homme pervers excite des querelles, et le rapporteur divise les amis.'),
('pr',16,29,'crampon1923','L''homme violent séduit son prochain, et le conduit dans une voie qui n''est pas bonne.'),
('pr',16,30,'crampon1923','Celui qui ferme les yeux pour méditer la tromperie, celui qui pince les lèvres, commet déjà le mal.'),
('pr',16,31,'crampon1923','Les cheveux blancs sont une couronne d''honneur; c''est dans le chemin de la justice qu''on la trouve.'),
('pr',16,32,'crampon1923','Celui qui est lent à la colère vaut mieux qu''un héros; et celui qui domine son esprit, que le guerrier qui prend les villes.'),
('pr',16,33,'crampon1923','On jette les sorts dans le pan de la robe, mais de Yahweh vient toute décision.'),
('pr',17,1,'crampon1923','Mieux vaut un morceau de pain sec avec la paix, qu''une maison pleine de viande avec la discorde.'),
('pr',17,2,'crampon1923','Un serviteur prudent l''emporte sur le fils qui fait honte, et il partagera l''héritage avec les frères.'),
('pr',17,3,'crampon1923','Le creuset éprouve l''argent et le fourneau l''or; celui qui éprouve les cœurs, c''est le Seigneur.'),
('pr',17,4,'crampon1923','Le méchant écoute la lèvre inique, le menteur prête l''oreille à la mauvaise langue.'),
('pr',17,5,'crampon1923','Celui qui se moque du pauvre outrage celui qui l''a fait; celui qui se réjouit d''un malheur ne restera pas impuni.'),
('pr',17,6,'crampon1923','Les enfants des enfants sont la couronne des vieillards, et les pères sont la gloire de leurs enfants.'),
('pr',17,7,'crampon1923','Des paroles distinguées ne conviennent pas à l''insensé; mais bien moins à un noble les paroles mensongères!'),
('pr',17,8,'crampon1923','Un présent est une pierre précieuse aux yeux de qui le possède; partout où il se tourne, il a du succès.'),
('pr',17,9,'crampon1923','Celui qui couvre une faute cherche l''amitié, et celui qui la rappelle en ses paroles divise les amis.'),
('pr',17,10,'crampon1923','Un blâme fait plus d''impression sur l''homme intelligent que cent coups sur l''insensé.'),
('pr',17,11,'crampon1923','Le méchant ne cherche que rébellion, mais un messager cruel sera envoyé contre lui.'),
('pr',17,12,'crampon1923','Mieux vaut rencontrer une ourse privée de ses petits qu''un insensé pendant sa folie.'),
('pr',17,13,'crampon1923','Celui qui rend le mal pour le bien ne verra jamais le malheur quitter sa maison.'),
('pr',17,14,'crampon1923','C''est ouvrir une digue que de commencer une querelle; avant que la dispute s''allume, retire-toi.'),
('pr',17,15,'crampon1923','Celui qui absout le coupable et celui qui condamne le juste sont tous deux en abomination à Yahweh.'),
('pr',17,16,'crampon1923','A quoi sert l''argent dans la main de l''insensé? A acheter la sagesse? Il n''a pas le sens pour le faire.'),
('pr',17,17,'crampon1923','L''ami aime en tout temps; dans le malheur il devient un frère.'),
('pr',17,18,'crampon1923','L''homme sans intelligence prend des engagements, il se fait caution pour son prochain.'),
('pr',17,19,'crampon1923','Celui qui aime les querelles aime le péché; celui qui élève sa parole aime sa ruine.'),
('pr',17,20,'crampon1923','Qui a un cœur faux ne trouve pas le bonheur, et qui a une langue perverse tombe dans le malheur.'),
('pr',17,21,'crampon1923','Celui qui donne naissance à un insensé en aura du chagrin; le père d''un fou ne sera pas joyeux.'),
('pr',17,22,'crampon1923','Un cœur joyeux est un excellent remède; un esprit abattu dessèche les os.'),
('pr',17,23,'crampon1923','Le méchant reçoit des présents cachés dans le pli du manteau, pour pervertir les sentiers de la justice.'),
('pr',17,24,'crampon1923','L''homme intelligent a devant lui la sagesse, mais les yeux de l''insensé sont à l''extrémité de la terre.'),
('pr',17,25,'crampon1923','Un fils insensé fait le chagrin de son père, et l''amertume de sa mère.'),
('pr',17,26,'crampon1923','Il n''est pas bon de frapper le juste d''amende, ni de condamner les nobles à cause de leur droiture.'),
('pr',17,27,'crampon1923','Celui qui contient ses paroles possède la science, et celui qui est calme d''esprit est un homme d''intelligence.'),
('pr',17,28,'crampon1923','L''insensé lui-même, quand il se tait, passe pour un sage, pour intelligent, quand il ferme ses lèvres.'),
('pr',18,1,'crampon1923','Celui qui se tient à l''écart ne cherche qu''à contenter sa passion, il s''irrite contre tout sage conseil.'),
('pr',18,2,'crampon1923','Ce n''est pas l''intelligence qui plaît à l''insensé, c''est la manifestation de ses pensées.'),
('pr',18,3,'crampon1923','Quand vient le méchant, vient aussi le mépris, et avec la honte vient l''opprobre.'),
('pr',18,4,'crampon1923','Les paroles de la bouche de l''homme sont des eaux profondes; la source de la sagesse est un torrent qui déborde.'),
('pr',18,5,'crampon1923','Il n''est pas bon d''avoir égard à la personne du méchant, pour faire tort au juste dans le jugement.'),
('pr',18,6,'crampon1923','Les lèvres de l''insensé se mêlent aux querelles et sa bouche provoque les outrages.'),
('pr',18,7,'crampon1923','La bouche de l''insensé cause sa ruine, et ses lèvres sont un piège pour son âme.'),
('pr',18,8,'crampon1923','Les paroles du rapporteur sont des morceaux friands, elles descendent jusqu''au fond des entrailles.'),
('pr',18,9,'crampon1923','Celui qui est lâche dans son travail est frère de celui qui va à la perdition.'),
('pr',18,10,'crampon1923','Le nom de Yahweh est une tour forte; le juste s''y réfugie et y est en sûreté.'),
('pr',18,11,'crampon1923','La fortune du riche est sa ville forte; dans sa pensée, c''est une muraille élevée.'),
('pr',18,12,'crampon1923','Avant la ruine, le cœur de l''homme s''élève, mais l''humilité précède la gloire.'),
('pr',18,13,'crampon1923','Celui qui répond avant d''avoir écouté, c''est pour lui folie et confusion.'),
('pr',18,14,'crampon1923','L''esprit de l''homme le soutient dans la maladie mais l''esprit abattu, qui le relèvera?'),
('pr',18,15,'crampon1923','Un cœur intelligent acquiert la science, et l''oreille des sages cherche la science.'),
('pr',18,16,'crampon1923','Le présent d''un homme lui élargit la voie, et l''introduit auprès des grands.'),
('pr',18,17,'crampon1923','Le premier qui expose sa cause paraît juste; vient la partie adverse, et on examine le différend.'),
('pr',18,18,'crampon1923','Le sort fait cesser les contestations, et décide entre les puissants.'),
('pr',18,19,'crampon1923','Un frère ennemi de son frère résiste plus qu''une ville forte, et leurs querelles sont comme les verrous d''un palais.'),
('pr',18,20,'crampon1923','C''est du fruit de la bouche de l''homme que se nourrit son corps, du produit de ses lèvres qu''il se rassasie.'),
('pr',18,21,'crampon1923','La mort et la vie sont au pouvoir de la langue; suivant son choix, on mangera ses fruits.'),
('pr',18,22,'crampon1923','Celui qui trouve une femme trouve le bonheur; c''est une faveur qu''il a reçue de Yahweh.'),
('pr',18,23,'crampon1923','Le pauvre parle en suppliant, et le riche répond durement.'),
('pr',18,24,'crampon1923','L''homme aux nombreux amis les a pour sa perte, mais il tel ami plus attaché qu''un frère.'),
('pr',19,1,'crampon1923','Mieux vaut le pauvre qui marche dans son intégrité, que l''homme aux lèvres dédaigneuses et qui est insensé.'),
('pr',19,2,'crampon1923','L''ignorance de l''âme n''est pas bonne, et celui dont les pieds se hâtent tombe.'),
('pr',19,3,'crampon1923','La folie de l''homme pervertit sa voie, et c''est contre Yahweh que son cœur s''irrite.'),
('pr',19,4,'crampon1923','La richesse procure un grand nombre d''amis, mais le pauvre se voit séparé de son ami.'),
('pr',19,5,'crampon1923','Le faux témoin ne restera pas impuni, et celui qui dit des mensonges n''échappera pas.'),
('pr',19,6,'crampon1923','Nombreux sont les flatteurs de l''homme généreux, et tous sont les amis de celui qui fait des présents.'),
('pr',19,7,'crampon1923','Tous les frères du pauvre le haïssent; combien plus ses amis s''éloignent-ils de lui! Il cherche des paroles bienveillantes, et il n''en trouve pas.'),
('pr',19,8,'crampon1923','Celui qui acquiert de l''intelligence aime son âme; et celui qui observe la prudence obtiendra le bonheur.'),
('pr',19,9,'crampon1923','Le faux témoin ne restera pas impuni, et celui qui dit des mensonges périra.'),
('pr',19,10,'crampon1923','Il ne sied pas à l''insensé de vivre dans les délices; moins encore à l''esclave de dominer sur les princes!'),
('pr',19,11,'crampon1923','La sagesse d''un homme le rend patient, et il se fait une gloire d''oublier les offenses.'),
('pr',19,12,'crampon1923','La colère du roi est comme le rugissement d''un lion, et sa faveur est comme la rosée sur l''herbe.'),
('pr',19,13,'crampon1923','Un fils insensé est le malheur de son père, et les querelles d''une femme une gouttière sans fin.'),
('pr',19,14,'crampon1923','Une maison et des richesses sont un héritage paternel; mais une femme intelligente est un don de Yahweh.'),
('pr',19,15,'crampon1923','La paresse fait tomber dans l''assoupissement, et l''âme nonchalante éprouvera la faim.'),
('pr',19,16,'crampon1923','Celui qui garde le commandement garde son âme; celui qui n''est pas attentif à sa voie mourra.'),
('pr',19,17,'crampon1923','Celui qui a pitié du pauvre prête à Yahweh, qui récompensera sa bonne œuvre.'),
('pr',19,18,'crampon1923','Châtie ton fils, car il y a encore de l''espérance; mais ne va pas jusqu''à le faire mourir.'),
('pr',19,19,'crampon1923','L''homme à la colère violente en subira la peine; si tu le sauves une fois, il te faudra recommencer.'),
('pr',19,20,'crampon1923','Écoute les conseils et reçois l''instruction, afin que tu sois sage dans la suite de ta vie.'),
('pr',19,21,'crampon1923','Beaucoup de projets s''agitent dans le cœur de l''homme, mais c''est le dessein de Yahweh qui s''accomplit.'),
('pr',19,22,'crampon1923','Ce qui recommande un homme, c''est sa bonté, et mieux vaut un pauvre qu''un menteur.'),
('pr',19,23,'crampon1923','La crainte de Yahweh mène à la vie, et l''on reste rassasié, sans être visité par le malheur.'),
('pr',19,24,'crampon1923','Le paresseux plonge sa main dans le plat, et ne la ramène pas à sa bouche.'),
('pr',19,25,'crampon1923','Frappe le moqueur, et l''homme simple deviendra sage; reprends l''homme intelligent, et il comprendra la science.'),
('pr',19,26,'crampon1923','Celui qui maltraite son père et qui fait fuir sa mère est un fils qui se couvre de honte et d''opprobre.'),
('pr',19,27,'crampon1923','Cesse, mon fils, d''écouter l''instruction, et tu t''éloigneras des paroles de la science.'),
('pr',19,28,'crampon1923','Un témoin pervers se moque de la justice, et la bouche des méchants avale l''iniquité.'),
('pr',19,29,'crampon1923','Les jugements sont prêts pour les railleurs, et les coups pour le dos des insensés.'),
('pr',20,1,'crampon1923','Le vin est moqueur, les boissons fermentées tumultueuses; quiconque s''y adonne n''est pas sage.'),
('pr',20,2,'crampon1923','Semblable au rugissement du lion est la terreur qu''inspire le roi; celui qui l''irrite pèche contre lui-même.'),
('pr',20,3,'crampon1923','C''est une gloire pour l''homme de s''abstenir des querelles, mais tout insensé s''abandonne à la colère.'),
('pr',20,4,'crampon1923','A cause du mauvais temps, le paresseux ne laboure pas; à la moisson, il cherchera, et il n''y aura rien.'),
('pr',20,5,'crampon1923','La pensée dans le cœur de l''homme est une eau profonde, mais l''homme intelligent y puisera.'),
('pr',20,6,'crampon1923','Beaucoup d''hommes vantent leur bonté; mais un homme fidèle, qui le trouvera?'),
('pr',20,7,'crampon1923','Le juste marche dans son intégrité; heureux ses enfants après lui!'),
('pr',20,8,'crampon1923','Le roi, assis sur le trône de la justice, dissipe tout mal par son regard.'),
('pr',20,9,'crampon1923','Qui dira: « J''ai purifié mon cœur, je suis net de mon péché? »'),
('pr',20,10,'crampon1923','Poids et poids, épha et épha, sont l''un et l''autre en horreur à Yahweh.'),
('pr',20,11,'crampon1923','L''enfant montre déjà par ses actions si ses œuvres seront pures et droites.'),
('pr',20,12,'crampon1923','L''oreille qui entend et l''œil qui voit, c''est Yahweh qui les a faits l''un et l''autre.'),
('pr',20,13,'crampon1923','N''aime pas le sommeil, pour ne pas devenir pauvre; ouvre les yeux, et rassasie-toi de pain.'),
('pr',20,14,'crampon1923','Mauvais! Mauvais! dit l''acheteur, et, en s''en allant, il se félicite.'),
('pr',20,15,'crampon1923','Il y a de l''or et beaucoup de perles, mais les lèvres sages sont un vase précieux.'),
('pr',20,16,'crampon1923','Prends son vêtement, car il a répondu pour autrui; exige de lui des gages à cause des étrangers.'),
('pr',20,17,'crampon1923','Le pain de fourberie est doux à l''homme, mais à la fin sa bouche est remplie de gravier.'),
('pr',20,18,'crampon1923','Les projets s''affermissent par le conseil; conduis la guerre avec prudence.'),
('pr',20,19,'crampon1923','Celui qui s''en va médisant dévoile les secrets; évite avec soin celui qui a les lèvres toujours ouvertes.'),
('pr',20,20,'crampon1923','Si quelqu''un maudit son père et sa mère, sa lampe s''éteindra au sein des ténèbres.'),
('pr',20,21,'crampon1923','Un héritage hâté à l''origine ne sera pas béni à la fin.'),
('pr',20,22,'crampon1923','Ne dis pas: « Je rendrai le mal; » espère en Yahweh, et il te délivrera.'),
('pr',20,23,'crampon1923','Poids et poids sont en horreur à Yahweh, et la balance fausse n''est pas une chose bonne.'),
('pr',20,24,'crampon1923','C''est Yahweh qui dirige les pas de l''homme; et l''homme peut-il comprendre sa voie?'),
('pr',20,25,'crampon1923','C''est un piège pour l''homme de dire à la légère: « Cela est sacré! » et de ne réfléchir qu''après le vœu fait.'),
('pr',20,26,'crampon1923','Un roi sage dissipe les méchants, et fait passer sur eux la roue.'),
('pr',20,27,'crampon1923','L''âme de l''homme est une lampe de Yahweh; elle pénètre jusqu''au fond des entrailles.'),
('pr',20,28,'crampon1923','La bonté et la fidélité gardent le roi, et il affermit son trône par la bonté.'),
('pr',20,29,'crampon1923','La force est la parure des jeunes gens, et les cheveux blancs sont l''ornement des vieillards.'),
('pr',20,30,'crampon1923','La meurtrissure qui déchire la chair guérit le mal; de même les coups qui atteignent au fond des entrailles.'),
('pr',21,1,'crampon1923','Le cœur du roi est un cours d''eau dans la main de Yahweh, il l''incline partout où il veut.'),
('pr',21,2,'crampon1923','Toutes les voies de l''homme sont droites à ses yeux; mais celui qui pèse les cœurs, c''est Yahweh.'),
('pr',21,3,'crampon1923','Pratiquer la justice et l''équité, est aux yeux de Yahweh préférable aux sacrifices.'),
('pr',21,4,'crampon1923','Des regards hautains et un cœur superbe: flambeau des méchants, ce n''est que péché.'),
('pr',21,5,'crampon1923','Les projets de l''homme diligent ne vont qu''à l''abondance; mais quiconque précipite ses démarches n''arrive qu''à la disette.'),
('pr',21,6,'crampon1923','Des trésors acquis par une langue mensongère: vanité fugitive d''hommes qui courent à la mort.'),
('pr',21,7,'crampon1923','La violence des méchants les égare, parce qu''ils n''ont pas voulu pratiquer la justice.'),
('pr',21,8,'crampon1923','La voie du criminel est tortueuse, mais l''innocent agit avec droiture.'),
('pr',21,9,'crampon1923','Mieux vaut habiter à l''angle d''un toit, que de rester avec une femme querelleuse.'),
('pr',21,10,'crampon1923','L''âme du méchant désire le mal; son ami ne trouve pas grâce à ses yeux.'),
('pr',21,11,'crampon1923','Quand on châtie le méchant, le simple devient sage, et quand on instruit le sage, il devient plus sage.'),
('pr',21,12,'crampon1923','Le juste considère la maison du méchant; Dieu précipite les méchants dans le malheur.'),
('pr',21,13,'crampon1923','Celui qui ferme l''oreille au cri du pauvre criera lui-même sans qu''on lui réponde.'),
('pr',21,14,'crampon1923','Un don fait en secret apaise la colère, un présent tiré du pli du manteau calme la fureur violente.'),
('pr',21,15,'crampon1923','C''est une joie pour le juste de pratiquer la justice, mais l''épouvante est pour ceux qui font le mal.'),
('pr',21,16,'crampon1923','L''homme qui s''écarte du sentier de la prudence reposera dans l''assemblée des morts.'),
('pr',21,17,'crampon1923','Celui qui aime la joie sera indigent; celui qui aime le vin et l''huile parfumée ne s''enrichit pas.'),
('pr',21,18,'crampon1923','Le méchant sert de rançon pour le juste, et le perfide pour les hommes droits.'),
('pr',21,19,'crampon1923','Mieux vaut habiter dans une terre déserte qu''avec une femme querelleuse et colère.'),
('pr',21,20,'crampon1923','De précieux trésors, de l''huile sont dans la maison du sage; mais un homme insensé les engloutit.'),
('pr',21,21,'crampon1923','Celui qui poursuit la justice et la miséricorde trouvera la vie, la justice et la gloire.'),
('pr',21,22,'crampon1923','Le sage prend d''assaut une ville de héros, et il renverse le rempart où elle mettait sa confiance.'),
('pr',21,23,'crampon1923','Celui qui garde sa bouche et sa langue garde son âme des angoisses.'),
('pr',21,24,'crampon1923','On appelle moqueur l''homme hautain, enflé d''orgueil, qui agit avec un excès d''arrogance.'),
('pr',21,25,'crampon1923','Les désirs du paresseux le tuent, parce que ses mains refusent de travailler.'),
('pr',21,26,'crampon1923','Tout le jour il désire avec ardeur, mais le juste donne sans relâche.'),
('pr',21,27,'crampon1923','Le sacrifice des méchants est abominable, surtout quand ils l''offrent avec des pensées criminelles!'),
('pr',21,28,'crampon1923','Le témoin menteur périra, mais l''homme qui écoute pourra parler toujours.'),
('pr',21,29,'crampon1923','Le méchant prend un air effronté, mais l''homme droit dirige sa voie.'),
('pr',21,30,'crampon1923','Il n''y a ni sagesse, ni prudence, ni conseil en face de Yahweh.'),
('pr',21,31,'crampon1923','On équipe le cheval pour le jour du combat, mais de Yahweh dépend la victoire.'),
('pr',22,1,'crampon1923','La bonne renommée vaut mieux que de grandes richesses, et l''estime a plus de prix que l''argent et que l''or.'),
('pr',22,2,'crampon1923','Le riche et le pauvre se rencontrent; Yahweh est leur auteur à tous deux.'),
('pr',22,3,'crampon1923','L''homme prudent voit le mal et se cache, mais les simples passent outre et en portent la peine.'),
('pr',22,4,'crampon1923','Le fruit de l''humilité, c''est la crainte de Yahweh; c''est la richesse, la gloire et la vie.'),
('pr',22,5,'crampon1923','Des épines et des pièges sont sur la voie du pervers; celui qui garde son âme s''en éloigne.'),
('pr',22,6,'crampon1923','Instruis l''enfant selon la voie qu''il doit suivre; et, même lorsqu''il sera vieux, il ne s''en détournera pas.'),
('pr',22,7,'crampon1923','Le riche domine sur les pauvres, et celui qui emprunte est l''esclave de celui qui prête.'),
('pr',22,8,'crampon1923','Celui qui sème l''injustice moissonne le malheur, et la verge de sa colère disparaît.'),
('pr',22,9,'crampon1923','L''homme au regard bienveillant sera béni, parce qu''il donne de son pain au pauvre.'),
('pr',22,10,'crampon1923','Chasse le moqueur, et la querelle prendra fin; la dispute et l''outrage cesseront.'),
('pr',22,11,'crampon1923','Celui qui aime la pureté du cœur, et qui a la grâce sur les lèvres, a le roi pour ami.'),
('pr',22,12,'crampon1923','Les yeux de Yahweh gardent la science, mais il confond les paroles du pervers.'),
('pr',22,13,'crampon1923','Le paresseux dit: « Il y a un lion dehors! Je serai tué au milieu des places! »'),
('pr',22,14,'crampon1923','La bouche des étrangères est une fosse profonde; celui contre qui Yahweh est irrité y tombera.'),
('pr',22,15,'crampon1923','La folie est attachée au cœur de l''enfant; la verge de la discipline l''éloignera de lui.'),
('pr',22,16,'crampon1923','Opprimer un pauvre, c''est l''enrichir; donner à un riche, c''est l''appauvrir. PAROLES DES SAGES — 1-INTRODUCTION —'),
('pr',22,17,'crampon1923','Prête l''oreille et écoute les paroles des sages, applique ton cœur à mon enseignement.'),
('pr',22,18,'crampon1923','Car c''est une chose agréable, si tu les gardes au dedans de toi: puissent-elles toutes demeurer sur tes lèvres!'),
('pr',22,19,'crampon1923','Afin que ta confiance repose sur Yahweh, c''est toi que je veux instruire aujourd''hui.'),
('pr',22,20,'crampon1923','N''ai-je pas, plusieurs fois déjà, mis pour toi par écrit des conseils et des enseignements?'),
('pr',22,21,'crampon1923','Pour t''enseigner la vérité des choses certaines, afin que tu répondes par des paroles vraies à eux qui t''envoient.'),
('pr',22,22,'crampon1923','Ne dépouille pas le pauvre parce qu''il est pauvre, et n''opprime pas le malheureux à la porte.'),
('pr',22,23,'crampon1923','Car Yahweh prendra en main leur cause, et il ôtera la vie à ceux qui les auront dépouillés.'),
('pr',22,24,'crampon1923','Ne lie pas société avec l''homme colère, et ne va pas avec l''homme violent,'),
('pr',22,25,'crampon1923','de peur que tu n''apprennes ses voies, et que tu ne prépares un piège à ton âme.'),
('pr',22,26,'crampon1923','Ne sois pas de ceux qui prennent des engagements, de ceux qui se portent caution pour dettes.'),
('pr',22,27,'crampon1923','Si tu n''as pas de quoi payer, pourquoi t''exposer à ce qu''on enlève ton lit de dessous toi?'),
('pr',22,28,'crampon1923','Ne déplace pas la borne ancienne, que tes pères ont posée.'),
('pr',22,29,'crampon1923','Vois-tu un homme habile dans son ouvrage? Il demeurera auprès des rois, il ne demeurera pas auprès des gens obscurs.'),
('pr',23,1,'crampon1923','Si tu es à table avec un grand, fais attention à ce qui est devant toi.'),
('pr',23,2,'crampon1923','Mets un couteau à ta gorge, si tu as trop d''avidité.'),
('pr',23,3,'crampon1923','Ne convoite pas ses mets délicats, c''est un aliment trompeur.'),
('pr',23,4,'crampon1923','Ne te tourmente pas pour devenir riche, abstiens-toi d''y appliquer ton intelligence.'),
('pr',23,5,'crampon1923','Veux-tu poursuivre du regard ce qui va s''évanouir? Car la richesse se fait des ailes, et, comme l''aigle, elle s''envole vers les cieux.'),
('pr',23,6,'crampon1923','Ne mange pas le pain de l''homme envieux, et ne convoite pas ses mets délicats;'),
('pr',23,7,'crampon1923','car il ne vaut pas plus que les pensées de son âme. « Mange et bois, » te dira-t-il; mais son cœur n''est pas avec toi.'),
('pr',23,8,'crampon1923','Tu vomiras le morceau que tu as mangé, et tu en seras pour tes belles paroles.'),
('pr',23,9,'crampon1923','Ne parle pas aux oreilles de l''insensé, car il méprisera la sagesse de tes discours.'),
('pr',23,10,'crampon1923','Ne déplace pas la borne antique, et n''entre pas dans le champ des orphelins.'),
('pr',23,11,'crampon1923','Car leur vengeur est puissant: il défendra leur cause contre toi.'),
('pr',23,12,'crampon1923','Applique ton cœur à l''instruction, et tes oreilles aux paroles de la science.'),
('pr',23,13,'crampon1923','N''épargne pas la correction à l''enfant; si tu le frappes de la verge, il ne mourra point.'),
('pr',23,14,'crampon1923','Tu le frappes de la verge, et tu délivres son âme du schéol.'),
('pr',23,15,'crampon1923','Mon fils, si ton cœur est sage, mon cœur, à moi aussi, sera dans la joie.'),
('pr',23,16,'crampon1923','Mes entrailles tressailliront d''allégresse, quand tes lèvres diront ce qui est droit.'),
('pr',23,17,'crampon1923','Que ton cœur n''envie pas les pécheurs, mais qu''il reste toujours dans la crainte de Yahweh;'),
('pr',23,18,'crampon1923','car il y a un avenir, et ton espérance ne sera pas anéantie.'),
('pr',23,19,'crampon1923','Ecoute, mon fils, et sois sage; dirige ton cœur dans la voie droite.'),
('pr',23,20,'crampon1923','Ne sois pas parmi les buveurs de vin, parmi ceux qui se gorgent de viandes;'),
('pr',23,21,'crampon1923','car le buveur et le gourmand s''appauvrissent, et la somnolence fait porter des haillons.'),
('pr',23,22,'crampon1923','Ecoute ton père, lui qui t''a engendré, et ne méprise pas ta mère, quand elle est devenue vieille.'),
('pr',23,23,'crampon1923','Acquiers la vérité, et ne la vend pas, la sagesse, l''instruction et l''intelligence.'),
('pr',23,24,'crampon1923','Le père du juste est dans l''allégresse, celui qui donne le jour à un sage en aura de la joie.'),
('pr',23,25,'crampon1923','Que ton père et ta mère se réjouissent! Que celle qui t''a enfanté soit dans l''allégresse!'),
('pr',23,26,'crampon1923','Mon fils, donne-moi ton cœur, et que tes yeux gardent mes voies:'),
('pr',23,27,'crampon1923','car la courtisane est une fosse profonde, et l''étrangère un puits étroit.'),
('pr',23,28,'crampon1923','Elle dresse des embûches comme pour une proie et elle augmente parmi les hommes le nombre des prévaricateurs.'),
('pr',23,29,'crampon1923','Pour qui les ah? Pour qui les hélas? Pour qui les disputes? Pour qui les murmures? Pour qui les blessures sans raison? Pour qui les yeux rouges?...'),
('pr',23,30,'crampon1923','Pour ceux qui s''attardent auprès du vin, pour ceux qui vont goûter du vin aromatisé.'),
('pr',23,31,'crampon1923','Ne regarde pas le vin: comme il est vermeil; comme il donne son éclat dans la coupe, comme il coule aisément.'),
('pr',23,32,'crampon1923','Il finit par mordre comme un serpent, et par piquer comme un basilic.'),
('pr',23,33,'crampon1923','Tes yeux se porteront sur des étrangères, et ton cœur tiendra des discours pervers.'),
('pr',23,34,'crampon1923','Tu seras comme un homme couché au milieu de la mer, comme un homme endormi au sommet d''un mât.'),
('pr',23,35,'crampon1923','« On m''a frappé... Je n''ai point de mal! On m''a battu... Je ne sens rien!... Quand me réveillerai-je?... Il m''en faut encore! »'),
('pr',24,1,'crampon1923','Ne porte pas envie aux hommes méchants, et ne désire pas d''être avec eux.'),
('pr',24,2,'crampon1923','Car leur cœur médite la violence, et leurs lèvres ne profèrent que le malheur.'),
('pr',24,3,'crampon1923','C''est par la sagesse qu''une maison s''élève, et par l''intelligence qu''elle s''affermit.'),
('pr',24,4,'crampon1923','C''est par la science que l''intérieur se remplit, de tous les biens précieux et agréables.'),
('pr',24,5,'crampon1923','Un homme sage est plein de force, et celui qui a de la science montre une grande puissance.'),
('pr',24,6,'crampon1923','Car avec la prudence tu conduiras la guerre, et le salut est dans le grand nombre des conseillers.'),
('pr',24,7,'crampon1923','La sagesse est trop haute pour l''insensé; il n''ouvre pas la bouche à la porte de la ville.'),
('pr',24,8,'crampon1923','Celui qui pense à faire le mal s''appelle un artisan d''intrigues.'),
('pr',24,9,'crampon1923','Le dessein de l''insensé, c''est le péché, et le railleur est en abomination parmi les hommes.'),
('pr',24,10,'crampon1923','Si tu te montres faible au jour de la détresse, ta force n''est que faiblesse.'),
('pr',24,11,'crampon1923','Délivre ceux qu''on traîne à la mort; ceux qui vont en chancelant au massacre, sauve-les!'),
('pr',24,12,'crampon1923','Si tu dis: « Mais! Nous ne le savions pas! » Celui qui pèse les cœurs ne le voit-il pas? Celui qui veille sur ton âme ne le connaît-il pas, et ne rendra-t-il pas à chacun selon ses œuvres?'),
('pr',24,13,'crampon1923','Mon fils, mange du miel, car il est bon; un rayon de miel est doux à ton palais.'),
('pr',24,14,'crampon1923','Sache que la sagesse est la même chose pour ton âme; si tu l''acquiers, il est un avenir, et ton espérance ne sera pas frustrée.'),
('pr',24,15,'crampon1923','Ne tends pas, ô méchant, des embûches à la demeure du juste, et ne dévaste pas le lieu où il repose;'),
('pr',24,16,'crampon1923','car sept fois le juste tombe, et il se relève, mais les méchants sont précipités dans le malheur.'),
('pr',24,17,'crampon1923','Si ton ennemi tombe, ne te réjouis pas, et que ton cœur ne se réjouisse pas de sa ruine,'),
('pr',24,18,'crampon1923','de peur que Yahweh ne le voie, que cela soit mauvais à ses yeux, et qu''il ne détourne de lui sa colère.'),
('pr',24,19,'crampon1923','Ne t''irrite pas à cause des méchants, ne porte pas envie aux pervers,'),
('pr',24,20,'crampon1923','car il n''y a point d''avenir pour celui qui fait le mal, et la lampe des méchants s''éteindra.'),
('pr',24,21,'crampon1923','Mon fils, crains Yahweh et le roi; ne te mêle pas avec les hommes remuants;'),
('pr',24,22,'crampon1923','car soudain surgira leur malheur, et qui connaît la ruine des uns et des autres? AUTRES PAROLES DES SAGES.'),
('pr',24,23,'crampon1923','Ce qui suit vient encore des sages: Il n''est pas bon, dans les jugements, d''avoir égard aux personnes.'),
('pr',24,24,'crampon1923','Celui qui dit aux méchants: « Tu es juste », les peuples le maudissent, les nations l''exècrent.'),
('pr',24,25,'crampon1923','Mais ceux qui le corrigent sont applaudis, sur eux viennent la bénédiction et le bonheur.'),
('pr',24,26,'crampon1923','Il baise sur les lèvres celui qui répond des paroles justes.'),
('pr',24,27,'crampon1923','Règle ton travail au dehors, applique-le à ton champ, puis tu bâtiras ta maison.'),
('pr',24,28,'crampon1923','Ne témoigne pas à la légère contre ton prochain: voudrais-tu tromper par tes lèvres?'),
('pr',24,29,'crampon1923','Ne dis pas: « Comme il m''a fait, je lui ferai; je rendrai à cet homme selon ses œuvres. »'),
('pr',24,30,'crampon1923','J''ai passé près du champ d''un paresseux, et près de la vigne d''un insensé.'),
('pr',24,31,'crampon1923','Et voici,... les épines y croissaient partout, les ronces en couvraient la surface, et le mur de pierres était écroulé.'),
('pr',24,32,'crampon1923','J''ai regardé, et j''ai appliqué mon cœur, j''ai considéré et j''ai tiré cette leçon:'),
('pr',24,33,'crampon1923','« Un peu de sommeil, un peu d''assoupissement, un peu croiser les mains pour dormir,'),
('pr',24,34,'crampon1923','et ta pauvreté viendra comme un rôdeur, et ton indigence comme un homme armé. » PROVERBES DE SALOMON RECUEILLIS PAR LES GENS D''ÉZÉCHIAS.'),
('pr',25,1,'crampon1923','Voici encore des Proverbes de Salomon, recueillis par les gens d''Ézéchias, roi de Juda.'),
('pr',25,2,'crampon1923','La gloire de Dieu, c''est de cacher les choses; la gloire des rois, c''est de les examiner.'),
('pr',25,3,'crampon1923','Le ciel dans sa hauteur, la terre dans sa profondeur, et le cœur des rois sont impénétrables.'),
('pr',25,4,'crampon1923','Ote les scories de l''argent, et il en sortira un vase pour le fondeur.'),
('pr',25,5,'crampon1923','Ote le méchant de devant le roi, et son trône s''affermira dans la justice.'),
('pr',25,6,'crampon1923','Ne prends pas des airs superbes devant le roi, et ne te mets pas à la place des grands;'),
('pr',25,7,'crampon1923','car il vaut mieux qu''on te dise: « Monte ici », que si l''on t''humilie devant le prince que tes yeux ont vu.'),
('pr',25,8,'crampon1923','Ne pars pas trop vite en contestation, de peur qu''à la fin tu ne saches que faire.'),
('pr',25,9,'crampon1923','Lorsque ton prochain t''aura outragé, défends ta cause contre ton prochain, mais ne révèle pas le secret d''un autre,'),
('pr',25,10,'crampon1923','de peur que celui qui l''apprendra ne te couvre de honte, et que ton ignominie ne s''efface pas.'),
('pr',25,11,'crampon1923','Comme des pommes d''or sur des ciselures d''argent, ainsi est une parole dite à propos.'),
('pr',25,12,'crampon1923','Comme un anneau d''or et un ornement d''or fin, ainsi est le sage qui reprend une oreille docile.'),
('pr',25,13,'crampon1923','Comme la fraîcheur de la neige au temps de la moisson, ainsi est le messager fidèle pour ceux qui l''envoient; il réjouit l''âme de son maître.'),
('pr',25,14,'crampon1923','Des nuages et du vent sans pluie, tel est l''homme qui se glorifie de présents mensongers.'),
('pr',25,15,'crampon1923','Par la patience le juge se laisse persuader, et une langue douce peut briser des os.'),
('pr',25,16,'crampon1923','Si tu trouves du miel, n''en mange que ce qui te suffit, de peur que, rassasié, tu ne le vomisses.'),
('pr',25,17,'crampon1923','Mets rarement le pied dans la maison de ton prochain, de peur que, fatigué de toi, il ne te haïsse.'),
('pr',25,18,'crampon1923','Une massue, une épée et une flèche aiguë, tel est l''homme qui porte un faux témoignage contre son prochain.'),
('pr',25,19,'crampon1923','Une dent cassée et un pied qui glisse, c''est la confiance qu''inspire un perfide au jour du malheur.'),
('pr',25,20,'crampon1923','Oter son manteau un jour de froid, répandre du vinaigre sur du nitre, ainsi fait celui qui dit des chansons à un cœur affligé.'),
('pr',25,21,'crampon1923','Si ton ennemi a faim, donne-lui du pain à manger; s''il a soif, donne-lui de l''eau à boire;'),
('pr',25,22,'crampon1923','car tu amasses ainsi des charbons sur sa tête, et Yahweh te récompensera.'),
('pr',25,23,'crampon1923','Le vent du nord enfante la pluie, et la langue qui médit en secret, un visage irrité.'),
('pr',25,24,'crampon1923','Mieux vaut habiter à l''angle d''un toit, que de rester avec une femme querelleuse.'),
('pr',25,25,'crampon1923','De l''eau fraîche pour une personne altérée, telle est une bonne nouvelle venant d''une terre lointaine.'),
('pr',25,26,'crampon1923','Une fontaine troublée et une source corrompue, tel est le juste qui chancelle devant le méchant.'),
('pr',25,27,'crampon1923','Il n''est pas bon de manger beaucoup de miel; ainsi celui qui veut sonder la majesté divine sera accablé par sa gloire.'),
('pr',25,28,'crampon1923','Une ville forcée qui n''a plus de murailles, tel est l''homme qui ne peut se contenir.'),
('pr',26,1,'crampon1923','Comme la neige en été, et la pluie pendant la moisson, ainsi la gloire ne convient pas à un insensé.'),
('pr',26,2,'crampon1923','Comme le passereau qui s''échappe, comme l''hirondelle qui s''envole, ainsi la malédiction sans cause n''atteint pas.'),
('pr',26,3,'crampon1923','Le fouet est pour le cheval, le mors pour l''âne et la verge pour le dos des insensés.'),
('pr',26,4,'crampon1923','Ne réponds pas à l''insensé selon sa folie, de peur de lui ressembler toi-même.'),
('pr',26,5,'crampon1923','Réponds à l''insensé selon sa folie, de peur qu''il ne se regarde comme sage.'),
('pr',26,6,'crampon1923','Il se coupe les pieds, il boit l''iniquité, celui qui donne des messages à un insensé.'),
('pr',26,7,'crampon1923','Otez les jambes au boiteux, est la sentence de la bouche de l''insensé.'),
('pr',26,8,'crampon1923','C''est attacher une pierre à la fronde, que de rendre gloire à un insensé.'),
('pr',26,9,'crampon1923','Comme une épine qui s''enfonce dans la main d''un homme ivre, ainsi est une sentence dans la bouche des insensés.'),
('pr',26,10,'crampon1923','Comme un archer qui blesse tout le monde, ainsi est celui qui prend à gage les insensés et les passants.'),
('pr',26,11,'crampon1923','Comme un chien qui retourne à son vomissement, ainsi est un insensé qui revient à sa folie.'),
('pr',26,12,'crampon1923','Si tu vois un homme qui est sage à ses yeux, il faut plus espérer d''un insensé que de lui.'),
('pr',26,13,'crampon1923','Le paresseux dit: « Il y a un lion sur la route, il y a un lion dans les rues. »'),
('pr',26,14,'crampon1923','La porte tourne sur ses gonds, ainsi le paresseux sur sa couche.'),
('pr',26,15,'crampon1923','Le paresseux met sa main dans le plat, et il a de la peine à la porter à la bouche.'),
('pr',26,16,'crampon1923','Le paresseux est plus sage à ses yeux que sept conseillers prudents.'),
('pr',26,17,'crampon1923','Comme celui qui saisit un chien par les oreilles, tel est le passant qui s''échauffe dans la querelle d''autrui.'),
('pr',26,18,'crampon1923','Comme un furieux qui lance des traits enflammés, des flèches et la mort,'),
('pr',26,19,'crampon1923','ainsi est un homme qui a trompé son prochain et qui dit: « Est-ce que je ne plaisantais pas. »'),
('pr',26,20,'crampon1923','Faute de bois, le feu s''éteint; éloignez le rapporteur, et la querelle s''apaise.'),
('pr',26,21,'crampon1923','Le charbon donne un brasier et le bois du feu: ainsi l''homme querelleur irrite une discussion.'),
('pr',26,22,'crampon1923','Les paroles du rapporteur sont comme des friandises; elles descendent jusqu''au fond des entrailles.'),
('pr',26,23,'crampon1923','Des scories d''argent appliquées sur un vase de terre, telles sont les lèvres brûlantes avec un cœur mauvais.'),
('pr',26,24,'crampon1923','Celui qui hait se déguise par ses lèvres, mais il met au dedans de lui la perfidie.'),
('pr',26,25,'crampon1923','Quand il adoucit sa voix, ne te fies pas à lui, car il a sept abominations dans son cœur.'),
('pr',26,26,'crampon1923','Il peut bien cacher sa haine sous la dissimulation, mais sa méchanceté se révélera dans l''assemblée.'),
('pr',26,27,'crampon1923','Celui qui creuse une fosse y tombe, et la pierre revient sur celui qui la roule.'),
('pr',26,28,'crampon1923','La langue fausse hait ceux qu''elle blesse, et la bouche flatteuse cause la ruine.'),
('pr',27,1,'crampon1923','Ne te glorifie pas du lendemain, car tu ne sais pas ce qu''enfantera le jour suivant.'),
('pr',27,2,'crampon1923','Qu''un autre te loue, et non ta bouche; un étranger, et non tes lèvres.'),
('pr',27,3,'crampon1923','La pierre est lourde et le sable est pesant: plus que l''un et l''autre pèse la colère de l''insensé.'),
('pr',27,4,'crampon1923','La fureur est cruelle et la colère impétueuse; mais qui pourra tenir devant la jalousie?'),
('pr',27,5,'crampon1923','Mieux vaut une réprimande ouverte qu''une amitié cachée.'),
('pr',27,6,'crampon1923','Les blessures d''un ami sont inspirées par la fidélité, mais les baisers d''un ennemi sont trompeurs.'),
('pr',27,7,'crampon1923','Celui qui est rassasié foule aux pieds le rayon de miel, mais à celui qui a faim tout ce qui est amer paraît doux.'),
('pr',27,8,'crampon1923','Comme l''oiseau qui erre loin de son nid, ainsi l''homme qui erre loin de son lieu.'),
('pr',27,9,'crampon1923','L''huile et les parfums réjouissent le cœur; telle la douceur d''un ami dont le conseil vient du cœur.'),
('pr',27,10,'crampon1923','N''abandonne pas ton ami et l''ami de ton père, et n''entre pas dans la maison de ton frère au jour de ta détresse; mieux vaut un voisin proche qu''un frère éloigné.'),
('pr',27,11,'crampon1923','Mon fils, deviens sage et réjouis mon cœur, afin que je puisse répondre à celui qui m''outrage.'),
('pr',27,12,'crampon1923','L''homme prudent voit le mal et se cache; les simples passent et en portent la peine.'),
('pr',27,13,'crampon1923','Prends son vêtement, car il a répondu pour autrui; demande des gages à cause des étrangers.'),
('pr',27,14,'crampon1923','Bénir son prochain à haute voix et de grand matin est réputé comme une malédiction.'),
('pr',27,15,'crampon1923','Une gouttière continue dans un jour de pluie et une femme querelleuse se ressemblent.'),
('pr',27,16,'crampon1923','Celui qui la retient, retient le vent, et sa main saisit de l''huile.'),
('pr',27,17,'crampon1923','Le fer aiguise le fer; ainsi un homme aiguise un autre homme.'),
('pr',27,18,'crampon1923','Celui qui garde son figuier en mangera les fruits, et celui qui garde son maître sera honoré.'),
('pr',27,19,'crampon1923','Comme dans l''eau le visage répond au visage, ainsi le cœur de l''homme répond à l''homme.'),
('pr',27,20,'crampon1923','Le schéol et l''abîme ne sont jamais rassasiés, de même les yeux de l''homme ne sont jamais rassasiés.'),
('pr',27,21,'crampon1923','Le creuset est pour l''argent, et le fourneau pour l''or; que l''homme éprouve de même la louange qu''il reçoit!'),
('pr',27,22,'crampon1923','Quand tu pilerais l''insensé dans un mortier, comme on broie le grain, avec le pilon, sa folie ne se séparerait pas de lui.'),
('pr',27,23,'crampon1923','Connais bien l''état de tes brebis, applique ton attention à ton troupeau;'),
('pr',27,24,'crampon1923','car la richesse ne dure pas toujours, ni une couronne d''âge en âge.'),
('pr',27,25,'crampon1923','Mais quand l''herbe a paru, que la verdure s''est montrée, que le foin des montagnes est recueilli,'),
('pr',27,26,'crampon1923','tu as des agneaux pour te vêtir, des boucs pour payer un champ;'),
('pr',27,27,'crampon1923','tu as en abondance le lait des chèvres, pour ta nourriture et celle de ta maison, et pour l''entretien de tes servantes.'),
('pr',28,1,'crampon1923','Les méchants fuient sans qu''on les poursuive, mais les justes ont de l''assurance comme un lion.'),
('pr',28,2,'crampon1923','Dans un pays en révolte, les chefs se multiplient; mais avec un homme intelligent et sage l''ordre se prolonge.'),
('pr',28,3,'crampon1923','Un homme pauvre qui opprime les malheureux, c''est une pluie violente qui cause la disette.'),
('pr',28,4,'crampon1923','Ceux qui abandonnent la loi louent le méchant, ceux qui l''observent s''irritent contre lui.'),
('pr',28,5,'crampon1923','Les hommes pervers ne comprennent pas ce qui est juste, mais ceux qui cherchent Yahweh comprennent tout.'),
('pr',28,6,'crampon1923','Mieux vaut le pauvre dans son intégrité que l''homme aux voies tortueuses et qui est riche.'),
('pr',28,7,'crampon1923','Celui qui observe la loi est un fils intelligent, mais celui qui nourrit les débauchés fait honte à son père.'),
('pr',28,8,'crampon1923','Celui qui augmente ses biens par l''intérêt et l''usure les amasse pour celui qui a pitié des pauvres.'),
('pr',28,9,'crampon1923','Si quelqu''un détourne l''oreille pour ne pas écouter la loi, sa prière même est une abomination.'),
('pr',28,10,'crampon1923','Celui qui égare les hommes droits dans la voie mauvaise tombera lui-même dans la fosse qu''il a creusée; mais les hommes intègres posséderont le bonheur.'),
('pr',28,11,'crampon1923','L''homme riche est sage à ses yeux; mais le pauvre intelligent le connaît.'),
('pr',28,12,'crampon1923','Quand les justes triomphent, c''est une grande fête; quand les méchants se lèvent, chacun se cache.'),
('pr',28,13,'crampon1923','Celui qui cache ses fautes ne prospérera point, mais celui qui les avoue et les quitte obtiendra miséricorde.'),
('pr',28,14,'crampon1923','Heureux l''homme qui est continuellement dans la crainte! Mais celui qui endurcit son cœur tombera dans le malheur.'),
('pr',28,15,'crampon1923','Un lion rugissant et un ours affamé, tel est le méchant qui domine sur un peuple pauvre.'),
('pr',28,16,'crampon1923','Le prince sans intelligence multiplie l''oppression, mais celui qui hait la cupidité aura de longs jours.'),
('pr',28,17,'crampon1923','Un homme chargé du sang d''un autre fuit jusqu''à la fosse: ne l''arrêtez pas!'),
('pr',28,18,'crampon1923','Celui qui marche dans l''intégrité trouvera le salut, mais celui qui suit des voies tortueuses tombera pour ne plus se relever.'),
('pr',28,19,'crampon1923','Celui qui cultive son champ sera rassasié de pain, mais celui qui poursuit des choses vaines sera rassasié de pauvreté.'),
('pr',28,20,'crampon1923','Un homme fidèle sera comblé de bénédictions, mais celui qui a hâte de s''enrichir n''échappera pas à la faute.'),
('pr',28,21,'crampon1923','Il n''est pas bon de faire acception des personnes; pour un morceau de pain un homme devient criminel.'),
('pr',28,22,'crampon1923','L''homme envieux a hâte de s''enrichir; il ne sait pas que la disette viendra sur lui.'),
('pr',28,23,'crampon1923','Celui qui reprend quelqu''un trouve ensuite plus de faveur que celui qui rend sa langue flatteuse.'),
('pr',28,24,'crampon1923','Celui qui vole son père et sa mère, et qui dit: « Ce n''est pas un péché, » c''est le compagnon du brigand.'),
('pr',28,25,'crampon1923','L''homme cupide excite les querelles; mais celui qui se confie en Yahweh sera rassasié.'),
('pr',28,26,'crampon1923','Celui qui a confiance dans son propre cœur est un insensé, mais celui qui marche dans la sagesse sera sauvé.'),
('pr',28,27,'crampon1923','Celui qui donne au pauvre n''éprouve pas la disette, mais celui qui ferme les yeux est chargé de malédictions.'),
('pr',28,28,'crampon1923','Quand les méchants s''élèvent, chacun se cache; quand ils périssent, les justes se multiplient.'),
('pr',29,1,'crampon1923','L''homme digne de reproches et qui raidit le cou sera brisé subitement et sans remède.'),
('pr',29,2,'crampon1923','Quand les justes se multiplient, le peuple est dans la joie; quand le méchant exerce le pouvoir, le peuple gémit.'),
('pr',29,3,'crampon1923','L''homme qui aime la sagesse réjouit son père, mais celui qui fréquente les courtisanes dissipe son bien.'),
('pr',29,4,'crampon1923','Un roi affermit le pays par la justice; mais celui qui est avide de présents le ruine.'),
('pr',29,5,'crampon1923','L''homme qui flatte son prochain tend un filet sous ses pieds.'),
('pr',29,6,'crampon1923','Dans le péché de l''homme méchant il y a un piège, mais le juste est dans la jubilation et la joie.'),
('pr',29,7,'crampon1923','Le juste connaît la cause des pauvres, mais le méchant ne comprend pas la science.'),
('pr',29,8,'crampon1923','Les railleurs soufflent le feu dans la ville, mais les sages apaisent la colère.'),
('pr',29,9,'crampon1923','Si un sage conteste avec un insensé, qu''il se fâche ou qu''il rie, il n''y aura pas de paix.'),
('pr',29,10,'crampon1923','Les hommes de sang haïssent l''homme intègre, mais les hommes droits protègent sa vie.'),
('pr',29,11,'crampon1923','L''insensé fait éclater toute sa passion, mais le sage la calme et la retient.'),
('pr',29,12,'crampon1923','Quand le prince écoute les paroles mensongères, tous ses serviteurs sont des méchants.'),
('pr',29,13,'crampon1923','Le pauvre et l''oppresseur se rencontrent; c''est Yahweh qui éclaire les yeux de l''un et de l''autre.'),
('pr',29,14,'crampon1923','Un roi qui juge fidèlement les pauvres aura son trône affermi pour toujours.'),
('pr',29,15,'crampon1923','La verge et la correction donnent la sagesse, mais l''enfant abandonné à son caprice fait honte à sa mère.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('pr',29,16,'crampon1923','Quand les méchants se multiplient, le crime se multiplie, mais les justes contempleront leur chute.'),
('pr',29,17,'crampon1923','Corrige ton fils, et il te donnera du repos, et il procurera des délices à ton âme.'),
('pr',29,18,'crampon1923','Quand il n''y a plus de vision, le peuple est sans frein; heureux qui observe la loi!'),
('pr',29,19,'crampon1923','Ce n''est pas par des paroles qu''on corrige un esclave; quand même il comprend, il n''obéit pas.'),
('pr',29,20,'crampon1923','Si tu vois un homme prompt à parler, il y a plus à espérer d''un insensé que de lui.'),
('pr',29,21,'crampon1923','Si quelqu''un traite mollement son esclave dès l''enfance, celui-ci finit par se croire un fils.'),
('pr',29,22,'crampon1923','Un homme colère excite des querelles, et l''homme violent tombe dans beaucoup de péchés.'),
('pr',29,23,'crampon1923','L''orgueil d''un homme le conduit à l''humiliation, mais l''humble d''esprit obtient la gloire.'),
('pr',29,24,'crampon1923','Celui qui partage avec un voleur hait son âme; il entend la malédiction et ne dit rien.'),
('pr',29,25,'crampon1923','La crainte des hommes porte avec elle un piège, mais celui qui se confie en Yahweh est mis en sûreté.'),
('pr',29,26,'crampon1923','Beaucoup de gens recherchent la faveur du prince, mais c''est de Yahweh que vient à chacun la justice.'),
('pr',29,27,'crampon1923','L''homme inique est en abomination aux justes, et celui dont la voie est droite est en abomination aux méchants. PAROLES D''AGUR.'),
('pr',30,1,'crampon1923','Paroles d''Agur, fils de Jaké; sentence. Cet homme a dit: Je me suis fatigué pour connaître Dieu, pour connaître Dieu, et je suis à bout de forces.'),
('pr',30,2,'crampon1923','Car je suis plus stupide que personne, et je n''ai pas l''intelligence d''un homme.'),
('pr',30,3,'crampon1923','Je n''ai pas appris la sagesse, et je ne connais pas la science du Saint.'),
('pr',30,4,'crampon1923','Qui monte au ciel et qui en descend? Qui a recueilli le vent dans ses mains? Qui a lié les eaux dans son vêtement? Qui a affermi toutes les extrémités de la terre? Quel est son nom et quel est le nom de son fils? Le sais-tu?'),
('pr',30,5,'crampon1923','Toute parole de Dieu est éprouvée par le feu; il est un bouclier pour ceux qui se réfugient auprès de lui.'),
('pr',30,6,'crampon1923','N''ajoute rien à ses paroles, de peur qu''il ne te reprenne et que tu ne sois trouvé menteur.'),
('pr',30,7,'crampon1923','Je te demande deux choses, ne me les refuse pas avant que je meure:'),
('pr',30,8,'crampon1923','Eloigne de moi la fausseté et la parole mensongère; ne me donne ni pauvreté, ni richesse, accorde-moi le pain qui m''est nécessaire:'),
('pr',30,9,'crampon1923','de peur que, rassasié, je ne te renie et ne dise: « Qui est Yahweh? »; et que, devenu pauvre, je ne dérobe, et n''outrage le nom de mon Dieu.'),
('pr',30,10,'crampon1923','Ne calomnie pas un serviteur auprès de son maître, de peur qu''il ne te maudisse et que tu n''en portes la peine.'),
('pr',30,11,'crampon1923','Il est une race qui maudit son père, et qui ne bénit pas sa mère.'),
('pr',30,12,'crampon1923','Il est une race qui est pure à ses propres yeux, et qui n''est pas lavée de sa souillure.'),
('pr',30,13,'crampon1923','Il est une race — combien ses regards sont altiers, et ses paupières élevées!'),
('pr',30,14,'crampon1923','Il est une race dont les dents sont des glaives, et les molaires des couteaux, pour dévorer les malheureux de dessus la terre, et les indigents parmi les hommes.'),
('pr',30,15,'crampon1923','La sangsue a deux filles: Donne! donne! Trois choses sont insatiables, quatre ne disent jamais: Assez:'),
('pr',30,16,'crampon1923','le schéol, le sein stérile, la terre qui n''est pas rassasiée d''eau et le feu qui ne dit jamais: Assez!'),
('pr',30,17,'crampon1923','L''œil qui se moque d''un père, et qui dédaigne l''obéissance envers une mère, les corbeaux du torrent le perceront, et les petits de l''aigle le dévoreront.'),
('pr',30,18,'crampon1923','Il y a trois choses qui me dépassent, et même quatre que je ne comprends pas:'),
('pr',30,19,'crampon1923','la trace de l''aigle dans les cieux, la trace du serpent sur le rocher, la trace du navire au milieu de la mer, et la trace de l''homme chez la jeune fille.'),
('pr',30,20,'crampon1923','Telle est la voie de la femme adultère: elle mange et, s''essuyant la bouche, elle dit: « Je n''ai pas fait de mal. »'),
('pr',30,21,'crampon1923','Sous trois choses la terre tremble, et sous quatre, qu''elle ne peut supporter:'),
('pr',30,22,'crampon1923','sous un esclave lorsqu''il vient à régner, et un insensé lorsqu''il est rassasié de pain,'),
('pr',30,23,'crampon1923','sous une femme dédaignée lorsqu''elle se marie, et sous une servante lorsqu''elle hérite de sa maîtresse.'),
('pr',30,24,'crampon1923','Il y a sur la terre quatre animaux bien petits, et qui sont cependant très sages:'),
('pr',30,25,'crampon1923','Les fourmis, peuple sans force, préparent en été leur nourriture;'),
('pr',30,26,'crampon1923','les damans, peuple sans puissance, placent leur gîte dans les rochers;'),
('pr',30,27,'crampon1923','les sauterelles n''ont pas de roi, et elles sortent toutes par bandes;'),
('pr',30,28,'crampon1923','tu peux prendre le lézard avec la main, et il se trouve dans le palais des rois.'),
('pr',30,29,'crampon1923','Il y en a trois qui ont une belle allure, et quatre qui ont une belle démarche:'),
('pr',30,30,'crampon1923','le lion, le plus brave des animaux, ne reculant devant aucun adversaire;'),
('pr',30,31,'crampon1923','l''animal aux reins agiles, ou le bouc, et le roi, à qui personne ne résiste.'),
('pr',30,32,'crampon1923','Si tu es assez fou pour te laisser emporter par l''orgueil, et si tu en as la pensée, mets la main sur ta bouche,'),
('pr',30,33,'crampon1923','car la pression du lait produit du beurre, la pression du nez produit du sang, et la pression de la colère produit la querelle. PAROLES DU ROI LAMUEL.'),
('pr',31,1,'crampon1923','Paroles du roi Lamuel; sentences par lesquelles sa mère l''instruisit:'),
('pr',31,2,'crampon1923','Que te dirai-je, mon fils? Que te dirai-je, fils de mes entrailles? Que te dirai-je, mon fils, objet de mes vœux?'),
('pr',31,3,'crampon1923','Ne livre pas ta vigueur aux femmes, et tes voies à celles qui perdent les rois.'),
('pr',31,4,'crampon1923','Ce n''est point aux rois, Lamuel, ce n''est point aux rois de boire du vin, ni aux puissants de rechercher les liqueurs fermentées:'),
('pr',31,5,'crampon1923','de peur qu''en buvant ils n''oublient la loi, et ne faussent le droit de tous les malheureux.'),
('pr',31,6,'crampon1923','Donnez des liqueurs fortes à celui qui périt, et du vin à celui dont l''âme est remplie d''amertume:'),
('pr',31,7,'crampon1923','qu''il boive, et qu''il oublie sa misère, et qu''il ne se souvienne plus de ses peines.'),
('pr',31,8,'crampon1923','Ouvre ta bouche en faveur du muet, pour la cause de tous les abandonnés.'),
('pr',31,9,'crampon1923','Ouvre ta bouche, rends de justes arrêts, et fais justice au malheureux et à l''indigent. LA FEMME FORTE.'),
('pr',31,10,'crampon1923','ALEPH. Qui peut trouver une femme forte? Son prix l''emporte de loin sur celui des perles.'),
('pr',31,11,'crampon1923','BETH. Le cœur de son mari a confiance en elle, et les profits ne lui feront pas défaut.'),
('pr',31,12,'crampon1923','GHIMEL. Elle lui fait du bien, et non du mal, tous les jours de sa vie.'),
('pr',31,13,'crampon1923','DALETH. Elle recherche de la laine et du lin, et travaille de sa main joyeuse.'),
('pr',31,14,'crampon1923','HÉ. Elle est comme le vaisseau du marchand, elle apporte son pain de loin.'),
('pr',31,15,'crampon1923','VAV. Elle se lève lorsqu''il est encore nuit, et elle donne la nourriture à sa maison, et la tâche à ses servantes.'),
('pr',31,16,'crampon1923','ZAÏN. Elle pense à un champ, et elle l''acquiert; du fruit de ses mains, elle plante une vigne.'),
('pr',31,17,'crampon1923','HETH. Elle ceint de force ses reins, et elle affermit ses bras.'),
('pr',31,18,'crampon1923','TETH. Elle sent que son gain est bon; sa lampe ne s''éteint pas pendant la nuit.'),
('pr',31,19,'crampon1923','YOD. Elle met la main à la quenouille, et ses doigts prennent le fuseau.'),
('pr',31,20,'crampon1923','CAPH. Elle tend la main au malheureux, elle ouvre la main à l''indigent.'),
('pr',31,21,'crampon1923','LAMED. Elle ne craint pas la neige pour sa maison, car toute sa maison est vêtue de cramoisi.'),
('pr',31,22,'crampon1923','MEM. Elle se fait des couvertures, le byssus et la pourpre sont ses vêtements.'),
('pr',31,23,'crampon1923','NUN. Son époux est bien connu aux portes de la ville, lorsqu''il siège avec les anciens du pays.'),
('pr',31,24,'crampon1923','SAMECH. Elle fait des chemises et les vend, et elle livre des ceintures au marchand.'),
('pr',31,25,'crampon1923','AÏN. La force et la grâce sont sa parure, et elle se rit de l''avenir.'),
('pr',31,26,'crampon1923','PHÉ. Elle ouvre la bouche avec sagesse, et les bonnes paroles sont sur sa langue.'),
('pr',31,27,'crampon1923','TSADÉ. Elle surveille les sentiers de sa maison, et elle ne mange pas le pain d''oisiveté.'),
('pr',31,28,'crampon1923','QOPH. Ses fils se lèvent et la proclament heureuse; son époux se lève et lui donne des éloges:'),
('pr',31,29,'crampon1923','RESCH. « Beaucoup de filles se sont montrées vertueuses; mais toi, tu les surpasses toutes. »'),
('pr',31,30,'crampon1923','SCHIN. Trompeuse est la grâce, et vaine est la beauté; la femme qui craint Yahweh est celle qui sera louée.'),
('pr',31,31,'crampon1923','THAV. Donnez-lui du fruit de ses mains, et que ses œuvres disent sa louange aux portes de la ville.'),
('qo',1,1,'crampon1923','Paroles de l''Ecclésiaste, fils de David, roi dans Jérusalem.'),
('qo',1,2,'crampon1923','Vanité des vanités! dit l''Ecclésiaste, vanité des vanités! Tout est vanité.'),
('qo',1,3,'crampon1923','Quel avantage revient-il à l''homme de toute la peine qu''il se donne sous le soleil?'),
('qo',1,4,'crampon1923','Une génération passe, une génération vient, et la terre subsiste toujours.'),
('qo',1,5,'crampon1923','Le soleil se lève, le soleil se couche, et il se hâte de retourner à sa demeure, d''où il se lève de nouveau.'),
('qo',1,6,'crampon1923','Allant vers le midi, tournant vers le nord, le vent se retourne encore, et reprend les mêmes circuits.'),
('qo',1,7,'crampon1923','Tous les fleuves vont à la mer, et la mer n''est point remplie; vers le lieu où ils se dirigent, ils continuent à aller.'),
('qo',1,8,'crampon1923','Toutes choses sont en travail, au-delà de ce qu''on peut dire; l''œil n''est pas rassasié de voir, et l''oreille ne se lasse pas d''entendre.'),
('qo',1,9,'crampon1923','Ce qui a été, c''est ce qui sera, et ce qui s''est fait, c''est ce qui se fera; et il n''y a rien de nouveau sous le soleil.'),
('qo',1,10,'crampon1923','S''il est une chose dont on dise: " Vois, c''est nouveau! ", cette chose a déjà existé dans les siècles qui nous ont précédés.'),
('qo',1,11,'crampon1923','On ne se souvient pas de ce qui est ancien, et ce qui arrivera dans la suite ne laissera pas de souvenir chez ceux qui vivront plus tard.'),
('qo',1,12,'crampon1923','Moi, l''Ecclésiaste, j''ai été roi d''Israël à Jérusalem,'),
('qo',1,13,'crampon1923','et j''ai appliqué mon cœur à rechercher et à sonder par la sagesse tout ce qui se fait sous les cieux: c''est une occupation pénible à laquelle Dieu impose aux enfants des hommes de se livrer.'),
('qo',1,14,'crampon1923','J''ai examiné toutes les œuvres qui se font sous le soleil: et voici, tout est vanité et poursuite du vent.'),
('qo',1,15,'crampon1923','Ce qui est courbé ne peut se redresser, et ce qui manque ne peut être compté.'),
('qo',1,16,'crampon1923','Je me suis dit en moi-même: Voici que j''ai accumulé et amassé de la sagesse, plus que tous ceux qui ont été avant moi à Jérusalem, et mon cœur a possédé amplement sagesse et science.'),
('qo',1,17,'crampon1923','J''ai appliqué mon esprit à connaître la sagesse, et à connaître la sottise et la folie; j''ai compris que cela aussi est poursuite du vent.'),
('qo',1,18,'crampon1923','Car avec beaucoup de sagesse on a beaucoup de chagrin, et celui qui augmente sa science augmente sa douleur.'),
('qo',2,1,'crampon1923','J''ai dit dans mon cœur: " Viens donc, je t''éprouverai par la joie; goûte le plaisir! " Et voici, cela est encore une vanité.'),
('qo',2,2,'crampon1923','J''ai dit du rire: " Insensé! " et de la joie: " Que produit-elle? "'),
('qo',2,3,'crampon1923','Je m''appliquai dans mon cœur à livrer ma chair au vin, tandis que mon cœur me conduirait avec sagesse, et à m''attacher à la folie, jusqu''à ce que je visse ce qu''il est bon pour les enfants des hommes de faire sous le ciel durant les jours de leur vie.'),
('qo',2,4,'crampon1923','J''exécutai de grands ouvrages, je me bâtis des maisons, je me plantai des vignes;'),
('qo',2,5,'crampon1923','Je me fis des jardins et des vergers, et j''y plantai des arbres à fruit de toute espèce;'),
('qo',2,6,'crampon1923','je me fis des réservoirs d''eau, pour arroser des bosquets où croissaient les arbres.'),
('qo',2,7,'crampon1923','J''achetai des serviteurs et des servantes, et j''eus leurs enfants nés dans la maison; j''eus aussi des troupeaux de bœufs et de brebis, plus que tous ceux qui furent avant moi dans Jérusalem.'),
('qo',2,8,'crampon1923','Je m''amassai aussi de l''argent et de l''or, et les richesses des rois et des provinces; je me procurai des chanteurs et des chanteuses, et les délices des enfants des hommes, des femmes en abondance.'),
('qo',2,9,'crampon1923','Je devins grand et je l''emportai sur tous ceux qui étaient avant moi dans Jérusalem; et même ma sagesse demeura avec moi.'),
('qo',2,10,'crampon1923','Tout ce que mes yeux désiraient, je ne les en ai pas privés; je n''ai refusé à mon cœur aucune joie; car mon cœur prenait plaisir à tout mon travail, et ce fut ma part de tout mon travail.'),
('qo',2,11,'crampon1923','Puis j''ai considéré toutes mes œuvres que mes mains avaient faites, et le labeur que leur exécution m''avait coûté; et voici, tout est vanité et poursuite du vent, et il n''y a aucun profit sous le soleil.'),
('qo',2,12,'crampon1923','Alors j''ai tourné mes regards vers la sagesse pour la comparer avec la sottise et la folie. Car quel est l''homme qui pourrait venir après le roi, lui à qui on a conféré cette dignité depuis longtemps?'),
('qo',2,13,'crampon1923','Et j''ai vu que la sagesse a autant d''avantage sur la folie, que la lumière sur les ténèbres:'),
('qo',2,14,'crampon1923','Le sage a ses yeux à la tête, et l''insensé marche dans les ténèbres. Et j''ai aussi reconnu qu''un même sort les atteindra tous deux.'),
('qo',2,15,'crampon1923','Et j''ai dit dans mon cœur: " Le même sort que celui de l''insensé m''atteindra moi aussi; à quoi bon donc toute ma sagesse? " Et j''ai dit dans mon cœur que cela encore est une vanité.'),
('qo',2,16,'crampon1923','Car la mémoire du sage n''est pas plus éternelle que celle de l''insensé; dès les jours qui suivent, tous deux sont également oubliés. Eh quoi! Le sage meurt aussi bien que l''insensé!'),
('qo',2,17,'crampon1923','Et j''ai haï la vie, car ce qui se fait sous le soleil est mauvais à mes yeux, car tout est vanité et poursuite du vent.'),
('qo',2,18,'crampon1923','Et j''ai haï tout mon travail, que j''ai fait sous le soleil, et que je laisserai à l''homme qui viendra après moi.'),
('qo',2,19,'crampon1923','Et qui sait s''il sera sage ou insensé? Cependant il sera maître de mon travail, dans lequel j''ai mis ma peine et ma sagesse sous le soleil. C''est encore là une vanité.'),
('qo',2,20,'crampon1923','Et j''en suis venu à livrer mon cœur au découragement, à cause de tout le travail que j''ai fait sous le soleil.'),
('qo',2,21,'crampon1923','Car, qu''un homme qui a déployé dans son travail sagesse, intelligence et habileté, en laisse le fruit en partage à un homme qui n''y a pas travaillé: c''est encore là une vanité et un grand mal.'),
('qo',2,22,'crampon1923','En effet, que revient-il à l''homme de tout son travail, et du souci de son cœur, qui le fatiguent sous le soleil?'),
('qo',2,23,'crampon1923','Tous ses jours ne sont que douleur, ses occupations que chagrins; la nuit même son cœur ne se repose pas: c''est encore là une vanité.'),
('qo',2,24,'crampon1923','Il n''y a rien de meilleur pour l''homme que de manger et de boire, et de faire jouir son âme du bien-être, au milieu de son travail; mais j''ai vu que cela aussi vient de la main de Dieu.'),
('qo',2,25,'crampon1923','Qui, en effet, peut sans lui manger et jouir du bien-être?'),
('qo',2,26,'crampon1923','Car à l''homme qui est bon devant lui, il donne la sagesse, la science et la joie; mais au pécheur, il donne le soin de recueillir et d''amasser, afin de donner à celui qui est bon devant Dieu. C''est encore là une vanité et la poursuite du vent.'),
('qo',3,1,'crampon1923','Il y a un temps fixé pour tout, un temps pour toute chose sous le ciel:'),
('qo',3,2,'crampon1923','un temps pour naître, et un temps pour mourir; un temps pour planter, et un temps pour arracher ce qui a été planté;'),
('qo',3,3,'crampon1923','un temps pour tuer, et un temps pour guérir; un temps pour abattre, et un temps pour bâtir;'),
('qo',3,4,'crampon1923','un temps pour pleurer, et un temps pour rire; un temps pour se lamenter, et un temps pour danser;'),
('qo',3,5,'crampon1923','un temps pour jeter des pierres, et un temps pour en ramasser; un temps pour embrasser, et un temps pour s''abstenir d''embrassements.'),
('qo',3,6,'crampon1923','un temps pour chercher, et un temps pour perdre; un temps pour garder, et un temps pour jeter;'),
('qo',3,7,'crampon1923','un temps pour déchirer, et un temps pour coudre; un temps pour se taire, et un temps pour parler;'),
('qo',3,8,'crampon1923','un temps pour aimer, et un temps pour haïr; un temps pour la guerre, et un temps pour la paix.'),
('qo',3,9,'crampon1923','Quel est l''avantage, pour celui qui travaille, de la peine qu''il se donne?'),
('qo',3,10,'crampon1923','J''ai examiné le labeur auquel Dieu impose aux enfants des hommes de se livrer:'),
('qo',3,11,'crampon1923','Dieu a fait toute chose belle en son temps, il a mis aussi dans leur cœur l''éternité, mais sans que l''homme puisse comprendre l''œuvre que Dieu fait, du commencement jusqu''à la fin.'),
('qo',3,12,'crampon1923','Et j''ai reconnu qu''il n''y a rien de meilleur pour eux que de se réjouir et se donner du bien-être pendant leur vie,'),
('qo',3,13,'crampon1923','et en même temps que si un homme mange et boit, et jouit du bien-être au milieu de son travail, c''est là un don de Dieu.'),
('qo',3,14,'crampon1923','J''ai reconnu que tout ce que Dieu fait durera toujours, qu''il n''y a rien à y ajouter ni rien à en retrancher: Dieu agit ainsi afin qu''on le craigne.'),
('qo',3,15,'crampon1923','Ce qui se fait existait déjà, et ce qui se fera a déjà été: Dieu ramène ce qui est passé.'),
('qo',3,16,'crampon1923','J''ai encore vu sous le soleil, qu''au siège même du droit il y a la méchanceté, et au lieu de la justice, il y a l''iniquité.'),
('qo',3,17,'crampon1923','J''ai dit dans mon cœur: " Dieu jugera le juste et le méchant, car il y a là un temps pour toute chose, et pour toute œuvre. "'),
('qo',3,18,'crampon1923','J''ai dit dans mon cœur au sujet des enfants des hommes: " Cela arrive ainsi, afin que Dieu les éprouve, et qu''ils voient qu''ils sont quant à eux-mêmes semblables aux bêtes. "'),
('qo',3,19,'crampon1923','Car le sort des enfants des hommes est le sort de la bête: ils ont un même sort; comme l''un meurt, l''autre meurt aussi, il n''y a qu''un même souffle pour tous; l''avantage de l''homme sur la bête est nul, car tout est vanité.'),
('qo',3,20,'crampon1923','Tout va dans un même lieu; tout est sorti de la poussière, et tout retourne à la poussière.'),
('qo',3,21,'crampon1923','Qui connaît le souffle des enfants des hommes, qui monte en haut, et le souffle de la bête, qui descend en bas vers la terre?'),
('qo',3,22,'crampon1923','Et j''ai vu qu''il n''y a rien de mieux pour l''homme que de se réjouir dans ses œuvres: c''est là sa part. Car qui lui donnera de découvrir ce qui arrivera après lui?'),
('qo',4,1,'crampon1923','Je me suis tourné et j''ai vu toutes les oppressions qui se commettent sous le soleil: et voici que les opprimés sont dans les larmes, et personne ne les console! Ils sont en butte à la violence de leurs oppresseurs, et personne ne les console!'),
('qo',4,2,'crampon1923','Et j''ai proclamé les morts qui sont déjà morts plus heureux que les vivants qui sont encore vivants,'),
('qo',4,3,'crampon1923','et plus heureux que les uns et les autres celui qui n''est pas encore arrivé à l''existence, qui n''a pas vu les mauvaises actions qui se commettent sous le soleil.'),
('qo',4,4,'crampon1923','J''ai vu que tout travail et que toute habileté dans un ouvrage n''est que jalousie contre un homme de la part de son prochain: cela encore est vanité et poursuite du vent.'),
('qo',4,5,'crampon1923','L''insensé se croise les mains, et mange sa propre chair.'),
('qo',4,6,'crampon1923','Mieux vaut une main pleine de repos, que les deux pleines de labeur et de poursuite du vent.'),
('qo',4,7,'crampon1923','Je me suis tourné et j''ai vu une autre vanité sous le soleil.'),
('qo',4,8,'crampon1923','Tel homme est seul et n''a pas de second, il n''a ni fils ni frère, et pourtant il n''y a pas de fin à tout son travail, et ses yeux ne sont jamais rassasiés de richesses: " Pour qui donc est-ce que je travaille, et que je prive mon âme de jouissance? " Cela encore est vanité, et mauvaise occupation.'),
('qo',4,9,'crampon1923','Mieux vaut vivre à deux que solitaire; il y a pour les deux un bon salaire dans leur travail;'),
('qo',4,10,'crampon1923','car s''ils tombent, l''un peut relever son compagnon. Mais malheur à celui qui est seul, et qui tombe sans avoir un second pour le relever!'),
('qo',4,11,'crampon1923','De même, si deux couchent ensemble, ils se réchauffent; mais un homme seul, comment aurait-il chaud!'),
('qo',4,12,'crampon1923','Et si quelqu''un maîtrise celui qui est seul, les deux pourront lui résister, et le fil triplé ne rompt pas facilement.'),
('qo',4,13,'crampon1923','Mieux vaut un jeune homme pauvre et sage qu''un roi vieux et insensé qui ne sait plus écouter les avis;'),
('qo',4,14,'crampon1923','car il sort de prison pour régner, quoiqu''il soit né pauvre dans son royaume.'),
('qo',4,15,'crampon1923','J''ai vu tous les vivants qui marchent sous le soleil près du jeune homme qui s''élevait à la place du vieux roi.'),
('qo',4,16,'crampon1923','Il n''y avait pas de fin à toute cette foule, à tous ceux à la tête desquels il était. Et cependant les descendants ne se réjouiront pas à son sujet. Cela encore est vanité et poursuite du vent.'),
('qo',4,17,'crampon1923','Prends garde à ton pied quand tu vas à la maison de Dieu; s''approcher pour écouter vaut mieux que d''offrir des victimes à la manière des insensés; car leur ignorance les conduit à faire mal.'),
('qo',5,1,'crampon1923','Ne sois pas pressé d''ouvrir la bouche, et que ton cœur ne se hâte pas d''exprimer une parole devant Dieu; car Dieu est au ciel, et toi sur la terre: que tes paroles soient donc peu nombreuses!'),
('qo',5,2,'crampon1923','Car de la multitude des occupations naissent les songes, et de la multitude des paroles, des propos d''insensé.'),
('qo',5,3,'crampon1923','Lorsque tu fais un vœu à Dieu, ne tarde pas à l''accomplir, car il n''y a pas de faveur pour les insensés: ce que tu voues, accomplis-le.'),
('qo',5,4,'crampon1923','Mieux vaut pour toi ne pas vouer, que vouer et ne pas accomplir.'),
('qo',5,5,'crampon1923','Ne permets pas à ta bouche de faire pécher ta chair, et ne dis pas en présence de l''envoyé de Dieu que c''est une inadvertance: pourquoi Dieu s''irriterait-il au sujet de tes paroles, et détruirait-il les œuvre de tes mains?'),
('qo',5,6,'crampon1923','Car, comme il y a des vanités dans la multitude des occupations, il y en a aussi dans beaucoup de paroles; c''est pourquoi crains Dieu.'),
('qo',5,7,'crampon1923','Si tu vois dans une province le pauvre opprimé, le droit et la justice violés, ne t''étonne point de la chose; car un plus grand veille sur un grand, et de plus grands encore veillent sur eux.'),
('qo',5,8,'crampon1923','Un avantage pour le pays à tous égards, c''est un roi qui donne ses soins à l''agriculture.'),
('qo',5,9,'crampon1923','Celui qui aime l''argent n''est pas rassasié par l''argent, et celui qui aime les richesses n''en goûte pas le fruit; c''est encore là une vanité.'),
('qo',5,10,'crampon1923','Quand les biens se multiplient, ceux qui les mangent se multiplient aussi; et quel avantage en revient-il à leurs possesseurs, sinon qu''ils les voient de leurs yeux?'),
('qo',5,11,'crampon1923','Le sommeil du travailleur est doux, qu''il ait peu ou beaucoup à manger; mais la satiété du riche ne le laisse pas dormir.'),
('qo',5,12,'crampon1923','Il est un mal grave que j''ai vu sous le soleil: des richesses conservées pour son malheur par celui qui les possède:'),
('qo',5,13,'crampon1923','Ces richesses se perdent par quelque fâcheux événement, et, s''il a engendré un fils, il ne lui reste rien entre les mains.'),
('qo',5,14,'crampon1923','Tel qu''il est sorti du sein de sa mère, il s''en retournera nu, comme il était venu; et il ne recevra rien pour son travail, qu''il puisse emporter dans sa main:'),
('qo',5,15,'crampon1923','C''est encore là un grave mal, qu''il s''en aille comme il est venu: et quel avantage lui revient-il d''avoir travaillé pour le vent?'),
('qo',5,16,'crampon1923','De plus, toute sa vie il mange dans les ténèbres; il a beaucoup de chagrin, de souffrance et d''irritation.'),
('qo',5,17,'crampon1923','Voici donc ce que j''ai vu: c''est qu''il est bon et séant pour l''homme de manger et de boire, et de jouir du bien-être dans tout son travail, auquel il se livre sous le soleil, durant les jours de vie que Dieu lui donne; car c''est là sa part.'),
('qo',5,18,'crampon1923','De plus, pour tout homme à qui Dieu donne richesses et biens, avec pouvoir d''en manger, d''en prendre sa part et de se réjouir de son travail, c''est là un don de Dieu.'),
('qo',5,19,'crampon1923','Car alors il ne songe guère aux jours de sa vie, parce que Dieu répand la joie dans son cœur.'),
('qo',6,1,'crampon1923','Il est un mal que j''ai vu sous le soleil, et ce mal est grand sur l''homme:'),
('qo',6,2,'crampon1923','Tel homme à qui Dieu a donné richesses, trésors et gloire, et qui ne manque pour son âme de rien de ce qu''il peut désirer; mais Dieu ne lui permet pas d''en jouir, car c''est un étranger qui en jouit: voilà une vanité et un mal grave.'),
('qo',6,3,'crampon1923','Quand un homme aurait engendré cent fils, eût vécu de nombreuses années, et que les jours de ses années se seraient multipliés, si son âme ne s''est pas rassasiée de bonheur, et qu''il n''ait pas même eu de sépulture, je dis qu''un avorton est plus heureux que lui.'),
('qo',6,4,'crampon1923','Car il est venu en vain, il s''en va dans les ténèbres, et les ténèbres couvriront son nom;'),
('qo',6,5,'crampon1923','il n''a même ni vu ni connu le soleil, il a plus de repos que cet homme.'),
('qo',6,6,'crampon1923','Et quand il vivrait deux fois mille ans, sans jouir du bonheur, tout ne va-t-il pas au même lieu?'),
('qo',6,7,'crampon1923','Tout le travail de l''homme est pour sa bouche; mais ses désirs ne sont jamais satisfaits.'),
('qo',6,8,'crampon1923','Car quel avantage a le sage sur l''insensé? Quel avantage a le pauvre qui sait se conduire devant les vivants?'),
('qo',6,9,'crampon1923','Ce que les yeux voient est préférable à la divagation des désirs. Cela encore est vanité et poursuite du vent.'),
('qo',6,10,'crampon1923','De toute chose qui arrive, le nom est déjà prononcé; on sait ce que sera un homme, et il ne peut contester avec qui est plus fort que lui.'),
('qo',6,11,'crampon1923','Car il y a beaucoup de paroles qui ne font qu''accroître la vanité: quel avantage en revient-il à l''homme?'),
('qo',6,12,'crampon1923','Car qui sait, en effet, ce qui est bon pour l''homme dans la vie, pendant les jours de sa vie de vanité, qu''il passe comme une ombre? Et qui peut indiquer à l''homme ce qui sera après lui sous le soleil?'),
('qo',7,1,'crampon1923','Une bonne renommée vaut mieux qu''un bon parfum, et le jour de la mort que le jour de la naissance.'),
('qo',7,2,'crampon1923','Mieux vaut aller à la maison de deuil qu''aller à la maison de festin, car dans la première apparaît la fin de tout homme, et le vivant y applique son cœur.'),
('qo',7,3,'crampon1923','Mieux vaut la tristesse que le rire, car un visage triste fait du bien au cœur.'),
('qo',7,4,'crampon1923','Le cœur des sages est dans la maison de deuil, et le cœur des insensés dans la maison de joie.'),
('qo',7,5,'crampon1923','Mieux vaut entendre la réprimande du sage que d''entendre la chanson des insensés.'),
('qo',7,6,'crampon1923','Car semblable au pétillement des épines sous la chaudière est le rire des insensés: c''est là encore une vanité.'),
('qo',7,7,'crampon1923','Car l''oppression rend insensé le sage, et les présents corrompent le cœur.'),
('qo',7,8,'crampon1923','Mieux vaut la fin d''une chose que son commencement; mieux vaut un esprit patient qu''un esprit hautain.'),
('qo',7,9,'crampon1923','Ne te hâte pas dans ton esprit de t''irriter, car l''irritation repose dans le sein des insensés.'),
('qo',7,10,'crampon1923','Ne dis pas: " D''où vient que les jours anciens étaient meilleurs que ceux-ci? " Car ce n''est pas par sagesse que tu interroges à ce sujet.'),
('qo',7,11,'crampon1923','La sagesse est bonne avec un patrimoine, et profitable à ceux qui voient le soleil.'),
('qo',7,12,'crampon1923','Car telle la protection de l''argent, telle la protection de la sagesse; mais un avantage du savoir, c''est que la sagesse fait vivre ceux qui la possèdent.'),
('qo',7,13,'crampon1923','Regarde l''œuvre de Dieu: qui pourra redresser ce qu''il a courbé?'),
('qo',7,14,'crampon1923','Au jour du bonheur, sois joyeux, et au jour du malheur, réfléchis: Dieu a fait l''un comme l''autre, afin que l''homme ne découvre point ce qui doit lui arriver.'),
('qo',7,15,'crampon1923','Tout ceci, je l''ai vu au jour de ma vanité: il y a tel juste qui périt dans sa justice, et il y a tel méchant qui prolonge sa vie dans sa méchanceté.'),
('qo',7,16,'crampon1923','Ne sois pas juste à l''excès, et ne te montre pas sage outre mesure: pourquoi voudrais-tu te détruire?'),
('qo',7,17,'crampon1923','Ne sois pas méchant à l''excès, et ne sois pas insensé: pourquoi voudrais-tu mourir avant ton temps?'),
('qo',7,18,'crampon1923','Il est bon que tu retiennes ceci, et que tu ne relâches pas ta main de cela, car celui qui craint Dieu évite tous ces excès.'),
('qo',7,19,'crampon1923','La sagesse donne au sage plus de force que n''en possèdent dix chefs qui sont dans la ville.'),
('qo',7,20,'crampon1923','Car il n''y a pas sur terre d''homme juste qui fasse le bien sans jamais pécher.'),
('qo',7,21,'crampon1923','Ne fais pas non plus attention à toutes les paroles qui se disent, de peur que tu n''entendes ton serviteur te maudire;'),
('qo',7,22,'crampon1923','car ton cœur sait que bien des fois aussi tu as maudit les autres.'),
('qo',7,23,'crampon1923','J''ai reconnu vrai tout cela par la sagesse; j''ai dit: je veux être sage! mais la sagesse est restée loin de moi.'),
('qo',7,24,'crampon1923','Ce qui arrive est lointain, profond, profond: qui peut l''atteindre?'),
('qo',7,25,'crampon1923','Je me suis appliqué et mon cœur a cherché à connaître, à sonder et à poursuivre la sagesse et la raison des choses, et j''ai reconnu que la méchanceté est une démence, et qu''une conduite folle est un délire.'),
('qo',7,26,'crampon1923','Et j''ai trouvé plus amère que la mort la femme dont le cœur est un piège et un filet, et dont les mains sont des liens; celui qui est agréable à Dieu lui échappe, mais le pécheur sera enlacé par elle.'),
('qo',7,27,'crampon1923','Vois, j''ai trouvé ceci, dit l''Ecclésiaste, en considérant les choses une à une pour en découvrir la raison, que mon âme a constamment cherchée, sans que je l''aie trouvée: J''ai trouvé un homme entre mille, mais je n''ai pas trouvé une femme dans le même nombre.'),
('qo',7,28,'crampon1923','Seulement, vois, j''ai trouvé ceci: C''est que Dieu a fait l''homme droit, mais eux cherchent beaucoup de subtilités.'),
('qo',7,29,'crampon1923',''),
('qo',8,1,'crampon1923','Qui est comme le sage, et qui connaît comme lui l''explication des choses? La sagesse d''un homme fait briller son visage, et la rudesse de sa face est transfigurée.'),
('qo',8,2,'crampon1923','Je te dis: Observe les ordres du roi, et cela à cause du serment fait à Dieu;'),
('qo',8,3,'crampon1923','ne te hâte pas de t''éloigner de lui. Ne persiste pas dans une chose mauvaise; car tout ce qu''il veut, il peut le faire;'),
('qo',8,4,'crampon1923','la parole du roi, en effet, est souveraine, et qui lui dira: " Que fais-tu? "'),
('qo',8,5,'crampon1923','Celui qui observe le précepte n''éprouve rien de mal, et le cœur du sage connaîtra le temps et le jugement.'),
('qo',8,6,'crampon1923','Il y a en effet, pour toute chose, un temps et un jugement, car il est grand le mal qui tombera sur l''homme.'),
('qo',8,7,'crampon1923','Il ne sait pas ce qui arrivera, et qui lui dira comment cela arrivera?'),
('qo',8,8,'crampon1923','L''homme n''est pas maître de son souffle, pour pouvoir retenir son souffle, et il n''a aucune puissance sur le jour de sa mort; il n''y a pas de dispense dans ce combat, et le crime ne saurait sauver son homme.'),
('qo',8,9,'crampon1923','J''ai vu toutes ces choses, en appliquant mon cœur à toute l''œuvre qui se fait sous le soleil, en un temps où un homme domine sur un homme pour le malheur de celui-ci.'),
('qo',8,10,'crampon1923','Et alors j''ai vu des méchants recevoir la sépulture et entrer dans leur repos, tandis que s''en vont loin du lieu saint et sont oubliés dans la ville des hommes qui ont agi avec droiture; cela encore est une vanité.'),
('qo',8,11,'crampon1923','Parce que la sentence portée contre les mauvaises actions ne s''exécute pas en toute hâte, à cause de cela le cœur des enfants des hommes s''enhardit en eux à faire le mal;'),
('qo',8,12,'crampon1923','mais, quoique le pécheur fasse cent fois le mal, et prolonge ses jours, je sais, moi, que le bonheur est pour ceux qui craignent Dieu, qui sont dans la crainte en sa présence.'),
('qo',8,13,'crampon1923','Mais le bonheur n''est pas pour le méchant; et pareil à l''ombre, il ne prolongera pas ses jours, parce qu''il ne craint pas Dieu.'),
('qo',8,14,'crampon1923','Il est une autre vanité qui se produit sur la terre: C''est qu''il y a des justes auxquels il arrive des choses qui conviennent aux œuvres des méchants; et il y a des méchants auxquels il arrive des choses qui conviennent aux œuvres des justes. Je dis que cela encore est une vanité.'),
('qo',8,15,'crampon1923','Aussi j''ai loué la joie, parce qu''il n''y a de bonheur pour l''homme sous le soleil qu''à manger et à boire et à se réjouir; et c''est là ce qui doit l''accompagner dans son travail, pendant les jours de vie que Dieu lui donne sous le soleil.'),
('qo',8,16,'crampon1923','Lorsque j''ai appliqué mon cœur à connaître la sagesse et à considérer la tâche qui s''accomplit sur la terre, — car ni le jour ni la nuit l''homme ne voit de ses yeux le sommeil, —'),
('qo',8,17,'crampon1923','j''ai vu toute l''œuvre de Dieu; j''ai vu que l''homme ne saurait trouver l''œuvre qui se fait sous le soleil; l''homme se fatigue à chercher, et ne trouve pas; même si le sage veut connaître, il ne peut trouver.'),
('qo',9,1,'crampon1923','En effet, j''ai pris tout ceci à cœur, et j''ai observé tout ceci: Que les justes et les sages et leurs œuvres sont dans la main de Dieu; l''homme ne connaît ni l''amour, ni la haine: tout est devant eux.'),
('qo',9,2,'crampon1923','Tout arrive également à tous: même sort pour le juste et pour le méchant, pour celui qui est bon et pur, et pour celui qui est impur, pour celui qui sacrifie et pour celui qui ne sacrifie pas. Comme il arrive à l''homme bon, il arrive au pécheur; il en est de celui qui jure comme de celui qui craint de jurer.'),
('qo',9,3,'crampon1923','C''est un mal, parmi tout ce qui se fait sous le soleil, qu''il y ait pour tous un même sort; c''est pourquoi le cœur des fils de l''homme est plein de malice, et la folie est dans leur cœur pendant leur vie; après quoi ils vont chez les morts.'),
('qo',9,4,'crampon1923','Car pour l''homme qui est parmi les vivants, il y a de l''espérance; mieux vaut un chien vivant qu''un lion mort.'),
('qo',9,5,'crampon1923','Les vivants, en effet, savent qu''ils mourront, mais les morts ne savent rien, et il n''y a plus pour eux de salaire; car leur mémoire est oubliée.'),
('qo',9,6,'crampon1923','Déjà leur amour, leur haine, leur envie ont péri, et ils n''auront plus jamais aucune part à ce qui se fait sous le soleil.'),
('qo',9,7,'crampon1923','Va, mange avec joie ton pain et bois ton vin d''un cœur content, puisque déjà Dieu se montre favorable à tes œuvres.'),
('qo',9,8,'crampon1923','Qu''en tout temps tes vêtements soient blancs, et que l''huile parfumée ne manque pas sur ta tête.'),
('qo',9,9,'crampon1923','Jouis de la vie avec une femme que tu aimes, pendant tous les jours de ta vie de vanité que Dieu t''a donnée sous le soleil, pendant tous les jours de ta vanité; car c''est ta part dans la vie et dans le travail que tu fais sous le soleil.'),
('qo',9,10,'crampon1923','Tout ce que ta main peut faire, fais-le avec ta force; car il n''y a plus ni œuvre, ni intelligence, ni science, ni sagesse, dans le schéol où tu vas.'),
('qo',9,11,'crampon1923','Je me suis tourné et j''ai vu sous le soleil que la course n''est pas aux agiles, ni la guerre aux vaillants, ni le pain aux sages, ni la richesse aux intelligents, ni la faveur aux savants; car le temps et les accidents les atteignent tous.'),
('qo',9,12,'crampon1923','Car l''homme ne connaît même pas son heure, pareil aux poissons qui sont pris au filet fatal, pareil aux oiseaux qui sont pris au piège; comme eux les enfants des hommes sont enlacés au temps du malheur, quand il fond sur eux tout à coup.'),
('qo',9,13,'crampon1923','J''ai encore vu sous le soleil ce trait de sagesse, et celle-ci m''a paru grande.'),
('qo',9,14,'crampon1923','Il y avait une petite ville, avec peu d''hommes dans ses murs; un roi puissant vint contre elle, l''investit, et bâtit contre elle de hautes tours.'),
('qo',9,15,'crampon1923','Et il s''y trouva un homme pauvre et sage, qui sauva la ville par sa sagesse. Et personne ne s''est souvenu de cet homme pauvre.'),
('qo',9,16,'crampon1923','Et j''ai dit: " La sagesse vaut mieux que la force; mais la sagesse du pauvre est méprisée, et ses paroles ne sont pas écoutées. "'),
('qo',9,17,'crampon1923','Les paroles des sages, prononcées avec calme, sont écoutées, mieux que les cris d''un chef au milieu des insensés.'),
('qo',9,18,'crampon1923','La sagesse vaut mieux que des instruments de guerre; mais un seul pécheur peut détruire beaucoup de bien.'),
('qo',10,1,'crampon1923','Des mouches mortes infectent et corrompent l''huile du parfumeur; de même un peu de folie l''emporte sur la sagesse et la gloire.'),
('qo',10,2,'crampon1923','Le cœur du sage est à sa droite, et le cœur de l''insensé, à sa gauche.'),
('qo',10,3,'crampon1923','Et aussi, quand l''insensé va dans le chemin, le sens lui manque, et il montre à tous qu''il est fou.'),
('qo',10,4,'crampon1923','Si l''esprit du prince s''élève contre toi, ne quitte point ta place; car le calme prévient de grandes fautes.'),
('qo',10,5,'crampon1923','Il est un mal que j''ai vu sous le soleil, comme une erreur qui provient du souverain:'),
('qo',10,6,'crampon1923','la folie occupe les postes élevés, et des riches sont assis dans de basses conditions.'),
('qo',10,7,'crampon1923','J''ai vu des esclaves portés sur des chevaux, et des princes aller à pied comme des esclaves.'),
('qo',10,8,'crampon1923','Celui qui creuse une fosse peut y tomber, et celui qui renverse une muraille peut être mordu par un serpent.'),
('qo',10,9,'crampon1923','Celui qui détache des pierres peut être blessé, et celui qui fend du bois peut se faire mal.'),
('qo',10,10,'crampon1923','Si le fer est émoussé et si l''on n''a pas aiguisé le tranchant, on devra redoubler de force; mais la sagesse est préférable pour le succès.'),
('qo',10,11,'crampon1923','Si le serpent mord faute d''enchantement, il n''y a pas d''avantage pour l''enchanteur.'),
('qo',10,12,'crampon1923','Les paroles de la bouche du sage sont pleines de grâce; mais les lèvres de l''insensé le dévorent.'),
('qo',10,13,'crampon1923','Le commencement des paroles de sa bouche est sottise, et la fin de son discours est démence furieuse.'),
('qo',10,14,'crampon1923','Et l''insensé multiplie les paroles!... L''homme ne sait pas ce qui arrivera, et qui lui dira ce qui sera après lui?'),
('qo',10,15,'crampon1923','Le travail de l''insensé le fatigue, lui qui ne sait pas même aller à la ville.'),
('qo',10,16,'crampon1923','Malheur à toi, pays dont le roi est un enfant, et dont les princes mangent dès le matin!'),
('qo',10,17,'crampon1923','Heureux es-tu, pays dont le roi est fils de nobles, et dont les princes mangent au temps convenable, pour soutenir leurs forces, et non pour se livrer à la boisson.'),
('qo',10,18,'crampon1923','Quand les mains sont paresseuses, la charpente s''affaisse, et quand les mains sont lâches, la maison ruisselle.'),
('qo',10,19,'crampon1923','On fait des repas pour goûter le plaisir; le vin rend la vie joyeuse, et l''argent répond à tout.'),
('qo',10,20,'crampon1923','Même dans ta pensée ne maudis pas le roi, même dans ta chambre à coucher ne maudis pas le puissant; car l''oiseau du ciel emporterait ta voix, et l''animal ailé publierait tes paroles.'),
('qo',11,1,'crampon1923','Jette ton pain sur la face des eaux, car après beaucoup de jours tu le retrouveras;'),
('qo',11,2,'crampon1923','donnes-en une part à sept, et même à huit: car tu ne sais pas quel malheur peut arriver sur la terre.'),
('qo',11,3,'crampon1923','Quand les nuées sont remplies de pluie, elles se vident sur la terre; et si un arbre tombe au midi ou au nord, il reste à la place où il est tombé.'),
('qo',11,4,'crampon1923','Celui qui observe le vent ne sèmera point, et celui qui interroge les nuages ne moissonnera point.'),
('qo',11,5,'crampon1923','Comme tu ne sais pas quel est le chemin du vent et comment se forment les os dans le sein de la mère, ainsi tu ne connais pas l''œuvre de Dieu, qui fait toutes choses.'),
('qo',11,6,'crampon1923','Dès le matin sème ta semence, et le soir ne laisse pas reposer ta main, car tu ne sais pas ce qui réussira, ceci ou cela, ou si l''un et l''autre ne sont pas également bons.'),
('qo',11,7,'crampon1923','La lumière est douce, et c''est un plaisir pour l''œil de voir le soleil.'),
('qo',11,8,'crampon1923','Même si l''homme vit de nombreuses années, qu''il se réjouisse pendant toutes ces années, et qu''il pense aux jours de ténèbres, car ils seront nombreux: tout ce qui arrive est vanité.'),
('qo',11,9,'crampon1923','Jeune homme, réjouis-toi dans ta jeunesse; que ton cœur te donne de la joie dans les jours de ta jeunesse! Marche dans les voies de ton cœur, et selon les regards de tes yeux; mais sache que pour tout cela Dieu te fera venir en jugement.'),
('qo',11,10,'crampon1923','Bannis de ton cœur le chagrin, et éloigne le mal de ta chair; la jeunesse et l''adolescence sont vanité.'),
('qo',12,1,'crampon1923','Et souviens-toi de ton créateur aux jours de ta jeunesse, avant que viennent les jours mauvais et qu''approchent les années dont tu diras: " Je n''y ai point de plaisir; "'),
('qo',12,2,'crampon1923','avant que s''obscurcissent le soleil et la lumière, et la lune et les étoiles, et que les nuages reviennent après la pluie;'),
('qo',12,3,'crampon1923','au jour où tremblent les gardiens de la maison, où se courbent les hommes forts, où celles qui moulent s''arrêtent parce que leur nombre est diminué, où s''obscurcissent celles qui regardent par les fenêtres,'),
('qo',12,4,'crampon1923','où les deux battants de la porte se ferment sur la rue, tandis que s''affaiblit le bruit de la meule; où l''on se lève au chant de l''oiseau, où disparaissent toutes les filles du chant;'),
('qo',12,5,'crampon1923','où l''on redoute les lieux élevés, où l''on a des terreurs dans le chemin, où l''amandier fleurit, où la sauterelle devient pesante, et où la câpre n''a plus d''effet, car l''homme s''en va vers sa maison d''éternité, et les pleureurs parcourent les rues;'),
('qo',12,6,'crampon1923','avant que se rompe le cordon d''argent, que se brise l''ampoule d''or, que la cruche se casse à la fontaine, que la poulie se brise et roule dans la citerne;'),
('qo',12,7,'crampon1923','et que la poussière retourne à la terre, selon ce qu''elle était; et que l''esprit retourne à Dieu qui l''a donné.'),
('qo',12,8,'crampon1923','Vanité des vanités, dit l''Écclésiaste, tout est vanité.'),
('qo',12,9,'crampon1923','Outre que l''Écclésiaste fut un sage, il a encore enseigné la science au peuple; il a pesé et sondé, et il a disposé un grand nombre de sentences.'),
('qo',12,10,'crampon1923','L''Ecclésiaste s''est étudié à trouver un langage agréable, et à écrire avec exactitude des paroles de vérité.'),
('qo',12,11,'crampon1923','Les paroles des sages sont comme des aiguillons, et leurs recueils comme des clous plantés; elles sont données par un seul Pasteur.'),
('qo',12,12,'crampon1923','Et quand à plus de paroles que celles-ci, mon fils, sois averti. Multiplier les livres n''aurait pas de fin, et beaucoup d''étude est une fatigue pour la chair.'),
('qo',12,13,'crampon1923','Fin du discours, le tout entendu: Crains Dieu et observe ses commandements, car c''est là le tout de l''homme.'),
('qo',12,14,'crampon1923','Car Dieu citera en un jugement portant sur tout ce qui est caché, toute œuvre, soit bonne, soit mauvaise.'),
('ct',1,1,'crampon1923','Cantique des Cantiques, de Salomon.'),
('ct',1,2,'crampon1923','Qu''il me baise des baisers de sa bouche! Car ton amour est meilleur que le vin;'),
('ct',1,3,'crampon1923','tes parfums ont une odeur suave, ton nom est une huile épandue; c''est pourquoi les jeunes filles t''aiment.'),
('ct',1,4,'crampon1923','Entraîne-moi après toi; courons! Le roi m''a fait entrer dans ses appartements; nous tressaillirons, nous nous réjouirons en toi: nous célébrerons ton amour plus que le vin. Qu''on a raison de t''aimer! L''ÉPOUSE.'),
('ct',1,5,'crampon1923','Je suis noire, mais belle, filles de Jérusalem, comme les tentes de Cédar, comme les pavillons de Salomon.'),
('ct',1,6,'crampon1923','Ne prenez pas garde à mon teint noir, c''est le soleil qui m''a brûlée; les fils de ma mère se sont irrités contre moi; ils m''ont mise à garder des vignes; ma vigne, à moi, je ne l''ai pas gardée.'),
('ct',1,7,'crampon1923','Dis-moi, ô toi que mon cœur aime, où tu mènes paître tes brebis, où tu les fais reposer à midi, pour que je ne sois pas comme une égarée, autour des troupeaux de tes compagnons. LE CHŒUR.'),
('ct',1,8,'crampon1923','Si tu ne le sais pas, ô la plus belle des femmes, sors sur les traces de ton troupeau, et mène paître tes chevreaux près des huttes des bergers. L''ÉPOUX.'),
('ct',1,9,'crampon1923','A ma cavale, quand elle est attelée aux chars de Pharaon, je te compare, ô mon amie.'),
('ct',1,10,'crampon1923','Tes joues sont belles au milieu des colliers, ton cou est beau au milieu des rangées de perles.'),
('ct',1,11,'crampon1923','Nous te ferons des colliers d''or, pointillés d''argent. L''ÉPOUSE.'),
('ct',1,12,'crampon1923','Tandis que le roi était à son divan, mon nard a donné son parfum.'),
('ct',1,13,'crampon1923','Mon bien-aimé est pour moi un sachet de myrrhe, qui repose entre mes seins.'),
('ct',1,14,'crampon1923','Mon bien-aimé est pour moi une grappe de cypre, dans les vignes d''Engaddi. L''ÉPOUX.'),
('ct',1,15,'crampon1923','Oui, tu es belle, mon amie; oui, tu es belle! Tes yeux sont des yeux de colombe. L''ÉPOUSE.'),
('ct',1,16,'crampon1923','Oui, tu es beau, mon bien-aimé; oui, tu es charmant! Notre lit est un lit de verdure. L''ÉPOUX.'),
('ct',1,17,'crampon1923','Les poutres de nos maisons sont des cèdres, nos lambris sont des cyprès.'),
('ct',2,1,'crampon1923','Je suis le narcisse de Saron, le lis des vallées. L''ÉPOUX.'),
('ct',2,2,'crampon1923','Comme un lis au milieu des épines, telle est mon amie parmi les jeunes filles. L''ÉPOUSE.'),
('ct',2,3,'crampon1923','Comme un pommier au milieu des arbres de la forêt, tel est mon bien-aimé parmi les jeunes hommes. J''ai désiré m''asseoir à son ombre, et son fruit est doux à mon palais.'),
('ct',2,4,'crampon1923','Il m''a fait entrer dans son cellier, et la bannière qu''il lève sur moi, c''est l''amour.'),
('ct',2,5,'crampon1923','Soutenez-moi avec des gâteaux de raisin, fortifiez-moi avec des pommes, car je suis malade d''amour.'),
('ct',2,6,'crampon1923','Que sa main gauche soutienne ma tête, et que sa droite me tienne embrassée. L''ÉPOUX.'),
('ct',2,7,'crampon1923','Je vous en conjure, filles de Jérusalem, par les gazelles et les biches des champs, n''éveillez pas, ne réveillez pas la bien-aimée, avant qu''elle le veuille. L''ÉPOUSE.'),
('ct',2,8,'crampon1923','La voix de mon bien-aimé! Voici qu''il vient, bondissant sur les montagnes, sautant sur les collines.'),
('ct',2,9,'crampon1923','Mon bien-aimé est semblable à la gazelle, ou au faon des biches. Le voici, il est derrière notre mur, regardant par la fenêtre, épiant par le treillis.'),
('ct',2,10,'crampon1923','Mon bien-aimé a pris la parole, il m''a dit: " Lève-toi, mon amie, ma belle, et viens!'),
('ct',2,11,'crampon1923','Car voici que l''hiver est fini; la pluie a cessé, elle a disparu.'),
('ct',2,12,'crampon1923','Les fleurs ont paru sur la terre, le temps des chants est arrivé; la voix de la tourterelle s''est fait entendre dans nos campagnes;'),
('ct',2,13,'crampon1923','le figuier pousse ses fruits naissants, la vigne en fleur donne son parfum. Lève-toi, mon amie, ma belle, et viens!'),
('ct',2,14,'crampon1923','Ma colombe, qui te tiens dans la fente du rocher, dans l''abri des parois escarpées. montre-moi ton visage, fais-moi entendre ta voix; car ta voix est douce, et ton visage charmant.'),
('ct',2,15,'crampon1923','Prenez-nous les renards, les petits renards, qui ravagent les vignes, car nos vignes sont en fleur. "'),
('ct',2,16,'crampon1923','Mon bien-aimé est à moi, et je suis à lui; il fait paître son troupeau parmi les lis.'),
('ct',2,17,'crampon1923','Avant que vienne la fraîcheur du jour, et que les ombres fuient, reviens!... Sois semblable, mon bien-aimé, à la gazelle ou au faon des biches, sur les montagnes ravinées.'),
('ct',3,1,'crampon1923','Sur ma couche, pendant la nuit, j''ai cherché celui que mon cœur aime; je l''ai cherché et je ne l''ai point trouvé.'),
('ct',3,2,'crampon1923','" Levons-nous, me suis-je dit, parcourons la ville, les rues et les places, cherchons celui que mon cœur aime. " Je l''ai cherché et je ne l''ai point trouvé.'),
('ct',3,3,'crampon1923','Les gardes m''ont rencontrée, ceux qui font la ronde dans la ville: " Avez-vous vu celui que mon cœur aime? "'),
('ct',3,4,'crampon1923','A peine les avais-je dépassés, que j''ai trouvé celui que mon cœur aime. Je l''ai saisi et je ne le lâcherai pas, jusqu''à ce que je l''aie introduit dans la maison de ma mère, et dans la chambre de celle qui m''a donné le jour. L''ÉPOUX.'),
('ct',3,5,'crampon1923','Je vous en conjure, filles de Jérusalem, par les gazelles et les biches des champs, n''éveillez pas, ne réveillez pas la bien-aimée, avant qu''elle le veuille. LE CHŒUR.'),
('ct',3,6,'crampon1923','Quelle est celle-ci qui monte du désert, comme une colonne de fumée, exhalant la myrrhe et l''encens, tous les aromates des marchands? —'),
('ct',3,7,'crampon1923','Voici le palanquin de Salomon; autour de lui, soixante braves, d''entre les vaillants d''Israël;'),
('ct',3,8,'crampon1923','tous sont armés de l''épée, exercés au combat; chacun porte son épée sur sa hanche, pour écarter les alarmes de la nuit.'),
('ct',3,9,'crampon1923','Le roi Salomon s''est fait une litière des bois du Liban.'),
('ct',3,10,'crampon1923','Il en a fait les colonnes d''argent, le dossier d''or, le siège de pourpre; au milieu est une broderie, œuvre d''amour des filles de Jérusalem.'),
('ct',3,11,'crampon1923','Sortez, filles de Sion, et voyez le roi Salomon, avec la couronne dont sa mère l''a couronné, le jour de ses épousailles, le jour de la joie de son cœur.'),
('ct',4,1,'crampon1923','Oui, tu es belle, mon amie; oui, tu es belle! Tes yeux sont des yeux de colombes derrière ton voile; tes cheveux sont comme un troupeau de chèvres, suspendues aux flancs de la montagne de Galaad.'),
('ct',4,2,'crampon1923','Tes dents sont comme un troupeau de brebis tondues, qui remontent du lavoir; chacune porte deux jumeaux, et, parmi elles, il n''est pas de stérile.'),
('ct',4,3,'crampon1923','Tes lèvres sont comme un fil de pourpre, et ta bouche est charmante; ta joue est comme une moitié de grenade, derrière ton voile.'),
('ct',4,4,'crampon1923','Ton cou est comme la tour de David, bâtie pour servir d''arsenal; mille boucliers y sont suspendus, tous les boucliers des braves.'),
('ct',4,5,'crampon1923','Tes deux seins sont comme deux faons, jumeaux d''une gazelle, qui paissent au milieu des lis.'),
('ct',4,6,'crampon1923','Avant que vienne la fraîcheur du jour, et que les ombres fuient, j''irai à la montagne de la myrrhe, et à la colline de l''encens.'),
('ct',4,7,'crampon1923','Tu es toute belle, mon amie, et il n''y a pas de tache en toi!'),
('ct',4,8,'crampon1923','Avec moi, viens du Liban, ma fiancée, viens avec moi du Liban! Regarde du sommet de l''Amana, du sommet du Sanir et de l''Hermon, des tanières des lions, des montagnes des léopards.'),
('ct',4,9,'crampon1923','Tu m''as ravi le cœur, ma sœur fiancée tu m''as ravi le cœur par un seul de tes regards, par une seule des perles de ton collier.'),
('ct',4,10,'crampon1923','Que ton amour a de charme, ma sœur fiancée! Combien ton amour est meilleur que le vin, et l''odeur de tes parfums, que tous les aromates!'),
('ct',4,11,'crampon1923','Tes lèvres distillent le miel, ma fiancée, le miel et le lait sont sous ta langue, et l''odeur de tes vêtements est comme l''odeur du Liban.'),
('ct',4,12,'crampon1923','C''est un jardin fermé que ma sœur fiancée, une source fermée, une fontaine scellée.'),
('ct',4,13,'crampon1923','Tes pousses sont un bosquet de grenadiers, avec les fruits les plus exquis; le cypre avec le nard,'),
('ct',4,14,'crampon1923','le nard et le safran, la cannelle et le cinnamome, avec tous les arbres à encens, la myrrhe et l''aloès, avec tous les meilleurs baumiers.'),
('ct',4,15,'crampon1923','Source de jardins, puits d''eaux vives, ruisseau qui coule du Liban! L''ÉPOUSE.'),
('ct',4,16,'crampon1923','Levez-vous aquilons; venez autans! Soufflez sur mon jardin, et que ses baumiers exsudent! Que mon bien-aimé entre dans son jardin, et qu''il mange de ses beaux fruits!'),
('ct',4,17,'crampon1923',''),
('ct',5,1,'crampon1923','Je suis entré dans mon jardin, ma sœur fiancée, j''ai cueilli ma myrrhe avec mon baume; j''ai mangé mon rayon avec mon miel, j''ai bu mon vin avec mon lait!... Mangez, amis, buvez, enivrez-vous, mes bien-aimés. L''ÉPOUSE.'),
('ct',5,2,'crampon1923','Je dors mais mon cœur veille... C''est la voix de mon bien-aimé! Il frappe: " Ouvre-moi, ma sœur, mon amie, ma colombe, mon immaculée; car ma tête est couverte de rosée, les boucles de mes cheveux sont trempées des gouttes de la nuit. " —'),
('ct',5,3,'crampon1923','J''ai ôté ma tunique, comment la remettre? J''ai lavé mes pieds, comment les salirais-je?'),
('ct',5,4,'crampon1923','Mon bien-aimé a passé la main par le trou de la serrure, et mes entrailles se sont émues sur lui.'),
('ct',5,5,'crampon1923','Je me suis levée pour ouvrir à mon bien-aimé, et de mes mains a dégoutté la myrrhe, de mes doigts la myrrhe exquise, sur la poignée du verrou.'),
('ct',5,6,'crampon1923','J''ouvre à mon bien-aimé; mais mon bien-aimé avait disparu, il avait fui. J''étais hors de moi quand il me parlait. Je l''ai cherché, et ne l''ai pas trouvé; je l''ai appelé, il ne m''a pas répondu.'),
('ct',5,7,'crampon1923','Les gardes m''ont rencontrée, ceux qui font la ronde dans la ville; ils m''ont frappée, ils m''ont meurtrie; Ils m''ont enlevé mon manteau, ceux qui gardent la muraille.'),
('ct',5,8,'crampon1923','Je vous en conjure, filles de Jérusalem, si vous trouvez mon bien-aimé, que lui direz-vous?... Que je suis malade d''amour! LE CHŒUR.'),
('ct',5,9,'crampon1923','Qu''a donc ton bien-aimé de plus qu''un autre bien-aimé, ô la plus belle des femmes? Qu''a donc ton bien-aimé de plus qu''un autre bien-aimé, pour que tu nous conjures de la sorte? L''EPOUSE.'),
('ct',5,10,'crampon1923','Mon bien-aimé est frais et vermeil; il se distingue entre dix mille.'),
('ct',5,11,'crampon1923','Sa tête est de l''or pur, ses boucles de cheveux, flexibles comme des palmes, sont noires comme le corbeau.'),
('ct',5,12,'crampon1923','Ses yeux sont comme des colombes au bord des ruisseaux, se baignant dans le lait, posées sur les rives.'),
('ct',5,13,'crampon1923','Ses joues sont comme des parterres de baumiers, des carrés de plantes odorantes; ses lèvres sont des lis, d''où découle la myrrhe la plus pure.'),
('ct',5,14,'crampon1923','Ses mains sont des cylindres d''or, émaillés de pierres de Tharsis; son sein est un chef-d''œuvre d''ivoire, couvert de saphirs.'),
('ct',5,15,'crampon1923','Ses jambes sont des colonnes d''albâtre, posées sur des bases d''or pur. Son aspect est celui du Liban, élégant comme le cèdre.'),
('ct',5,16,'crampon1923','Son palais n''est que douceur, et toute sa personne n''est que charme. Tel est mon bien-aimé, tel est mon ami, filles de Jérusalem.'),
('ct',6,1,'crampon1923','Où est allé ton bien-aimé, ô la plus belle des femmes? De quel côté ton bien-aimé s''est-il tourné, pour que nous le cherchions avec toi? L''EPOUSE'),
('ct',6,2,'crampon1923','Mon bien-aimé est descendu dans son jardin, aux parterres de baumiers, pour faire paître son troupeau dans les jardins, et pour cueillir des lis.'),
('ct',6,3,'crampon1923','Je suis à mon bien-aimé, et mon bien-aimé est à moi; il fait paître son troupeau parmi les lis. L''ÉPOUX.'),
('ct',6,4,'crampon1923','Tu es belle, mon amie, comme Thirsa, charmante comme Jérusalem, mais terrible comme des bataillons.'),
('ct',6,5,'crampon1923','Détourne de moi tes yeux, car ils me troublent. Tes cheveux sont comme un troupeau de chèvres, suspendues aux flancs de la montagne de Galaad.'),
('ct',6,6,'crampon1923','Tes dents sont comme un troupeau de brebis, qui remontent du lavoir; chacune porte deux jumeaux; et parmi elles, il n''est pas de stérile.'),
('ct',6,7,'crampon1923','Ta joue est comme une moitié de grenade, derrière ton voile.'),
('ct',6,8,'crampon1923','Il y a soixante reines, quatre-vingts concubines, et des jeunes filles sans nombre:'),
('ct',6,9,'crampon1923','une seule est ma colombe, mon immaculée; elle est l''unique de sa mère, la préférée de celle qui lui donna le jour. Les jeunes filles l''ont vue et l''ont proclamée bienheureuse; les reines et les concubines l''ont vue et l''ont louée:'),
('ct',6,10,'crampon1923','" Quelle est celle-ci qui apparaît comme l''aurore, belle comme la lune, pure comme le soleil, mais terrible comme des bataillons? "'),
('ct',6,11,'crampon1923','J''étais descendu au jardin des noyers, pour voir les herbes de la vallée, pour voir si la vigne pousse, si les grenadiers sont en fleurs.'),
('ct',6,12,'crampon1923','Je ne sais, mais mon amour m''a fait monter sur les chars de mon noble peuple.'),
('ct',7,1,'crampon1923','Reviens, reviens, Sulamite? Reviens, reviens, afin que nous te regardions. L''ÉPOUX. Pourquoi regardez-vous la Sulamite, comme une danse de Machanaïm. LE CHOEUR.'),
('ct',7,2,'crampon1923','Que tes pieds sont beaux dans tes sandales, fille de prince! La courbure de tes reins est comme un collier, œuvre d''un artiste.'),
('ct',7,3,'crampon1923','Ton nombril est une coupe arrondie, où le vin aromatisé ne manque pas. Ton ventre est un monceau de froment, entouré de lis.'),
('ct',7,4,'crampon1923','Tes deux seins sont comme deux faons, jumeaux d''une gazelle.'),
('ct',7,5,'crampon1923','Ton cou est comme une tour d''ivoire; tes yeux sont comme les piscines d''Hésébon, près de la porte de cette ville populeuse. Ton nez est comme la Tour du Liban, qui surveille le côté de Damas.'),
('ct',7,6,'crampon1923','Ta tête est posée sur toi comme le Carmel, la chevelure de ta tête est comme la pourpre rouge: un roi est enchaîné à ses boucles. L''ÉPOUX.'),
('ct',7,7,'crampon1923','Que tu es belle, que tu es charmante, mon amour, au milieu des délices!'),
('ct',7,8,'crampon1923','Ta taille ressemble au palmier, et tes seins à ses grappes.'),
('ct',7,9,'crampon1923','J''ai dit: je monterai au palmier, j''en saisirai les régimes. Que tes seins soient comme les grappes de la vigne, le parfum de ton souffle comme celui des pommes,'),
('ct',7,10,'crampon1923','et ton palais comme un vin exquis!... L''ÉPOUSE. Qui coule aisément pour mon bien-aimé, qui glisse sur les lèvres de ceux qui s''endorment.'),
('ct',7,11,'crampon1923','Je suis à mon bien-aimé, et c''est vers moi qu''il porte ses désirs.'),
('ct',7,12,'crampon1923','Viens, mon bien-aimé, sortons dans les champs, passons la nuit dans les villages.'),
('ct',7,13,'crampon1923','Dès le matin nous irons aux vignes, nous verrons si la vigne bourgeonne, si les bourgeons se sont ouverts, si les grenadiers sont en fleurs; là je te donnerai mon amour.'),
('ct',7,14,'crampon1923','Les mandragores font sentir leur parfum, et nous avons à nos portes tous les meilleurs fruits, les nouveaux et aussi les vieux: mon bien-aimé, je les ai gardés pour toi.'),
('ct',8,1,'crampon1923','Oh! que ne m''es-tu un frère, qui aurait sucé les mamelles de ma mère! Te rencontrant dehors, je t''embrasserais, et on ne pourrait me mépriser.'),
('ct',8,2,'crampon1923','Je t''amènerais, je t''introduirais dans la maison de ma mère: tu m''enseignerais; et je te ferais boire du vin aromatisé, le jus de mes grenades.'),
('ct',8,3,'crampon1923','Sa main gauche est sous ma tête, et sa droite me tient embrassée. L''ÉPOUX.'),
('ct',8,4,'crampon1923','Je vous en conjure, filles de Jérusalem, n''éveillez pas, ne réveillez pas la bien-aimée, avant qu''elle le veuille. LE CHŒUR.'),
('ct',8,5,'crampon1923','Quelle est celle-ci qui monte du désert, appuyée sur son bien-aimé? L''ÉPOUX. Je t''ai réveillée sous le pommier, là, ta mère t''a conçue; là, elle t''a conçue, là, elle t''a donné le jour.'),
('ct',8,6,'crampon1923','Mets-moi comme un sceau sur ton cœur, comme un sceau sur ton bras; car l''amour est fort comme la mort, la jalousie est inflexible comme le schéol. Ses ardeurs sont des ardeurs de feu, une flamme de Yahweh.'),
('ct',8,7,'crampon1923','Les grandes eaux ne sauraient éteindre l''amour, et les fleuves ne le submergeraient pas. Un homme donnerait-il pour l''amour toutes les richesses de sa maison, on ne ferait que le mépriser. LE CHŒUR.'),
('ct',8,8,'crampon1923','Nous avons une petite sœur, qui n''a pas encore de mamelles: que ferons-nous à notre sœur, le jour où on la recherchera?'),
('ct',8,9,'crampon1923','Si elle est un mur, nous lui ferons un couronnement d''argent; si elle est une porte, nous la fermerons avec des ais de cèdre. L''ÉPOUSE.'),
('ct',8,10,'crampon1923','Je suis un mur, et mes seins sont comme des tours, aussi suis-je, à ses yeux, celle qui a trouvé la paix, LE CHŒUR.'),
('ct',8,11,'crampon1923','Salomon avait une vigne à Baal-Hamon, il remit la vigne à des gardiens, et pour son fruit chacun devait lui apporter mille sicles d''argent. L''ÉPOUSE.'),
('ct',8,12,'crampon1923','La vigne qui est à moi, j''en dispose: à toi, Salomon, les milles sicles, et deux cents aux gardiens de son fruit. L''ÉPOUX.'),
('ct',8,13,'crampon1923','Toi qui habites les jardins, les compagnons prêtent l''oreille à ta voix: daigne me la faire entendre. L''ÉPOUSE.'),
('ct',8,14,'crampon1923','Cours, mon bien aimé, et sois semblable à la gazelle, ou au faon des biches, sur les montagnes des baumiers!'),
('sg',1,1,'crampon1923','Aimez la justice, vous qui êtes les juges de la terre; que vos pensées sur le Seigneur soient selon la droiture, et cherchez-le d''un cœur sincère;'),
('sg',1,2,'crampon1923','car il se laisse trouver par ceux qui ne le tentent point, et il se manifeste à ceux qui se confient à lui.'),
('sg',1,3,'crampon1923','En effet, les pensées perverses séparent de Dieu, et sa puissance, quand on la met à l''épreuve, accuse les insensés.'),
('sg',1,4,'crampon1923','La sagesse n''entre pas dans une âme qui médite le mal, et n''habite pas dans un corps esclave du péché.'),
('sg',1,5,'crampon1923','L''Esprit-Saint, éducateur des hommes, fuit l''astuce; il s''éloigne des pensées dépourvues d''intelligence, et se retire quand approche l''iniquité.'),
('sg',1,6,'crampon1923','En effet, la Sagesse est un esprit qui aime les hommes, et il ne laisse pas impuni le blasphémateur pour ses discours, car Dieu est le témoin de ses reins, le véritable scrutateur de son cœur, et il entend ses paroles.'),
('sg',1,7,'crampon1923','Car l''Esprit du Seigneur remplit l''univers, et lui qui contient tout, sait tout ce qui se dit.'),
('sg',1,8,'crampon1923','Aussi celui qui tient des discours impies ne saurait rester caché, et la justice vengeresse ne l''oublie pas.'),
('sg',1,9,'crampon1923','Car il y aura une enquête sur les desseins de l''impie; la rumeur de ses paroles arrivera jusqu''au Seigneur, pour le châtiment de ses iniquités.'),
('sg',1,10,'crampon1923','Une oreille jalouse entend tout, et le bruit des murmures ne lui échappe pas.'),
('sg',1,11,'crampon1923','Gardez-vous donc des murmures inutiles, et préservez votre langue du blasphème; car la parole la plus secrète ne sort pas impunie, et la bouche qui ment donne la mort à l''âme.'),
('sg',1,12,'crampon1923','Ne courez pas après la mort par les égarements de votre vie; et n''attirez pas sur vous la perdition par les œuvres de vos mains.'),
('sg',1,13,'crampon1923','Car Dieu n''a pas fait la mort, et il n''éprouve pas de joie de la perte des vivants.'),
('sg',1,14,'crampon1923','Il a créé toutes choses pour la vie; les créatures du monde sont salutaires; il n''y a en elles aucun principe de destruction, et la mort n''a pas d''empire sur la terre.'),
('sg',1,15,'crampon1923','Car la justice est immortelle.'),
('sg',1,16,'crampon1923','Mais les impies appellent la mort du geste et de la voix; la regardant comme une amie, ils se passionnent pour elle, ils font alliance avec elle, et ils sont dignes, en effet, de lui appartenir.'),
('sg',2,1,'crampon1923','Ils se sont dit, raisonnant de travers: « Il est court et triste le temps de notre vie, et, quand vient la fin d''un homme, il n''y a point de remède; on ne connaît personne qui délivre du séjour des morts.'),
('sg',2,2,'crampon1923','Le hasard nous a amenés à l''existence, et, après cette vie, nous serons comme si nous n''avions jamais été; le souffle, dans nos narines, est une fumée, et la pensée, une étincelle qui jaillit au battement de notre cœur.'),
('sg',2,3,'crampon1923','Qu''elle s''éteigne, notre corps tombera en cendres, et l''esprit se dissipera comme l''air léger.'),
('sg',2,4,'crampon1923','Notre nom tombera dans l''oubli avec le temps, et personne ne se souviendra de nos œuvres. Notre vie passera comme une trace de nuée; elle se dissipera comme un brouillard, que chassent les rayons du soleil, et que la chaleur condense en pluie.'),
('sg',2,5,'crampon1923','Notre vie est le passage d''une ombre; sa fin est sans retour, le sceau est apposé et nul ne revient.'),
('sg',2,6,'crampon1923','« Venez donc, jouissons des biens présents; usons des créatures avec l''ardeur de la jeunesse,'),
('sg',2,7,'crampon1923','enivrons-nous de vin précieux et de parfums, et ne laissons point passer la fleur du printemps.'),
('sg',2,8,'crampon1923','Couronnons-nous de boutons de roses avant qu''ils se flétrissent.'),
('sg',2,9,'crampon1923','Qu''aucun de nous ne manque à nos orgies, laissons partout des traces de nos réjouissances; car c''est là notre part, c''est là notre destinée.'),
('sg',2,10,'crampon1923','« Opprimons le juste qui est pauvre; n''épargnons pas la veuve, et n''ayons nul égard pour les cheveux blancs du vieillard chargé d''années.'),
('sg',2,11,'crampon1923','Que notre force soit la loi de la justice; ce qui est faible est jugé bon à rien.'),
('sg',2,12,'crampon1923','Traquons donc le juste, puisqu''il nous incommode, qu''il est contraire à notre manière d''agir, qu''il nous reproche de violer la loi, et nous accuse de démentir notre éducation.'),
('sg',2,13,'crampon1923','Il prétend posséder la connaissance de Dieu, et se nomme fils du Seigneur.'),
('sg',2,14,'crampon1923','Il est pour nous la condamnation de nos pensées, sa vue seule nous est insupportable;'),
('sg',2,15,'crampon1923','car sa vie ne ressemble pas à celle des autres, et ses voies sont étranges.'),
('sg',2,16,'crampon1923','Dans sa pensée, nous sommes d''impures scories, il évite notre manière de vivre comme une souillure; il proclame heureux le sort final des justes, et se vante d''avoir Dieu pour père.'),
('sg',2,17,'crampon1923','Voyons donc si ce qu''il dit est vrai, et examinons ce qui lui arrivera au sortir de cette vie.'),
('sg',2,18,'crampon1923','Car si le juste est fils de Dieu, Dieu prendra sa défense, et le délivrera de la main de ses adversaires.'),
('sg',2,19,'crampon1923','Soumettons-le aux outrages et aux tourments, afin de connaître sa résignation, et de juger sa patience.'),
('sg',2,20,'crampon1923','Condamnons-le à une mort honteuse, car, selon qu''il le dit, Dieu aura souci de lui. »'),
('sg',2,21,'crampon1923','Telles sont leurs pensées, mais ils se trompent; leur malice les a aveuglés.'),
('sg',2,22,'crampon1923','Ignorant les desseins secrets de Dieu, ils n''espèrent pas de rémunération pour la sainteté, et ils ne croient pas à la récompense des âmes pures.'),
('sg',2,23,'crampon1923','Car Dieu a créé l''homme pour l''immortalité, et il l''a fait à l''image de sa propre nature.'),
('sg',2,24,'crampon1923','C''est par l''envie du diable que la mort est venue dans le monde; ils en feront l''expérience, ceux qui lui appartiennent.'),
('sg',3,1,'crampon1923','Les âmes des justes sont dans la main de Dieu, et le tourment ne les atteindra pas.'),
('sg',3,2,'crampon1923','Aux yeux des insensés, ils paraissent être morts, et leur sortie de ce monde semble un malheur,'),
('sg',3,3,'crampon1923','et leur départ du milieu de nous un anéantissement; mais ils sont dans la paix.'),
('sg',3,4,'crampon1923','Alors même que, devant les hommes, ils ont subi des châtiments, leur espérance est pleine d''immortalité.'),
('sg',3,5,'crampon1923','Après une légère peine, ils recevront une grande récompense; car Dieu les a éprouvés, et les a trouvés dignes de lui.'),
('sg',3,6,'crampon1923','Il les a essayés comme l''or dans la fournaise, et les a agréés comme un parfait holocauste.'),
('sg',3,7,'crampon1923','Au temps de leur récompense, ils brilleront; comme des étincelles, ils courront à travers le chaume.'),
('sg',3,8,'crampon1923','Ils jugeront les nations et domineront sur les peuples, et le Seigneur régnera sur eux à jamais.'),
('sg',3,9,'crampon1923','Eux qui ont mis en lui leur confiance, ils comprendront la vérité; ses fidèles habiteront avec lui dans l''amour; car la grâce et la miséricorde sont pour ses élus.'),
('sg',3,10,'crampon1923','Mais les impies auront le châtiment mérité par leurs pensées perverses, eux qui ont méprisé le juste, et se sont éloignés du Seigneur.'),
('sg',3,11,'crampon1923','Car qui rejette la sagesse et la correction est voué au malheur; leur espérance est vaine, leurs efforts sont infructueux, et leurs œuvres sans profit.'),
('sg',3,12,'crampon1923','Leurs femmes sont insensées, leurs enfants pleins de malice, et leur postérité est maudite.'),
('sg',3,13,'crampon1923','C''est pourquoi heureuse la femme stérile et sans tache, dont la couche ne connaît pas la souillure! Elle aura son fruit à la visite des âmes.'),
('sg',3,14,'crampon1923','Heureux encore l''eunuque qui de sa main n''a pas fait l''iniquité et qui n''a pas conçu de pensées criminelles contre le Seigneur! Il recevra une récompense de choix pour sa fidélité, et il aura dans le temple du Seigneur le sort le plus désirable.'),
('sg',3,15,'crampon1923','Car du travail des bonnes œuvres le fruit est glorieux, et la racine de la prudence ne périt pas.'),
('sg',3,16,'crampon1923','Mais les enfants des adultères n''atteindront pas leur fin, et la race sortie d''une couche criminelle disparaîtra.'),
('sg',3,17,'crampon1923','Si leur vie est longue, ils seront comptés pour rien, et leur vieillesse à la fin sera sans honneur.'),
('sg',3,18,'crampon1923','S''ils meurent promptement, ils n''auront pas d''espérance, ni de consolation au jour du jugement.'),
('sg',3,19,'crampon1923','Car la race injuste a toujours une fin funeste.'),
('sg',4,1,'crampon1923','Mieux vaut la stérilité avec la vertu; sa mémoire est immortelle, car elle est connue de Dieu et des hommes.'),
('sg',4,2,'crampon1923','Quand on l''a sous les yeux, on l''imite; quand elle n''est plus là, on la regrette; couronnée dans l''éternité, elle triomphe, ayant remporté la victoire dans des combats sans souillure.'),
('sg',4,3,'crampon1923','Mais la nombreuse postérité des impies est sans utilité; issue de rejetons bâtards, elle ne jettera pas de racines profondes, et ne s''établira pas sur un fondement assuré.'),
('sg',4,4,'crampon1923','Alors même qu''ils se couvriraient pour un temps de verts rameaux, fixés au sol sans solidité, ils seront ébranlés par le vent, et déracinés par la violence de l''ouragan.'),
('sg',4,5,'crampon1923','Leurs rameaux seront brisés encore tendres, leurs fruits sont inutiles, trop verts, pour être mangés, et impropres à tout usage.'),
('sg',4,6,'crampon1923','Car les enfants nés de sommeils impurs sont témoins du crime contre leurs parents quand on les interroge.'),
('sg',4,7,'crampon1923','Mais le juste, lors même qu''il meurt avant l''âge, trouve le repos.'),
('sg',4,8,'crampon1923','Une vieillesse honorable n''est pas celle que donne une longue vie; ni celle qui se mesure au nombre des années.'),
('sg',4,9,'crampon1923','Mais la prudence tient lieu pour l''homme de cheveux blancs; et l''âge de la vieillesse, c''est une vie sans tache.'),
('sg',4,10,'crampon1923','Étant agréable à Dieu, il était aimé de lui, et, comme il vivait parmi les pécheurs, il a été transféré.'),
('sg',4,11,'crampon1923','Il a été enlevé de peur que la malice n''altérât son intelligence, ou que la ruse ne pervertît son âme.'),
('sg',4,12,'crampon1923','Car l''enchantement du vice obscurcit le bien, et le vertige de la passion pervertit un esprit sans malice.'),
('sg',4,13,'crampon1923','Arrivé en peu de temps à la perfection, il a fourni une longue carrière.'),
('sg',4,14,'crampon1923','Car son âme était agréable au Seigneur; c''est pourquoi le Seigneur s''est hâté de le retirer du milieu de l''iniquité.'),
('sg',4,15,'crampon1923','Les peuples le voient sans y rien comprendre, ne se mettant pas ceci dans l''esprit que la grâce de Dieu et sa miséricorde sont avec ses élus, et qu''il a souci de ses saints.'),
('sg',4,16,'crampon1923','Mais le juste qui meurt condamne les impies qui survivent, et la jeunesse arrivée si vite à la perfection condamne la longue vieillesse de l''homme injuste.'),
('sg',4,17,'crampon1923','Ils verront la fin du sage, mais sans comprendre les desseins de Dieu sur lui, ni pourquoi le Seigneur l''a mis en sûreté.'),
('sg',4,18,'crampon1923','Ils verront et se moqueront, mais le Seigneur se rira d''eux;'),
('sg',4,19,'crampon1923','et après cela ils seront un cadavre sans honneur, ils seront parmi les morts dans l''opprobre pour toujours. Le Seigneur les brisera, et, réduits au silence, les précipitera; il les ébranlera de leurs fondements, et ils seront détruits jusqu''au dernier; ils seront dans la douleur, et leur mémoire périra.'),
('sg',4,20,'crampon1923','Ils viendront pleins d''effroi à la pensée de leurs péchés, et leurs crimes, se dressant devant eux, les accuseront.'),
('sg',5,1,'crampon1923','Alors le juste sera debout en grande assurance, en face de ceux qui l''ont persécuté, et qui méprisaient ses labeurs.'),
('sg',5,2,'crampon1923','A cette vue, ils seront agités d''une horrible épouvante, ils seront dans la stupeur devant la révélation du salut.'),
('sg',5,3,'crampon1923','Ils se diront, pleins de regret, et gémissant dans le serrement de leur cœur: « Voilà donc celui qui était autrefois l''objet de nos moqueries, et le but de nos outrages!'),
('sg',5,4,'crampon1923','Insensés, nous regardions sa vie comme une folie, et sa fin comme un opprobre.'),
('sg',5,5,'crampon1923','Comment est-il compté parmi les enfants de Dieu, et sa part est-elle parmi les saints?')
